(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("polybius-6-e", [{"sp": "HDR", "t": "Ἱστορίαι (ΚΗʹ–ΛΘʹ)"}, {"sp": "HDR", "t": "Βιβλίον ΚΗʹ", "st": "28"}, {"sp": "N", "t": "ὅτι τοῦ πολέμου τοῦ περὶ Κοίλης Συρίας ἤδη καταρχὴν λαβόντος Ἀντιόχῳ καὶ Πτολεμαίῳ τοῖς βασιλεῦσιν, ἧκον πρέσβεις εἰς τὴν Ῥώμην παρὰ μὲν Ἀντιόχου Μελέαγρος καὶ Σωσιφάνης καὶ Ἡρακλείδης, παρὰ δὲ Πτολεμαίου Τιμόθεος καὶ Δάμων. συνέβαινε δὲ κρατεῖν τὸν Ἀντίοχον τῶν κατὰ Κοίλην Συρίαν καὶ Φοινίκην πραγμάτων. ἐξ οὗ γὰρ Ἀντίοχος ὁ πατὴρ τοῦ νῦν λεγομένου βασιλέως ἐνίκησε τῇ περὶ τὸ Πάνιον μάχῃ τοὺς Πτολεμαίου στρατηγούς, ἀπ’ ἐκείνων τῶν χρόνων ἐπείθοντο πάντες οἱ προειρημένοι τόποι τοῖς ἐν Συρίᾳ βασιλεῦσιν. διόπερ ὁ μὲν Ἀντίοχος ἡγούμενος τὴν κατὰ πόλεμον ἰσχυροτάτην καὶ καλλίστην εἶναι κτῆσιν, ὡς ὑπὲρ ἰδίων ἐποιεῖτο τὴν σπουδήν· ὁ δὲ Πτολεμαῖος ἀδίκως ὑπολαμβάνων τὸν πρότερον Ἀντίοχον συνεπιθέμενον τῇ τοῦ πατρὸς ὀρφανίᾳ παρῃρῆσθαι τὰς κατὰ Κοίλην Συρίαν πόλεις αὐτῶν, οὐχ οἷός τ’ ἦν ἐκείνῳ παραχωρεῖν τῶν τόπων τούτων. διόπερ οἱ περὶ τὸν Μελέαγρον ἧκον, ἐντολὰς ἔχοντες μαρτύρεσθαι τὴν σύγκλητον διότι Πτολεμαῖος αὐτῷ παρὰ πάντα τὰ δίκαια τὰς χεῖρας ἐπιβάλλει πρότερος, οἱ δὲ περὶ τὸν Τιμόθεον περί τε τῆς τῶν φιλανθρώπων ἀνανεώσεως καὶ τοῦ διαλύειν τὸν πρὸς Περσέα πόλεμον, μάλιστα δὲ παρατηρεῖν τὰς τῶν περὶ τὸν Μελέαγρον ἐντεύξεις. περὶ μὲν οὖν τῆς διαλύσεως οὐκ ἐθάρρησαν εἰπεῖν, Μάρκου συμβουλεύσαντος αὐτοῖς Αἰμιλίου· περὶ δὲ τῶν φιλανθρώπων ἀνανεωσάμενοι καὶ λαβόντες ἀποκρίσεις ἀκολούθους τοῖς ἀξιουμένοις ἐπανῆλθον εἰς τὴν Ἀλεξάνδρειαν. τοῖς δὲ περὶ τὸν Μελέαγρον ἡ σύγκλητος ἀπεκρίθη διότι Κοΐντῳ Μαρκίῳ δώσει τὴν ἐπιτροπὴν γράψαι περὶ τούτων πρὸς Πτολεμαῖον, ὡς αὐτῷ δοκεῖ συμφέρειν ἐκ τῆς ἰδίας πίστεως. καὶ ταῦτα μὲν οὕτως ἐχειρίσθη κατὰ τὸ παρόν. —", "st": "28.1"}, {"sp": "N", "t": "ὅτι κατὰ τοὺς καιροὺς τούτους ἦλθον καὶ παρὰ Ῥοδίων πρέσβεις, ἤδη τῆς θερείας ληγούσης, Ἁγησίλοχος καὶ Νικαγόρας καὶ Νίκανδρος, τήν τε φιλίαν ἀνανεωσόμενοι καὶ σίτου θέλοντες ἐξαγωγὴν λαβεῖν, ἅμα δὲ καὶ περὶ τῶν διαβολῶν ἀπολογησόμενοι τῶν λεγομένων κατὰ τῆς πόλεως. ἐκφανέστατα γὰρ ἐδόκουν στασιάζειν [ἐν τῇ Ῥόδῳ] οἱ μὲν περὶ τὸν Ἀγαθάγητον καὶ Φιλόφρονα καὶ Ῥοδοφῶντα καὶ Θεαίδητον, ἀπερειδόμενοι πάσας τὰς ἐλπίδας ἐπὶ Ῥωμαίους, οἱ δὲ περὶ τὸν Δείνωνα καὶ Πολυάρατον ἐπὶ Περσέα καὶ Μακεδόνας. ἐξ ὧν πλεονάκις ἐν τοῖς ἐκείνων πράγμασιν ἀντιρρήσεως γινομένης, καὶ διελκομένων τῶν διαβουλίων, ἐλάμβανον ἀφορμὰς οἱ βουλόμενοι λογοποιεῖν κατὰ τῆς πόλεως. οὐ μὴν ἥ γε σύγκλητος τότε προσεποιήθη τούτων οὐδέν, καίπερ σαφῶς εἰδυῖα τὰ γενόμενα παρ’ αὐτοῖς· σίτου δ’ ἔδωκε δέκα μυριάδας μεδίμνων ἐξάγειν ἐκ Σικελίας. ταῦτα μὲν οὖν ἡ σύγκλητος ἐχρημάτισεν ἰδίᾳ τοῖς Ῥοδίων πρεσβευταῖς, ἀκολούθως δὲ καὶ τοῖς ἄλλοις ἅπασιν ἀπήντησε τοῖς ἀπὸ τῆς Ἑλλάδος παραγεγονόσι, τηροῦσιν τὴν αὐτὴν ὑπόθεσιν. καὶ τὰ μὲν κατὰ τὴν Ἰταλίαν ἐν τούτοις ἦν.", "st": "28.2"}, {"sp": "N", "t": "ὅτι Αὖλος κατὰ τοῦτον τὸν χρόνον ἀντιστράτηγος ὢν καὶ παραχειμάζων ἐν Θετταλίᾳ μετὰ τῶν δυνάμεων ἐξέπεμψε πρεσβευτὰς εἰς τοὺς κατὰ τὴν Ἑλλάδα τόπους Γάιον Ποπίλιον καὶ Γνάιον Ὀκτάουιον· οἳ πρῶτον μὲν εἰς Θήβας ἐλθόντες ἐπῄνεσαν καὶ παρεκάλεσαν τοὺς Θηβαίους διαφυλάττειν τὴν πρὸς Ῥωμαίους εὔνοιαν. ἑξῆς δὲ τούτοις ἐπιπορευόμενοι τὰς ἐν Πελοποννήσῳ πόλεις ἐπιδεικνύειν ἐπειρῶντο τοῖς ἀνθρώποις τὴν τῆς συγκλήτου πρᾳότητα καὶ φιλανθρωπίαν, προφερόμενοι τὰ δόγματα τὰ μικρῷ πρότερον ῥηθέντα, ἅμα δὲ διὰ τῶν λόγων παρενέφαινον ὡς εἰδότες τοὺς ἐν ἑκάσταις τῶν πόλεων παρὰ τὸ δέον ἀναχωροῦντας, ὡσαύτως δὲ καὶ τοὺς προπίπτοντας. καὶ δῆλοι πᾶσιν ἦσαν δυσαρεστούμενοι τοῖς ἀναχωροῦσιν οὐχ ἧττον ἢ τοῖς ἐκφανῶς ἀντιπράττουσιν. ἐξ ὧν τοὺς πολλοὺς εἰς ἐπίστασιν καὶ διαπόρησιν ἦγον ὑπὲρ τοῦ τί ποτ’ ἂν ἢ λέγοντες ἢ πράττοντες εὐστοχοῖεν τῶν παρεστώτων καιρῶν. οἱ δὲ περὶ τὸν Γάιον, συναχθείσης τῆς τῶν Ἀχαιῶν ἐκκλησίας, ἐλέγοντο μὲν βεβουλεῦσθαι κατηγορήσειν τῶν περὶ τὸν Λυκόρταν καὶ τὸν Ἄρχωνα καὶ Πολύβιον, καὶ παραδείξειν ἀλλοτρίους ὑπάρχοντας τῆς. τῶν Ῥωμαίων αἱρέσεως καὶ τὴν ἡσυχίαν ἄγοντας κατὰ τὸ παρόν, οὐ φύσει τοιούτους ὄντας, ἀλλὰ παρατηροῦντας τὰ συμβαίνοντα καὶ τοῖς καιροῖς ἐφεδρεύοντας. οὐ μὴν ἐθάρρησαν τοῦτο ποιῆσαι διὰ τὸ μηδεμίαν εὔλογον ἀφορμὴν ἔχειν κατὰ τῶν προειρημένων ἀνδρῶν. διὸ συναχθείσης αὐτοῖς τῆς βουλῆς εἰς Αἴγιον, ἀσπαστικήν τε καὶ παρακλητικὴν ποιησάμενοι τὴν πρὸς τοὺς Ἀχαιοὺς ἔντευξιν ἀπέπλευσαν εἰς τὴν Αἰτωλίαν.", "st": "28.3"}, {"sp": "N", "t": "καὶ πάλιν ἐκεῖ συναχθείσης αὐτοῖς τῆς ἐκκλησίας εἰς Θέρμον, παρελθόντες εἰς τοὺς πολλοὺς παρακλητικοὺς καὶ φιλανθρώπους διετίθεντο λόγους. τὸ δὲ συνέχον αὐτοῖς τῆς ἐκκλησίας, ὁμήρους ἔφασαν δεῖν δοθῆναι σφίσι παρὰ τῶν Αἰτωλῶν. τούτων δὲ καταβάντων, Πρόανδρος ἐπαναστὰς ἐβούλετό τινας εὐχρηστίας πρὸς αὐτοῦ γεγενημένας εἰς τοὺς Ῥωμαίους προφέρεσθαι καὶ κατηγορεῖν τῶν διαβαλλόντων αὐτόν· ἐφ’ ὃν Γάιος πάλιν ἐπαναστάς, καὶ καλῶς εἰδὼς ἀλλότριον αὐτὸν ὄντα Ῥωμαίων, ὅμως ἐπῄνεσε καὶ πᾶσι τοῖς εἰρημένοις ἀνθωμολογήσατο. μετὰ δὲ τοῦτον προελθὼν Λυκίσκος ἐπ’ ὀνόματος μὲν οὐδενὸς ἐποιήσατο κατηγορίαν, καθ’ ὑπόνοιαν δὲ πολλῶν. ἔφη γὰρ περὶ μὲν τῶν κορυφαίων καλῶς βεβουλεῦσθαι Ῥωμαίους, ἀπαγαγόντας αὐτοὺς εἰς τὴν Ῥώμην, λέγων τοὺς περὶ τὸν Εὐπόλεμον καὶ Νίκανδρον, τοὺς δὲ συναγωνιστὰς καὶ τοὺς παραστάτας τοὺς ἐκείνων ἔτι μένειν κατὰ τὴν Αἰτωλίαν, οὓς δεῖν ἅπαντας τῆς αὐτῆς τυχεῖν ἐκείνοις ἐπιστροφῆς, ἂν μὴ προῶνται τὰ τέκνα Ῥωμαίοις εἰς ὁμηρείαν. μάλιστα δὲ κατ’ Ἀρχεδάμου καὶ Πανταλέοντος ἐποίει τὰς ἐμφάσεις. τούτου δὲ παραχωρήσαντος, Πανταλέων ἀναστὰς τὸν μὲν Λυκίσκον διὰ βραχέων ἐλοιδόρησε, φήσας αὐτὸν ἀναισχύντως καὶ ἀνελευθέρως κολακεύειν τοὺς ὑπερέχοντας, ἐπὶ δὲ τὸν Θόαντα μετέβη, τοῦτον ὑπολαμβάνων εἶναι τὸν ἀξιοπίστως ἐνιέντα τὰς κατ’ αὐτῶν διαβολὰς τῷ δοκεῖν μηδεμίαν ὑπάρχειν αὐτοῖς πρὸς τοῦτον διαφοράν. καὶ τὰ μὲν ὑπομνήσας τῶν κατ’ Ἀντίοχον καιρῶν, τὰ δ’ ὀνειδίσας εἰς ἀχαριστίαν αὐτῷ, διότι δοθεὶς ἔκδοτος Ῥωμαίοις, πρεσβεύσαντος αὐτοῦ καὶ Νικάνδρου, τύχοι τῆς σωτηρίας ἀνελπίστως, ταχέως ἐξεκαλέσατο τοὺς ὄχλους εἰς τὸ μὴ μόνον θορυβεῖν τὸν Θόανθ’, ὅτε βουληθείη τι λέγειν, ἀλλὰ καὶ βάλλειν ὁμοθυμαδόν. γενομένων δὲ τούτων βραχέα καταμεμψάμενος ὁ Γάιος τοὺς Αἰτωλοὺς ἐπὶ τῷ βάλλειν τὸν Θόανθ’, οὗτος μὲν εὐθέως μετὰ τοῦ συμπρεσβευτοῦ συναπῆρεν εἰς Ἀκαρνανίαν, ἐκσιωπηθεὶς περὶ τῶν ὁμήρων· τὰ δὲ κατὰ τὴν Αἰτωλίαν ἐν ὑποψίαις ἦν πρὸς ἀλλήλους καὶ ταραχαῖς ὁλοσχερέσιν.", "st": "28.4"}, {"sp": "N", "t": "κατὰ δὲ τὴν Ἀκαρνανίαν συναχθείσης τῆς ἐκκλησίας εἰς Θύρρειον, Αἰσχρίων μὲν καὶ Γλαῦκος καὶ Χρέμας ὄντες Ῥωμαίων παρεκάλουν τοὺς περὶ τὸν Γάιον ἔμφρουρον ποιῆσαι τὴν Ἀκαρνανίαν· εἶναι γὰρ παρ’ αὐτοῖς τοὺς ἀποφέροντας τὰ πράγματα πρὸς Περσέα καὶ Μακεδόνας. Διογένης δὲ τὴν ἐναντίαν ἐποιήσατο τούτοις συμβουλίαν. οὐ γὰρ ἔφη δεῖν φρουρὰν εἰσάγειν εἰς οὐδεμίαν πόλιν· ταῦτα γὰρ ὑπάρχειν τοῖς πολεμίοις γενομένοις καὶ καταπολεμηθεῖσιν ὑπὸ Ῥωμαίων· οὐδὲν δὲ πεποιηκότας Ἀκαρνᾶνας οὐκ ἀξίους εἶναι φρουρὰν εἰσδέχεσθαι κατ’ οὐδένα τρόπον. τοὺς δὲ περὶ Χρέμαν καὶ Γλαῦκον ἰδίαν ἐθέλοντας κατασκευάζεσθαι δυναστείαν διαβάλλειν τοὺς ἀντιπολιτευομένους καὶ θέλειν ἐπισπᾶσθαι φρουρὰν τὴν συνεπισχύουσαν ταῖς αὐτῶν πλεονεξίαις. ῥηθέντων δὲ τούτων οἱ περὶ τὸν Γάιον θεωροῦντες τοὺς ὄχλους δυσαρεστουμένους ταῖς φρουραῖς καὶ βουλόμενοι στοιχεῖν τῇ τῆς συγκλήτου προθέσει, συγκαταθέμενοι τῇ τοῦ Διογένους γνώμῃ καὶ συνεπαινέσαντες ἀπῆραν ἐπὶ Λαρίσης πρὸς τὸν ἀνθύπατον. —", "st": "28.5"}, {"sp": "N", "t": "ὅτι ἔδοξε τοῖς Ἕλλησι περὶ τῆς πρεσβείας ἐπιστάσεως χρείαν ἔχειν τὸ γινόμενον. παραλαβόντες οὖν τοὺς κατὰ τὴν ἄλλην πολιτείαν ὁμογνωμονοῦντας· οὗτοι δ’ ἦσαν Ἀρκεσίλαος, Ἀρίστων Μεγαλοπολῖται, Στρατίος Τριταιεύς, Ξένων Πατρεύς, Ἀπολλωνίδας Σικυώνιος· ἐβουλεύοντο περὶ τῶν ἐνεστώτων. ὁ μὲν οὖν Λυκόρτας ἔμεινεν ἐπὶ τῆς ἐξ ἀρχῆς προθέσεως, κρίνων μήτε Περσεῖ μήτε Ῥωμαίοις συνεργεῖν μηδέν, ὁμοίως μηδ’ ἀντιπράττειν μηδετέροις. τὸ μὲν γὰρ συνεργεῖν ἀλυσιτελὲς ἐνόμιζε πᾶσιν εἶναι τοῖς Ἕλλησιν, προορώμενος τὸ μέγεθος τῆς ἐσομένης ἐξουσίας περὶ τοὺς κρατήσαντας, τὸ δ’ ἀντιπράττειν Ῥωμαίοις ἐπισφαλὲς διὰ τὸ πολλοῖς καὶ τοῖς ἐπιφανεστάτοις Ῥωμαίων ἀντωφθαλμηκέναι περὶ τῶν κοινῶν πραγμάτων κατὰ τοὺς ἀνώτερον καιρούς. ὁ δ’ Ἀπολλωνίδας καὶ Στρατίος ἀντιπράττειν μὲν ἐπίτηδες Ῥωμαίοις οὐκ ᾤοντο δεῖν· τοὺς δ’ ὑπερκυβιστῶντας καὶ διὰ τῶν κοινῶν πραγμάτων ἰδίαν χάριν ἀποτιθεμένους παρὰ Ῥωμαίοις καὶ τοῦτο πράττοντας παρὰ τοὺς νόμους καὶ παρὰ τὸ κοινῇ συμφέρον, τούτους ἔφασαν δεῖν κωλύειν καὶ πρὸς τούτους ἀντοφθαλμεῖν εὐγενῶς. ὁ δ’ Ἄρχων ἀκολουθεῖν ἔφη δεῖν τοῖς καιροῖς καὶ μὴ διδόναι τοῖς ἐχθροῖς ἀφορμὴν εἰς διαβολὴν μηδὲ προέσθαι σφᾶς αὐτοὺς εἰς τὴν αὐτὴν ἐλθεῖν διάθεσιν τοῖς περὶ Νίκανδρον, οἵτινες, πρὶν ἢ λαβεῖν πεῖραν τῆς τούτων ἐξουσίας, ἐν ταῖς μεγίσταις εἰσὶ συνταλαιπωρίαις. ταύτης δὲ τῆς γνώμης μετέσχον Πολύβιος, Ἀρκεσίλαος, Ἀρίστων, Ξένων. διὸ καὶ τὸν μὲν Ἄρχωνα πρὸς τὴν στρατηγίαν ἔδοξεν αὐτοῖς εὐθέως προπορεύεσθαι, τὸν δὲ Πολύβιον πρὸς τὴν ἱππαρχίαν.", "st": "28.6"}, {"sp": "N", "t": "τούτων δὴ νεωστὶ γεγονότων καὶ προδιειληφότων τῶν περὶ τὸν Ἄρχωνα διότι δεῖ συμπράττειν Ῥωμαίοις καὶ τοῖς τούτων φίλοις, τυχικῶς πως συνέβη τὸν Ἄτταλον πρὸς ἑτοίμους ὄντας ποιήσασθαι τοὺς λόγους. διὸ καὶ προθύμως αὐτῷ κατανεύσαντες ὑπέσχοντο συμπράξειν ὑπὲρ τῶν παρακαλουμένων. τοῦ δ’ Ἀττάλου πέμψαντος πρεσβευτάς, καὶ παραγενομένων τούτων εἰς τὴν πρώτην ἀγορὰν καὶ διαλεγομένων τοῖς Ἀχαιοῖς περὶ τοῦ τὰς τιμὰς ἀποκατασταθῆναι τῷ βασιλεῖ καὶ παρακαλούντων ποιῆσαι τοῦτο διὰ τῆς Ἀττάλου χάριτος, ὁ μὲν ὄχλος ἄδηλος ἦν ἐπὶ τίνος ὑπάρχει γνώμης, πρὸς δὲ τὴν ἀντιλογίαν ἀνίσταντο πολλοὶ καὶ διὰ πολλὰς αἰτίας. οἱ μὲν γὰρ ἐξ ἀρχῆς αἴτιοι γενόμενοι τῆς ἀναιρέσεως τῶν τιμῶν βεβαιοῦν ἐβούλοντο τὴν αὑτῶν γνώμην· οἱ δ’ ἐκ τῶν κατ’ ἰδίαν ἐγκλημάτων ὑπέλαβον καιρὸν ἔχειν ἀμύνεσθαι τὸν βασιλέα· τινὲς δὲ διὰ τὸν πρὸς τοὺς συμπράττοντας φθόνον ἐφιλοτιμοῦντο μὴ κρατῆσαι τὸν Ἄτταλον τῆς ἐπιβολῆς. ὁ δ’ Ἄρχων ἀνέστη μὲν βοηθήσων τοῖς πρεσβευταῖς· ἐκάλει γὰρ τὰ πράγματα τὴν τοῦ στρατηγοῦ γνώμην. βραχέα δ’ εἰπὼν ἀνεχώρησε, διευλαβηθεὶς μὴ δόξῃ κέρδους τινὸς ἕνεκεν συμβουλεύειν διὰ τὸ πλῆθος ἱκανὸν χρημάτων εἰς τὴν ἀρχὴν δεδαπανηκέναι. πολλῆς δ’ οὔσης ἀπορίας ὁ Πολύβιος ἀναστὰς ἐποιήσατο μὲν καὶ πλείονας λόγους, μάλιστα δὲ προσέδραμε πρὸς τὴν τῶν πολλῶν γνώμην, ὑποδείξας τὸ γεγονὸς ἐξ ἀρχῆς ψήφισμα τῶν Ἀχαιῶν ὑπὲρ τῶν τιμῶν, ἐν ᾧ γεγραμμένον ἦν ὅτι δεῖ τὰς ἀπρεπεῖς ἀρθῆναι τιμὰς καὶ τὰς παρανόμους, οὐ μὰ Δί’ ἁπάσας. τοὺς δὲ περὶ Σωσιγένη καὶ Διοπείθη, δικαστὰς [Ῥοδίους] ὑπάρχοντας κατ’ ἐκεῖνον τὸν καιρὸν καὶ διαφερομένους ἔκ τινων ἰδίων πρὸς τὸν Εὐμένη, λαβομένους ἔφη τῆς ἀφορμῆς ταύτης πάσας ἀνατετροφέναι τὰς τιμὰς τοῦ βασιλέως· καὶ τοῦτο πεποιηκέναι παρὰ τὸ τῶν Ἀχαιῶν δόγμα καὶ παρὰ τὴν δοθεῖσαν αὐτοῖς ἐξουσίαν, καὶ τὸ μέγιστον, παρὰ τὸ δίκαιον καὶ τὸ καλῶς ἔχον. οὐ γὰρ ὡς ἠδικημένους τι τοὺς Ἀχαιοὺς βουλεύσασθαι τὰς τιμὰς αἴρειν τὰς Εὐμένους, ἀλλὰ μείζους αὐτοῦ ζητοῦντος τῶν εὐεργεσιῶν, τούτῳ προσκόψαντας ψηφίσασθαι τὸ πλεονάζον παρελεῖν. διόπερ ἔφη δεῖν, καθάπερ οἱ δικασταὶ τὴν ἰδίαν ἔχθραν ἐπίπροσθεν ποιήσαντες τοῦ τῶν Ἀχαιῶν εὐσχήμονος ἀνέτρεψαν πάσας τὰς τιμάς, οὕτω τοὺς Ἀχαιοὺς κυριώτατον ἡγησαμένους τὸ σφίσι καθῆκον καὶ πρέπον διορθώσασθαι τὴν τῶν δικαστῶν ἁμαρτίαν καὶ καθόλου τὴν πρὸς τὸν Εὐμένη γεγενημένην ἀλογίαν, ἄλλως τε καὶ μέλλοντας μὴ μόνον ἐπ’ αὐτὸν τὸν βασιλέα τὴν χάριν ἀπερείδεσθαι ταύτην, ἔτι δὲ μᾶλλον εἰς τὸν ἀδελφὸν Ἄτταλον. τοῦ δὲ πλήθους εὐδοκήσαντος τοῖς λεγομένοις, ἐγράφη δόγμα προστάττον τοῖς ἄρχουσι πάσας ἀποκαταστῆσαι τὰς Εὐμένους τοῦ βασιλέως τιμάς, πλὴν εἴ τινες ἀπρεπές τι περιέχουσι τῷ κοινῷ τῶν Ἀχαιῶν ἢ παράνομον. τοῦτον μὲν δὴ τὸν τρόπον καὶ κατὰ τοῦτον τὸν καιρὸν Ἄτταλος διωρθώσατο τὴν γενομένην ἀλογίαν περὶ τὰς ὑπαρχούσας Εὐμένει τἀδελφῷ τιμὰς κατὰ τὴν Πελοπόννησον. —", "st": "28.7"}, {"sp": "N", "t": "ὅτι Περσεὺς πρὸς Γένθιον τὸν βασιλέα ἀπέστειλε πρεσβευτὰς Πλευρᾶτόν τε τὸν Ἰλλυριόν, ὄντα φυγάδα παρ’ αὐτῷ, καὶ τὸν Βεροιαῖον Ἀδαῖον, δοὺς ἐντολὰς διασαφεῖν τὰ πεπραγμένα κατὰ τὸν πόλεμον πρός τε Ῥωμαίους αὐτῷ καὶ πρὸς Δαρδανίους, ἔτι δὲ καὶ πρὸς Ἠπειρώτας καὶ πρὸς Ἰλλυριοὺς κατὰ τὸ παρόν, καὶ παρακαλεῖν αὐτὸν πρὸς τὴν τούτου καὶ Μακεδόνων φιλίαν καὶ συμμαχίαν. οἳ καὶ ποιησάμενοι τὴν πορείαν ὑπὲρ τὸ Σκάρδον ὄρος διὰ τῆς Ἐρήμου καλουμένης Ἰλλυρίδος, ἣν οὐ πολλοῖς χρόνοις ἀνώτερον ἀνάστατον ἐποίησαν Μακεδόνες εἰς τὸ δυσέργους ποιῆσαι τοῖς Δαρδανεῦσι τὰς εἰς τὴν Ἰλλυρίδα καὶ Μακεδονίαν εἰσβολάς· πλὴν οἵ γε περὶ τὸν Ἀδαῖον διὰ τούτων τῶν τόπων μετὰ πολλῆς κακοπαθείας ἦλθον εἰς Σκόδραν καὶ πυθόμενοι τὸν Γένθιον ἐν Λίσσῳ διατρίβειν διεπέμψαντο πρὸς αὐτόν. τοῦ δὲ ταχέως αὐτοὺς μεταπεμψαμένου, συμμίξαντες διελέγοντο περὶ ὧν εἶχον τὰς ἐντολάς. ὁ δὲ Γένθιος οὐκ ἐδόκει μὲν ἀλλότριος εἶναι τῆς πρὸς τὸν Περσέα φιλίας, ἐσκήπτετο δὲ τοῦ μὴ παραχρῆμα συγκατατίθεσθαι τοῖς ἀξιουμένοις τὴν ἀχορηγησίαν καὶ μὴ δύνασθαι χωρὶς χρημάτων ἀναδέξασθαι τὸν πρὸς Ῥωμαίους πόλεμον. οἱ μὲν οὖν περὶ τὸν Ἀδαῖον ταύτας λαβόντες τὰς ἀποκρίσεις ἐπανῆγον. ὁ δὲ Περσεὺς παραγενόμενος εἰς Στύβερραν τήν τε λείαν ἐλαφυροπώλησεν καὶ τὴν δύναμιν ἀνέπαυσε, προσδεχόμενος τοὺς περὶ τὸν Πλευρᾶτον. παραγενομένων δ’ αὐτῶν, ἀκούσας τὰ παρὰ τοῦ Γενθίου πάλιν ἐξ αὐτῆς ἔπεμπε τὸν Ἀδαῖον καὶ σὺν τούτῳ τὸν Γλαυκίαν, ἕνα τῶν σωματοφυλάκων, καὶ τρίτον τὸν Ἰλλυριὸν διὰ τὸ τὴν διάλεκτον εἰδέναι τὴν Ἰλλυρίδα, δοὺς ἐντολὰς τὰς αὐτάς, ὥσπερ οὐ κυρίως τοῦ Γενθίου διασεσαφηκότος τίνος προσδεῖται καὶ τίνος γενομένου δύναται συγκαταβαίνειν εἰς τὰ παρακαλούμενα. τούτων δ’ ἀφορμησάντων, ἀναζεύξας αὐτὸς μετὰ τῆς δυνάμεως ἐποιεῖτο τὴν πορείαν ἐφ’ Ὕσκανα. —", "st": "28.8"}, {"sp": "N", "t": "ὅτι κατὰ τὸν καιρὸν τοῦτον ἧκον οἱ πρὸς τὸν Γένθιον ἀποσταλέντες πρέσβεις οὔτ’ ᾠκονομηκότες πλεῖον οὐδὲν τῶν πρότερον οὔτ’ ἀναγγέλλοντες, διὰ τὸ τὸν Γένθιον μένειν ἐπὶ τῆς αὐτῆς αἱρέσεως, ὄντα μὲν ἕτοιμον τῷ Περσεῖ κοινωνεῖν τῶν αὐτῶν πραγμάτων, χρημάτων δὲ φάσκοντα χρείαν ἔχειν. ὧν ὁ Περσεὺς παρακούσας πάλιν ἔπεμπε τοὺς περὶ τὸν Ἱππίαν βεβαιωσομένους ὑπὲρ τῶν ὁμολογιῶν, τὸ συνέχον παραλιπών, φάσκων ἐξιγμένον εὐνοοῦντα ποιήσειν τὸν Γένθιον· ὥστε διαπορεῖν πότερα δεῖ λέγειν ἐπὶ τῶν τοιούτων ἀλογιστίαν ἢ δαιμονοβλάβειαν. δοκῶ μὲν ὅτι δαιμονοβλάβειαν, οἵτινες ἐφίενται μὲν τοῦ μεγάλα τολμᾶν καὶ παραβάλλονται τῇ ψυχῇ, παριᾶσιν δὲ τὸ συνέχον ἐν ταῖς ἐπιβολαῖς, βλέποντες αὐτὸ καὶ δυνάμενοι πράττειν ὅτι γάρ, εἰ Περσεὺς κατ’ ἐκεῖνον τὸν καιρὸν ἠβουλήθη προέσθαι χρήματα καὶ κοινῇ τοῖς πολιτεύμασι καὶ κατ’ ἰδίαν τοῖς βασιλεῦσι καὶ τοῖς πολιτευομένοις, οὐ λέγω μεγαλομερῶς, καθάπερ ἐξῆν αὐτῷ χορηγιῶν ἕνεκεν, ἀλλὰ μετρίως μόνον, πάντας ἂν συνέβη καὶ τοὺς Ἕλληνας καὶ τοὺς βασιλεῖς, εἰ δὲ μή γε, τοὺς πλείστους ἐξελεγχθῆναι, δοκῶ μηδένα τῶν νοῦν ἐχόντων πρός με διαμφισβητῆσαι περὶ τούτων. νῦν δὲ καλῶς ποιῶν οὐκ ἦλθε ταύτην τὴν ὁδόν, δι’ ἧς ἢ κρατήσας τῶν ὅλων ἐξουσίαν ἂν ὑπερήφανον ἔσχεν ἢ σφαλεὶς πολλοὺς ἂν ἐποίησε τῆς αὐτῆς τύχης πεῖραν αὑτῷ λαβεῖν, ἀλλὰ τὴν ἐναντίαν, δι’ ἧς ὀλίγοι τελέως ἠλογήθησαν τῶν Ἑλλήνων ὑπὸ τὸν τῆς πράξεως καιρόν. —", "st": "28.9"}, {"sp": "N", "t": "ὅτι ὁ Περσεὺς ἐπταικὼς τοῖς ὅλοις ἐπὶ τῷ εἰσελθεῖν Ῥωμαίους εἰς Μακεδονίαν τῷ Ἱππίᾳ ἐπετίμα. ἀλλά μοι δοκεῖ τὸ μὲν ἐπιτιμῆσαι τοῖς ἄλλοις εἶναι ῥᾴδιον καὶ συνιδεῖν τὰς τῶν πέλας ἁμαρτίας, τὸ δ’ αὐτὸν πράττειν τὰ δυνατὰ καὶ γνῶναι τὰ καθ’ αὑτὸν πάντων δυσχερέστατον. ὃ καὶ περὶ τὸν Περσέα συνέβη γενέσθαι. —", "st": "28.10"}, {"sp": "N", "t": "τὸ Ἡράκλειον ἥλω ἰδίαν τινὰ ἅλωσιν. ἐχούσης τῆς πόλεως ἐφ’ ἑνὸς μέρους ἐπ’ ὀλίγον τόπον ταπεινὸν τεῖχος, οἱ Ῥωμαῖοι τρεῖς σημείας προεχειρίσαντο. καὶ τῇ μὲν πρώτῃ τοὺς θυρεοὺς ὑπὲρ τῆς κεφαλῆς ποιήσαντες συνέφραξαν, ὥστε τῇ τῶν ὅπλων πυκνότητι κεραμωτῷ καταρρύτῳ γίνεσθαι παραπλήσιον. ἐφεξῆς δ’ ἕτεραι δύο — Κεραμωτόν, τακτικὴ διάταξις· ὅπερ ἐποίουν Ῥωμαῖοι ἐν παιδιᾶς μέρει.", "st": "28.11"}, {"sp": "N", "t": "ὅτι τοῦ Περσέως βουλομένου ἥξειν μετὰ δυνάμεως εἰς τὴν Θετταλίαν καὶ λήψεσθαι τὰ ὅλα κρίσιν ἐκ τῶν κατὰ λόγον, ἔδοξε τοῖς περὶ τὸν Ἄρχωνα δι’ αὐτῶν τῶν πραγμάτων ἀπολογεῖσθαι πάλιν πρὸς τὰς ὑπονοίας καὶ διαβολάς. εἰσήνεγκαν οὖν εἰς τοὺς Ἀχαιοὺς δόγμα διότι δεῖ πανδημεὶ ποιησαμένους τὴν ἔξοδον εἰς Θετταλίαν κοινωνῆσαι τῶν πραγμάτων ὁλοσχερῶς τοῖς Ῥωμαίοις. καὶ τούτου κυρωθέντος ἔδοξε τοῖς Ἀχαιοῖς τὸν Ἄρχωνα γίνεσθαι περὶ τὴν συναγωγὴν τοῦ στρατεύματος καὶ περὶ τὰς εἰς τὴν ἔξοδον παρασκευάς, πρὸς δὲ τὸν ὕπατον πρεσβευτὰς πέμπειν εἰς Θετταλίαν τοὺς τὰ δεδογμένα τοῖς Ἀχαιοῖς διασαφήσοντας καὶ πευσομένους πότε καὶ ποῦ δεῖ συμμιγνύειν αὐτῷ τὸ στρατόπεδον. καὶ κατέστησαν πρεσβευτὰς παραχρῆμα Πολύβιον καὶ ἄλλους καὶ ἐνετείλαντο τῷ Πολυβίῳ φιλοτίμως, ἐὰν ὁ στρατηγὸς εὐδοκῇ τῇ παρουσίᾳ τοῦ στρατοπέδου, τοὺς μὲν συμπρεσβευτὰς ἐξ αὐτῆς πέμπειν διασαφήσοντας, ἵνα μὴ καθυστερῶσι τῶν καιρῶν, αὐτὸν δὲ φροντίζειν ἵνα τὸ στράτευμα πᾶν ἐν ταῖς πόλεσιν ἀγορὰς ἔχῃ, δι’ ὧν ἂν πορεύηται, καὶ μηδὲν ἐλλείπῃ τῶν ἐπιτηδείων τοὺς στρατιώτας. ταύτας μὲν οὖν ἔχοντες οἱ προειρημένοι τὰς ἐντολὰς ἐξώρμησαν· κατέστησαν δὲ καὶ πρεσβευτὰς πρὸς Ἄτταλον τοὺς περὶ Τηλόκριτον, ἀποκομίζοντας τὸ δόγμα τὸ περὶ τῆς ἀποκαταστάσεως τῶν Εὐμένους τιμῶν. καὶ κατὰ τὸν αὐτὸν καιρὸν καὶ περὶ τοῦ βασιλέως Πτολεμαίου προσπεσόντος τοῖς Ἀχαιοῖς διότι γέγονεν αὐτῷ τὰ νομιζόμενα γίνεσθαι τοῖς βασιλεῦσιν, ὅταν εἰς ἡλικίαν ἔλθωσιν, ἀνακλητήρια, νομίσαντες σφίσι καθήκειν ἐπισημήνασθαι τὸ γεγονός, ἐψηφίσαντο πέμπειν πρεσβευτὰς ἀνανεωσομένους τὰ προϋπάρχοντα τῷ ἔθνει φιλάνθρωπα πρὸς τὴν βασιλείαν, καὶ παραυτίκα κατέστησαν Ἀλκίθον καὶ Πασιάδαν.", "st": "28.12"}, {"sp": "N", "t": "οἱ δὲ περὶ τὸν Πολύβιον καταλαβόντες τοὺς Ῥωμαίους ἐκ μὲν τῆς Θετταλίας κεκινηκότας, τῆς δὲ Περραιβίας στρατοπεδεύοντας Ἀζωρίου μεταξὺ καὶ Δολίχης, τὴν μὲν ἔντευξιν ὑπερέθεντο διὰ τοὺς περιεστῶτας καιρούς, τῶν δὲ κατὰ τὴν εἴσοδον τὴν εἰς Μακεδονίαν κινδύνων μετεῖχον. ἐπεὶ δὲ τοῦ στρατεύματος κατάραντος ἐπὶ τοὺς καθ’ Ἡράκλειον τόπους ἔδοξε καιρὸς εἶναι πρὸς ἔντευξιν, ἅτε τοῦ στρατηγοῦ δοκοῦντος ἠνύσθαι τὸ μέγιστον τῶν προκειμένων, τότε λαβόντες καιρὸν τὸ ψήφισμα τῷ Μαρκίῳ προσήνεγκαν καὶ διεσάφουν τὴν τῶν Ἀχαιῶν προαίρεσιν διότι βουληθεῖεν αὐτῷ πανδημεὶ τῶν αὐτῶν μετασχεῖν ἀγώνων καὶ κινδύνων. καὶ πρὸς τούτοις ὑπέδειξαν διότι πᾶν τὸ γραφὲν ἢ παραγγελθὲν τοῖς Ἀχαιοῖς ὑπὸ Ῥωμαίων κατὰ τὸν ἐνεστῶτα πόλεμον ἀναντίρρητον γέγονεν. τοῦ δὲ Μαρκίου τὴν μὲν προαίρεσιν ἀποδεχομένου τὴν Ἀχαιῶν μεγαλωστί, τῆς δὲ κακοπαθείας αὐτοὺς καὶ τῆς δαπάνης παραλύοντος διὰ τὸ μηκέτι χρείαν ἔχειν τοὺς καιροὺς τῆς τῶν συμμάχων βοηθείας, οἱ μὲν ἄλλοι πρέσβεις ἐπανῆλθον εἰς τὴν Ἀχαΐαν, ὁ δὲ Πολύβιος αὐτοῦ μείνας μετεῖχε τῶν ἐνεστώτων πραγμάτων, ἕως ὁ Μάρκιος ἀκούσας Ἄππιον τὸν Κέντωνα πεντακισχιλίους στρατιώτας αἰτεῖσθαι παρὰ τῶν Ἀχαιῶν εἰς Ἤπειρον, ἐξαπέστειλε τὸν προειρημένον, παρακαλέσας φροντίζειν ἵνα μὴ δοθῶσιν οἱ στρατιῶται μηδὲ τηλικοῦτο δαπάνημα μάταιον γένηται τοῖς Ἀχαιοῖς· πρὸς οὐδένα γὰρ λόγον αἰτεῖν τοὺς στρατιώτας τὸν Ἄππιον. πότερα δὲ τοῦτ’ ἐποίει κηδόμενος τῶν Ἀχαιῶν ἢ τὸν Ἄππιον ἀπραγεῖν βουλόμενος χαλεπὸν εἰπεῖν. πλὴν ὅ γε Πολύβιος ἀναχωρήσας εἰς τὴν Πελοπόννησον, ἤδη τῶν γραμμάτων ἐκ τῆς Ἠπείρου προσπεπτωκότων καὶ μετ’ οὐ πολὺ συναχθέντων εἰς Σικυῶνα τῶν Ἀχαιῶν, εἰς πρόβλημα παμμέγεθες ἐνέπεσε. τοῦ γὰρ διαβουλίου προτεθέντος ὑπὲρ ὧν ὁ Κέντων ᾐτεῖτο στρατιωτῶν, ἃ μὲν ὁ Μάρκιος αὐτῷ φροντίζειν κατ’ ἰδίαν ἐνετείλατο, ταῦτα φωτίζειν οὐδαμῶς ἔκρινεν· τὸ δὲ μηδεμιᾶς αἰτίας ὑπαρχούσης φανερῶς ἀντιλέγειν τῇ βοηθείᾳ τελείως ἦν ἐπισφαλές. δυσχρήστου δὲ καὶ ποικίλης οὔσης τῆς ὑποθέσεως, ἐχρήσατο βοηθήματι πρὸς τὸ παρὸν τῷ τῆς συγκλήτου δόγματι τῷ κελεύοντι μηδένα προσέχειν τοῖς ὑπὸ τῶν στρατηγῶν γραφομένοις, ἐὰν μὴ τοῦτο ποιῶσιν κατὰ τὸ δόγμα τῆς συγκλήτου. τοῦτο δ’ οὐκ ἦν προσκείμενον τοῖς γράμμασι. διὸ καὶ κατεκράτησε τοῦ τὴν ἀναφορὰν ἐπὶ τὸν ὕπατον γενέσθαι καὶ δι’ ἐκείνου παραλυθῆναι τῆς δαπάνης τὸ ἔθνος, οὔσης ὑπὲρ ἑκατὸν εἴκοσι τάλαντα μεγάλα. τοῖς γε μὴν βουλομένοις διαβάλλειν αὐτὸν πρὸς τὸν Ἄππιον ἀφορμὰς ἔδωκεν, ὅτι διακόψαι τὴν ἐπιβολὴν αὐτοῦ τὴν περὶ τῆς βοηθείας. —", "st": "28.13"}, {"sp": "N", "t": "ὅτι οἱ Κυδωνιᾶται κατὰ τὸν καιρὸν τοῦτον ἐποίησαν πρᾶγμα δεινὸν καὶ παράσπονδον ὁμολογουμένως. καίπερ γὰρ πολλῶν τοιούτων γενομένων κατὰ τὴν Κρήτην, ὅμως ἔδοξεν ὑπεραίρειν τὴν συνήθειαν τὸ τότε γενόμενον. ὑπαρχούσης γὰρ αὐτοῖς οὐ μόνον φιλίας, ἀλλὰ συμπολιτείας πρὸς Ἀπολλωνιάτας καὶ καθόλου κοινωνίας πάντων τῶν ἐν ἀνθρώποις νομιζομένων δικαίων, καὶ περὶ τούτων κειμένης ἐνόρκου συνθήκης παρὰ τὸν Δία τὸν Ἰδαῖον, παρασπονδήσαντες τοὺς Ἀπολλωνιάτας κατελάβοντο τὴν πόλιν καὶ τοὺς μὲν ἄνδρας κατέσφαξαν, τὰ δ’ ὑπάρχοντα διήρπασαν, τὰς δὲ γυναῖκας καὶ τὰ τέκνα καὶ τὴν πόλιν καὶ τὴν χώραν διανειμάμενοι κατεῖχον. —", "st": "28.14"}, {"sp": "N", "t": "ὅτι κατὰ τὴν Κρήτην δεδιότες Κυδωνιᾶται τοὺς Γορτυνίους διὰ τὸ καὶ τῷ πρότερον ἔτει παρ’ ὀλίγον κεκινδυνευκέναι τῇ πόλει τῶν περὶ Νοθοκράτην ἐπιβαλομένων αὐτὴν κατασχεῖν, ἐξέπεμψαν πρέσβεις πρὸς Εὐμένη, βοήθειαν αἰτούμενοι κατὰ τὴν συμμαχίαν. ὁ δὲ βασιλεὺς προχειρισάμενος Λέοντα καὶ στρατιώτας σὺν τούτῳ τριακοσίους ἐξαπέστειλε κατὰ σπουδήν. ὧν παραγενομένων οἱ Κυδωνιᾶται τάς τε κλεῖς τῶν πυλῶν τῷ Λέοντι παρέδωκαν καὶ καθόλου τὴν πόλιν ἐνεχείρισαν. —", "st": "28.15"}, {"sp": "N", "t": "ὅτι ἐν τῇ Ῥόδῳ τὰ τῆς ἀντιπολιτείας αἰεὶ μᾶλλον ἐπέτεινεν. προσπεσόντος γὰρ αὐτοῖς τοῦ τῆς συγκλήτου δόγματος, ἐν ᾧ διεσάφει μηκέτι προσέχειν τοῖς τῶν στρατηγῶν ἐπιτάγμασιν, ἀλλὰ τοῖς αὑτῆς δόγμασι, καὶ τῶν πολλῶν ἀποδεχομένων τὴν τῆς συγκλήτου πρόνοιαν, οἱ περὶ τὸν Φιλόφρονα καὶ Θεαίδητον ἐπιλαβόμενοι τῆς ἀφορμῆς ταύτης ἐξειργάζοντο τἀκόλουθα, φάσκοντες δεῖν ἐκπέμπειν πρεσβευτὰς πρὸς τὴν σύγκλητον καὶ τὸν Κόιντον Μάρκιον τὸν ὕπατον καὶ πρὸς Γάιον τὸν ἐπὶ τοῦ ναυτικοῦ. τότε γὰρ ἤδη γνώριμον ἦν ἅπασιν οἵτινες τῶν καθεσταμένων ἀρχόντων ἐν τῇ Ῥώμῃ παραγίνεσθαι μέλλουσιν εἰς τοὺς κατὰ τὴν Ἑλλάδα τόπους. κροτηθείσης δὲ τῆς ὑποθέσεως, καίπερ ἀντιρρήσεως γενομένης, ἀπεστάλησαν εἰς μὲν τὴν Ῥώμην ἀρχομένης θερείας Ἁγησίλοχος Ἁγησίου, Νικαγόρας, Νίκανδρος, πρὸς δὲ τὸν ὕπατον καὶ τὸν ἐπὶ τοῦ ναυτικοῦ στρατηγὸν Ἁγέπολις, ἀρίστων, Πασικράτης, ἐντολὰς ἔχοντες ἀνανεοῦσθαι τὰ φιλάνθρωπα πρὸς Ῥωμαίους καὶ πρὸς τὰς διαβολὰς ἀπολογεῖσθαι τὰς λεγομένας ὑπό τινων κατὰ τῆς πόλεως, οἱ δὲ περὶ τὸν Ἁγησίλοχον ἅμα τοῖς προειρημένοις καὶ περὶ σιτικῆς ἐξαγωγῆς ποιησόμενοι λόγους. τὰ μὲν οὖν ὑπὸ τούτων ῥηθέντα πρὸς τὴν σύγκλητον καὶ τὰς δοθείσας αὐτοῖς ἀποκρίσεις ὑπὸ τῆς συγκλήτου καὶ διότι πάντων τῶν φιλανθρώπων τυχόντες ἐπανῆλθον, ἐν τοῖς Ἰταλικοῖς εἴπομεν. περὶ δὲ τούτου τοῦ μέρους χρήσιμόν ἐστι πλεονάκις ὑπομιμνήσκειν, ὃ δὴ καὶ πειρώμεθα ποιεῖν, διότι πολλάκις ἀναγκαζόμεθα τὰς ἐντεύξεις τῶν πρεσβειῶν καὶ τοὺς χρηματισμοὺς προτέρους ἐξαγγέλλειν τῆς καταστάσεως καὶ τῆς ἐξαποστολῆς. ἐπεὶ γὰρ καθ’ ἕκαστον ἔτος τὰς καταλλήλους πράξεις γράφοντες πειρώμεθ’ ἐν ἑνὶ καιρῷ συγκεφαλαιοῦσθαι τὰς παρ’ ἑκάστοις πράξεις, δῆλον ὡς ἀναγκαῖόν ἐστιν τοῦτο συμβαίνειν περὶ τὴν γραφήν.", "st": "28.16"}, {"sp": "N", "t": "οἱ δὲ περὶ τὸν Ἁγέπολιν ἀφικόμενοι πρὸς τὸν Κόιντον, καταλαβόντες αὐτὸν ἐν Μακεδονίᾳ πρὸς Ἡράκλειον στρατοπεδεύοντα διελέγοντο περὶ ὧν εἶχον τὰς ἐντολάς. ὁ δὲ διακούσας οὐχ οἷον αὐτὸς ἔφη προσέχειν ταῖς διαβολαῖς, ἀλλὰ κἀκείνους παρεκάλει μηδενὸς ἀνέχεσθαι τῶν λέγειν τι τολμώντων κατὰ Ῥωμαίων, καὶ πολλὰ καθόλου τῶν εἰς φιλανθρωπίαν ἡκόντων ἐπεμέτρησεν. ἔγραψε δὲ ταῦτα καὶ πρὸς τὸν δῆμον τῶν Ῥοδίων. τοῦ δ’ Ἁγεπόλιδος ἐψυχαγωγημένου κατὰ τὴν ὅλην ἀπάντησιν ἰσχυρῶς, λαβὼν αὐτὸν κατ’ ἰδίαν εἰς τὰς χεῖρας ὁ Κόιντος θαυμάζειν ἔφη πῶς οὐ πειρῶνται διαλύειν οἱ Ῥόδιοι τὸν ἐνεστῶτα πόλεμον, μάλιστα τοῦ πράγματος ἐκείνοις καθήκοντος. πότερα δὲ τοῦτ’ ἐποίει τὸν Ἀντίοχον ὑποπτεύων μή ποτε κρατήσας τῆς Ἀλεξανδρείας βαρὺς ἔφεδρος αὐτοῖς γένηται, τοῦ πρὸς τὸν Περσέα πολέμου χρόνον λαμβάνοντος· ἤδη γὰρ τότε συνέβαινε συγκεχύσθαι τὸν περὶ Κοίλης Συρίας πόλεμον· ἢ θεωρῶν ὅσον οὔπω κριθησόμενα τὰ κατὰ τὸν Περσέα, τῶν Ῥωμαϊκῶν στρατοπέδων ἐν Μακεδονίᾳ παραβεβληκότων, καὶ καλὰς ἐλπίδας ἔχων ὑπὲρ τῶν ἀποβησομένων ἐβούλετο τοὺς Ῥοδίους προνύξας μεσίτας ἀποδεῖξαι, καὶ τοῦτο πράξαντας δοῦναι τοῖς Ῥωμαίοις ἀφορμὰς εὐλόγους εἰς τὸ βουλεύεσθαι περὶ αὐτῶν ὡς ἂν αὐτοῖς φαίνηται, τὸ μὲν ἀκριβὲς οὐ ῥᾴδιον εἰπεῖν, δοκῶ δὲ μᾶλλον τὸ τελευταῖον εἰρημένον, ἐξ ὧν ἐμαρτύρησε τὰ μετ’ ὀλίγον συμβάντα τοῖς Ῥοδίοις. οἵ γε μὴν περὶ τὸν Ἁγέπολιν ἐξ αὐτῆς βαδίσαντες πρὸς τὸν Γάιον καὶ πάντων τυχόντες τῶν φιλανθρώπων ὑπερβολικώτερον ἢ παρὰ τῷ Μαρκίῳ ταχέως εἰς τὴν Ῥόδον ἀνεχώρησαν. γινομένης δὲ τῆς ἀποπρεσβείας, καὶ τῆς τε διὰ τῶν λόγων φιλανθρωπίας καὶ τῆς διὰ τῶν ἀποκρίσεων εὐνοίας ἑκατέρων τῶν στρατηγῶν ἐφαμίλλου γενομένης, ὀρθοὶ καὶ μετέωροι ταῖς διανοίαις ἐγενήθησαν οἱ Ῥόδιοι πάντες, οὐ μὴν ὡσαύτως. οἱ μὲν γὰρ ὑγιαίνοντες περιχαρεῖς ἦσαν ἐπὶ τῇ φιλανθρωπίᾳ τῶν Ῥωμαίων, οἱ δὲ κινηταὶ καὶ καχέκται συνελογίζοντο παρ’ αὑτοῖς σημεῖον εἶναι τὴν ὑπερβολὴν τῆς φιλανθρωπίας τοῦ δεδιέναι τὴν περίστασιν τοὺς Ῥωμαίους καὶ μὴ χωρεῖν αὐτοῖς τὰ πράγματα κατὰ λόγον. ὅτε δὲ καὶ τὸν Ἁγέπολιν συνέβη παραφθέγξασθαι πρός τινας τῶν φίλων, ὅτι παρὰ τοῦ Μαρκίου κατ’ ἰδίαν ἐντολὰς εἴληφε μνημονεύειν πρὸς τὴν βουλὴν ὑπὲρ τοῦ διαλύειν τὸν πόλεμον, τότε δὴ τελέως οἱ περὶ τὸν Δείνωνα συνέθεσαν ἐν κακοῖς μεγάλοις εἶναι τοὺς Ῥωμαίους. ἀπέστειλαν δὲ καὶ πρεσβευτὰς εἰς τὴν Ἀλεξάνδρειαν τοὺς διαλύσοντας τὸν ἐνεστῶτα πόλεμον Ἀντιόχῳ καὶ Πτολεμαίῳ.", "st": "28.17"}, {"sp": "N", "t": "ὅτι Ἀντίοχος ὁ βασιλεὺς ἦν καὶ πρακτικὸς καὶ μεγαλεπίβολος καὶ τοῦ τῆς βασιλείας προσχήματος ἄξιος, πλὴν τῶν κατὰ τὸ Πηλούσιον στρατηγημάτων. —", "st": "28.18"}, {"sp": "N", "t": "ὅτι μετὰ τὸ παραλαβεῖν Ἀντίοχον τὰ κατὰ τὴν Αἴγυπτον ἔδοξε τοῖς περὶ τὸν Κομανὸν καὶ Κινέαν συνεδρεύσασιν μετὰ τοῦ βασιλέως κοινοβούλιον καταγράφειν ἐκ τῶν ἐπιφανεστάτων ἡγεμόνων τὸ βουλευσόμενον περὶ τῶν ἐνεστώτων. πρῶτον οὖν ἔδοξε τῷ συνεδρίῳ τοὺς ἀπὸ τῆς Ἑλλάδος παρεπιδημήσαντας πέμπειν πρεσβευτὰς ὡς τὸν Ἀντίοχον κοινολογησομένους ὑπὲρ διαλύσεως. ἦσαν δὲ τότε παρὰ μὲν τοῦ κοινοῦ τῶν Ἀχαιῶν πρεσβεῖαι διτταί, μία μὲν ὑπὲρ τῆς τῶν φιλανθρώπων ἀνανεώσεως, ἣν ἐπρέσβευον Ἀλκίθος Ξενοφῶντος Αἰγιεὺς καὶ Πασιάδας, ἄλλη δὲ περὶ τοῦ τῶν Ἀντιγονείων ἀγῶνος. ἦν δὲ καὶ παρὰ τῶν Ἀθηναίων πρεσβεία περὶ δωρεᾶς, ἧς ἡγεῖτο Δημάρατος, καὶ θεωρίαι διτταί, μία μὲν ὑπὲρ τῶν Παναθηναίων, ἧς προειστήκει Καλλίας ὁ παγκρατιαστής, ἡ δ’ ἄλλη περὶ μυστηρίων, ὑπὲρ ἧς Κλεόστρατος ἐποιεῖτο τὸν χρηματισμὸν καὶ τοὺς λόγους. ἐκ δὲ Μιλήτου παρῆσαν Εὔδημος καὶ Ἱκέσιος, ἐκ δὲ Κλαζομενῶν Ἀπολλωνίδης καὶ Ἀπολλώνιος. ἐξαπέστειλε δὲ καὶ Πτολεμαῖος ὁ βασιλεὺς Τληπόλεμον καὶ Πτολεμαῖον τὸν ῥήτορα πρεσβευτάς. οὗτοι μὲν οὖν ἔπλεον ἀνὰ τὸν ποταμὸν εἰς τὴν ἀπάντησιν. —", "st": "28.19"}, {"sp": "N", "t": "ὅτι κατὰ τὸν καιρόν, ὅτε Ἀντίοχος τὴν Αἴγυπτον παρέλαβε, συνῆψαν τῶν ἀπὸ τῆς Ἑλλάδος πρεσβευτῶν οἱ πεμφθέντες ἐπὶ τὰς διαλύσεις. ἀποδεξάμενος δὲ τοὺς ἄνδρας φιλανθρώπως τὴν μὲν πρώτην ὑποδοχὴν αὐτῶν ἐποιήσατο μεγαλομερῆ, κατὰ δὲ τὴν ἑξῆς ἔδωκεν ἔντευξιν καὶ λέγειν ἐκέλευσεν περὶ ὧν ἔχουσι τὰς ἐντολάς. πρῶτοι μὲν οὖν οἱ παρὰ τῶν Ἀχαιῶν ἐποιήσαντο λόγους, τούτοις δ’ ἑξῆς Δημάρατος ὁ παρὰ τῶν Ἀθηναίων, μετὰ δὲ τοῦτον Εὔδημος ὁ Μιλήσιος. πάντων δὲ πρὸς τὸν αὐτὸν καιρὸν καὶ τὴν αὐτὴν ὑπόθεσιν διαλεγομένων, παραπλησίους εἶναι συνέβαινε καὶ τοὺς κατὰ μέρος αὐτῶν λόγους. τὴν μὲν γὰρ αἰτίαν τῶν συμβεβηκότων πάντες ἀνέφερον ἐπὶ τοὺς περὶ τὸν Εὐλαῖον, τὴν δὲ συγγένειαν καὶ τὴν ἡλικίαν τὴν τοῦ Πτολεμαίου προφερόμενοι παρῃτοῦντο τὴν ὀργὴν τοῦ βασιλέως. Ἀντίοχος δὲ πᾶσι τούτοις ἀνθομολογησάμενος καὶ προσαυξήσας τὴν ἐκείνων ὑπόθεσιν ἤρξατο λέγειν [τὴν] ὑπὲρ τῶν ἐξ ἀρχῆς δικαίων, δι’ ὧν ἐπειρᾶτο συνιστάνειν τῶν ἐν Συρίᾳ βασιλέων ὑπάρχουσαν τὴν κτῆσιν τῶν κατὰ Κοίλην Συρίαν τόπων, ἰσχυροποιῶν μὲν τὰς ἐπικρατείας τὰς Ἀντιγόνου τοῦ πρώτου κατασχόντος τὴν ἐν Συρίᾳ βασιλείαν, προφερόμενος δὲ τὰ συγχωρήματα τὰ γενόμενα Σελεύκῳ διὰ τῶν ἀπὸ Μακεδονίας βασιλέων μετὰ τὸν Ἀντιγόνου θάνατον· ἑξῆς δὲ τούτοις ἀπερειδόμενος ἐπὶ τὴν τελευταίαν κατὰ πόλεμον Ἀντιόχου τοῦ πατρὸς ἔγκτησιν, ἐπὶ δὲ πᾶσιν ἐξαρνούμενος τὴν ὁμολογίαν, ἣν ἔφασαν οἱ κατὰ τὴν Ἀλεξάνδρειαν γενέσθαι Πτολεμαίῳ τῷ νεωστὶ μετηλλαχότι πρὸς Ἀντίοχον τὸν ἐκείνου πατέρα, διότι δεῖ λαβεῖν αὐτὸν ἐν φερνῇ Κοίλην Συρίαν, ὅτ’ ἐλάμβανε Κλεοπάτραν τὴν τοῦ νῦν βασιλεύοντος μητέρα. πρὸς ταύτην τὴν ὑπόθεσιν διαλεχθεὶς καὶ πείσας οὐ μόνον αὑτόν, ἀλλὰ καὶ τοὺς ἀπηντηκότας ὡς δίκαια λέγει, τότε μὲν διέπλευσεν εἰς τὴν Ναύκρατιν. χρησάμενος δὲ καὶ τούτοις φιλανθρώπως καὶ δοὺς ἑκάστῳ τῶν Ἑλλήνων τῶν κατοικούντων χρυσοῦν προῆγεν ἐπὶ τῆς Ἀλεξανδρείας. τοῖς δὲ πρεσβευταῖς τὴν ἀπόκρισιν ὑπέσχετο δώσειν, ὅταν οἱ περὶ τὸν Ἀριστείδην καὶ Θῆριν ἀνακάμψωσιν ὡς αὐτόν. ἐξαπεσταλκέναι γὰρ ἐκείνους ἔφη πρὸς τὸν Πτολεμαῖον, βούλεσθαι δὲ πάντων συνίστορας εἶναι καὶ μάρτυρας τοὺς ἀπὸ τῆς Ἑλλάδος πρεσβευτάς. —", "st": "28.20"}, {"sp": "N", "t": "ὅτι Εὐλαῖος ὁ εὐνοῦχος ἔπεισε Πτολεμαῖον ἀναλαβόντα τὰ χρήματα, τὴν βασιλείαν προιέμενον τοῖς ἐχθροῖς, ὑποχωρεῖν εἰς Σαμοθρᾴκην· ἐφ’ ἃ τίς οὐκ ἂν ἐπιστήσας ὁμολογήσειεν ὅτι μέγιστα κακὰ ποιοῦσιν αἱ κακαὶ συντροφίαι τοὺς ἀνθρώπους; τὸ γὰρ μηδ’, ἐκτὸς γενόμενον τῶν δεινῶν καὶ τοσοῦτον τόπον ἀποστάντα τῶν ἐχθρῶν, ὁρμῆσαι πρός τι τῶν καθηκόντων, ἄλλως τε καὶ τηλικαύτας ἀφορμὰς ἔχοντα καὶ τοιούτων τόπων κυριεύοντα καὶ τοσούτων πληθῶν, ἀλλ’ εὐθέως αὐτόθεν ἀκονιτὶ παραχωρῆσαι βασιλείας τῆς ἐπιφανεστάτης καὶ μακαριωτάτης, πῶς οὐκ ἄν τις εἶναι φήσειε ψυχῆς ἐκτεθηλυμμένης καὶ διεφθαρμένης ὁλοσχερῶς; ἣν εἰ μὲν συνέβαινε φύσει περὶ Πτολεμαῖον ὑπάρχειν, τὴν φύσιν ἔδει καταμέμψασθαι καὶ μηδενὶ τῶν ἐκτὸς αἰτίαν ἐπιφέρειν· ἐπειδὴ δὲ διὰ τῶν μετὰ ταῦτα πράξεων ἡ φύσις ὑπὲρ αὑτῆς ἀπελογήθη, δείξασα τὸν Πτολεμαῖον καὶ στάσιμον ἱκανῶς καὶ γενναῖον ἐν τοῖς κινδύνοις ὑπάρχοντα, δῆλον ὡς εἰκότως ἄν τις τῆς τότε περὶ αὐτὸν γενομένης ἀγεννίας καὶ τῆς ὁρμῆς τῆς εἰς τὴν Σαμοθρᾴκην τὴν αἰτίαν ἐπὶ τὸν σπάδωνα καὶ τὴν τούτου συντροφίαν ἀναφέροι. —", "st": "28.21"}, {"sp": "N", "t": "ὅτι Ἀντίοχος μετὰ τὸ καταλιπεῖν Ἀλεξάνδρειαν πολιορκεῖν πρεσβευτὰς εἰς τὴν Ῥώμην ἐξέπεμπεν· οὗτοι δ’ ἦσαν Μελέαγρος, Σωσιφάνης, Ἡρακλείδης· συνθεὶς ἑκατὸν καὶ πεντήκοντα τάλαντα, πεντήκοντα μὲν στέφανον Ῥωμαίοις, τὰ δὲ λοιπὰ τῶν χρημάτων εἰς δωρεάν τισιν τῶν κατὰ τὴν Ἑλλάδα πόλεων. —", "st": "28.22"}, {"sp": "N", "t": "ὅτι κατὰ τὰς αὐτὰς ἡμέρας κατέπλευσαν ἐκ Ῥόδου πρέσβεις εἰς τὴν Ἀλεξάνδρειαν ἐπὶ τὰς διαλύσεις οἱ περὶ Πράξωνα καὶ μετ’ οὐ πολὺ παρῆσαν εἰς τὴν παρεμβολὴν πρὸς Ἀντίοχον. γενομένης δὲ τῆς ἐντεύξεως, πολλοὺς διετίθεντο λόγους, τήν τε τῆς ἰδίας πατρίδος εὔνοιαν προφερόμενοι πρὸς ἀμφοτέρας τὰς βασιλείας καὶ τὴν αὐτῶν τῶν βασιλέων ἀναγκαιότητα πρὸς ἀλλήλους καὶ τὸ συμφέρον ἑκατέροις ἐκ τῆς διαλύσεως. ὁ δὲ βασιλεὺς ἔτι λέγοντα τὸν πρεσβευτὴν ἐπιτεμὼν οὐκ ἔφη προσδεῖσθαι πολλῶν λόγων. τὴν μὲν γὰρ βασιλείαν εἶναι Πτολεμαίου τοῦ πρεσβυτέρου, πρὸς δὲ τοῦτον καὶ διαλελύσθαι πάλαι καὶ φίλους ὑπάρχειν, καὶ νῦν βουλομένων τῶν ἐν τῇ πόλει κατάγειν τοῦτον μὴ κωλύειν Ἀντίοχον. καὶ δὴ πεποίηκεν.", "st": "28.23"}, {"sp": "HDR", "t": "Βιβλίον ΚΘʹ", "st": "29"}, {"sp": "N", "t": "ἔφη γὰρ αὐτοὺς μίαν ἔχειν διατριβὴν καὶ παρὰ τὰς συνουσίας καὶ παρὰ τὰς ἐν τοῖς περιπάτοις ὁμιλίας διοικεῖν αὐτοὺς ἐν Ῥώμῃ καθημένους τὸν ἐν Μακεδονίᾳ πόλεμον, ποτὲ μὲν ἐπιτιμῶντας τοῖς ὑπὸ τῶν στρατηγῶν πραττομένοις, ποτὲ δὲ τὰ παραλειπόμενα διεξιόντας· ἐξ ὧν ὄνησιν μὲν οὐδέποτε γίνεσθαι τοῖς κοινοῖς πράγμασι, βλάβην δὲ πολλάκις καὶ ἐπὶ πολλῶν γεγονέναι· καὶ ποτὲ δὲ τοὺς ἄρχοντας μεγάλα βλάπτεσθαι διὰ τὰς ἀκαίρους εὑρησιλογίας· πάσης γὰρ διαβολῆς ἐχούσης ὀξύ τι καὶ κινητικόν, ὅταν προκαταληφθῇ τὸ πλῆθος ἐκ τῆς συνεχοῦς λαλιᾶς, εὐκαταφρονήτους γίνεσθαι τοῖς ἐχθροῖς. —", "st": "29.1"}, {"sp": "N", "t": "ὅτι ἡ σύγκλητος πυνθανομένη τὸν Ἀντίοχον τῆς μὲν Αἰγύπτου κύριον γεγονέναι, τῆς δ’ Ἀλεξανδρείας παρ’ ὀλίγον, νομίζουσα πρὸς αὑτήν τι διατείνειν τὴν αὔξησιν τοῦ προειρημένου βασιλέως, κατέστησε πρεσβευτὰς τοὺς περὶ Γάιον Ποπίλιον, τόν τε πόλεμον λύσοντας καὶ καθόλου θεασομένους τὴν τῶν πραγμάτων διάθεσιν ποία τις ἐστίν. καὶ τὰ μὲν κατὰ τὴν Ἰταλίαν ἐν τούτοις ἦν.", "st": "29.2"}, {"sp": "N", "t": "ὅτι παραγενομένων πρὸ τοῦ χειμῶνος τῶν περὶ τὸν Ἱππίαν, οὓς ἀπεστάλκει πρεσβευτὰς ὁ Περσεὺς πρὸς Γένθιον ὑπὲρ τῆς συμμαχίας, καὶ διασαφούντων ὅτι πρόθυμος ὁ βασιλεύς ἐστιν ἀναδέχεσθαι τὸν πρὸς Ῥωμαίους πόλεμον, ἐὰν αὐτῷ δοθῇ τριακόσια τάλαντα καὶ πίστεις αἱ προσήκουσαι περὶ τῶν ὅλων, πυθόμενος ταῦτα καὶ κρίνων ἀναγκαίαν εἶναι τὴν Γενθίου κοινοπραγίαν προεχειρίσατο Πάνταυχον, ἕνα τῶν πρώτων φίλων, καὶ τοῦτον ἐξαπέστειλε, δοὺς ἐντολὰς πρῶτον μὲν ὁμολογήσαντα περὶ τῶν χρημάτων ὅρκους καὶ δοῦναι καὶ λαβεῖν ὑπὲρ τῆς συμμαχίας, εἶτα τοὺς ὁμήρους ἐξ αὐτῆς κἀκεῖνον πέμπειν, οὓς ἂν δοκῇ Πανταύχῳ, καὶ παρ’ αὐτοῦ λαμβάνειν οὓς ἂν ἀποφήνῃ Γένθιος διὰ τῶν ἐγγράπτων, πρὸς δὲ τούτοις διατάξασθαι περὶ τῆς κομιδῆς τῶν τριακοσίων ταλάντων. ὁ δὲ Πάνταυχος ἐξ αὐτῆς ποιησάμενος τὴν ὁρμὴν καὶ παραγενόμενος εἰς Μετέωνα τῆς Λαβεάτιδος κἀνταῦθα συμμίξας τῷ Γενθίῳ ταχέως παρεστήσατο τὸν νεανίσκον πρὸς τὸ κοινωνεῖν τῷ Περσεῖ τῶν αὐτῶν ἐλπίδων. τμηθέντων δὲ τῶν ὁρκίων ὑπὲρ τῆς συμμαχίας καὶ καταγραφέντων, εὐθέως ὁ Γένθιος ἅμα τοὺς ὁμήρους ἔπεμπε τοὺς ὑπὸ τοῦ Πανταύχου καταγραφέντας καὶ σὺν τούτοις Ὀλυμπίωνα παραληψόμενον τοὺς ὅρκους καὶ τοὺς ὁμήρους παρὰ τοῦ Περσέως, ἑτέρους δὲ τοὺς περὶ τῶν χρημάτων ἕξοντας τὴν ἐπιμέλειαν. σὺν δὲ τοῖς προειρημένοις ἔπεισεν ὁ Πάνταυχος τὸν Γένθιον καὶ πρεσβευτὰς συνεξαποστέλλειν, οἵτινες ἅμα τοῖς παρὰ τοῦ Περσέως πεμπομένοις εἰς τὴν Ῥόδον πρεσβεύσουσιν ὑπὲρ τῆς κοινῆς συμμαχίας. τούτου γὰρ γενομένου, καὶ συνεμβάντων τῶν Ῥοδίων εἰς τὸν πόλεμον, τελέως εὐκαταγωνίστους ἐσομένους ἀπέφαινε τοὺς Ῥωμαίους. ὁ δὲ πεισθεὶς τοῖς παρακαλουμένοις καὶ προχειρισάμενος Παρμενίωνα καὶ Μόρκον ἐξαπέστειλε, δοὺς ἐντολάς, ὅταν λάβωσιν τοὺς ὅρκους παρὰ τοῦ Περσέως καὶ τοὺς ὁμήρους, καὶ περὶ τῶν χρημάτων γένηται σύμφωνον, πρεσβεύειν εἰς τὴν Ῥόδον.", "st": "29.3"}, {"sp": "N", "t": "οὗτοι μὲν οὖν πάντες προῆγον εἰς τὴν Μακεδονίαν· ὁ δὲ Πάνταυχος μένων παρὰ πλευρὰν ὑπεμίμνησκεν καὶ παρώξυνε τὸν νεανίσκον πρὸς τὸ μὴ καθυστερεῖν ταῖς παρασκευαῖς, ἀλλ’ ἕτοιμον ὄντα προκαταλαμβάνειν καὶ τόπους καὶ πόλεις καὶ συμμάχους· μάλιστα δ’ αὐτὸν ἠξίου παρασκευάζεσθαι πρὸς τὴν κατὰ θάλατταν μάχην· τῶν γὰρ Ῥωμαίων εἰς τέλος ἀπαρασκεύων ὄντων πρὸς τοῦτο τὸ μέρος κατά τε τοὺς περὶ τὴν Ἤπειρον καὶ τοὺς περὶ τὴν Ἰλλυρίδα τόπους, ἀκονιτὶ πᾶν τὸ προτεθὲν ἐπιτελεσθήσεσθαι δι’ αὐτοῦ καὶ τῶν ὑπ’ αὐτοῦ πεμπομένων. ὁ μὲν οὖν Γένθιος τούτοις τοῖς λόγοις ἀναπειθόμενος ἐγίνετο περί τε τὰς κατὰ γῆν καὶ κατὰ θάλατταν παρασκευάς. ὁ δὲ Περσεύς, παραγενομένων εἰς τὴν Μακεδονίαν τῶν πρεσβευτῶν παρὰ τοῦ Γενθίου καὶ τῶν ὁμηρευόντων, ὁρμήσας ἀπὸ τῆς περὶ τὸν Ἐλπειὸν ποταμὸν παρεμβολῆς μετὰ πάντων τῶν ἱππέων ἀπήντα τοῖς προειρημένοις εἰς τὸ Δῖον, καὶ συμμίξας πρῶτον μὲν ἀπέδωκε τοὺς ὅρκους ὑπὲρ τῆς συμμαχίας ἐναντίον πάντων τῶν ἱππέων· πάνυ γὰρ ἐβούλετο σαφῶς εἰδέναι τοὺς Μακεδόνας τὴν τοῦ Γενθίου κοινοπραγίαν, ἐλπίζων εὐθαρσεστέρους αὐτοὺς ὑπάρξειν, προσγενομένης ταύτης τῆς ῥοπῆς. ἔπειτα δὲ τοὺς ὁμήρους παρελάμβανε καὶ παρεδίδου τοὺς ἑαυτοῦ τοῖς περὶ Ὀλυμπίωνα. ὧν ἦσαν ἐπιφανέστατοι Λιμναῖος ὁ Πολεμοκράτους καὶ Βάλακρος ὁ Πανταύχου. μετὰ δὲ ταῦτα τοὺς μὲν ἐπὶ τὰ χρήματα παρόντας εἰς Πέλλαν ἐξέπεμπεν, ὡς ἐκεῖ παραληψομένους, τοὺς δὲ πρεσβευτὰς τοὺς εἰς τὴν Ῥόδον εἰς Θετταλονίκην πρὸς Μητρόδωρον, συντάξας ἑτοίμους εἶναι πρὸς τὸν πλοῦν. ἔπεισε δὲ καὶ τοὺς Ῥοδίους συνεμβαίνειν εἰς τὸν πόλεμον. ταῦτα δὲ διοικήσας Ἡροφῶντα μὲν ἐξέπεμψε πρεσβευτὴν πρὸς τὸν Εὐμένη, καὶ πρότερον ἤδη διαπεσταλμένον, Τηλέμναστον δὲ τὸν Κρῆτα πρὸς τὸν Ἀντίοχον, μὴ παρορᾶν τὸν καιρὸν μηδ’ ὑπολαμβάνειν πρὸς αὐτὸν μόνον ἀνήκειν τὴν ὑπερηφανίαν καὶ τὴν βαρύτητα τῶν Ῥωμαίων, σαφῶς δὲ γινώσκειν ὡς ἐὰν μὴ καὶ νῦν αὐτὸς συνεπιλαμβάνηται, μάλιστα μὲν διαλύων τὸν πόλεμον, εἰ δὲ μή, βοηθῶν, ταχέως πεῖραν λήψεται τῆς αὐτῆς ἑαυτῷ τύχης. —", "st": "29.4"}, {"sp": "N", "t": "ὑπὲρ ὧν ἔγωγε διηπόρηκα τί δεῖ ποιεῖν· τό τε γὰρ γράφειν κατὰ μέρος ὑπὲρ τοιούτων ἀκριβολογούμενον ἃ δι’ ἀπορρήτων πρὸς αὑτοὺς οἱ βασιλεῖς ἔπραττον εὐεπίληπτον ἐφαίνετο καὶ τελέως ἐπισφαλές, τό τε παρασιωπῆσαι πάλιν ὁλοσχερῶς τὸ δοκοῦν πραγματικώτατον ἐν τῷ πολέμῳ τούτῳ γεγονέναι, καὶ δι’ οὗ πολλὰ τῶν ὕστερον ἀπορουμένων γνωρίμους ἔσχε τὰς αἰτίας, τελέως τινὸς ἀργίας ἐδόκει μοι σημεῖον εἶναι καὶ τῆς πάσης ἀτολμίας· οὐ μὴν ἀλλὰ κατηνέχθην ἐπὶ τὸ γράφειν κεφαλαιωδῶς τὸ δοκοῦν, καὶ δι’ ὧν εἰκότων καὶ σημείων ἐπὶ ταύτης ἐγενόμην τῆς γνώμης, ὑπάρχων κατὰ τοὺς αὐτοὺς καιροὺς καὶ μᾶλλον ἑτέρων ἐκπληττόμενος ἕκαστα τῶν γενομένων.", "st": "29.5"}, {"sp": "N", "t": "ὅτι μὲν οὖν Κύδας ὁ Κρὴς στρατευόμενος παρ’ Εὐμένει καὶ τιμώμενος ὡς ἔνι μάλιστα, πρῶτον μὲν πρὸς Ἀμφίπολιν παραγενόμενος Χειμάρῳ, τινὶ τῶν σὺν Περσεῖ στρατευομένων Κρητῶν, καὶ πάλιν πρὸς Δημητριάδι συνεγγίσας τῷ τείχει ἐκοινολογεῖτο τὸ μὲν πρῶτον Μενεκράτει, τὸ δὲ δεύτερον Ἀντιμάχῳ, εἴρηται· καὶ μὴν ὅτι δὶς Ἡροφῶν ἐπρέσβευσε πρὸς Εὐμένη παρὰ Περσέως, καὶ διὰ τοῦτο Ῥωμαίων οἱ πλείους ὑποψίαν ἔσχον οὐκ ἀπίθανον περὶ τοῦ βασιλέως Εὐμένους, δῆλον ἐκ τῶν περὶ Ἄτταλον συμβάντων· τῷ μὲν γὰρ συνεχώρησαν καὶ παραγενέσθαι πρὸς σφᾶς εἰς τὴν Ῥώμην ἐκ τοῦ Βρεντεσίου καὶ χρηματίσαι περὶ ὧν προῃρεῖτο, καὶ τέλος ἀποκρίσεις δόντες αὐτῷ φιλανθρώπους ἀπέστειλαν, οὐδὲν οὔτε πρότερον οὔτε κατὰ τὸν πρὸς Περσέα πόλεμον ἀξιόλογον αὐτοῖς συνηργηκότα· τὸν Εὐμένη δὲ τὰς μεγίστας χρείας σφίσι παρεσχημένον καὶ πλεῖστα συνηργηκότ’ ἔν τε τοῖς πρὸς Ἀντίοχον καὶ κατὰ τὸν πρὸς Περσέα πόλεμον οὐ μόνον τῆς εἰς τὴν Ῥώμην ἀναβάσεως ἐκώλυσαν, ἀλλὰ καὶ προσέταξαν μέσου χειμῶνος ὄντος ἐν ἡμέραις τακταῖς ἐκχωρεῖν ἐξ Ἰταλίας. ἐξ ὧν ὅτι μὲν γέγονέ τις ἐπιπλοκὴ τῷ Περσεῖ πρὸς τὸν Εὐμένη, δι’ ἣν ἐπὶ τοσοῦτον ἠλλοτριώθησαν πρὸς αὐτὸν Ῥωμαῖοι, προφανὲς ἐκ τῶν εἰρημένων· τίς δ’ αὕτη καὶ μέχρι τίνος προύβη πάρεστι σκοπεῖν.", "st": "29.6"}, {"sp": "N", "t": "ὅτι μὲν οὖν Εὐμένης οὐκ ἂν ἠβουλήθη Περσέα κρατῆσαι τῷ πολέμῳ καὶ γενέσθαι κύριον τῶν ὅλων, εὐχερὲς καταμαθεῖν· χωρὶς γὰρ τῆς πατρικῆς ἀλλοτριότητος καὶ δυσμενείας, ἣν εἶχον πρὸς ἀλλήλους, καὶ τὸ τῆς ἀρχῆς ὁμογενὲς ἱκανὸν ἦν ἀπιστίαν καὶ ζηλοτυπίαν καὶ καθόλου τὴν μεγίστην ἀλλοτριότητα παρασκευάζειν ἐν αὐτοῖς· λοιπὸν ἦν ἐξαπατᾶν καὶ στρατηγεῖν ἀλλήλους δι’ ἀπορρήτων· ὅπερ ἐποίουν ἀμφότεροι. θεωρῶν γὰρ Εὐμένης δυσπαθοῦντα καὶ συγκλειόμενον τὸν Περσέα πανταχόθεν καὶ πᾶν τὸ παραγγελλόμενον ἐπιδεχόμενον χάριν τοῦ τὸν πόλεμον διαλύσασθαι καὶ διαπεμπόμενον ὑπὲρ τούτων πρὸς τοὺς στρατηγοὺς καθ’ ἕκαστον ἔτος, τοὺς δὲ Ῥωμαίους ὡσαύτως δυσχρηστουμένους τοῖς ὅλοις διά τε τὸ μηδὲν προκόπτειν ἐν τῷ πολέμῳ μέχρι τῆς Παύλου στρατηγίας καὶ διὰ τὸ τοὺς κατὰ τὴν Αἰτωλίαν μετεώρους ὑπάρχειν, ὑπέλαβεν οὐκ ἀδύνατον εἶναι τὸ συγκαταβῆναι Ῥωμαίους εἰς ἐξαγωγὴν τοῦ πολέμου καὶ διάλυσιν· πρὸς δὲ τὸ μεσιτεῦσαι ταῦτα καὶ συναγαγεῖν ἐνόμισεν αὑτὸν ἐπιτηδειότατον εἶναι. ταῦτα δὲ συλλογισάμενος ἐφ’ ἑαυτοῦ κατεπείραζε τοῦ Περσέως διὰ Κύδα τοῦ Κρητὸς τῷ πρότερον ἔτει πόσου βούλοιτ’ ἂν ὠνήσασθαι τὴν ἐλπίδα ταύτην.", "st": "29.7"}, {"sp": "N", "t": "ἡ μὲν οὖν καταρχὴ τῆς πρὸς ἀλλήλους ἐπιπλοκῆς δοκεῖ μοι διὰ ταῦτα γεγονέναι· δυεῖν δὲ συγκρινομένων, τοῦ μὲν πανουργοτάτου δοκοῦντος εἶναι, τοῦ δὲ φιλαργυρωτάτου, γελοίαν συνέβαινε γίνεσθαι τὴν διαμάχην αὐτῶν. ὁ μὲν γὰρ Εὐμένης πᾶσαν ἐλπίδα προύτεινε καὶ πᾶν γένος δελέατος ὑπερρίπτει, πεπεισμένος θηρεύσειν τὸν Περσέα ταῖς ἐπαγγελίαις· ὁ δὲ Περσεὺς μακρόθεν ὥρμα πρὸς τὰ προτεινόμενα καὶ συνετίθετο, καταπιεῖν δὲ τῶν λεγομένων οὐδὲν οἷός τ’ ἦν ἐπὶ τοσοῦτον ὥστε καὶ προέσθαι τι τῶν αὑτοῦ. τὸ δὲ γένος τῶν παλαισμάτων ἦν τοιοῦτον. ὁ μὲν γὰρ Εὐμένης ᾔτει τοῦ μὲν ἡσυχίαν ἔχειν κατὰ τὸ τέταρτον ἔτος καὶ μὴ συστρατεῦσαι Ῥωμαίοις μήτε κατὰ γῆν μήτε κατὰ θάλατταν πεντακόσια τάλαντα, τοῦ δὲ διαλῦσαι τὸν πόλεμον χίλια πεντακόσια, καὶ τούτων ὁμήρους δώσειν κατὰ τάχος ὑπισχνεῖτο καὶ πίστεις. ὁ δὲ Περσεὺς ἐδέχετο περὶ τῶν ὁμήρων καὶ πόσα καὶ πότε πέμπεσθαι καὶ πῶς δεήσει ταῦτα τηρεῖσθαι παρὰ τοῖς Κνωσίοις· περὶ δὲ τῶν χρημάτων ὑπὲρ μὲν τῶν πεντακοσίων ταλάντων αἰσχρὸν ἔφησεν εἶναι καὶ τῷ διδόντι καὶ μᾶλλον ἔτι τῷ λαμβάνοντι τὸ δοκεῖν μισθοῦ τὴν ἡσυχίαν ἔχειν, τὰ δὲ χίλια καὶ πεντακόσια πέμψειν φέροντας ἔφη τοὺς περὶ Πολεμοκράτην εἰς Σαμοθρᾴκην κἀκεῖ μεσιτεύσειν. τῆς δὲ Σαμοθρᾴκης αὐτὸς ἦν κύριος· ὁ δ’ Εὐμένης σπουδάζων, καθάπερ οἱ μοχθηροὶ τῶν ἰατρῶν, περὶ τὸ πρόδομα μᾶλλον ἢ περὶ τὸν μισθὸν τέλος ἀπέστη τῆς ἐπιβολῆς, ἀδυνατήσας καταγωνίσασθαι τῇ σφετέρᾳ πανουργίᾳ τὴν τοῦ Περσέως μικρολογίαν. καὶ δὴ τῷ τοιούτῳ τρόπῳ ποιήσαντες ἱερὸν τὸν στέφανον τῆς φιλαργυρίας διελύθησαν ἐπ’ ἴσης, καθάπερ ἀγαθοὶ παλαισταί. τούτων δ’ ἔνια μὲν ἐξερρύη παρ’ αὐτὸν τὸν καιρόν, ἔνια δὲ μετ’ ὀλίγον εἰς τοὺς παρακειμένους τῷ Περσεῖ φίλους, παρ’ ὧν ἡμῖν ἐξεποίησε πυθέσθαι διότι πάσης κακίας ὡσανεὶ πατταλεῖόν ἐστιν ἡ φιλαργυρία.", "st": "29.8"}, {"sp": "N", "t": "προστίθημι δ’ ἔτι παρ’ ἐμαυτοῦ τοσοῦτον, μὴ καὶ μωροποιεῖσθαι συμβαίνει τὴν φιλαργυρίαν. τίς γὰρ οὐκ ἂν ἐπισημήναιτο τὴν ἄγνοιαν ἀμφοτέρων τῶν βασιλέων, Εὐμένους μέν, κατὰ τίνα λόγον ἤλπισε τηλικαύτης ἀλλοτριότητος ὑπαρχούσης πιστευθήσεσθαι καὶ προσλήψεσθαι τοσοῦτο πλῆθος χρημάτων, μηδεμίαν δυνάμενος ἱκανὴν πίστιν παρασχέσθαι τῷ Περσεῖ τῆς κομιδῆς τούτων, ἐὰν μὴ βεβαιοῖ τὰς ὑποσχέσεις; πῶς δὲ λαβὼν τοσοῦτο πλῆθος χρημάτων ὑπέλαβε λήσειν Ῥωμαίους; εἰ γὰρ καὶ κατὰ τὸ παρόν, οὐκ ἂν ἔν γε τῷ μετὰ ταῦτα χρόνῳ διέλαθε. λοιπὸν ἔδει πάντως ἀντὶ τῶν διδομένων χρημάτων ἀλλάξασθαι τὴν πρὸς Ῥωμαίους διαφοράν, δι’ ἣν ἔμελλε καὶ τῶν ληφθέντων χρημάτων ἅμα καὶ τῆς ἀρχῆς, σχεδὸν δὲ καὶ τοῦ βίου στερήσεσθαι, πολέμιος φανεὶς Ῥωμαίοις. εἰ γὰρ καὶ νῦν μηδὲν πράξας, ἐπινοήσας δὲ μόνον εἰς τοὺς μεγίστους ἦλθε κινδύνους, τί ποτε παθεῖν αὐτῷ προσῆκεν ἐπὶ τέλος ἀχθείσης τῆς προειρημένης πράξεως; τοῦ δὲ Περσέως πάλιν τίς οὐκ ἂν θαυμάσειε πῶς ἄλλο τι συμφορώτερον ἢ προυργιαίτερον ἐνόμισε τοῦ δοῦναι τὰ χρήματα καὶ καταπιεῖν ἐᾶσαι τὸν Εὐμένη τὸ δέλεαρ; εἰ μὲν γὰρ συνήργησέ τι τῶν κατὰ τὰς ἐπαγγελίας καὶ διέλυσε τὸν πόλεμον, εἰς καλὸν ἡ δόσις. εἰ δὲ ταύτης διεψεύσθη τῆς ἐλπίδος, εἴς γε τὴν πρὸς Ῥωμαίους ἔχθραν ὁμολογουμένως ἂν αὐτὸν ἐμβεβλήκει· τοῦ γὰρ εἰς τὸ μέσον ἐνεγκεῖν ταῦτα κύριος ὑπῆρχεν αὐτός. πόσου δὲ τοῦτ’ ἄξιον Περσεῖ καὶ κατορθοῦντι τῷ πολέμῳ καὶ πταίοντι, ῥᾴδιον συλλογίσασθαι· πάντων γὰρ τῶν συμβάντων κακῶν αἴτιον ἐνόμιζεν Εὐμένη γεγονέναι, ὃν οὐκ ἂν ἠδυνήθη κατ’ οὐδένα τρόπον ἀμύνασθαι βέλτιον ἢ πολέμιον ποιήσας Ῥωμαίοις. τίς οὖν αἰτία τῆς οὕτως ἐκφανοῦς ἀλογιστίας; φιλαργυρία· τί γὰρ ἂν ἄλλο τις εἴπειεν; ὁ μὲν γὰρ χάριν τοῦ λαβεῖν τὰ μὴ καθήκοντα πάντα παρεώρα τἄλλα καὶ πάντ’ ἀνεδέχετο ποιήσειν, ὁ δὲ τοῦ μὴ δοῦναι πάντα παθεῖν καὶ πᾶν ὑπεριδεῖν ὑπέμενεν. ἀκολούθως δὲ τούτοις Περσεὺς καὶ τὰ πρὸς Γαλάτας καὶ τὰ πρὸς Γένθιον —", "st": "29.9"}, {"sp": "N", "t": "ὅτι προτεθείσης χειροτονίας τοῖς Ῥοδίοις, ἐνίκων οἷς ἤρεσκε πέμπειν τοὺς πρεσβευτὰς ὑπὲρ τῶν διαλύσεων. καὶ τὴν μὲν Ῥοδίων ἀντιπολιτείαν τοῦτον τὸν τρόπον [ὡς ἐν τῷ περὶ δημηγορίας τέθειται] διέκρινε τὸ διαβούλιον, ἐν ᾧ πλεῖον ἐφάνησαν ἰσχύοντες οἱ τὰ τοῦ Περσέως αἱρούμενοι τῶν σῴζειν σπουδαζόντων τὴν πατρίδα καὶ τοὺς νόμους. οἱ δὲ πρυτάνεις παραχρῆμα πρεσβευτὰς κατέστησαν τοὺς διαλύσοντας τὸν πόλεμον, εἰς μὲν τὴν Ῥώμην Ἁγέπολιν, Διοκλῆ, Κλινόμβροτον, πρὸς δὲ τὸν στρατηγὸν καὶ Περσέα Δάμωνα, Νικόστρατον, Ἁγησίλοχον, Τήλεφον. τούτῳ δ’ ἑξῆς τὸ συνεχὲς ἐξειργάζοντο καὶ προσετίθεσαν, ποιοῦντες ἀναπολόγητον τὴν ἁμαρτίαν· εὐθέως γὰρ εἰς τὴν Κρήτην ἔπεμπον πρεσβευτὰς τοὺς ἀνανεωσομένους πρὸς πάντας Κρηταιεῖς τὰ ὑπάρχοντα φιλάνθρωπα καὶ παρακαλέσοντας βλέπειν τοὺς καιροὺς καὶ τὴν περίστασιν καὶ συμφρονεῖν τῷ δήμῳ καὶ τὸν αὐτὸν ἐχθρὸν αἱρεῖσθαι καὶ φίλον, ὁμοίως δὲ καὶ κατ’ ἰδίαν πρὸς τὰς πόλεις ὑπὲρ τῶν αὐτῶν διαλεχθησομένους. —", "st": "29.10"}, {"sp": "N", "t": "ὅτι τῶν περὶ τὸν Παρμενίωνα καὶ Μόρκον, τῶν παρὰ τοῦ Γενθίου, καὶ σὺν τούτοις τοῦ Μητροδώρου παραγενομένων εἰς τὴν Ῥόδον, καὶ συναχθείσης τῆς βουλῆς, παντάπασιν θορυβώδης ἦν ἐκκλησία, τῶν μὲν περὶ τὸν Δείνωνα καὶ Πολυάρατον φανερῶς ἤδη τολμώντων λέγειν τὰ τοῦ Περσέως, τῶν δὲ περὶ Θεαίδητον καταπεπληγμένων τὰ συμβαίνοντα· καὶ γὰρ ἡ τῶν λέμβων παρουσία καὶ τὸ πλῆθος τῶν ἀπολωλότων ἱππέων καὶ ἡ τοῦ Γενθίου μετάθεσις συνέτριβεν αὐτούς. διὸ καὶ τὸ πέρας τῆς ἐκκλησίας ἀκόλουθον ἐγενήθη τοῖς προειρημένοις· ἔδοξε γὰρ τοῖς Ῥοδίοις ἀποκριθῆναι φιλανθρώπως ἀμφοτέροις τοῖς βασιλεῦσι καὶ διασαφεῖν ὅτι δέδοκται διαλύειν αὐτοῖς τὸν πόλεμον καὶ παρακαλεῖν κἀκείνους εὐδιαλύτους ὑπάρχειν. ἐδέξαντο δὲ καὶ τοὺς πρεσβευτὰς ἐπὶ τὴν κοινὴν ἑστίαν τοὺς παρὰ τοῦ Γενθίου μετὰ πολλῆς φιλανθρωπίας. —", "st": "29.11"}, {"sp": "N", "t": "πάλιν ἕτεροι περὶ τοῦ Συριακοῦ πολέμου· τούτου δ’ αἴτιόν ἐστιν ὅπερ ἡμῖν εἴρηται διὰ πλειόνων. ὅταν γὰρ ἁπλᾶς καὶ μονοειδεῖς λαβόντες ὑποθέσεις βούλωνται μὴ τοῖς πράγμασιν, ἀλλὰ τῷ πλήθει τῶν βύβλων ἱστοριογράφοι νομίζεσθαι καὶ τὴν τοιαύτην ἐφέλκεσθαι φαντασίαν, ἀναγκαῖόν ἐστι τὰ μὲν μικρὰ μεγάλα ποιεῖν, τὰ δὲ βραχέως εἰρημένα διασκευάζειν καὶ λογοποιεῖν, ἔνια δὲ τῶν ἐν παρέργῳ πεπραγμένων ἔργα καὶ πράγματα κατασκευάζειν, ἀγῶνας διατιθεμένους καὶ παρατάξεις ἐξαγγέλλοντας, ἐν αἷς ἐνίοτε πεζοὶ μὲν ἔπεσον δέκα, ποτὲ δὲ μικρῷ πλείους, ἱππεῖς δ’ ἔτι τούτων ἐλάττους. πολιορκίας μὲν γὰρ καὶ τοπογραφίας καὶ τὰ παραπλήσια τούτοις οὐκ ἂν εἴποι τις ἀξίως ἐφ’ ὅσον ἐξεργάζονται διὰ τὴν ἀπορίαν τῶν πραγμάτων. περὶ δὲ τοὺς τὰ καθόλου γράφοντας ἐναντίος ἐστὶν ὁ τρόπος· διόπερ οὐ χρὴ καταγινώσκειν ὡς ἡμῶν ἐπισυρόντων τὰς πράξεις, ὅταν τὰ παρ’ ἐνίοις πολλοῦ τετευχότα λόγου καὶ διασκευῆς ἡμεῖς ποτὲ μὲν παραλείπωμεν, ποτὲ δὲ βραχέως ἐξαγγέλλωμεν, ἀλλὰ πιστεύειν ὅτι τὸν καθήκοντα λόγον ἑκάστοις ἀποδίδομεν. ἐκεῖνοι μὲν γὰρ ὅταν ἐν τῇ συμπάσῃ πραγματείᾳ λόγου χάριν Φανοτείας καὶ Κορωνείας καὶ … ε … οῦ πολιορκίαν γράφωσιν, ἀναγκάζονται πάσας τὰς τῆς πολιορκίας ἐπινοίας καὶ τόλμας καὶ διαθέσεις ἐκτίθεσθαι, πρὸς δὲ τούτοις Τάραντος κατάληψιν, Κορίνθου [πολιορκίαν], Σάρδεων, Γάζης, Βάκτρων, ἐπὶ πᾶσι Καρχηδόνος πολιορκίαν διατρίβειν καὶ προστιθέναι παρ’ αὑτῶν, ἀλλ’ οὐ παντάπασιν εὐδοκεῖν ἐὰν ψιλῶς περὶ τῶν τοιούτων αὐτὸν τὸν ἀληθῆ καὶ κύριον ἀποδιδῶμεν λόγον. ἡ δ’ αὐτὴ καὶ περὶ παρατάξεων ἡμῖν ἔστω καὶ δημηγοριῶν ἀπόφασις, παραπλησίως δὲ καὶ τῶν ἄλλων μερῶν τῆς ἱστορίας· ἐν οἷς ἅπασι πολλῆς ἂν δικαίως τυγχάνοιμεν συγγνώμης, ὁμοίως δὲ καὶ περὶ τῶν λέγεσθαι μελλόντων,. οιον ει τ … φανείημεν ἢ λήμμασι χρώμενοι τοῖς αὐτοῖς ἢ χειρισμῷ πραγμάτων ἢ τοῖς τῆς λέξεως ῥήμασι· πρὸς δὲ τούτοις ἐάν που παραπίπτωμεν ἐν ὀνομασίαις ὀρῶν ἢ ποταμῶν ἢ τόπων ἰδιότησι· τὸ γὰρ μέγεθος τῆς πραγματείας ἱκανόν ἐστιν ἡμᾶς ἐν ἅπασι τούτοις παραιτεῖσθαι· πλὴν ἐάν που κατὰ πρόθεσιν ἢ κέρδους τινὸς ἕνεκεν εὑρισκώμεθα ψευδογραφοῦντες· τοῦτο γὰρ οὐ παραιτούμεθα, καθάπερ ἤδη καὶ πλεονάκις ἐν τῇ πραγματείᾳ περὶ τούτου τοῦ μέρους διεστάλμεθα. —", "st": "29.12"}, {"sp": "N", "t": "ἐν δὲ τῇ ἐνάτῃ καὶ εἰκοστῇ ὁ αὐτὸς Γένθιόν φησι τὸν τῶν Ἰλλυριῶν βασιλέα διὰ τὴν πολυποσίαν πολλὰ ποιεῖν ἀσελγῆ κατὰ τὸν βίον, νύκτωρ τε αἰεὶ καὶ μεθ’ ἡμέραν μεθύοντα· ἀποκτείναντα δὲ καὶ Πλάτορα τὸν ἀδελφόν, γαμεῖν μέλλοντα τὴν Μονουνίου θυγατέρα, αὐτὸν γῆμαι τὴν παῖδα καὶ ὠμῶς χρῆσθαι τοῖς ἀρχομένοις. —", "st": "29.13"}, {"sp": "N", "t": "πρῶτος δὲ τῶν παρόντων ὁ Νασικᾶς ἐπικαλούμενος Σκιπίων, γαμβρὸς Ἀφρικανοῦ Σκιπίωνος, ὕστερον δὲ μέγιστον ἐν τῇ συγκλήτῳ δυνηθείς, ὑπεδέξατο τῆς κυκλώσεως ἡγεμὼν γενέσθαι. δεύτερος δὲ Φάβιος Μάξιμος ὁ πρεσβύτατος τῶν Αἰμιλίου παίδων, ἔτι μειράκιον ὤν, ἀνέστη προθυμούμενος. ἡσθεὶς οὖν ὁ Αἰμίλιος δίδωσιν αὐτοῖς οὐχ ὅσους Πολύβιος εἴρηκεν, ἀλλ’ ὅσους αὐτὸς ὁ Νασικᾶς λαβεῖν φησι, γεγραφὼς περὶ τῶν πράξεων τούτων ἐπιστόλιον πρός τινα τῶν βασιλέων.", "st": "29.14"}, {"sp": "N", "t": "τῇ δυνάμει τῆς πάρμης καὶ τῶν Λιγυστικῶν θυρεῶν ἀντεῖχον ἐρρωμένως οἱ Ῥωμαῖοι. —", "st": "29.15"}, {"sp": "N", "t": "τῷ δὲ Περσεῖ τὸν Αἰμίλιον ἀτρεμοῦντα κατὰ χώραν ὁρῶντι καὶ μὴ λογιζομένῳ τὸ γινόμενον, ἀποδρὰς ἐκ τῆς ὁδοῦ Κρὴς αὐτόμολος ἧκε μηνύων τὴν περίοδον τῶν Ῥωμαίων. ὁ δὲ συνταραχθεὶς τὸ μὲν στρατόπεδον οὐκ ἐκίνησε, μυρίους δὲ μισθοφόρους ξένους καὶ δισχιλίους Μακεδόνας Μίλωνι παραδοὺς ἐξαπέστειλε, παρακελευσάμενος ταχῦναι καὶ καταλαβεῖν τὰς ὑπερβολάς. τούτοις ὁ μὲν Πολύβιος φησιν ἔτι κοιμωμένοις ἐπιπεσεῖν τοὺς Ῥωμαίους, ὁ δὲ Νασικᾶς ὀξὺν ἀγῶνα περὶ τοῖς ἄκροις γενέσθαι καὶ κίνδυνον. —", "st": "29.15"}, {"sp": "N", "t": "Πολύβιος· ὅτι τῆς σελήνης ἐκλειπούσης ἐπὶ Περσέως τοῦ Μακεδόνος ἐκράτησεν ἡ φήμη παρὰ τοῖς πολλοῖς ὅτι βασιλέως ἔκλειψιν σημαίνει. καὶ τοῦτο τοὺς μὲν Ῥωμαίους εὐθαρσεστέρους ἐποίησε, τοὺς δὲ Μακεδόνας ἐταπείνωσε ταῖς ψυχαῖς. οὕτως ἀληθές ἐστι τὸ περιφερόμενον ὅτι πολλὰ κενὰ τοῦ πολέμου. —", "st": "29.16"}, {"sp": "N", "t": "Λεύκιος δὲ ὁ ὕπατος οὐχ ἑωρακὼς φάλαγγα τὸ παράπαν ἀλλὰ τότε πρῶτον ἐπὶ τοῦ Περσέως πρός τινας πολλάκις ἀνθωμολογεῖτο τῶν ἐν τῇ Ῥώμῃ μετὰ ταῦτα μηδὲν ἑωρακέναι φοβερώτερον καὶ δεινότερον φάλαγγος Μακεδονικῆς, καίτοι γε πολλοὺς οὐ μόνον θεασάμενος ἀλλὰ καὶ χειρισάμενος ἀγῶνας, εἰ καί τις ἄλλος. — ὅτι πολλὰ τῶν ἐπινοημάτων κατὰ μὲν τὸν λόγον φαίνεται πιθανὰ καὶ δυνατά, παραγενόμενα δ’ εἰς τὴν χρείαν, καθάπερ τὰ κίβδηλα τῶν νομισμάτων εἰς τὸ πῦρ, οὐκέτι ποιεῖ τἀκόλουθον ταῖς πρώταις ἐπινοίαις. — Πολύβιος· ὁ δὲ Περσεὺς μίαν ἔχων πρόληψιν ἢ νικᾶν ἢ θνήσκειν, τότε οὐχ ὑπέμεινε τῇ ψυχῇ ἀλλ’ ἀπεδειλία, καθάπερ οἱ προόπται τῶν ἱππέων. — Πολύβιος· ὁ δὲ Περσεὺς προσαγόμενος τὸν χρόνον καὶ τὸν πόνον ἐξελύετο τῇ ψυχῇ, καθάπερ οἱ καχεκτοῦντες τῶν ἀθλητῶν· ὅτε γὰρ τὸ δεινὸν ἐγγίζοι καὶ δέοι κρίνεσθαι περὶ τῶν ὅλων, οὐχ ὑπέμεινε τῇ ψυχῇ. —", "st": "29.17"}, {"sp": "N", "t": "ὁ δὲ τῶν Μακεδόνων βασιλεύς, ὥς φησι Πολύβιος, τῆς μάχης ἀρχὴν λαμβανούσης ἀποδειλιάσας εἰς πόλιν ἀφιππάσατο, σκηψάμενος Ἡρακλεῖ θύειν, δειλὰ παρὰ δειλῶν ἱερὰ μὴ δεχομένῳ μηδ’ εὐχὰς ἀθεμίτους ἐπιτελοῦντι. —", "st": "29.17"}, {"sp": "N", "t": "ὅτι κατὰ τὸν καιρόν, ἐν ᾧ Περσεὺς ἡττηθεὶς ἀνεδίδρασκεν, ἔδοξε τῇ συγκλήτῳ τοὺς παρὰ τῶν Ῥοδίων πρεσβευτὰς παραγεγονότας ὑπὲρ τοῦ διαλύειν τὸν πρὸς Περσέα πόλεμον προσκαλέσασθαι, τῆς τύχης ὥσπερ ἐπίτηδες ἀναβιβαζούσης ἐπὶ σκηνὴν τὴν τῶν Ῥοδίων ἄγνοιαν, εἰ χρὴ Ῥοδίων λέγειν, ἀλλὰ μὴ τῶν ἐπιπολασάντων ἀνθρώπων τότε κατὰ τὴν Ῥόδον. οἱ δὲ περὶ τὸν Ἁγέπολιν εἰσπορευθέντες ἐλθεῖν μὲν ἔφασαν διαλύσοντες τὸν πόλεμον· τὸν γὰρ δῆμον τῶν Ῥοδίων, ἑλκομένου τοῦ πολέμου καὶ πλείω χρόνον, θεωροῦντα διότι πᾶσιν μὲν τοῖς Ἕλλησιν ἀλυσιτελὴς καὶ αὐτοῖς δὲ Ῥωμαίοις διὰ τὸ μέγεθος τῶν δαπανημάτων, ἐλθεῖν ἐπὶ ταύτην τὴν γνώμην· νῦν δὲ λελυμένου τοῦ πολέμου κατὰ τὴν τῶν Ῥοδίων βούλησιν συγχαίρειν αὐτοῖς. ταῦτα μὲν οὖν οἱ περὶ τὸν Ἁγέπολιν εἰπόντες βραχέως ἐπανῆλθον. ἡ δὲ σύγκλητος χρωμένη τῷ καιρῷ καὶ βουλομένη παραδειγματίσαι τοὺς Ῥοδίους ἀπόκρισιν ἐξέβαλεν, ἧς ἦν τὰ συνέχοντα ταῦτα, διότι τὴν πρεσβείαν ταύτην οὔτε τῶν Ἑλλήνων ἕνεκεν ὑπολαμβάνουσιν ἐσταλκέναι τοὺς Ῥοδίους οὔθ’ ἑαυτῶν, ἀλλὰ Περσέως. εἰ μὲν γὰρ τῶν Ἑλλήνων χάριν ἐπρέσβευον, ἐκεῖνον οἰκειότερον εἶναι τὸν καιρόν, ὅτε Περσεὺς τὴν τῶν Ἑλλήνων χώραν ἐπόρθει καὶ τὰς πόλεις, στρατοπεδεύων μὲν ἐν Θετταλίᾳ σχεδὸν ἐπὶ δύ’ ἐνιαυτοὺς τὸ δὲ παρέντας ἐκεῖνον τὸν καιρὸν νῦν παρεῖναι σπουδάζοντας διαλύειν τὸν πόλεμον, ὅτε παρεμβεβληκότων τῶν ἡμετέρων στρατοπέδων εἰς Μακεδονίαν συγκεκλεισμένος ὁ Περσεὺς ὀλίγας παντάπασιν ἐλπίδας εἶχε τῆς σωτηρίας, προφανὲς εἶναι τοῖς ὀρθῶς σκοπουμένοις διότι τὰς πρεσβείας ἐξέπεμψαν οὐ διαλύειν ἐθέλοντες τὸν πόλεμον, ἀλλ’ ἐξελέσθαι τὸν Περσέα καὶ σῶσαι, καθ’ ὅσον εἰσὶν δυνατοί. δι’ ἃς αἰτίας οὔτ’ εὐεργετεῖν οὔτε φιλανθρώπως αὐτοῖς ἀποκρίνεσθαι κατὰ τὸ παρὸν ὀφείλειν ἔφασαν. ταῦτα μὲν ἡ σύγκλητος ἐχρημάτισε τοῖς παρὰ τῶν Ῥοδίων πρεσβευταῖς. —", "st": "29.19"}, {"sp": "N", "t": "ὁ δὲ μεταλαβὼν τὴν Ῥωμαϊκὴν διάλεκτον παρεκάλει τοὺς ἐν τῷ συνεδρίῳ βλέποντας εἰς τὰ παρόντα, δεικνὺς ὑπὸ τὴν ὄψιν τὸν Περσέα, μήτε μεγαλαυχεῖν ἐπὶ τοῖς κατορθώμασι παρὰ τὸ δέον μήτε βουλεύεσθαι μηδὲν ὑπερήφανον μηδ’ ἀνήκεστον περὶ μηδενός, μήτε καθόλου πιστεύειν μηδέποτε ταῖς παρούσαις εὐτυχίαις· ἀλλ’ ὅτε μάλιστά τις κατορθοίη κατὰ τὸν ἴδιον βίον καὶ κατὰ τὰς κοινὰς πράξεις, τότε μάλιστα παρεκάλει τῆς ἐναντίας τύχης ἔννοιαν λαμβάνειν. καὶ γὰρ οὕτω μόλις ἂν ἐν ταῖς εὐκαιρίαις ἄνθρωπον μέτριον ὄντα φανῆναι. τοῦτο γὰρ διαφέρειν ἔφη τοὺς ἀνοήτους τῶν νοῦν ἐχόντων, διότι συμβαίνει τοὺς μὲν ἐν ταῖς ἰδίαις ἀτυχίαις παιδεύεσθαι, τοὺς δ’ ἐν ταῖς τῶν πέλας. —", "st": "29.20"}, {"sp": "N", "t": "ὥστε πολλάκις καὶ λίαν μνημονεύειν τῆς Δημητρίου τοῦ Φαληρέως φωνῆς. ἐκεῖνος γὰρ ἐν τῷ περὶ τῆς τύχης ὑπομνήματι βουλόμενος ἐναργῶς ὑποδεικνύναι τοῖς ἀνθρώποις τὸ ταύτης εὐμετάβολον, ἐπιστὰς ἐπὶ τοὺς κατ’ Ἀλέξανδρον καιρούς, ὅτε κατέλυσε τὴν Περσῶν ἀρχήν, λέγει ταῦτα· \" εἰ γὰρ λάβοιτ’ ἐν νῷ μὴ χρόνον ἄπειρον μηδὲ γενεὰς πολλάς, ἀλλὰ πεντήκοντα μόνον ἔτη ταυτὶ τὰ πρὸ ἡμῶν, γνοίητ’ ἂν ὡς τὸ τῆς τύχης χαλεπὸν ἐνταῦθα. πεντηκοστῷ γὰρ ἔτει πρότερον οἴεσθ’ ἂν ἢ Πέρσας ἢ βασιλέα τῶν Περσῶν ἢ Μακεδόνας ἢ βασιλέα τῶν Μακεδόνων, εἴ τις θεῶν αὐτοῖς προύλεγε τὸ μέλλον, πιστεῦσαί ποτ’ ἂν ὡς εἰς τοῦτον τὸν καιρὸν Περσῶν μὲν οὐδ’ ὄνομα λειφθήσεται τὸ παράπαν, οἳ πάσης σχεδὸν τῆς οἰκουμένης ἐδέσποζον, Μακεδόνες δὲ καὶ πάσης κρατήσουσιν, ὧν οὐδ’ ὄνομα πρότερον ἦν γνώριμον. ἀλλ’ ὅμως ἡ πρὸς τὸν βίον ἡμῶν ἀσύνθετος τύχη καὶ πάντα παρὰ τὸν λογισμὸν τὸν ἡμέτερον καινοποιοῦσα καὶ τὴν αὑτῆς δύναμιν ἐν τοῖς παραδόξοις ἐνδεικυμένη καὶ νῦν, ὡς ἐμοὶ δοκεῖ, δείκνυσι πᾶσιν ἀνθρώποις, Μακεδόνας εἰς τὴν Περσῶν εὐδαιμονίαν εἰσοικίσασα, διότι καὶ τούτοις ταῦτα τἀγαθὰ κέχρηκεν, ἕως ἂν ἄλλο τι βουλεύσηται περὶ αὐτῶν. \" ὃ νῦν γέγονε κατὰ Περσέα. ταῦτα μὲν οὖν Δημήτριος ὡσανεὶ θείῳ τινὶ στόματι περὶ τοῦ μέλλοντος ἀποπεφοίβακεν. ἐγὼ δὲ κατὰ τὴν γραφὴν ἐπιστὰς τοῖς καιροῖς καθ’ οὓς συνέβη καταλυθῆναι τὴν Μακεδόνων βασιλείαν, οὐκ ἔκρινον ἀνεπιστάτως παραδραμεῖν, ἅτε γεγονὼς αὐτόπτης τῆς πράξεως, ἀλλ’ αὐτός τε τὸν πρέποντα λόγον ἐπιφθέγξασθαι καὶ Δημητρίου μνησθῆναι· δοκεῖ γάρ μοι θειοτέραν ἢ κατ’ ἄνθρωπον τὴν ἀπόφασιν ποιήσασθαι σχεδὸν γὰρ ἑκατὸν καὶ πεντήκοντα πρότερον ἔτεσι τἀληθὲς ἀπεφήνατο περὶ τῶν ἔπειτα συμβησομένων.", "st": "29.21"}, {"sp": "N", "t": "ὅτι Εὐμένης ὁ βασιλεὺς τῆς Περσέως καὶ Ῥωμαίων μάχης συντετελεσμένης εἰς παράλογον ἐνέπεσε διάθεσιν, ὡς οἱ πολλοί φασιν, ὡς δὲ τἀνθρώπινα πράγματα φύσιν ἔχει γίνεσθαι κατὰ τὸ πλεῖστον, εἴς τι τῶν εἰωθότων συμβαίνειν· ἱκανὴ γὰρ ἡ τύχη τοῖς παρὰ λόγον τὰ κατὰ λόγον ἐπιτρῖψαι, κἄν τινι συνεργήσῃ καὶ προσθῆται τὴν αὑτῆς ῥοπήν, αὖθις οἷον ἐκ μεταμελείας ἀντισηκοῦν καὶ λυμαίνεσθαι τὰ κατορθώματα παρὰ πόδας. ὃ καὶ τότε περὶ τὸν Εὐμένη γενέσθαι συνέπεσε· δόξας γὰρ μάλιστα τότε τὴν ἰδίαν ἀρχὴν ἐν ἀσφαλεῖ βεβηκέναι καὶ πολλὴν ἐπιφέρειν ῥᾳστώνην τὸν ἑξῆς χρόνον, ἅτε τοῦ Περσέως καὶ καθόλου τῆς ἐν Μακεδονίᾳ βασιλείας ἄρδην ἀνῃρημένης, τότε μεγίστοις ἐνεκύρησε κινδύνοις τῶν κατὰ τὴν Ἀσίαν Γαλατῶν ἀνυπονοήτως συνεξαναστάντων τοῖς καιροῖς.", "st": "29.22"}, {"sp": "N", "t": "ὅτι κατὰ τὴν Πελοπόννησον ἔτι κατὰ χειμῶνα πρεσβείας παραγενομένης παρὰ τῶν βασιλέων ἀμφοτέρων [Πτολεμαίου καὶ Πτολεμαίου] περὶ βοηθείας, ἐγενήθη διαβούλια καὶ πλείω, πολλὴν ἔχοντα φιλοτιμίαν. τοῖς μὲν γὰρ περὶ τὸν Καλλικράτην καὶ Διοφάνην καὶ σὺν τούτοις Ὑπέρβατον οὐκ ἤρεσκε διδόναι βοήθειαν, τοῖς δὲ περὶ τὸν Ἄρχωνα καὶ Λυκόρταν καὶ Πολύβιον ἤρεσκε τὸ διδόναι τοῖς βασιλεῦσι κατὰ τὴν ὑπάρχουσαν συμμαχίαν. ἤδη γὰρ συνέβαινε τότε τὸν νεώτερον Πτολεμαῖον ὑπὸ τῶν ὄχλων ἀναδεδεῖχθαι βασιλέα διὰ τὴν περίστασιν, τὸν δὲ πρεσβύτερον ἐκ τῆς Μέμφεως καταπεπορεῦσθαι καὶ συμβασιλεύειν τἀδελφῷ. καὶ δεόμενοι παντοδαπῆς ἐπικουρίας ἐξαπέστειλαν πρεσβευτὰς Εὐμένη καὶ Διονυσόδωρον πρὸς τοὺς Ἀχαιούς, αἰτοῦντες πεζοὺς μὲν χιλίους ἱππεῖς δὲ διακοσίους, ἡγεμόνα δὲ τῆς ὅλης συμμαχίας Λυκόρταν, τῶν δ’ ἱππέων Πολύβιον. πρὸς δὲ Θεοδωρίδαν τὸν Σικυώνιον διεπέμψαντο, παρακαλοῦντες αὐτὸν συστήσασθαι ξενολόγιον χιλίων ἀνδρῶν. συνέβαινε δὲ τοὺς μὲν βασιλεῖς τὴν ἐπὶ πλεῖον σύστασιν ἔχειν πρὸς τοὺς εἰρημένους ἄνδρας ἐκ τῶν πράξεων ὧν εἰρήκαμεν. τῶν δὲ πρεσβευτῶν παραγενομένων, τῆς συνόδου τῶν Ἀχαιῶν οὔσης ἐν Κορίνθῳ, καὶ τά τε φιλάνθρωπα πρὸς τὴν βασιλείαν ἀνανεωσαμένων ὄντα μεγάλα καὶ τὴν περίστασιν τῶν βασιλέων ὑπὸ τὴν ὄψιν ἀγόντων καὶ δεομένων σφίσι βοηθεῖν, τὸ μὲν πλῆθος τῶν Ἀχαιῶν ἕτοιμον ἦν οὐ μέρει τινί, πανδημεὶ δὲ συγκινδυνεύειν, εἰ δέοι, τοῖς βασιλεῦσιν· ἀμφότεροι γὰρ εἶχον τό τε διάδημα καὶ τὴν ἐξουσίαν. οἱ δὲ περὶ τὸν Καλλικράτην ἀντέλεγον, φάσκοντες δεῖν καθόλου μὲν μὴ πραγματοκοπεῖν, ἐν δὲ τοῖς παροῦσι καιροῖς μηδ’ ὅλως, ἀλλ’ ἀπερισπάστους ὑπάρχοντας Ῥωμαίοις παρέχεσθαι χρείας· μάλιστα γὰρ ἦν τότε προσδόκιμος ὁ περὶ τῶν ὅλων κίνδυνος, ἅτε τοῦ Κοΐντου τοῦ Φιλίππου τὴν παραχειμασίαν ἐν τῇ Μακεδονίᾳ ποιουμένου.", "st": "29.23"}, {"sp": "N", "t": "τῶν δὲ πολλῶν εἰς ἀπορίαν ἐμπιπτόντων, μὴ δόξωσι Ῥωμαίων ἀστοχεῖν, μεταλαβόντες τοὺς λόγους οἱ περὶ τὸν Λυκόρταν καὶ Πολύβιον ἐδίδασκον, ἄλλα τε καὶ πλείω προφερόμενοι καὶ διότι, τῷ πρότερον ἔτει ψηφισαμένων τῶν Ἀχαιῶν πανδημεὶ συστρατεύειν τοῖς Ῥωμαίοις καὶ πεμψάντων πρεσβευτὴν τὸν Πολύβιον, ὁ Κόιντος ἀποδεξάμενος τὴν προθυμίαν ἀπείπατο μὴ χρείαν ἔχειν τῆς βοηθείας, ἐπεὶ κεκράτηκε τῆς εἰς Μακεδονίαν εἰσβολῆς. ἐξ ὧν ἀπεδείκνυσαν σκῆψιν οὖσαν τὴν Ῥωμαίων χρείαν πρὸς τὸ διακωλῦσαι βοηθεῖν. διὸ παρεκάλουν τοὺς Ἀχαιούς, ὑποδεικνύοντες τὸ μέγεθος τῆς περιστάσεως, ἐν ᾗ συνέβαινε τότε τὴν βασιλείαν ὑπάρχειν, μὴ παριδεῖν τὸν καιρόν, ἀλλὰ μνημονεύοντας τῶν ὁμολογιῶν καὶ τῶν εὐεργεσιῶν, μάλιστα δὲ τῶν ὅρκων, ἐμπεδοῦν τὰς συνθήκας. τῶν δὲ πολλῶν ἐπιφερομένων πάλιν βοηθεῖν, τότε μὲν οἱ περὶ τὸν Καλλικράτην ἐξέβαλον τὸ διαβούλιον, διασείσαντες τοὺς ἄρχοντας, ὡς οὐκ οὔσης ἐξουσίας κατὰ τοὺς νόμους ἐν ἀγορᾷ βουλεύεσθαι περὶ βοηθείας. μετὰ δέ τινα χρόνον συγκλήτου συναχθείσης εἰς τὴν τῶν Σικυωνίων πόλιν, ἐν ᾗ συνέβαινε μὴ μόνον συμπορεύεσθαι τὴν βουλὴν ἀλλὰ πάντας τοὺς ἀπὸ τριάκοντ’ ἐτῶν, καὶ λόγων γινομένων πλειόνων, καὶ μάλιστα τοῦ Πολυβίου διοριζομένου πρῶτον μὲν περὶ τοῦ μὴ χρείαν ἔχειν τοὺς Ῥωμαίους τῆς βοηθείας καὶ δοκοῦντος οὐκ εἰκῇ ταῦτα λέγειν διὰ τὸ γεγονέναι τὴν παρελθοῦσαν θερείαν ἐν τῇ Μακεδονίᾳ παρὰ τῷ Φιλίππῳ, δεύτερον δὲ φάσκοντος, ἐὰν καὶ δέωνται Ῥωμαῖοι τῆς συμμαχίας, οὐ διὰ τοὺς διακοσίους ἱππεῖς καὶ χιλίους πεζοὺς τοὺς ἀποσταλησομένους εἰς Ἀλεξάνδρειαν ἀδυνατήσειν τοὺς Ἀχαιοὺς βοηθεῖν Ῥωμαίοις· καλῶς γὰρ ποιοῦντας αὐτοὺς καὶ τρεῖς ἄγειν καὶ τέτταρας μυριάδας ἀνδρῶν μαχίμων· εὐδοκοῦντες τοῖς λεγομένοις ἔρρεπον οἱ πολλοὶ πρὸς τὸ πέμπειν τὴν συμμαχίαν. τῇ δὲ δευτέρᾳ τῶν ἡμερῶν, ἐν ᾗ κατὰ τοὺς νόμους ἔδει τὰ ψηφίσματα προσφέρειν τοὺς βουλομένους, οἱ μὲν περὶ τὸν Λυκόρταν προσήνεγκαν διότι δεῖ πέμπειν τὴν βοήθειαν, οἱ δὲ περὶ τὸν Καλλικράτην διότι δεῖ πρεσβευτὰς ἐξαποστέλλειν τοὺς διαλύσοντας τοὺς βασιλεῖς πρὸς τὸν Ἀντίοχον. πάλιν δὲ τῶν διαβουλίων προτεθέντων ἀγὼν ἐγίνετο νεανικός· πολύ γε μὴν ὑπερεῖχον οἱ περὶ τὸν Λυκόρταν. αἵ τε γὰρ βασιλεῖαι συγκρινόμεναι μεγάλην εἶχον διαφοράν· ὑπὸ μὲν γὰρ τῆς Ἀντιόχου σπάνιον ἦν εὑρεῖν οἰκεῖόν τι γεγονὸς καθόλου πρὸς τοὺς Ἕλληνας ἔν γε τοῖς ἀνώτερον χρόνοις· καὶ γὰρ ἡ τοῦ τότε βασιλεύοντος μεγαλοψυχία διάδηλος ἐγένετο τοῖς Ἕλλησιν· ὑπὸ δὲ τῆς Πτολεμαίου τοσαῦτα καὶ τηλικαῦτα τοῖς Ἀχαιοῖς ἐγεγόνει φιλάνθρωπα κατὰ τοὺς ἀνώτερον χρόνους ὥστ’ ἂν μηδένα πλεῖον ἀξιοῦν. ἃ διατιθέμενος ὁ Λυκόρτας μεγάλην ἐποιεῖτο φαντασίαν, ἅτε τῆς παραθέσεως ὁλοσχερῆ τὴν διαφορὰν ἐχούσης· καθ’ ὅσον γὰρ οὐκ ἐξαριθμήσασθαι ῥᾴδιον ἦν τὰς τῶν ἐν Ἀλεξανδρείᾳ βασιλέων εὐεργεσίας, κατὰ τοσοῦτον ἁπλῶς οὐδὲν ἦν εὑρεῖν φιλάνθρωπον ἐκ τῆς Ἀντιόχου βασιλείας ἀπηντημένον εἰς πραγμάτων λόγον τοῖς Ἀχαιοῖς. —", "st": "29.24"}, {"sp": "N", "t": "ὅτι ἕως μέν τινος οἱ περὶ τὸν Ἀνδρωνίδαν καὶ Καλλικράτην ἐχρῶντο τοῖς ὑπὲρ τῆς διαλύσεως λόγοις, οὐδενὸς δὲ προσέχοντος αὐτοῖς ἐπεισήγαγον μηχανήν. παρῆν γὰρ ἐκ πορείας εἰς τὸ θέατρον γραμματηφόρος φέρων ἐπιστολὴν παρὰ Κοΐντου Μαρκίου, δι’ ἧς παρεκάλει τοὺς Ἀχαιοὺς ἀκολουθοῦντας τῇ Ῥωμαίων προαιρέσει πειρᾶσθαι διαλύειν τοὺς βασιλεῖς· συνέβαινε γὰρ καὶ τὴν σύγκλητον ἀπεσταλκέναι πρεσβευτὰς τοὺς περὶ Νεμέσιον διαλύσοντας τοὺς βασιλεῖς. ἦν δὲ τοῦτο κατὰ τῆς ὑποθέσεως· οἱ γὰρ περὶ τὸν Τίτον ἀδυνατήσαντες τοῦ διαλύειν ἀνακεχωρήκεισαν εἰς τὴν Ῥώμην ἄπρακτοι τελείως. ἀλλ’ οἱ περὶ τὸν Πολύβιον οὐ βουλόμενοι διὰ τὸν Μάρκιον πρὸς τὴν ἐπιστολὴν ἀντιλέγειν ἀνεχώρησαν ἐκ τῶν πραγμάτων. καὶ τὰ μὲν κατὰ τὴν βοήθειαν οὕτω διέπεσε τοῖς βασιλεῦσι, τοῖς δ’ Ἀχαιοῖς ἔδοξε πρεσβευτὰς ἀποστέλλειν τοὺς διαλύσοντας· καὶ κατεστάθησαν Ἄρχων Αἰγειράτης, Ἀρκεσίλαος Ἀρίστων Μεγαλοπολῖται. οἱ δὲ παρὰ τοῦ Πτολεμαίου πρεσβευταὶ διαψευσθέντες τῆς συμμαχίας ἀνέδωκαν τοῖς ἄρχουσιν, ἑτοίμας ἔχοντες, ἐπιστολὰς παρὰ τῶν βασιλέων, δι’ ὧν ἠξίουν τοὺς Ἀχαιοὺς ἐκπέμπειν Λυκόρταν καὶ Πολύβιον ἐπὶ τὸν ἐνεστῶτα πόλεμον. —", "st": "29.25"}, {"sp": "N", "t": "ἐπιλαθόμενος δὲ τῶν γεγραμμένων ὑπ’ αὐτοῦ Ἀντίοχος καὶ τῶν εἰρημένων ἐξήρτυε πόλεμον κατὰ Πτολεμαίου, ὥστε καὶ λίαν ἀληθὲς φαίνεσθαι τὸ ῥηθὲν ὑπὸ Σιμωνίδου \"χαλεπὸν ἐσθλὸν ἔμμεναι. \" ἔχειν μὲν γὰρ ὁρμὰς ἐπὶ τὰ καλὰ καὶ μέχρι τινὸς ἀντιποιήσασθαι τούτων εὐμαρές, ὁμαλίσαι δὲ καὶ κατὰ πᾶσαν περίστασιν ἐπίμονον γενέσθαι τῇ γνώμῃ, μηδὲν τοῦ καλοῦ καὶ τοῦ δικαίου προυργιαίτερον τιθέμενον, δυσχερές. —", "st": "29.26"}, {"sp": "N", "t": "ὅτι τοῦ Ἀντιόχου πρὸς Πτολεμαῖον ἕνεκεν τοῦ Πηλούσιον κατασχεῖν ἀφικομένου, ὁ Ποπίλιος ὁ τῶν Ῥωμαίων στρατηγός, τοῦ βασιλέως πόρρωθεν ἀσπαζομένου διὰ τῆς φωνῆς καὶ τὴν δεξιὰν προτείνοντος, πρόχειρον ἔχων τὸ δελτάριον, ἐν ᾧ τὸ τῆς συγκλήτου δόγμα κατετέτακτο, προύτεινεν αὐτῷ καὶ τοῦτ’ ἐκέλευσε πρῶτον ἀναγνῶναι τὸν Ἀντίοχον, ὡς μὲν ἐμοὶ δοκεῖ, μὴ πρότερον ἀξιώσας τὸ τῆς φιλίας σύνθημα ποιεῖν πρὶν ἢ τὴν προαίρεσιν ἐπιγνῶναι τοῦ δεξιουμένου, πότερα φίλιος ἢ πολέμιός ἐστιν. ἐπεὶ δ’ ὁ βασιλεὺς ἀναγνοὺς ἔφη βούλεσθαι μεταδοῦναι τοῖς φίλοις ὑπὲρ τῶν προσπεπτωκότων, ἀκούσας ὁ Ποπίλιος ἐποίησε πρᾶγμα βαρὺ μὲν δοκοῦν εἶναι καὶ τελέως ὑπερήφανον· ἔχων γὰρ πρόχειρον ἀμπελίνην βακτηρίαν περιέγραφε τῷ κλήματι τὸν Ἀντίοχον ἐν τούτῳ τε τῷ γύρῳ τὴν ἀπόφασιν ἐκέλευσε δοῦναι περὶ τῶν γεγραμμένων· ὁ δὲ βασιλεὺς ξενισθεὶς τὸ γινόμενον καὶ τὴν ὑπεροχήν, βραχὺν χρόνον ἐναπορήσας ἔφη ποιήσειν πᾶν τὸ παρακαλούμενον ὑπὸ Ῥωμαίων. οἱ δὲ περὶ τὸν Ποπίλιον τότε τὴν δεξιὰν αὐτοῦ λαμβάνοντες ἅμα πάντες ἠσπάζοντο φιλοφρόνως. ἦν δὲ τὰ γεγραμμένα λύειν ἐξ αὐτῆς τὸν πρὸς Πτολεμαῖον πόλεμον. διὸ καὶ δοθεισῶν αὐτῷ τακτῶν ἡμερῶν, οὗτος μὲν ἀπῆγε τὰς δυνάμεις εἰς τὴν Συρίαν, βαρυνόμενος καὶ στένων, εἴκων δὲ τοῖς καιροῖς κατὰ τὸ παρόν· οἱ δὲ περὶ τὸν Ποπίλιον καταστησάμενοι τὰ κατὰ τὴν Ἀλεξάνδρειαν καὶ παρακαλέσαντες τοὺς βασιλεῖς ὁμονοεῖν, ἅμα δὲ προστάξαντες αὐτοῖς Πολυάρατον ἀναπέμπειν εἰς Ῥώμην, ἀνέπλευσαν ἐπὶ τῆς Κύπρου, βουλόμενοι καὶ τὰς ἐκεῖ καθυπαρχούσας δυνάμεις ἐκβαλεῖν ἐκ τῆς νήσου κατὰ σπουδήν. ἀφικόμενοι δὲ καὶ καταλαβόντες ἡττημένους μάχῃ τοὺς τοῦ Πτολεμαίου στρατηγοὺς καὶ καθόλου φερόμενα τὰ κατὰ τὴν Κύπρον ἄνω καὶ κάτω ταχέως ἀνέστησαν τὸ στρατόπεδον ἐκ τῆς χώρας καὶ παρήδρευσαν, ἕως ἀπέπλευσαν αἱ δυνάμεις ἐπὶ Συρίας. καὶ Ῥωμαῖοι μὲν ὅσον οὔπω καταπεπονημένην τὴν Πτολεμαίου βασιλείαν τούτῳ τῷ τρόπῳ διέσωσαν, τῆς τύχης οὕτω βραβευούσης τὰ κατὰ τὸν Περσέα πράγματα καὶ τοὺς Μακεδόνας ὥστε καὶ πρὸς τὸν ἔσχατον καιρὸν ἐλθόντα τὰ κατὰ τὴν Ἀλεξάνδρειαν καὶ τὴν ὅλην Αἴγυπτον παρὰ τοῦτο πάλιν ὀρθωθῆναι, παρὰ τὸ φθάσαι κριθέντα τὰ κατὰ τὸν Περσέα πράγματα· μὴ γὰρ γενομένου τούτου καὶ πιστευθέντος, οὐκ ἄν μοι δοκεῖ πειθαρχῆσαι τοῖς ἐπιταττομένοις Ἀντίοχος.", "st": "29.27"}, {"sp": "HDR", "t": "Βιβλίον Λʹ", "st": "30"}, {"sp": "N", "t": "ὅτι κατὰ τὸν καιρὸν τοῦτον ἦλθε παρὰ τοῦ βασιλέως Εὐμένους ἀδελφὸς Ἄτταλος, ἔχων μὲν πρόφασιν, εἰ καὶ μὴ τὸ κατὰ τοὺς Γαλάτας ἐγεγόνει σύμπτωμα περὶ τὴν βασιλείαν, ὅμως ἐλθεῖν εἰς τὴν Ῥώμην ἕνεκεν τοῦ συγχαρῆναι τῇ συγκλήτῳ καὶ τυχεῖν τινος ἐπισημασίας διὰ τὸ συμπεπολεμηκέναι καὶ πάντων εὐμενῶς σφίσι μετεσχηκέναι τῶν κινδύνων· τότε δὲ καὶ διὰ τὴν Γαλατικὴν περίστασιν ἠναγκασμένος ἧκεν εἰς τὴν Ῥώμην. πάντων δὲ φιλοφρόνως αὐτὸν ἀποδεχομένων διά τε τὴν ἐν τῇ στρατείᾳ γεγενημένην συνήθειαν καὶ διὰ τὸ δοκεῖν εὔνουν αὐτοῖς ὑπάρχειν, καὶ γινομένης τῆς ἀπαντήσεως ὑπὲρ τὴν προσδοκίαν, μετέωρος ἐγενήθη ταῖς ἐλπίσιν, οὐκ εἰδὼς τὴν ἀληθινὴν αἰτίαν τῆς ἀποδοχῆς. διὸ καὶ παρ’ ὀλίγον ἦλθε τοῦ λυμήνασθαι τὰ σφέτερα πράγματα καὶ τὴν ὅλην βασιλείαν. τῶν γὰρ πλείστων Ῥωμαίων ἀπηλλοτριωμένων τῆς τοῦ βασιλέως Εὐμένους εὐνοίας καὶ πεπεισμένων αὐτὸν πλάγιον ἐν τῷ πολέμῳ γεγονέναι, λαλοῦντα τῷ Περσεῖ καὶ τοῖς καιροῖς ἐφεδρεύοντα τοῖς κατ’ αὐτῶν, ἔνιοι τῶν ἐπιφανῶν ἀνδρῶν λαμβάνοντες εἰς τὰς χεῖρας τὸν Ἄτταλον παρεκάλουν τὴν μὲν ὑπὲρ τἀδελφοῦ πρεσβείαν ἀποθέσθαι, περὶ δ’ ἑαυτοῦ ποιεῖσθαι τοὺς λόγους· βούλεσθαι γὰρ αὐτῷ τὴν σύγκλητον συγκατασκευάζειν ἰδίαν ἀρχὴν καὶ δυναστείαν διὰ τὴν ἀλλοτριότητα τὴν πρὸς τὸν ἀδελφόν. ἐφ’ οἷς συνέβαινε τὸν Ἄτταλον ἐπὶ πολὺ μετεωρίζεσθαι καὶ συγκατανεύειν ἐν ταῖς κατ’ ἰδίαν ὁμιλίαις τοῖς εἰς τοῦτο τὸ μέρος αὐτὸν παρορμῶσι. τέλος δὲ πρὸς ἐνίους τῶν ἀξιολόγων ἀνδρῶν συνέθετο καὶ παρελθὼν εἰς τὴν σύγκλητον ποιήσεσθαι τοὺς περὶ τούτων λόγους.", "st": "30.1"}, {"sp": "N", "t": "τοιαύτης δ’ οὔσης τῆς διαθέσεως περὶ τὸν Ἄτταλον, ὀττευσάμενος ὁ βασιλεὺς τὸ μέλλον ἐπιπέμπει Στρατίον τὸν ἰατρὸν εἰς τὴν Ῥώμην, ὃς μεγίστην παρ’ αὐτῷ πίστιν εἶχε, τὰ μὲν ὑποδείξας, τὰ δ’ ἐντειλάμενος πᾶσαν εἰσενέγκασθαι μηχανὴν πρὸς τὸ μὴ κατακολουθῆσαι τὸν Ἄτταλον τοῖς βουλομένοις λυμήνασθαι τὴν βασιλείαν αὐτῶν. ὁ δὲ παραγενόμενος εἰς τὴν Ῥώμην καὶ λαβὼν εἰς τὰς χεῖρας τὸν Ἄτταλον πολλοὺς μὲν καὶ ποικίλους διέθετο λόγους· καὶ γὰρ ἦν ὁ ἄνθρωπος ἔχων τι νουνεχὲς καὶ πειστικόν· μόγις δὲ καθίκετο τῆς προθέσεως καὶ μετεκάλεσε τὸν Ἄτταλον ἀπὸ τῆς ἀλόγου φορᾶς, θεὶς ὑπὸ τὴν ὄψιν ὅτι κατὰ μὲν τὸ παρὸν συμβασιλεύει τἀδελφῷ, τούτῳ διαφέρων ἐκείνου τῷ μὴ διάδημα περιτίθεσθαι μηδὲ χρηματίζειν βασιλεύς, τὴν δὲ λοιπὴν ἴσην καὶ τὴν αὐτὴν ἔχων ἐξουσίαν, εἰς δὲ τὸ μέλλον ὁμολογουμένως καταλείπεται διάδοχος τῆς ἀρχῆς, οὐ μακρὰν ταύτης τῆς ἐλπίδος ὑπαρχούσης, ἅτε τοῦ βασιλέως διὰ μὲν τὴν σωματικὴν ἀσθένειαν αἰεὶ προσδοκῶντος τὴν ἐκ τοῦ βίου μετάστασιν, διὰ δὲ τὴν ἀπαιδίαν οὐδ’ εἰ βουληθείη δυναμένου τὴν ἀρχὴν ἄλλῳ καταλιπεῖν· οὐδέπω γὰρ ἀναδεδειγμένος ἐτύγχανεν κατὰ φύσιν υἱὸς ὢν αὐτῷ τις ὁ μετὰ ταῦτα διαδεξάμενος τὴν ἀρχήν. τὸ δὲ συνέχον, θαυμάζειν ἔφη πόσα βλάπτει τοὺς ἐνεστῶτας καιρούς. μεγάλην γὰρ δεῖν ἔχειν πᾶσι τοῖς θεοῖς χάριν, εἰ συμπνεύσαντες καὶ μιᾷ γνώμῃ χρώμενοι δύναιντο τὸν ἀπὸ Γαλατῶν φόβον ἀπώσασθαι καὶ τὸν ἀπὸ τούτων ἐφεστῶτα κίνδυνον. εἰ δὲ νῦν εἰς στάσιν καὶ διαφορὰν ἥξει πρὸς τὸν ἀδελφόν, πρόδηλον εἶναι διότι καταστρέψει τὴν βασιλείαν καὶ στερήσει μὲν αὑτὸν καὶ τῆς παρούσης ἐξουσίας καὶ τῆς εἰς τὸ μέλλον ἐλπίδος, στερήσει δὲ καὶ τοὺς ἀδελφοὺς τῆς ἀρχῆς καὶ τῆς ἐν αὐτῇ δυναστείας. ταῦτα δὴ καὶ τούτοις ἕτερα παραπλήσια διατιθέμενος ὁ Στρατίος ἔπεισε τὸν Ἄτταλον μένειν ἐπὶ τῶν ὑποκειμένων.", "st": "30.2"}, {"sp": "N", "t": "διόπερ εἰσελθὼν εἰς τὴν σύγκλητον ὁ προειρημένος συνεχάρη μὲν ἐπὶ τοῖς γεγονόσιν καὶ περὶ τῆς καθ’ αὑτὸν εὐνοίας καὶ προθυμίας, ἣν παρέσχετο κατὰ τὸν πρὸς Περσέα πόλεμον, ἀπελογίσατο· παραπλησίως δὲ καὶ περὶ τοῦ πέμψαι πρεσβευτὰς τοὺς παρακαθέξοντας τὴν τῶν Γαλατῶν ἀπόνοιαν καὶ πάλιν εἰς τὴν ἐξ ἀρχῆς αὐτοὺς ἀποκαταστήσοντας διάθεσιν παρεκάλεσε διὰ πλειόνων. ἐποιήσατο δὲ λόγους καὶ περὶ τῆς Αἰνίων καὶ τῆς Μαρωνειτῶν πόλεως, ἀξιῶν αὑτῷ δοθῆναι ταύτας ἐν δωρεᾷ. τὸν δὲ κατὰ τοῦ βασιλέως λόγον καὶ τὸν περὶ τοῦ μερισμοῦ τῆς ἀρχῆς εἰς τέλος παρεσιώπησεν. ἡ δὲ σύγκλητος ὑπολαμβάνουσα πάλιν αὐτὸν ἰδίᾳ περὶ τούτων εἰσπορεύσεσθαι, τούς τε πρεσβευτὰς συμπέμψειν ὑπέσχετο καὶ τοῖς εἰθισμένοις δώροις ἐτίμησεν αὐτὸν μεγαλομερῶς· ἐπηγγείλατο δὲ καὶ τὰς προειρημένας πόλεις δώσειν. ἐπειδὴ δὲ παραυτὰ τυχὼν τῶν φιλανθρώπων ὥρμησεν ἐκ τῆς Ῥώμης οὐδὲν ποιήσας τῶν προσδοκωμένων, διαψευσθεῖσα τῶν ἐλπίδων ἡ σύγκλητος ἄλλο μὲν οὐδὲν εἶχε ποιεῖν, ἔτι δὲ κατὰ τὴν Ἰταλίαν ὄντος αὐτοῦ τὴν μὲν Αἶνον καὶ τὴν Μαρώνειαν ἠλευθέρωσεν, ἀθετήσασα τὴν ἐπαγγελίαν, τοὺς δὲ περὶ τὸν Πόπλιον Λικίννιον ἔπεμψε πρεσβευτὰς πρὸς τοὺς Γαλάτας. οἷς ποίας μὲν ἔδωκεν ἐντολὰς εἰπεῖν οὐ ῥᾴδιον, στοχάζεσθαι δ’ ἐκ τῶν μετὰ ταῦτα συμβάντων οὐ δυσχερές. τοῦτο δ’ ἔσται δῆλον ἐκ τῶν πράξεων αὐτῶν.", "st": "30.3"}, {"sp": "N", "t": "ἧκον δὲ καὶ παρὰ Ῥοδίων πρέσβεις, πρῶτον μὲν οἱ περὶ Φιλοκράτην, μετὰ δὲ τούτους οἱ περὶ Φιλόφρονα καὶ Ἀστυμήδην. οἱ γὰρ Ῥόδιοι κομισάμενοι τὴν ἀπόκρισιν, ἣν οἱ περὶ τὸν Ἁγέπολιν ἔλαβον εὐθέως μετὰ τὴν παράταξιν, καὶ θεωροῦντες ἐκ ταύτης τὴν πρὸς αὑτοὺς ὀργὴν καὶ τὴν ἀνάτασιν τῆς συγκλήτου παραυτίκα τὰς προειρημένας πρεσβείας ἐξέπεμψαν. οἱ δὲ περὶ τὸν Ἀστυμήδην καὶ Φιλόφρονα κατανοοῦντες ἐκ τῶν ἐντεύξεων καὶ κοινῇ καὶ κατ’ ἰδίαν τὴν ὑφόρασιν καὶ τὴν ἀλλοτριότητα τῶν ἀνθρώπων τὴν πρὸς αὑτοὺς εἰς ἀθυμίαν ὁλοσχερῆ καὶ δυσχρηστίαν ἐνέπιπτον. ὡς δὲ καὶ τῶν στρατηγῶν τις ἀναβὰς ἐπὶ τοὺς ἐμβόλους παρεκάλει τοὺς ὄχλους ἐπὶ τὸν κατὰ Ῥοδίων πόλεμον, τότε δὴ παντάπασιν ἔξω τοῦ φρονεῖν γενόμενοι διὰ τὸν περὶ τῆς πατρίδος κίνδυνον εἰς τοιαύτην ἦλθον διάθεσιν ὥστε καὶ φαιὰ λαβεῖν ἱμάτια καὶ κατὰ τὰς παρακλήσεις μηκέτι παρακαλεῖν μηδ’ ἀξιοῦν τοὺς φίλους, ἀλλὰ δεῖσθαι μετὰ δακρύων μηδὲν ἀνήκεστον βουλεύσασθαι περὶ αὑτῶν. μετὰ δέ τινας ἡμέρας εἰσαγαγόντος αὐτοὺς Ἀντωνίου τοῦ δημάρχου, τοῦ καὶ τὸν στρατηγὸν τὸν παρακαλοῦντα πρὸς τὸν πόλεμον κατασπάσαντος ἀπὸ τῶν ἐμβόλων, ἐποιεῖτο τοὺς λόγους πρῶτον μὲν Φιλόφρων, μετὰ δὲ τοῦτον Ἀστυμήδης. ὅτε δὴ κατὰ τὴν παροιμίαν τὸ κύκνειον ἐξηχήσαντες ἔλαβον ἀποκρίσεις τοιαύτας, δι’ ὧν τοῦ μὲν ὁλοσχεροῦς φόβου τοῦ κατὰ τὸν πόλεμον ἐδόκουν παραλελύσθαι, περὶ δὲ τῶν κατὰ μέρος ἐγκλημάτων αὐτοῖς ἡ σύγκλητος πικρῶς καὶ βαρέως ὠνείδισεν. ἦν δ’ ὁ νοῦς τῆς ἀποκρίσεως τοιοῦτος, ὅτι εἰ μὴ δι’ ὀλίγους ἀνθρώπους τοὺς αὑτῶν φίλους, καὶ μάλιστα δι’ αὐτούς, ᾔδεισαν καλῶς καὶ δικαίως ὡς δέον ἦν αὐτοῖς χρήσασθαι. ὁ δ’ Ἀστυμήδης αὑτῷ μὲν ἐδόκει καλῶς εἰρηκέναι περὶ τῆς πατρίδος, οὐ μὴν τοῖς γε παρεπιδημοῦσιν οὐδὲ τοῖς οἴκοι μένουσιν τῶν Ἑλλήνων οὐδαμῶς ἤρεσκεν. ἐξέβαλε γὰρ ἔγγραπτον μετὰ ταῦτα ποιήσας τὴν σύνταξιν τῆς δικαιολογίας, ἣ τοῖς πλείστοις τῶν ἀναλαμβανόντων εἰς τὰς χεῖρας ἄτοπος ἐφαίνετο καὶ τελέως ἀπίθανος. συνεστήσατο γὰρ τὴν δικαιολογίαν οὐ μόνον ἐκ τῶν τῆς πατρίδος δικαίων, ἔτι δὲ μᾶλλον ἐκ τῆς τῶν ἄλλων κατηγορίας. τὰ μὲν γὰρ εὐεργετήματα καὶ συνεργήματα παραβάλλων καὶ συγκρίνων τὰ μὲν τῶν ἄλλων ἐπειρᾶτο ψευδοποιεῖν καὶ ταπεινοῦν, τὰ δὲ τῶν Ῥοδίων ηὔξανε, πολλαπλασιάζων καθ’ ὅσον οἷός τ’ ἦν· τὰ δ’ ἁμαρτήματα κατὰ τοὐναντίον τὰ μὲν τῶν ἄλλων ἐξωνείδιζε πικρῶς καὶ δυσμενικῶς, τὰ δὲ τῶν Ῥοδίων ἐπειρᾶτο περιστέλλειν, ἵνα κατὰ τὴν παράθεσιν τὰ μὲν οἰκεῖα μικρὰ καὶ συγγνώμης ἄξια φανῇ, τὰ δὲ τῶν πέλας μεγάλα καὶ ἀπαραίτητα τελέως, ἐφ’ οἷς ἔφη συγγνώμης τετευχέναι τοὺς ἡμαρτηκότας ἅπαντας. τὸ δὲ γένος τοῦτο τῆς δικαιολογίας οὐδαμῶς ἂν πρέπειν ἀνδρὶ πολιτικῷ δόξειεν, ἐπείτοι καὶ τῶν κοινοπραγησάντων περί τινων ἀπορρήτων οὐ τοὺς διὰ φόβον ἢ πόρον μηνυτὰς γενομένους τῶν συνειδότων ἐπαινοῦμεν, ἀλλὰ τοὺς πᾶσαν ἐπιδεξαμένους βάσανον καὶ τιμωρίαν καὶ μηδενὶ τῶν συνειδότων παραιτίους γενομένους τῆς αὐτῆς συμφορᾶς, τούτους ἀποδεχόμεθα καὶ τούτους ἄνδρας ἀγαθοὺς νομίζομεν. ὁ δὲ διὰ τὸν ἄδηλον φόβον πάντα τὰ τῶν ἄλλων ἁμαρτήματα τιθεὶς ὑπὸ τὴν ὄψιν τοῖς κρατοῦσιν καὶ καινοποιήσας, ὑπὲρ ὧν ὁ χρόνος εἰς λήθην ἀγηόχει τοὺς ὑπερέχοντας, πῶς οὐκ ἔμελλε δυσαρεστήσειν τοῖς ἱστορήσασιν;", "st": "30.4"}, {"sp": "N", "t": "τὴν δὲ προειρημένην ἀπόκρισιν οἱ μὲν περὶ τὸν Φιλοκράτην λαβόντες ἐξ αὐτῆς ὥρμησαν, οἱ δὲ περὶ τὸν Φιλόφρονα καὶ Ἀστυμήδην αὐτόθι μένοντες παρήδρευον χάριν τοῦ μηδὲν αὐτοὺς λανθάνειν τῶν προσπιπτόντων ἢ λεγομένων κατὰ τῆς πατρίδος. προσπεσούσης δὲ τῆς ἀποκρίσεως ταύτης εἰς τὴν Ῥόδον, δόξαντες ἀπολελύσθαι τοῦ μεγίστου φόβου τοῦ κατὰ τὸν πόλεμον, τἄλλα καίπερ ἀκμὴν ὄντα δυσχερῆ ῥᾳδίως ἔφερον. οὕτως αἰεὶ τὰ μείζω τῶν προσδοκωμένων κακῶν λήθην ποιεῖ τῶν ἐλαττόνων συμπτωμάτων. διὸ καὶ παραχρῆμα ψηφισάμενοι τῇ Ῥώμῃ στέφανον ἀπὸ μυρίων χρυσῶν καὶ καταστήσαντες πρεσβευτὴν ἅμα καὶ ναύαρχον Θεαίδητον ἐξέπεμπον θερείας ἀρχομένης ἄγοντα τὸν στέφανον καὶ μετὰ τούτου τοὺς περὶ Ῥοδοφῶντα, πειρασομένους κατὰ πάντα τρόπον συμμαχίαν συνθέσθαι πρὸς Ῥωμαίους. τοῦτο δ’ ἐποίησαν οὐ βουλόμενοι διὰ τοῦ ψηφίσματος καὶ πρεσβείας ἀποτυχεῖν, ἐὰν ἄλλως δόξῃ Ῥωμαίοις, δι’ αὐτῆς δὲ τῆς τοῦ ναυάρχου προαιρέσεως τὴν κατάπειραν ποιήσασθαι· τὴν γὰρ ἐξουσίαν εἶχε ταύτην ὁ ναύαρχος ἐκ τῶν νόμων. οὕτως γὰρ ἦν πραγματικὸν τὸ πολίτευμα τῶν Ῥοδίων ὡς σχεδὸν ἔτη τετταράκοντα πρὸς τοῖς ἑκατὸν κεκοινωνηκὼς ὁ δῆμος Ῥωμαίοις τῶν ἐπιφανεστάτων καὶ καλλίστων ἔργων οὐκ ἐπεποίητο πρὸς αὐτοὺς συμμαχίαν. τίνος δὲ χάριν οὕτως ἐχείριζον οἱ Ῥόδιοι τὰ καθ’ αὑτοὺς οὐκ ἄξιον παραλιπεῖν. βουλόμενοι γὰρ μηδένα τῶν ἐν ταῖς ὑπεροχαῖς καὶ δυναστείαις ἀπελπίζειν τὴν ἐξ αὑτῶν ἐπικουρίαν καὶ συμμαχίαν, οὐκ ἐβούλοντο συνδυάζειν οὐδὲ προκαταλαμβάνειν σφᾶς αὐτοὺς ὅρκοις καὶ συνθήκαις, ἀλλ’ ἀκέραιοι διαμένοντες κερδαίνειν τὰς ἐξ ἑκάστων ἐλπίδας. τότε δὲ μεγάλην ἐποιοῦντο φιλοτιμίαν, βουλόμενοι ταύτης τῆς τιμῆς τυχεῖν παρὰ Ῥωμαίων, οὐ κατεπειγόμενοι συμμαχίας οὐδ’ ἀγωνιῶντες ἁπλῶς οὐδένα κατὰ τὸ παρὸν πλὴν αὐτῶν τῶν Ῥωμαίων, ἀλλὰ βουλόμενοι κατὰ τὴν ὑπέρθεσιν τῆς ἐπιβολῆς ἀφαιρεῖσθαι τὰς ὑπονοίας τῶν δυσχερές τι διανοουμένων περὶ τῆς πόλεως. ἄρτι δὲ τῶν περὶ τὸν Θεαίδητον καταπεπλευκότων, ἀπέστησαν Καύνιοι, κατελάβοντο δὲ καὶ Μυλασεῖς τὰς ἐν Εὐρώμῳ πόλεις. κατὰ δὲ τὸν αὐτὸν καιρὸν ἡ σύγκλητος ἐξέβαλε δόγμα διότι δεῖ Κᾶρας καὶ Λυκίους ἐλευθέρους εἶναι πάντας, ὅσους προσένειμε Ῥοδίοις μετὰ τὸν Ἀντιοχικὸν πόλεμον. τὰ μὲν οὖν κατὰ τοὺς Καυνίους καὶ τοὺς Εὐρωμεῖς ταχέως οἱ Ῥόδιοι διωρθώσαντο· τοὺς μὲν γὰρ Καυνίους Λύκωνα πέμψαντες μετὰ στρατιωτῶν ἠνάγκασαν πάλιν ὑφ’ αὑτοὺς τάττεσθαι, καίπερ Κιβυρατῶν αὐτοῖς παραβοηθησάντων, ἐπὶ δὲ τὰς ἐν Εὐρώμῳ πόλεις στρατεύσαντες ἐνίκησαν μάχῃ Μυλασεῖς καὶ Ἀλαβανδεῖς, ἀμφοτέρων παραγενομένων μετὰ στρατιᾶς ἐπ’ Ὀρθωσίαν. τοῦ δὲ περὶ τῶν Λυκίων καὶ Καρῶν δόγματος αὐτοῖς προσπεσόντος, πάλιν ἀπεσοβήθησαν ταῖς διανοίαις, δείσαντες μή ποτε μάταιος μὲν αὐτοῖς ἡ τοῦ στεφάνου δόσις γέγονε, μάταιοι δ’ αἱ περὶ τῆς συμμαχίας ἐλπίδες.", "st": "30.5"}, {"sp": "N", "t": "ὅτι φησὶ Πολύβιος· πρότερον ἐπιστήσαντες τοὺς ἀναγινώσκοντας ἐπὶ τὴν περὶ Δείνωνος καὶ Πολυαράτου διάληψιν· μεγάλης γὰρ οὔσης τῆς περιστάσεως καὶ τῆς μεταβολῆς οὐ μόνον παρὰ τοῖς Ῥοδίοις, ἀλλὰ σχεδὸν ἁπάσαις ταῖς πολιτείαις, χρήσιμον ἂν εἴη τὸ τὰς προαιρέσεις τῶν παρ’ ἑκάστοις πολιτευομένων ἐπισκέψασθαι καὶ γνῶναι τίνες φανήσονται τὸ κατὰ λόγον πεποιηκότες καὶ τίνες παραπεπαικότες τοῦ καθήκοντος, ἵνα οἱ ἐπιγινόμενοι, ὡσανεὶ τύπων ἐκτιθεμένων, δύνωνται κατὰ τὰς ὁμοίας περιστάσεις τὰ μὲν αἱρετὰ διώκειν, τὰ δὲ φευκτὰ φεύγειν ἀληθινῶς, καὶ μὴ περὶ τὸν ἔσχατον καιρὸν τῆς ζωῆς ἀβλεπτοῦντες τὸ πρέπον καὶ τὰς ἐν τῷ προγεγονότι βίῳ πράξεις ταὐτὸν πάθωσιν. συνέβαινε τοιγαροῦν τρεῖς διαφορὰς γενέσθαι τῶν ἐμπεσόντων εἰς τὰς αἰτίας κατὰ τὸν πρὸς Περσέα πόλεμον. ὧν μία μὲν ἦν τῶν οὐχ ἡδέως μὲν ὁρώντων κρινόμενα τὰ ὅλα καὶ τὴν τῆς οἰκουμένης ἐξουσίαν ὑπὸ μίαν ἀρχὴν πίπτουσαν, οὔτε δὲ συνεργούντων οὔτ’ ἀντιπραττόντων ἁπλῶς Ῥωμαίοις οὐδέν, ἀλλ’ οἷον ἐπιτετραφότων τῇ τύχῃ περὶ τῶν ἀποβησομένων· ἑτέρα δὲ τῶν ἡδέως ὁρώντων κρινόμενα τὰ πράγματα καὶ βουλομένων νικᾶν τὸν Περσέα, μὴ δυναμένων δὲ συνεπισπᾶσθαι τοὺς ἰδίους πολίτας καὶ τοὺς ὁμοεθνεῖς πρὸς τὴν αὑτῶν γνώμην· τρίτη δὲ καὶ τῶν συνεπισπασαμένων καὶ μεταρριψάντων τὰ πολιτεύματα πρὸς τὴν Περσέως συμμαχίαν.", "st": "30.6"}, {"sp": "N", "t": "πῶς οὖν ἕκαστοι τούτων ἐχείρισαν τὰ καθ’ αὑτοὺς σκοπεῖν πάρεστιν. μετέρριψαν πρὸς Περσέα τὸ τῶν Μολοττῶν ἔθνος Ἀντίνους καὶ Θεόδοτος καὶ Κέφαλος μετ’ αὐτῶν· οἳ τῶν πραγμάτων ἀντιπεσόντων ταῖς ἐπιβολαῖς αὐτῶν ὁλοσχερῶς, καὶ περιστάντος τοῦ κινδύνου, καὶ συνεγγίζοντος τοῦ δεινοῦ, πάντες ὁμόσε χωρήσαντες τοῖς παροῦσιν ἀπέθανον γενναίως. διόπερ ἄξιον ἐπαινεῖν τοὺς ἄνδρας ἐπὶ τῷ μὴ προέσθαι μηδὲ περιιδεῖν σφᾶς αὐτοὺς εἰς ἀναξίαν διάθεσιν ἐμπεσόντας τοῦ προγεγονότος βίου. καὶ μὴν ἐν Ἀχαΐᾳ καὶ παρὰ Θετταλοῖς καὶ Περραιβοῖς ἔσχον αἰτίαν καὶ πλείους διὰ τὴν ἡσυχίαν, ὡς ἐφεδρεύοντες τοῖς καιροῖς καὶ φρονοῦντες τὰ Περσέως. ἀλλ’ οὔτε λόγον ἐν τῷ μέσῳ τοιοῦτον ἐξέβαλον οὔτε γράφοντες οὔτε διαπεμπόμενοι πρὸς τὸν Περσέα περί τινος ἐφωράθησαν, ἀλλὰ διεφύλαξαν ἀνεπιλήπτους ἑαυτούς. τοιγαροῦν εἰκότως οὗτοι καὶ δικαιολογίαν καὶ κρίσιν ὑπέμενον καὶ πάσας ἐξήλεγχον τὰς ἐλπίδας· οὐ γὰρ ἔλαττόν ἐστιν ἀγεννίας σημεῖον τὸ μηδὲν αὑτῷ συνειδότα μοχθηρὸν προεξάγειν ἐκ τοῦ ζῆν αὑτόν, ποτὲ μὲν τὰς τῶν ἀντιπολιτευομένων ἀνατάσεις καταπλαγέντα, ποτὲ δὲ τὴν τῶν κρατούντων ἐξουσίαν, τοῦ παρὰ τὸ καθῆκον φιλοζωεῖν. καὶ μὴν ἐν Ῥόδῳ καὶ Κῷ καὶ πλείοσιν ἑτέραις πόλεσιν ἐγένοντό τινες οἱ φρονοῦντες τὰ Περσέως, οἳ καὶ λέγειν ἐθάρρουν περὶ Μακεδόνων ἐν τοῖς ἰδίοις πολιτεύμασι καὶ κατηγορεῖν μὲν Ῥωμαίων καὶ καθόλου συνίστασθαι πρὸς τὸν Περσέα κοινοπραγίαν, οὐ δυνηθέντες δὲ μεταρρῖψαι τὰ πολιτεύματα πρὸς τὴν τοῦ βασιλέως συμμαχίαν. τούτων δ’ ἦσαν ἐπιφανέστατοι παρὰ μὲν τοῖς Κῴοις Ἱππόκριτος καὶ Διομέδων ἀδελφοί, παρὰ δὲ Ῥοδίοις Δείνων καὶ Πολυάρατος.", "st": "30.7"}, {"sp": "N", "t": "ὧν τίς οὐκ ἂν καταμέμψαιτο τὴν προαίρεσιν; οἳ πρῶτον μὲν τοὺς πολίτας συνίστορας ἔχοντες πάντων τῶν σφίσι πεπραγμένων καὶ τῶν εἰρημένων, ἔπειτα δὲ τῶν γραμμάτων ἑαλωκότων καὶ πεφωτισμένων καὶ τῶν παρὰ τοῦ Περσέως πρὸς ἐκείνους διαπεμπομένων καὶ τῶν πρὸς τὸν Περσέα παρ’ ἐκείνων, ἅμα δὲ καὶ τῶν ἀνθρώπων ὑποχειρίων γεγονότων τῶν διαπεμπομένων παρ’ ἑκατέρων καὶ πρὸς ἑκατέρους, οὐχ οἷοί τ’ ἦσαν εἴκειν οὐδ’ ἐκποδὼν ποιεῖν ἑαυτούς, ἀλλ’ ἀκμὴν ἠμφισβήτουν. τοιγαροῦν προσκαρτεροῦντες καὶ φιλοζωοῦντες πρὸς ἀπεγνωσμένας ἐλπίδας καὶ τὸ δοκοῦν εἶναι περὶ αὐτοὺς τολμηρὸν καὶ παράβολον ἀνέτρεψαν, ὥστε παρὰ τοῖς ἐπιγινομένοις μηδ’ ἔσχατον ἐλέῳ καὶ συγγνώμῃ τόπον καταλιπεῖν. ἐλεγχόμενοι γὰρ κατὰ πρόσωπον ὑπὸ τῶν ἰδίων χειρογράφων καὶ τῶν ὑπουργῶν οὐ μόνον ἀτυχεῖν, ἔτι δὲ μᾶλλον ἀναισχυντεῖν ἔδοξαν. Θόας γάρ τις ἦν τῶν πλοϊζομένων, ὃς καὶ πολλάκις εἰς τὴν Μακεδονίαν ἐπεπλεύκει, διαπεσταλμένος ὑπὸ τῶν προειρημένων. οὗτος ἐν τῇ μεταβολῇ τῶν πραγμάτων συνειδὼς αὑτῷ τὰ πεπραγμένα, δείσας ἀπεχώρησεν εἰς τὴν Κνίδον. τῶν δὲ Κνιδίων αὐτὸν εἰς φυλακὴν ἀποθεμένων, ἐξαιτηθεὶς ὑπὸ τῶν Ῥοδίων ἦλθεν εἰς τὴν Ῥόδον. κἀκεῖ διὰ τῶν βασάνων ἐλεγχόμενος ἀνθωμολογεῖτο καὶ σύμφωνος ἦν πᾶσι τοῖς ἐκ τῶν αἰχμαλώτων γραμμάτων συνθήμασιν, ὁμοίως δὲ καὶ ταῖς ἐπιστολαῖς ταῖς παρά τε τοῦ Περσέως ἀποστελλομέναις πρὸς τὸν Δείνωνα καὶ Πολυάρατον καὶ παρὰ τούτων πρὸς ἐκεῖνον. ἐξ ὧν θαυμάζειν ἦν τίνι ποτὲ λογισμῷ χρώμενος ὁ Δείνων προσανεῖχε τῷ ζῆν καὶ τὸν παραδειγματισμὸν ὑπέμενε τοῦτον.", "st": "30.8"}, {"sp": "N", "t": "πολὺ δὲ κατὰ τὴν ἀβουλίαν καὶ κατὰ τὴν ἀγεννίαν ὁ Πολυάρατος ὑπερέθετο τὸν Δείνωνα. τοῦ γὰρ Ποπιλίου προστάξαντος Πτολεμαίῳ τῷ βασιλεῖ τὸν Πολυάρατον ἀναπέμπειν εἰς τὴν Ῥώμην, ὁ βασιλεὺς εἰς μὲν τὴν Ῥώμην οὐκ ἔκρινε πέμπειν, ἐντρεπόμενος τὴν πατρίδα καὶ τὸν Πολυάρατον, εἰς δὲ τὴν Ῥόδον ἀποστέλλειν διέλαβε, κἀκείνου τοῦτο παρακαλοῦντος. παραστήσας οὖν λέμβον καὶ παραδοὺς αὐτὸν Δημητρίῳ τινὶ τῶν φίλων ἐξαπέστειλεν. ἔγραφε δὲ καὶ τοῖς Ῥοδίοις ὑπὲρ τῆς ἐκπομπῆς. ὁ δὲ Πολυάρατος προσσχὼν Φασηλίδι κατὰ πλοῦν καὶ διανοηθεὶς ἅττα δή ποτ’ οὖν, λαβὼν θαλλοὺς κατέφυγεν ἐπὶ τὴν κοινὴν ἑστίαν. ὃν εἴ τις ἤρετο τί βούλεται, πέπεισμαι μηδ’ ἂν αὐτὸν ἔχειν εἰπεῖν. εἰ μὲν γὰρ εἰς τὴν πατρίδα μολεῖν ἐπεθύμει, τί θαλλῶν ἔδει; τοῦτο γὰρ προύκειτό που τοῖς ἄγουσιν αὐτόν. εἰ δ’ εἰς τὴν Ῥώμην, καὶ μὴ βουλομένου ’κείνου τοῦτ’ ἔδει γενέσθαι κατ’ ἀνάγκην. τί οὖν κατελείπεθ’ ἕτερον; ἄλλος γὰρ τόπος ὁ δεξόμενος αὐτὸν μετ’ ἀσφαλείας οὐκ ἦν. οὐ μὴν ἀλλὰ τῶν Φασηλιτῶν πεμψάντων εἰς τὴν Ῥόδον καὶ παρακαλούντων κομίζεσθαι καὶ παραλαμβάνειν τὸν Πολυάρατον, νουνεχῶς οἱ Ῥόδιοι διαλαβόντες ἄφρακτον μὲν ἐξαπέστειλαν τὸ παραπέμψον, ἀναλαβεῖν δ’ εἰς τὴν ναῦν ἐκώλυσαν τὸν ἄρχοντα διὰ τὸ προστετάχθαι τοῖς ἐκ τῆς Ἀλεξανδρείας εἰς Ῥώμην ἀποκαταστῆσαι τὸν ἄνθρωπον. παραγενομένης δὲ τῆς νεὼς εἰς τὴν Φασηλίδα, καὶ τοῦ μὲν Ἐπιχάρους, ὃς ἦν ἄρχων τῆς νεώς, οὐ βουλομένου δέχεσθαι τῷ πλοίῳ τὸν ἄνθρωπον, τοῦ δὲ Δημητρίου τοῦ προχειρισθέντος ὑπὸ τοῦ βασιλέως διὰ τὴν ἀναπομπὴν κελεύοντος ἀνίστασθαι καὶ πλεῖν αὐτόν, καὶ τῶν Φασηλιτῶν συνεπισχυόντων αὐτῷ διὰ τὸ δεδιέναι μή τις ἐκ Ῥωμαίων σφίσι διὰ ταῦτα μέμψις ἐπακολουθήσῃ, καταπλαγεὶς τὴν περίστασιν ἐνέβη πάλιν τὸν λέμβον πρὸς τὸν Δημήτριον. κατὰ δὲ τὸν ἀπόπλουν ἐπιλαβόμενος ἀφορμῆς εὐκαίρου, προσδραμὼν κατέφυγε πάλιν εἰς Καῦνον κἀκεῖ παραπλησίως ἐδεῖτο τῶν Καυνίων βοηθεῖν. τούτων δὲ πάλιν ἀποτριβομένων αὐτὸν διὰ τὸ τάττεσθαι μετὰ Ῥοδίων, διεπέμπετο πρὸς Κιβυράτας, δεόμενος αὐτὸν δέξασθαι τῇ πόλει καὶ πέμψαι παραπομπήν. ἔσχε γὰρ ἀφορμὴν πρὸς τὴν πόλιν διὰ τὸ τεθράφθαι παρ’ αὐτῷ τοὺς παῖδας Παγκράτους τοῦ τυράννου. τῶν δὲ πεισθέντων καὶ ποιησάντων τὰ παρακαλούμενα, παραγενόμενος εἰς τὴν Κιβύραν εἰς ἀπορίαν ἐνέβαλεν αὑτόν τε καὶ τοὺς Κιβυράτας μείζω τῆς πρότερον, ὅτε παρὰ τοῖς Φασηλίταις ἦν. οὔτε γὰρ ἔχειν παρ’ αὑτοῖς ἐθάρρουν αὐτὸν διὰ τὸ δεδιέναι τὸν ἀπὸ Ῥωμαίων κίνδυνον, οὔτ’ ἀναπέμπειν εἰς τὴν Ῥώμην ἐδύναντο διὰ τὴν ἀπειρίαν τῶν κατὰ θάλατταν ἔργων, ἅτε μεσόγαιοι τελέως ὑπάρχοντες. λοιπὸν ἠναγκάζοντο πρεσβεύειν εἰς τὴν Ῥόδον καὶ πρὸς τὸν στρατηγὸν εἰς Μακεδονίαν, ἀξιοῦντες παραλαβεῖν τὸν ἄνθρωπον. τοῦ δὲ Λευκίου γράψαντος τοῖς μὲν Κιβυράταις τηρεῖν ἐπιμελῶς τὸν Πολυάρατον καὶ κομίζειν εἰς τὴν Ῥόδον, τοῖς δὲ Ῥοδίοις φροντίζειν τῆς κατὰ θάλατταν παραπομπῆς, ἵνα μετ’ ἀσφαλείας εἰς τὴν Ῥωμαίων ἀνακομισθῇ, πειθαρχησάντων δ’ ἀμφοτέρων τοῖς γραφομένοις, τούτῳ τῷ τρόπῳ συνέβη τὸν Πολυάρατον ἐλθεῖν εἰς τὴν Ῥώμην, ἐκθεατρίσαντα μὲν τὴν ἀβουλίαν τὴν αὑτοῦ καὶ τὴν ἀγεννίαν ἐφ’ ὅσον οἷός τ’ ἦν, ἔκδοτον δὲ γενόμενον οὐ μόνον παρὰ Πτολεμαίου τοῦ βασιλέως, ἀλλὰ καὶ παρὰ Φασηλιτῶν καὶ παρὰ Κιβυρατῶν καὶ παρὰ Ῥοδίων διὰ τὴν ἰδίαν ἄνοιαν. τίνος οὖν χάριν τὸν πλείω λόγον πεποίημαι περὶ Πολυαράτου καὶ Δείνωνος; οὐχ ἵνα συνεπεμβαίνειν δόξω ταῖς ἐκείνων ἀτυχίαις. καὶ γὰρ ἄτοπόν γε τοῦτο τελέως· ἀλλ’ ἵνα φανερὰν ποιήσας τὴν ἐκείνων ἀβουλίαν βέλτιον παρασκευάσω καὶ βουλεύεσθαι καὶ φρονεῖν τοὺς κατὰ τὰς περιστάσεις εἰς παραπλησίους ἐμπίπτοντας καιρούς. —", "st": "30.9"}, {"sp": "N", "t": "ἐξ ὧν μάλιστα κατίδοι τις ἂν ἅμα τὴν ὀξύτητα καὶ τὴν ἀβεβαιότητα τῆς τύχης, ὅταν ἃ μάλιστ’ ἄν τις αὑτοῦ χάριν οἴηται διαπονεῖν, ταῦτα παρὰ πόδας εὑρίσκηται τοῖς ἐχθροῖς κατασκευάζων· κίονας γὰρ κατεσκεύαζε Περσεύς, καὶ ταύτας καταλαβὼν ἀτελεῖς Λεύκιος Αἰμίλιος ἐτελείωσε καὶ τὰς ἰδίας εἰκόνας ἐπέστησεν. — ὁ δὲ θαυμάσας τὴν τῆς πόλεως θέσιν καὶ τὴν τῆς ἀκροπόλεως εὐκαιρίαν πρός τε τοὺς ἐντὸς Ἰσθμοῦ καὶ πρὸς τοὺς ἐκτὸς ἀπολαμβανομένους τόπους. — Ἐπισημηνάμενος δὲ τοῦ Σικυῶνος τὴν ὀχυρότητα καὶ τὸ βάρος τῆς τῶν Ἀργείων πόλεως ἦλθεν εἰς Ἐπίδαυρον. — πάλαι μετέωρος ὢν πρὸς τὴν τῆς Ὀλυμπίας θέαν ὥρμησε. — Πολύβιος· Λεύκιος Αἰμίλιος παρῆν εἰς τὸ τέμενος τὸ ἐν Ὀλυμπίᾳ, καὶ τὸ ἄγαλμα θεασάμενος ἐξεπλάγη καὶ τοσοῦτον εἶπεν ὅτι μόνος αὐτῷ δοκεῖ Φειδίας τὸν παρ’ Ὁμήρῳ Δία μεμιμῆσθαι, διότι μεγάλην ἔχων προσδοκίαν τῆς Ὀλυμπίας μείζω τῆς προσδοκίας εὑρηκὼς εἴη τὴν ἀλήθειαν. —", "st": "30.10"}, {"sp": "N", "t": "ὅτι Αἰτωλοὶ τὸν βίον ἀπὸ λῃστείας καὶ τῆς τοιαύτης παρανομίας εἰώθεισαν ἔχειν. καὶ ἕως μὲν ἐξῆν τοὺς Ἕλληνας φέρειν καὶ λεηλατεῖν, ἐκ τούτων ἐπορίζοντο τοὺς βίους, πᾶσαν γῆν ἡγούμενοι πολεμίαν· μετὰ δὲ ταῦτα Ῥωμαίων ἐπιστάντων τοῖς πράγμασι κωλυθέντες τῆς ἔξωθεν ἐπικουρίας εἰς ἑαυτοὺς κατήντησαν. καὶ πρότερον μὲν κατὰ τὸν ἐμφύλιον πόλεμον οὐκ ἔστιν ὃ τῶν δεινῶν οὐκ ἔπραξαν· βραχεῖ δ’ ἀνώτερον χρόνῳ γεγευμένοι τοῦ φόνου τοῦ κατ’ ἀλλήλων ἐν ταῖς κατὰ τὴν Ἀρσινοΐαν σφαγαῖς ἕτοιμοι πρὸς πᾶν ἦσαν, ἀποτεθηριωμένοι τὰς ψυχάς, ὥστε μηδὲ βουλὴν διδόναι τοῖς προεστῶσι. διόπερ ἦν ἀκρισίας καὶ παρανομίας καὶ φόνου πλήρη τὰ κατὰ τὴν Αἰτωλίαν, καὶ τῶν πραττομένων παρ’ αὐτοῖς ἐκ λογισμοῦ μὲν καὶ προθέσεως οὐδὲν ἐπετελεῖτο, πάντα δ’ εἰκῇ καὶ φύρδην ἐπράττετο, καθαπερεὶ λαίλαπός τινος ἐκπεπτωκυίας εἰς αὐτούς. —", "st": "30.11"}, {"sp": "N", "t": "ὅτι οἱ κατὰ τὴν Ἤπειρον παραπλήσια τούτοις ἔπραττον. ἐφ’ ὅσον γὰρ οἱ πολλοὶ τῶν ἀνθρώπων μετριώτεροι τῶν κατὰ τὴν Αἰτωλίαν ἦσαν, ἐπὶ τοσοῦτον ὁ προεστὼς αὐτῶν ἀσεβέστερος καὶ παρανομώτερος ὑπῆρχε τῶν ἄλλων. δοκῶ γὰρ μὴ γεγονέναι μηδ’ ἔσεσθαι θηριωδέστερον ἄνθρωπον μηδ’ εἰκαιότερον Χάροπος. —", "st": "30.12"}, {"sp": "N", "t": "ὅτι μετὰ τὴν τοῦ Περσέως κατάλυσιν ἅμα τῷ κριθῆναι τὰ ὅλα πανταχόθεν ἐξέπεμπον πρέσβεις συγχαρησομένους τοῖς στρατηγοῖς ἐπὶ τοῖς γεγονόσιν. τῶν δὲ πραγμάτων ὁλοσχερῶς ἐπὶ Ῥωμαίους κεκλικότων, ἐπιπολάζοντες διὰ τὸν καιρὸν οἱ δοκοῦντες εἶναι φίλοι Ῥωμαίων ἐν πᾶσι τοῖς πολιτεύμασιν, εἴς τε τὰς πρεσβείας οὗτοι καθίσταντο καὶ τὰς ἄλλας χρείας. διὸ συνέδραμον εἰς τὴν Μακεδονίαν ἐκ μὲν Ἀχαΐας Καλλικράτης, Ἀριστόδαμος, Ἀγησίας, Φίλιππος, ἐκ δὲ Βοιωτίας οἱ περὶ Μνάσιππον, ἐκ δὲ τῆς Ἀκαρνανίας οἱ περὶ Χρέμαν, παρὰ δὲ τῶν Ἠπειρωτῶν οἱ περὶ τὸν Χάροπα καὶ Νικίαν, παρὰ δὲ τῶν Αἰτωλῶν οἱ περὶ τὸν Λυκίσκον καὶ Τίσιππον. ἁπάντων δὲ τούτων ὁμοῦ γενομένων καὶ πρὸς τὴν αὐτὴν ὑπόθεσιν ἁμιλλωμένων προθύμως, καὶ μηδενὸς ὑπάρχοντος ἀνταγωνιστοῦ διὰ τὸ τοὺς ἀντιπολιτευομένους ἅπαντας εἴκοντας τοῖς καιροῖς ἀνακεχωρηκέναι τελέως, ἀκονιτὶ κατεκράτησαν τῆς ὑποθέσεως οἱ προειρημένοι. πρὸς μὲν οὖν τὰς ἄλλας πόλεις καὶ τὰς ἐθνικὰς συστάσεις οἱ δέκα δι’ αὐτῶν τῶν στρατηγῶν ἐποιήσαντο τὴν ἐπιταγήν, οὓς δεήσει πορεύεσθαι τῶν ἀνδρῶν εἰς τὴν Ῥώμην. οὗτοι δ’ ἦσαν ὡς ἐπίπαν οὓς ἀπέγραψαν οἱ προειρημένοι κατὰ τὰς ἰδίας ἀντιπαραγωγάς, πλὴν ὀλίγων τελέως τῶν ἔκδηλόν τι πεποιηκότων. πρὸς δὲ τὸ τῶν Ἀχαιῶν ἔθνος πρεσβευτὰς ἐξέπεμψαν τοὺς ἐπιφανεστάτους ἄνδρας τῶν δέκα, Γάιον Κλαύδιον καὶ Γνάιον Δομέτιον, διὰ δύ’ αἰτίας, πρῶτον μὲν εὐλαβούμενοι τοὺς Ἀχαιοὺς μή ποτ’ οὐ πειθαρχήσωσι τοῖς γραφομένοις, ἀλλὰ καὶ κινδυνεύσωσιν οἱ περὶ τὸν Καλλικράτην, δόξαντες ἐξειργάσθαι τὰς κατὰ πάντων τῶν Ἑλλήνων διαβολάς, ὃ κατ’ ἀλήθειαν ἦν, δεύτερον δὲ διὰ τὸ μηθὲν ἐν τοῖς αἰχμαλώτοις γράμμασιν ἀκριβὲς εὑρῆσθαι κατὰ μηδενὸς τῶν Ἀχαιῶν. περὶ μὲν οὖν τούτων μετά τινα χρόνον ἐξέπεμπεν ὁ στρατηγὸς τὰς ἐπιστολὰς καὶ τοὺς πρέσβεις, καίπερ οὐκ εὐδοκούμενος κατά γε τὴν αὑτοῦ γνώμην ταῖς τῶν περὶ τὸν Λυκίσκον καὶ Καλλικράτην διαβολαῖς, ὡς ἐξ αὐτῶν τῶν πραγμάτων ὕστερον ἐγένετο καταφανές. —", "st": "30.13"}, {"sp": "N", "t": "Λεύκιος δὲ Ἀνίκιος, καὶ αὐτὸς Ῥωμαίων στρατηγήσας, Ἰλλυριοὺς καταπολεμήσας καὶ αἰχμάλωτον ἀγαγὼν Γένθιον τὸν τῶν Ἰλλυριῶν βασιλέα σὺν τοῖς τέκνοις, ἀγῶνας ἐπιτελῶν τοὺς ἐπινικίους ἐν τῇ Ῥώμῃ παντὸς γέλωτος ἄξια πράγματα ἐποίησεν, ὡς Πολύβιος ἱστορεῖ ἐν τῇ τριακοστῇ. μεταπεμψάμενος γὰρ τοὺς ἐκ τῆς Ἑλλάδος ἐπιφανεστάτους τεχνίτας καὶ σκηνὴν κατασκευάσας μεγίστην ἐν τῷ κίρκῳ πρώτους εἰσῆγεν αὐλητὰς ἅμα πάντας. οὗτοι δ’ ἦσαν Θεόδωρος ὁ Βοιώτιος, Θεόπομπος, Ἕρμιππος, [ὁ] Λυσίμαχος, οἵτινες ἐπιφανέστατοι ἦσαν. τούτους οὖν στήσας ἐπὶ τὸ προσκήνιον μετὰ τοῦ χοροῦ αὐλεῖν ἐκέλευσεν ἅμα πάντας. τῶν δὲ διαπορευομένων τὰς κρούσεις μετὰ τῆς ἁρμοζούσης κινήσεως προσπέμψας οὐκ ἔφη καλῶς αὐτοὺς αὐλεῖν, ἀλλ’ ἀγωνίζεσθαι μᾶλλον ἐκέλευσεν. τῶν δὲ διαπορούντων ὑπέδειξέν τις τῶν ῥαβδούχων ἐπιστρέψαντας ἐπαγαγεῖν ἐφ’ αὑτοὺς καὶ ποιεῖν ὡσανεὶ μάχην. ταχὺ δὲ συννοήσαντες οἱ αὐληταὶ καὶ λαβόντες οἰκείαν ταῖς ἑαυτῶν ἀσελγείαις μεγάλην ἐποίησαν σύγχυσιν. συνεπιστρέψαντες δὲ τοὺς μέσους χοροὺς πρὸς τοὺς ἄκρους οἱ μὲν αὐληταὶ φυσῶντες ἀδιανόητα καὶ διαφέροντες τοὺς αὐλοὺς ἐπῆγον ἀνὰ μέρος ἐπ’ ἀλλήλους. ἅμα δὲ τούτοις ἐπικτυποῦντες οἱ χοροὶ καὶ συνεπεισιόντες τὴν σκηνὴν ἐπεφέροντο τοῖς ἐναντίοις καὶ πάλιν ἀνεχώρουν ἐκ μεταβολῆς. ὡς δὲ καὶ περιζωσάμενός τις τῶν χορευτῶν ἐκ τοῦ καιροῦ στραφεὶς ἦρε τὰς χεῖρας ἀπὸ πυγμῆς πρὸς τὸν ἐπιφερόμενον αὐλητήν, τότ’ ἤδη κρότος ἐξαίσιος ἐγένετο καὶ κραυγὴ τῶν θεωμένων. ἔτι δὲ τούτων ἐκ παρατάξεως ἀγωνιζομένων ὀρχησταὶ δύο εἰσήγοντο μετὰ συμφωνίας εἰς τὴν ὀρχήστραν, καὶ πύκται τέτταρες ἀνέβησαν ἐπὶ τὴν σκηνὴν μετὰ σαλπιγκτῶν καὶ βυκανιστῶν. ὁμοῦ δὲ τούτων πάντων ἀγωνιζομένων ἄλεκτον ἦν τὸ συμβαῖνον. περὶ δὲ τῶν τραγῳδῶν, φησὶν ὁ Πολύβιος, ὅ,τι ἂν ἐπιβάλωμαι λέγειν, δόξω τισὶ διαχλευάζειν.", "st": "30.14"}, {"sp": "N", "t": "ὅτι τῆς αὐτῆς ψυχῆς ἐστιν ἀγῶνάς τε διατίθεσθαι καλῶς καὶ παρασκευὴν καὶ πότον μεγαλομερῆ χειρίσαι δεόντως καὶ παρατάξασθαι τοῖς πολεμίοις στρατηγικῶς. —", "st": "30.15"}, {"sp": "N", "t": "τῶν γοῦν Ἠπειρωτῶν ἑβδομήκοντα πόλεις Πολύβιός φησιν ἀνατρέψαι Παῦλον μετὰ τὴν Μακεδόνων καὶ Περσέως κατάλυσιν· Μολοττῶν δ’ ὑπάρξαι τὰς πλείστας· πέντε δὲ καὶ δέκα μυριάδας ἀνθρώπων ἐξανδραποδίσασθαι.", "st": "30.16"}, {"sp": "N", "t": "ὅτι κατὰ τὴν Αἴγυπτον οἱ βασιλεῖς ἀπολελυμένοι τοῦ πρὸς Ἀντίοχον πολέμου πρῶτον μὲν εἰς Ῥώμην πρεσβευτὴν ἐξέπεμψαν Νουμήνιον, ἕνα τῶν φίλων, εὐχαριστήσοντα περὶ τῶν εἰς αὐτοὺς γεγονότων εὐεργετημάτων· ἀπέλυσαν δὲ καὶ τὸν Λακεδαιμόνιον Μεναλκίδαν, ἐνεργῶς κεχρημένον τοῖς κατὰ τῆς βασιλείας καιροῖς πρὸς τὴν ἰδίαν ἐπανόρθωσιν, Γαΐου Ποπιλίου τὴν ὑπὲρ τῆς ἀπολύσεως χάριν αἰτησαμένου παρὰ τῶν βασιλέων.", "st": "30.17"}, {"sp": "N", "t": "ὅτι κατὰ τὸν καιρὸν τοῦτον Κότυς ὁ τῶν Ὀδρυσῶν βασιλεὺς ἀπέστειλε πρεσβευτὰς εἰς τὴν Ῥώμην, ἀξιῶν ἀποδοθῆναι τὸν υἱὸν αὑτῷ καὶ περὶ τῆς γενομένης πρὸς Περσέα κοινοπραγίας δικαιολογούμενος. οἱ δὲ Ῥωμαῖοι νομίσαντες ἠνύσθαι σφίσι τὸ προκείμενον, τοῦ πρὸς τὸν Περσέα πολέμου κατὰ νοῦν προκεχωρηκότος, τὴν δὲ πρὸς Κότυν διαφορὰν πρὸς οὐδὲν ἔτι διατείνειν, συνεχώρησαν αὐτῷ κομίζεσθαι τὸν υἱόν, ὃς ὁμηρείας χάριν δοθεὶς εἰς Μακεδονίαν ἑαλώκει μετὰ τῶν Περσέως τέκνων, βουλόμενοι τὴν αὑτῶν πρᾳότητα καὶ μεγαλοψυχίαν ἐμφαίνειν, ἅμα δὲ καὶ τὸν Κότυν ἀναδούμενοι διὰ τῆς τοιαύτης χάριτος. —", "st": "30.18"}, {"sp": "N", "t": "ὅτι κατὰ τὸν αὐτὸν καιρὸν ἦλθε καὶ Προυσίας ὁ βασιλεὺς εἰς τὴν Ῥώμην, συγχαρησόμενος τῇ συγκλήτῳ καὶ τοῖς στρατηγοῖς ἐπὶ τοῖς γεγονόσιν. ὁ δὲ Προυσίας οὗτος οὐδαμῶς γέγονεν ἄξιος τοῦ τῆς βασιλείας προσχήματος. τεκμήραιτο δ’ ἄν τις ἐκ τούτων. ὅς γε πρῶτον μέν, πρεσβευτῶν παραγεγονότων Ῥωμαϊκῶν πρὸς αὐτόν, ἐξυρημένος τὴν κεφαλὴν καὶ πιλίον ἔχων λευκὸν καὶ τήβενναν καὶ καλικίους ἀπήντα τούτοις, καὶ καθόλου τοιαύτῃ διασκευῇ κεχρημένος οἵαν ἔχουσιν οἱ προσφάτως ἠλευθερωμένοι παρὰ Ῥωμαίοις, οὓς καλοῦσι λιβέρτους· καὶ δεξιωσάμενος τοὺς πρεσβευτάς \"ὁρᾶτ’\" ἔφη \"τὸν ὑμέτερον λίβερτον ἐμέ, πάντα βουλόμενον χαρίζεσθαι καὶ μιμεῖσθαι τὰ παρ’ ὑμῖν.\" ἧς ἀγεννεστέραν φωνὴν οὐ ῥᾴδιον εὑρεῖν. τότε δὲ κατὰ τὴν εἴσοδον γενόμενος τὴν εἰς τὴν σύγκλητον, στὰς κατὰ τὸ θύρετρον ἀντίος τοῦ συνεδρίου καὶ καθεὶς τὰς χεῖρας ἀμφοτέρας προσεκύνησε τὸν οὐδὸν καὶ τοὺς καθημένους, ἐπιφθεγξάμενος \"χαίρετε, θεοὶ σωτῆρες\", ὑπερβολὴν οὐ καταλιπὼν ἀνανδρίας, ἅμα δὲ καὶ γυναικισμοῦ καὶ κολακείας οὐδενὶ τῶν ἐπιγινομένων. ἀκόλουθα δὲ τούτοις καὶ κατὰ τὴν κοινολογίαν εἰσελθὼν ἐπετελέσατο, περὶ ὧν καὶ τὸ γράφειν ἀπρεπὲς ἦν. φανεὶς δὲ τελέως εὐκαταφρόνητος ἀπόκρισιν ἔλαβε δι’ αὐτὸ τοῦτο φιλάνθρωπον.", "st": "30.19"}, {"sp": "N", "t": "ἤδη δὲ τούτου τὰς ἀποκρίσεις εἰληφότος, προσέπεσε παραγίνεσθαι τὸν Εὐμένη. τοῦτο δὲ τὸ πρᾶγμα πολλὴν ἀπορίαν παρέσχε τοῖς ἐν τῷ συνεδρίῳ· διαβεβλημένοι γὰρ πρὸς αὐτὸν καὶ διαλήψεις ἀμεταθέτους ἔχοντες οὐκ ἐβούλοντο κατ’ οὐδένα τρόπον ἐμφανίζειν αὑτούς. πᾶσι γὰρ ἀναδεδειχότες πρῶτον καὶ μέγιστον φίλον τὸν βασιλέα τοῦτον ἔμελλον εἰς ὄψιν ἐλθόντες καὶ προσδεξάμενοι δικαιολογίαν, εἰ μὲν τὸ δοκοῦν ἀποκριθεῖεν ἀκολουθοῦντες ταῖς ἰδίαις διαλήψεσιν, ἐκθεατριεῖν αὑτούς, εἰ τοιοῦτον ἄνθρωπον ἐπὶ τοσοῦτον ἐξετίμησαν ἐν τοῖς ἀνώτερον χρόνοις, εἰ δὲ δουλεύοντες τῇ τῶν ἐκτὸς φαντασίᾳ φιλανθρώπως ἀποκριθεῖεν, παρόψεσθαι τὴν ἀλήθειαν καὶ τὸ τῇ πατρίδι συμφέρον. διόπερ ἐξ ἑκατέρας τῆς ἀποφάσεως μέλλοντος ἀπιθάνου τινὸς αὐτοῖς ἐξακολουθήσειν, εὕροντο λύσιν τοῦ προβλήματος τοιαύτην. ὡς γὰρ καθόλου δυσαρεστούμενοι ταῖς τῶν βασιλέων ἐπιδημίαις δόγμα τι τοιοῦτον ἐξέβαλον, μηδένα βασιλέα παραγίνεσθαι πρὸς αὑτούς. μετὰ δὲ ταῦτα πυθόμενοι τὸν Εὐμένη καταπεπλευκέναι τῆς Ἰταλίας εἰς Βρεντέσιον ἐπαπέστειλαν τὸν ταμίαν φέροντα τὸ δόγμα καὶ κελεύσοντα λέγειν πρὸς αὑτόν, εἴ τι τυγχάνει τῆς συγκλήτου χρείαν ἔχων· εἰ δὲ μηδενὸς δεῖται, παραγγελοῦντα τὴν ταχίστην αὐτὸν ἐκ τῆς Ἰταλίας ἀπαλλάττεσθαι. ὁ δὲ βασιλεύς, συμμίξαντος αὐτῷ τοῦ ταμίου, γνοὺς τὴν τῆς συγκλήτου προαίρεσιν εἰς τέλος ἀπεσιώπησεν, οὐδενὸς φήσας προσδεῖσθαι. καὶ δὴ τούτῳ τῷ τρόπῳ συνέβη τὸν Εὐμένη κωλυθῆναι τῆς εἰς τὴν Ῥώμην ἀναβάσεως. συνηκολουθήκει δὲ καὶ ἕτερόν τι πραγματικὸν τούτῳ τῷ διαβουλίῳ. μεγάλου γὰρ ὑπὸ τῶν Γαλατῶν ἐπικρεμαμένου κινδύνου τῇ βασιλείᾳ, προφανὲς ἦν ὅτι διὰ τὸν σκυβαλισμὸν τοῦτον οἱ μὲν τοῦ βασιλέως σύμμαχοι ταπεινωθήσονται πάντες, οἱ δὲ Γαλάται διπλασίως ἐπιρρωσθήσονται πρὸς τὸν πόλεμον. διὸ πάντῃ πάντως βουλόμενοι ταπεινοῦν αὐτὸν ἐπὶ ταύτην κατηνέχθησαν τὴν γνώμην. τούτων δὲ γινομένων ἔτι κατ’ ἀρχὰς τοῦ χειμῶνος, λοιπὸν ἡ σύγκλητος ἅπασιν τοῖς παραγεγονόσι κατὰ πρεσβείαν· οὐ γὰρ ἦν οὔτε πόλις οὔτε δυνάστης οὔτε βασιλεὺς ὃς οὐκ ἀπεστάλκει πρεσβείαν κατ’ ἐκεῖνον τὸν καιρὸν τὴν συγχαρησομένην ἐπὶ τοῖς γεγονόσιν· οἷς ἅπασιν οἰκείως ἀπήντησε καὶ φιλανθρώπως πλὴν τῶν Ῥοδίων. τούτους δὲ παρέπεμπε ποικίλας ἐμφάσεις ποιοῦσα περὶ τοῦ μέλλοντος. ἐπείχετο δὲ καὶ τὰ κατὰ τοὺς Ἀθηναίους. —", "st": "30.20"}, {"sp": "N", "t": "ὅτι οἱ Ἀθηναῖοι παρεγένοντο πρεσβεύοντες τὸ μὲν πρῶτον ὑπὲρ τῆς Ἁλιαρτίων σωτηρίας, παρακουόμενοι δὲ περὶ τούτου τοῦ μέρους ἐκ μεταθέσεως διελέγοντο περὶ Δήλου καὶ Λήμνου καὶ τῆς τῶν Ἁλιαρτίων χώρας, εἰς ἑαυτοὺς ἐξαιτούμενοι τὴν κτῆσιν· εἶχον γὰρ διττὰς ἐντολάς. οἷς περὶ μὲν τῶν κατὰ Δῆλον καὶ Λῆμνον οὐκ ἄν τις ἐπιτιμήσειε διὰ τὸ καὶ πρότερον ἀντιπεποιῆσθαι τῶν νήσων τούτων, περὶ δὲ τῆς τῶν Ἁλιαρτίων χώρας εἰκότως ἄν τις καταμέμψαιτο. τὸ γὰρ πόλιν σχεδὸν ἀρχαιοτάτην τῶν κατὰ τὴν Βοιωτίαν ἐπταικυῖαν μὴ συνεπανορθοῦν κατὰ πάντα τρόπον, τὸ δ’ ἐναντίον ἐξαλείφειν, ἀφαιρουμένους καὶ τὰς εἰς τὸ μέλλον ἐλπίδας τῶν ἠκληρηκότων, δῆλον ὡς οὐδενὶ μὲν ἂν δόξαι τῶν Ἑλλήνων καθήκειν, ἥκιστα δὲ τῶν ἄλλων Ἀθηναίοις. τὸ γὰρ τὴν μὲν ἰδίαν πατρίδα κοινὴν ποιεῖν ἅπασιν, τὰς δὲ τῶν ἄλλων ἀναιρεῖν, οὐδαμῶς οἰκεῖον ἂν φανείη τοῦ τῆς πόλεως ἤθους. πλὴν ἥ γε σύγκλητος καὶ τὴν Δῆλον αὐτοῖς ἔδωκε καὶ τὴν Λῆμνον καὶ τὴν τῶν Ἁλιαρτίων χώραν. καὶ τὰ μὲν κατὰ τοὺς Ἀθηναίους τοιαύτην ἔσχε διάθεσιν. — καὶ τὴν μὲν Λῆμνον καὶ τὴν Δῆλον κατὰ τὴν παροιμίαν τὸν λύκον τῶν ὤτων ἔλαβον· πολλὰ γὰρ ὑπέμειναν δυσκληρήματα συμπλεκόμενοι τοῖς Δηλίοις· ἐκ δὲ τῆς τῶν Ἁλιαρτίων χώρας ὄνειδος αὐτοῖς μᾶλλον ἢ καρπός τις συνεξηκολούθησεν. —", "st": "30.21"}, {"sp": "N", "t": "ὅτι κατὰ τὸν καιρὸν τοῦτον Θεαίδητος εἰσελθὼν εἰς τὴν σύγκλητον λόγους μὲν ἐποιήσατο περὶ τῆς συμμαχίας· ὑπερθεμένης δὲ τῆς συγκλήτου τὸ διαβούλιον, οὗτος μὲν μετήλλαξε τὸν βίον κατὰ φύσιν· ἔτη γὰρ εἶχε πλείω τῶν ὀγδοήκοντα· παραγενομένων δὲ φυγάδων ἔκ τε Καύνου καὶ Στρατονικείας εἰς τὴν Ῥώμην καὶ παρελθόντων εἰς τὴν σύγκλητον, ἐγένετο δόγμα Ῥοδίους ἐξάγειν τὰς φρουρὰς ἔκ τε Καύνου καὶ Στρατονικείας. οἱ δὲ περὶ τὸν Φιλόφρονα καὶ Ἀστυμήδην λαβόντες ταύτην τὴν ἀπόκρισιν ἀπέπλευσαν κατὰ σπουδὴν εἰς τὴν οἰκείαν, δεδιότες μὴ παρακούσαντες οἱ Ῥόδιοι περὶ τοῦ τὰς φρουρὰς ἐξαγαγεῖν αὖθις ἄλλην ἀρχὴν ἐγκλημάτων ποιήσωσιν. —", "st": "30.22"}, {"sp": "N", "t": "ὅτι κατὰ τὴν Πελοπόννησον, παραγενομένων τῶν πρεσβευτῶν καὶ διασαφούντων τὰ κατὰ τὰς ἀποκρίσεις, οὐκέτι θόρυβος ἦν, ἀλλ’ ὀργὴ καὶ μῖσος ἐκφανὲς πρὸς τοὺς περὶ τὸν Καλλικράτην. — ὅτι τοῦ περὶ Καλλικράτην μίσους καὶ Ἀνδρωνίδαν καὶ τοὺς λοιποὺς τοὺς ὁμογνώμονας τούτων οὕτως ἄν τις τεκμήραιτο. τῆς γὰρ τῶν Ἀντιγονείων πανηγύρεως ἐν τῷ Σικυῶνι συντελουμένης, καὶ τῶν βαλανείων ἁπάντων ἐχόντων τάς τε κοινὰς μάκτρας καὶ πυέλους ταύταις παρακειμένας, εἰς ἃς οἱ κομψότεροι τῶν ἀνθρώπων εἰώθασι κατ’ ἰδίαν ἐμβαίνειν, εἰς ταύτας ὅτε τις καθείη τῶν περὶ τὸν Ἀνδρωνίδαν καὶ Καλλικράτην, οὐδεὶς ἐτόλμα τῶν ἐφεστώτων ἔτι καθιέναι, πρὶν ἢ τὸν βαλανείτην τὸ μὲν ὑπάρχον ὕδωρ ἀφεῖναι πᾶν, ἕτερον δὲ καθαρὸν ἐγχέαι. τοῦτο δ’ ἐποίουν, ὑπολαμβάνοντες ὡσανεὶ μιαίνεσθαι καθιέντες εἰς ταὐτὸ τοῖς προειρημένοις ὕδωρ. τοὺς δὲ συριγμοὺς τοὺς ἐν ταῖς κοιναῖς πανηγύρεσι τῶν Ἑλλήνων καὶ τοὺς χλευασμούς, ὅτε τις ἐπιβάλοιτο κηρύττειν τινὰ τῶν προειρημένων, οὐδ’ ἂν ἐξηγήσαιτο ῥᾳδίως οὐδείς. ἐθάρρει δὲ καὶ τὰ παιδάρια κατὰ τὰς ὁδοὺς ἐκ τῶν διδασκαλείων ἐπανάγοντα κατὰ πρόσωπον αὐτοὺς προδότας ἀποκαλεῖν. τοιαύτη τις ὑπέδραμε προσκοπὴ καὶ μῖσος κατὰ τῶν προειρημένων.", "st": "30.23"}, {"sp": "N", "t": "ὅμοιοι γὰρ ἦσαν οἱ τὴν Περαίαν κατοικοῦντες τοῖς οἰκέταις τοῖς ἐκ τῶν δεσμῶν ἀνελπίστως λελυμένοις, οἵτινες ἀπιστοῦντες τοῖς παροῦσι μείζω μὲν διαβαίνουσι τῆς κατὰ φύσιν κινήσεως, οὐ δοκοῦσι δὲ γινώσκεσθαι παρὰ τοῖς ἀπαντῶσιν οὐδὲ συνορᾶσθαι διότι λέλυνται σαφῶς, ἐὰν μή τι παράλογον ποιῶσι καὶ τῶν ἄλλων ἐξηλλαγμένον.", "st": "30.24"}, {"sp": "HDR", "t": "Βιβλίον ΛΑʹ", "st": "31"}, {"sp": "N", "t": "ὅτι ἐξεπολέμησαν κατὰ τὸν καιρὸν τοῦτον Κνώσιοι μετὰ Γορτυνίων πρὸς τοὺς Ῥαυκίους καὶ συνθήκας ἐποιήσαντο πρὸς ἀλλήλους ἐνόρκους μὴ πρότερον λύσειν τὸν πόλεμον πρὶν ἢ κατὰ κράτος ἑλεῖν τὴν Ῥαῦκον. οἱ δὲ Ῥόδιοι κομισάμενοι τὰ περὶ τῶν Καυνίων καὶ θεωροῦντες οὐ καταλήγουσαν τὴν ὀργὴν τῶν Ῥωμαίων, ἐπειδὴ περὶ πάντων ἀκολούθως ταῖς ἀποκρίσεσιν ἐπειθάρχησαν, εὐθέως τοὺς περὶ Ἀριστοτέλην πρεσβευτὰς καταστήσαντες ἐξέπεμπον εἰς τὴν Ῥώμην, δόντες ἐντολὰς πειράζειν πάλιν περὶ τῆς συμμαχίας. οἳ καὶ παραγενηθέντες εἰς τὴν Ῥώμην θερείας ἀκμαζούσης εἰσῆλθον εἰς τὴν σύγκλητον καὶ παραυτίκα περὶ τοῦ πεπειθαρχηκέναι τὸν δῆμον τοῖς ἐπιταττομένοις διεσάφουν καὶ παρεκάλουν ὑπὲρ τῆς συμμαχίας, πολλοὺς καὶ ποικίλους διατιθέμενοι λόγους. ἡ δὲ σύγκλητος ἔδωκεν ἀπόκρισιν, ἐν ᾗ τὴν μὲν φιλίαν παρεσιώπησε, περὶ δὲ τῆς συμμαχίας οὐκ ἔφη καθήκειν αὑτῇ τοῦτο συγχωρεῖν Ῥοδίοις κατὰ τὸ παρόν. —", "st": "31.1"}, {"sp": "N", "t": "ὅτι τοῖς παρὰ τῶν ἐκ τῆς Ἀσίας Γαλατῶν πρεσβευταῖς συνεχώρησαν τὴν αὐτονομίαν μένουσιν ἐν ταῖς ἰδίαις κατοικίαις καὶ μὴ στρατευομένοις ἐκτὸς τῶν ἰδίων ὅρων.", "st": "31.2"}, {"sp": "N", "t": "ὁ δ’ αὐτὸς οὗτος βασιλεὺς ἀκούσας τοὺς ἐν τῇ Μακεδονίᾳ συντετελεσμένους ἀγῶνας ὑπὸ Αἰμιλίου Παύλου τοῦ Ῥωμαίων στρατηγοῦ, βουλόμενος τῇ μεγαλοδωρίᾳ ὑπερᾶραι τὸν Παῦλον ἐξέπεμψε πρέσβεις καὶ θεωροὺς εἰς τὰς πόλεις καταγγελοῦντας τοὺς ἐσομένους ἀγῶνας ὑπ’ αὐτοῦ ἐπὶ Δάφνης, ὡς πολλὴν γενέσθαι τῶν Ἑλλήνων σπουδὴν εἰς τὴν ὡς αὐτὸν ἄφιξιν. ἀρχὴν δ’ ἐποιήσατο τῆς πανηγύρεως τὴν πομπείαν οὕτως ἐπιτελεσθεῖσαν. καθηγοῦντό τινες Ῥωμαϊκὸν ἔχοντες καθοπλισμὸν ἐν θώραξιν ἁλυσιδωτοῖς, ἄνδρες ἀκμάζοντες ταῖς ἡλικίαις πεντακισχίλιοι· μεθ’ οὓς Μυσοὶ πεντακισχίλιοι. συνεχεῖς δ’ ἦσαν Κίλικες εἰς τὸν τῶν εὐζώνων τρόπον καθωπλισμένοι τρισχίλιοι, χρυσοῦς ἔχοντες στεφάνους. ἐπὶ δὲ τούτοις Θρᾷκες τρισχίλιοι καὶ Γαλάται πεντακισχίλιοι. τούτοις ἐπέβαλλον Μακεδόνες δισμύριοι καὶ χαλκάσπιδες πεντακισχίλιοι, ἄλλοι δὲ ἀργυράσπιδες, οἷς ἐπηκολούθει μονομάχων ζεύγη διακόσια τετταράκοντα. τούτων κατόπιν ἦσαν ἱππεῖς Νισαῖοι μὲν χίλιοι πολιτικοὶ δὲ τρισχίλιοι, ὧν οἱ μὲν πλείους ἦσαν χρυσοφάλαροι καὶ χρυσοστέφανοι, οἱ δ’ ἄλλοι ἀργυροφάλαροι. μετὰ δὲ τούτους ἦσαν οἱ λεγόμενοι Ἑταῖροι ἱππεῖς· οὗτοι δὲ ἦσαν εἰς χιλίους, πάντες χρυσοφάλαροι. τούτοις συνεχὲς ἦν τὸ τῶν φίλων σύνταγμα, ἴσον καὶ κατὰ τὸ πλῆθος καὶ κατὰ τὸν κόσμον. ἐπὶ δὲ τούτοις ἐπίλεκτοι χίλιοι, οἷς ἐπηκολούθει τὸ καλούμενον ἄγημα, κράτιστον εἶναι δοκοῦν σύστημα τῶν ἱππέων, περὶ χιλίους. τελευταία δ’ ἦν ἡ κατάφρακτος ἵππος, οἰκείως τῇ προσηγορίᾳ τῶν ἵππων καὶ τῶν ἀνδρῶν ἐσκεπασμένων τοῖς ὅπλοις· ἦσαν δὲ καὶ αὐτοὶ χίλιοι καὶ πεντακόσιοι. πάντες δ’ οἱ προειρημένοι εἶχον πορφυρᾶς ἐφαπτίδας, πολλοὶ δὲ καὶ διαχρύσους καὶ ζῳωτάς. ἐπὶ δὲ τούτοις ἕξιππα μὲν ἦν ἑκατόν, τέθριππα δὲ τετταράκοντα, ἔπειτα ἐλεφάντων ἅρμα καὶ συνωρίς. καθ’ ἕνα δὲ εἵποντο ἐλέφαντες διεσκευασμένοι τριάκοντα καὶ ἕξ. τὴν δ’ ἄλλην πομπὴν λέγειν ἐστὶ δυσέφικτον, ὡς ἐν κεφαλαίῳ δὲ λεκτέον. ἔφηβοι μὲν γὰρ ἐπόμπευσαν εἰς ὀκτακοσίους, χρυσοῦς ἔχοντες στεφάνους, βόες δ’ εὐτραφεῖς περὶ χιλίους, θεωρίδες δὲ βραχὺ λείπουσαι τριακοσίων, ἐλεφάντων δὲ ὀδόντες ὀκτακόσιοι. τὸ δὲ τῶν ἀγαλμάτων πλῆθος οὐ δυνατὸν ἐξηγήσασθαι· πάντων γὰρ τῶν παρ’ ἀνθρώποις λεγομένων ἢ νομιζομένων θεῶν ἢ δαιμόνων, προσέτι δὲ ἡρώων εἴδωλα διήγετο, τὰ μὲν κεχρυσωμένα, τὰ δ’ ἠμφιεσμένα στολαῖς διαχρύσοις. καὶ πᾶσι τούτοις οἱ προσήκοντες μῦθοι κατὰ τὰς παραδεδομένας ἱστορίας ἐν διασκευαῖς πολυτελέσι παρέκειντο. εἵπετο δ’ αὐτοῖς καὶ Νυκτὸς εἴδωλον καὶ Ἡμέρας, Γῆς τε καὶ Οὐρανοῦ, καὶ Ἠοῦς καὶ Μεσημβρίας. τὸ δὲ τῶν χρυσωμάτων καὶ ἀργυρωμάτων πλῆθος οὕτως ἄν τις ὑπονοήσειεν ὅσον ἦν· ἑνὸς γὰρ τῶν φίλων, Διονυσίου τοῦ ἐπιστολιαγράφου, χίλιοι παῖδες ἐπόμπευσαν ἀργυρώματα ἔχοντες, ὧν οὐδὲν ἐλάττον’ ὁλκὴν εἶχεν δραχμῶν χιλίων. βασιλικοὶ δὲ παῖδες παρῆλθον ἑξακόσιοι χρυσώματα ἔχοντες. ἔπειτα γυναῖκες ἐκ χρυσῶν καλπίδων μύροις ἔρραινον, εἰς διακοσίας. ταύταις δ’ ἑξῆς ἐπόμπευον ἐν χρυσόποσι μὲν φορείοις ὀγδοήκοντα γυναῖκες, ἐν ἀργυρόποσι δὲ πεντακόσιαι καθήμεναι, πολυτελῶς διεσκευασμέναι. καὶ τῆς μὲν πομπῆς τὰ ἐπιφανέστατα ταῦτα ἦν.", "st": "31.3"}, {"sp": "N", "t": "ἐπιτελεσθέντων δὲ τῶν ἀγώνων καὶ μονομαχιῶν καὶ κυνηγεσίων κατὰ τριάκονθ’ ἡμέρας, ἐν αἷς τὰς θέας συνετέλει, πέντε μὲν τὰς πρώτας ἐν τῷ γυμνασίῳ πάντες ἐκ χρυσῶν ὁλκείων ἠλείφοντο κροκίνῳ μύρῳ. ἦν δὲ ταῦτα πεντεκαίδεκα, καὶ κινναμωμίνου τὰ ἴσα καὶ ναρδίνου. παραπλησίως δὲ καὶ ταῖς ἑξῆς εἰσεφέρετο τήλινον, ἀμαράκινον, ἴρινον, πάντα διαφέροντα ταῖς εὐωδίαις. ἔστρωτο δὲ εἰς εὐωχίαν ποτὲ μὲν χίλια τρίκλινα, ποτὲ δὲ χίλια πεντακόσια μετὰ τῆς πολυτελεστάτης διασκευῆς.", "st": "31.4"}, {"sp": "N", "t": "ὅτι μετὰ τὴν συντέλειαν τῶν ἀγώνων, ἄρτι τούτων γεγονότων, ἧκον οἱ περὶ τὸν Τεβέριον πρεσβευταί, κατασκόπων ἔχοντες τάξιν. οἷς οὕτως ἐπιδεξίως ἀπήντησεν Ἀντίοχος καὶ φιλοφρόνως ὥστε μὴ οἷον τοὺς περὶ τὸν Τεβέριον ὑποπτεῦσαί τι περὶ αὐτοῦ πραγματικὸν ἢ παρατριβῆς ἔμφασιν ἔχον ἐκ τῶν κατὰ τὴν Ἀλεξάνδρειαν, ἀλλὰ καὶ τῶν λεγόντων τι τοιοῦτον καταγινώσκειν διὰ τὴν ὑπερβολὴν τῆς κατὰ τὴν ἀπάντησιν φιλανθρωπίας· ὅς γε πρὸς τοῖς ἄλλοις καὶ τῆς αὐλῆς παρεχώρησε τοῖς πρεσβευταῖς, μικροῦ δὲ καὶ τοῦ διαδήματος κατὰ τὴν ἐπίφασιν, καίπερ οὐκ ὢν τῇ προαιρέσει τοιοῦτος, ἀλλὰ τοὐναντίον ἀλλοτριώτατα διακείμενος πρὸς Ῥωμαίους.", "st": "31.5"}, {"sp": "N", "t": "ὅτι εἰς τὴν Ῥώμην παραγεγονότων πρεσβευτῶν πλειόνων καὶ ἑτέρων, ἐπιφανεστάτων δὲ παρὰ μὲν Ῥοδίων τῶν περὶ Ἀστυμήδην, παρὰ δὲ τῶν Ἀχαιῶν τῶν περὶ Εὐρέαν καὶ Ἀναξίδαμον καὶ Σάτυρον, παρὰ δὲ Προυσίου τῶν περὶ Πύθωνα, τούτοις ἐχρημάτισεν ἡ σύγκλητος. οἱ μὲν οὖν παρὰ τοῦ Προυσίου κατηγορίαν ἐποιοῦντ’ Εὐμένους τοῦ βασιλέως, φάσκοντες αὑτῶν τέ τινα χωρία παραιρεῖσθαι τὸν Εὐμένη καὶ τῆς Γαλατίας οὐκ ἀφίστασθαι τὸ παράπαν οὐδὲ πειθαρχεῖν τοῖς τῆς συγκλήτου δόγμασιν, ἀλλὰ τοὺς τὰ σφέτερα μὲν φρονοῦντας σωματοποιεῖν, τοὺς δὲ τὰ Ῥωμαίων αἱρουμένους καὶ βουλομένους πολιτεύεσθαι τοῖς τῆς συγκλήτου δόγμασιν ἀκολούθως κατὰ πάντα τρόπον ἐλαττοῦν. ἦσαν δέ τινες πρεσβευταὶ καὶ παρὰ τῶν τῆς Ἀσίας πόλεων, οἳ κατηγόρουν τοῦ βασιλέως, ἔμφασιν ποιοῦντες τῆς πρὸς τὸν Ἀντίοχον κοινοπραγίας. ἡ δὲ σύγκλητος διακούσασα τῶν κατηγορούντων οὔτ’ ἀπέρριπτε τὰς διαβολὰς οὔτ’ ἐξέφαινε τὴν ἑαυτῆς γνώμην, ἀλλὰ συνετήρει παρ’ ἑαυτῇ, διαπιστοῦσα καθόλου τοῖς περὶ τὸν Εὐμένη καὶ τὸν Ἀντίοχον· τοῖς γε μὴν Γαλάταις ἀεί τι προσετίθει καὶ συνεπίσχυε περὶ τῆς ἐλευθερίας. οἱ δὲ περὶ τὸν Τεβέριον ἥκοντες ἀπὸ τῆς πρεσβείας οὐδὲν περιττότερον ἠδυνήθησαν οὔτ’ αὐτοὶ διαλαβεῖν οὔτε τῇ συγκλήτῳ διασαφῆσαι περὶ τῶν κατὰ τὸν Εὐμένη καὶ τὸν Ἀντίοχον, ἤπερ ἃ καὶ πρότερον ὄντες ἐν τῇ Ῥώμῃ διελάμβανον. οὕτως αὐτοὺς οἱ βασιλεῖς ἐξετέμοντο τῇ κατὰ τὴν ἀπάντησιν φιλανθρωπίᾳ.", "st": "31.6"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα προσκαλεσαμένη τοὺς Ῥοδίους διήκουε τούτων. ὁ δ’ Ἀστυμήδης εἰσελθὼν μετρίως ἔστη καὶ βέλτιον ἢ κατὰ τὴν πρὸ ταύτης πρεσβείαν· ἀφέμενος γὰρ τοῦ κατηγορεῖν τῶν ἄλλων ὥρμησεν ἐπὶ τὸ παραιτεῖσθαι, καθάπερ οἱ μαστιγούμενοι τὰς πληγάς, φάσκων ἱκανοῖς προστίμοις περιπεπτωκέναι τὴν πατρίδα καὶ μείζοσι τῆς ἁμαρτίας. καὶ προσθέμενος ἐξηγεῖτο τὰς ἐλαττώσεις, κεφαλαιωδῶς διεξιών, πρῶτον μὲν ὅτι Λυκίαν καὶ Καρίαν ἀπολωλέκασιν, εἰς ἣν ἐξ ἀρχῆς μὲν ἐδαπάνησαν χρημάτων ἱκανὸν πλῆθος, τριττοὺς πολέμους ἀναγκασθέντες πολεμεῖν αὐτοῖς, νυνὶ δὲ προσόδων ἐστέρηνται πολλῶν ὧν ἐλάμβανον παρὰ τῶν προειρημένων. \"ἀλλ’ ἴσως\" ἔφη \"ταῦτα μὲν ἔχει λόγον· καὶ γὰρ ἐδώκαθ’ ὑμεῖς αὐτὰ τῷ δήμῳ, μετὰ χάριτος διὰ τὴν εὔνοιαν, καὶ ἀφανίζοντες αὐτὰ κατὰ λόγον ἐδοκεῖτε τοῦτο πράττειν, ἐμπεσούσης τινὸς ὑποψίας καὶ διαφορᾶς ὑμῖν. ἀλλὰ Καῦνον δήπου διακοσίων ταλάντων ἐξηγοράσαμεν παρὰ τῶν Πτολεμαίου στρατηγῶν καὶ Στρατονίκειαν ἐλάβομεν ἐν μεγάλῃ χάριτι παρ’ Ἀντιόχου τοῦ Σελεύκου· καὶ παρὰ τούτων τῶν πόλεων ἀμφοτέρων ἑκατὸν καὶ εἴκοσι τάλαντα τῷ δήμῳ πρόσοδος ἔπιπτε καθ’ ἕκαστον ἔτος. τούτων ἁπασῶν ἐστερήμεθα τῶν προσόδων, θέλοντες πειθαρχεῖν τοῖς ὑμετέροις προστάγμασιν. ἐξ ὧν μείζονα φόρον ἐπιτεθείκατε τοῖς Ῥοδίοις τῆς ἀγνοίας ἢ Μακεδόσι τοῖς διὰ παντὸς πολεμίοις ὑμῖν ὑπάρξασι. τὸ δὲ μέγιστον σύμπτωμα τῆς πόλεως· καταλέλυται γὰρ ἡ τοῦ λιμένος πρόσοδος ὑμῶν, Δῆλον μὲν ἀτελῆ πεποιηκότων, ἀφῃρημένων δὲ τὴν τοῦ δήμου παρρησίαν, δι’ ἧς καὶ τὰ κατὰ τὸν λιμένα καὶ τἄλλα πάντα τῆς πόλεως ἐτύγχανε τῆς ἁρμοζούσης προστασίας. ὅτι δὲ τοῦτ’ ἔστιν ἀληθὲς οὐ δυσχερὲς καταμαθεῖν· τοῦ γὰρ ἐλλιμενίου κατὰ τοὺς ἀνώτερον χρόνους εὑρίσκοντος ἑκατὸν μυριάδας δραχμῶν, νῦν ἀφῃρήκατε πεντεκαίδεκα μυριάδας, ὥστε καὶ λίαν, ὦ ἄνδρες Ῥωμαῖοι, τὴν ὑμετέραν ὀργὴν ἧφθαι τῶν κυρίων πόρων τῆς πόλεως. εἰ μὲν οὖν συμβεβήκει πάνδημον γεγονέναι τὴν ἁμαρτίαν καὶ τὴν ἀλλοτριότητα τοῦ δήμου, τάχ’ ἴσως ἐδοκεῖτε κἂν ὑμεῖς εὐλόγως ἐπίμονον καὶ δυσπαραίτητον ἔχειν τὴν ὀργήν· εἰ δὲ σαφῶς ἴστε παντάπασιν ὀλίγους γεγονότας αἰτίους τῆς τοιαύτης ἀλογίας, καὶ τούτους ἅπαντας ἀπολωλότας ὑπ’ αὐτοῦ τοῦ δήμου, τί πρὸς τοὺς μηδὲν αἰτίους ἀκαταλλάκτως ἔχετε, καὶ ταῦτα πρὸς τοὺς ἄλλους ἅπαντας εἶναι δοκοῦντες πρᾳότατοι καὶ μεγαλοψυχότατοι; διόπερ, ὦ ἄνδρες, ἀπολωλεκὼς ὁ δῆμος τὰς προσόδους, τὴν παρρησίαν, τὴν ἰσολογίαν, ὑπὲρ ὧν τὸν πρὸ τοῦ χρόνον πᾶν ἀναδεχόμενος διατετέλεκεν, ἀξιοῖ καὶ δεῖται πάντων ὑμῶν, ἱκανὰς ἔχων πληγάς, λήξαντας τῆς ὀργῆς διαλυθῆναι καὶ συνθέσθαι τὴν συμμαχίαν, ἵνα γένηται τοῦτο συμφανὲς ἅπασιν ὅτι τὴν μὲν ὀργὴν ἀποτέθεισθε τὴν πρὸς Ῥοδίους, ἀνακεχωρήκατε δ’ ἐπὶ τὴν ἐξ ἀρχῆς αἵρεσιν καὶ φιλίαν. τούτου γὰρ χρείαν ἔχει νῦν ὁ δῆμος, οὐ τῆς διὰ τῶν ὅπλων καὶ στρατιωτῶν συμμαχίας.\" ταῦτα μὲν οὖν καὶ τούτοις παραπλήσια διαλεχθεὶς Ἀστυμήδης ἐδόκει πρεπόντως τοῖς καιροῖς πεποιῆσθαι τοὺς λόγους· πλεῖστά γε μὴν συνήργησαν τοῖς Ῥοδίοις πρὸς τὸ τυχεῖν τῆς συμμαχίας οἱ περὶ τὸν Τεβέριον ἄρτι παραγεγονότες. οὗτοι γὰρ ἀπομαρτυρήσαντες πρῶτον μὲν πᾶσιν τοῖς τῆς συγκλήτου δόγμασι πεπειθαρχηκέναι τοὺς Ῥοδίους, ἔπειτα πάντας τοὺς αἰτίους τῆς ἀλλοτριότητος κατακεκρίσθαι θανάτου παρ’ αὐτοῖς, ἥττησαν τοὺς ἀντιλέγοντας καὶ ἐποιήσαντο τὴν πρὸς Ῥωμαίους συμμαχίαν. —", "st": "31.7"}, {"sp": "N", "t": "ὅτι μετά τινα χρόνον εἰσῆλθον οἱ παρὰ τῶν Ἀχαιῶν πρέσβεις, ἔχοντες ἐντολὰς ἀκολούθως ταῖς ἀποκρίσεσιν, αἷς πρότερον ἔλαβον· αὗται δ’ ἦσαν διότι θαυμάζουσιν πῶς, ὑπὲρ ὧν αὐτοὶ κεκρίκασι, περὶ τούτων αὐτοὺς παρακαλοῦσιν κρίνειν. διὸ τότε παρῆσαν οἱ περὶ τὸν Εὐρέαν, πάλιν ἐξ ἀρχῆς ἐμφανίζοντες διότι τὸ μὲν ἔθνος οὔτε δικαιολογουμένων ἀκήκοε τῶν κατῃτιαμένων οὔτε κρίσιν οὐδεμίαν πεποίηται περὶ αὐτῶν, τὴν δὲ σύγκλητον ἀξιοῖ πρόνοιαν ποιήσασθαι τῶν ἀνθρώπων, ἵνα κρίσεως τύχωσι καὶ μὴ καταφθαρῶσιν ἄκριτοι, καὶ μάλιστα μὲν αὐτὴν ἐξετάσασαν διασαφῆσαι τοὺς ἐνόχους ὄντας τοῖς ἐγκλήμασιν· εἰ δὲ διὰ τοὺς περισπασμοὺς αὐτὴ μὴ δύναται τοῦτο ποιῆσαι, τοῖς Ἀχαιοῖς ἐπιτρέψαι περὶ τοῦ πράγματος. οἳ πειράσονται μισοπονήρως χρήσασθαι τοῖς αἰτίοις. ἡ δὲ σύγκλητος διακούσασα τῶν πρεσβευτῶν, ἀκολούθως ταῖς ἐντολαῖς διαλεγομένων, καὶ δυσχρηστοῦσα διὰ τὸ πανταχόθεν ἐξελέγχεσθαι· τό τε γὰρ κρίνειν οὐκ ἐνόμιζεν αὑτῇ καθήκειν, τό τε χωρὶς κρίσεως ἀπολύειν τοὺς ἄνδρας πρόδηλον ἔχειν ἐδόκει τὸν ὄλεθρον τοῖς φίλοις αὐτῶν· διόπερ ἀναγκαζομένη καὶ βουλομένη παρελέσθαι καθόλου τὴν ἐλπίδα τῶν πολλῶν ὑπὲρ τῆς τῶν κατεχομένων σωτηρίας, ἵνα συμμύσαντες πειθαρχῶσιν ἐν μὲν Ἀχαΐᾳ τοῖς περὶ τὸν Καλλικράτην, ἐν δὲ τοῖς ἄλλοις πολιτεύμασι τοῖς δοκοῦσιν εἶναι Ῥωμαίων, ἔγραψαν ἀπόκρισιν τοιαύτην, ὅτι ἡμεῖς οὐχ ὑπολαμβάνομεν συμφέρειν οὔτε τοῖς Ῥωμαίοις οὔτε τοῖς ὑμετέροις δήμοις τούτους τοὺς ἄνδρας ἐπανελθεῖν εἰς οἶκον. ταύτης δὲ τῆς ἀποκρίσεως ἐκπεσούσης, οὐ μόνον περὶ τοὺς ἀνακεκλημένους ἐγένετό τις ὁλοσχερὴς ἀθυμία καὶ παράλυσις τῆς ψυχῆς, ἀλλὰ καὶ περὶ τοὺς Ἕλληνας ὡσανεὶ κοινόν τι πένθος, ἅτε δοκούσης τῆς ἀποκρίσεως ὁλοσχερῶς ἀφαιρεῖσθαι τὴν ἐλπίδα τῆς σωτηρίας τῶν ἀκληρούντων. κατὰ δὲ τὴν Ἑλλάδα διαγγελθείσης τῆς ἀποκρίσεως τῆς τοῖς Ἀχαιοῖς δεδομένης ὑπὲρ τῶν καταιτιαθέντων, τὰ μὲν πλήθη συνετρίβη ταῖς διανοίαις, καί τις οἷον ἀπελπισμὸς ὑπέδραμεν τοὺς ἀνθρώπους, οἱ δὲ περὶ τὸν Χάροπα καὶ Καλλικράτην καὶ πάντες οἱ τῆς αὐτῆς ὑποθέσεως προεστῶτες μετέωροι πάλιν ἐγενήθησαν.", "st": "31.8"}, {"sp": "N", "t": "ὅτι Τεβέριος τοὺς Καμμανοὺς τὰ μὲν βιασάμενος, τὰ δὲ παραλογισάμενος ὑπηκόους ἐποίησε Ῥωμαίοις. — εἰς δὲ τὴν Ῥώμην καὶ πλειόνων παραγεγονότων πρεσβευτῶν ἐχρημάτισεν ἡ σύγκλητος τοῖς περὶ Ἄτταλον καὶ τὸν Ἀθήναιον. συνέβαινε γὰρ τὸν Προυσίαν οὐ μόνον αὐτὸν ἐνεργῶς κεχρῆσθαι ταῖς διαβολαῖς ταῖς κατὰ τὸν Εὐμένη καὶ τὸν Ἀντίοχον, ἀλλὰ καὶ τοὺς Γαλάτας παρωξυκέναι καὶ τοὺς Σελγεῖς καὶ πλείους ἑτέρους κατὰ τὴν Ἀσίαν πρὸς τὴν αὐτὴν ὑπόθεσιν. ὧν χάριν ὁ βασιλεὺς Εὐμένης ἐξαπεστάλκει τοὺς ἀδελφούς, ἀπολογησομένους πρὸς τὰς ἐπιφερομένας διαβολάς. οἳ καὶ παρελθόντες εἰς τὴν σύγκλητον ἐνδεχομένως ἔδοξαν πρὸς ἅπαντας τοὺς κατηγοροῦντας ποιήσασθαι τὴν ἀπολογίαν, καὶ τέλος οὐ μόνον ἀποτριψάμενοι τὰς ἐπιφερομένας αἰτίας, ἀλλὰ καὶ τιμηθέντες ἐπανῆλθον εἰς τὴν Ἀσίαν. οὐ μὴν τῆς γε κατὰ τὸν Εὐμένη καὶ κατὰ τὸν Ἀντίοχον ὑποψίας ἔληγεν ἡ σύγκλητος, ἀλλὰ Γάιον Σολπίκιον καὶ Μάνιον Σέργιον καταστήσασα πρεσβευτὰς ἐξαπέστελλεν, ἅμα μὲν ἐποπτεύσοντας τὰ κατὰ τοὺς Ἕλληνας, ἅμα δὲ τοῖς Μεγαλοπολίταις καὶ τοῖς Λακεδαιμονίοις διευκρινήσοντας περὶ τῆς ἀντιλεγομένης χώρας, μάλιστα δὲ πολυπραγμονήσοντας τὰ κατὰ τὸν Ἀντίοχον καὶ τὰ κατὰ τὸν Εὐμένη, μή τις ἐξ αὐτῶν παρασκευὴ γίνεται καὶ κοινοπραγία κατὰ Ῥωμαίων. —", "st": "31.9"}, {"sp": "N", "t": "ὅτι Γάιος ὁ Γάλλος, χωρὶς τῶν ἄρτι ῥηθέντων ἀλογημάτων, παραγενόμενος εἰς τὴν Ἀσίαν ἐκθέματα κατὰ τὰς πόλεις ἐξέθηκε τὰς ἐπιφανεστάτας, κελεύων, εἴ τις βούλεται κατηγορεῖν Εὐμένους τοῦ βασιλέως, ἀπαντᾶν εἰς Σάρδεις ἐπίτινα χρόνον ὡρισμένον. μετὰ δὲ ταῦτα παραγενηθεὶς αὐτὸς εἰς τὰς Σάρδεις, ἀποκαθίσας ἐν τῷ γυμνασίῳ περὶ δέχ’ ἡμέρας διήκουε τῶν κατηγορούντων, πᾶσαν ἐπιδεχόμενος αἰσχρολογίαν καὶ λοιδορίαν κατὰ τοῦ βασιλέως καὶ καθόλου πᾶν ἕλκων πρᾶγμα καὶ κατηγορίαν, ἅτε παρεστηκὼς ἄνθρωπος τῇ διανοίᾳ καὶ φιλοδοξῶν ἐν τῇ πρὸς Εὐμένην διαφορᾷ. — ὅτι καθ’ ὅσον ἐδόκουν οἱ Ῥωμαῖοι βαρύτερον τῷ Εὐμένει προσφέρεσθαι, κατὰ τοσοῦτο συνέβαινε τοὺς Ἕλληνας προσοικειοῦσθαι, φύσει τῶν ἀνθρώπων ἀεὶ τῷ θλιβομένῳ τὴν εὔνοιαν προσνεμόντων. —", "st": "31.10"}, {"sp": "N", "t": "ὅτι κατὰ τὴν Συρίαν Ἀντίοχος ὁ βασιλεὺς βουλόμενος εὐπορῆσαι χρημάτων προέθετο στρατεύειν ἐπὶ τὸ τῆς Ἀρτέμιδος ἱερὸν εἰς τὴν Ἐλυμαΐδα. παραγενόμενος δ’ ἐπὶ τοὺς τόπους καὶ διαψευσθεὶς τῆς ἐλπίδος διὰ τὸ μὴ συγχωρεῖν τῇ παρανομίᾳ τοὺς βαρβάρους τοὺς οἰκοῦντας περὶ τὸν τόπον, ἀναχωρῶν ἐν Τάβαις τῆς Περσίδος ἐξέλιπε τὸν βίον, δαιμονήσας, ὡς ἔνιοί φασι, διὰ τὸ γενέσθαι τινὰς ἐπισημασίας τοῦ δαιμονίου κατὰ τὴν περὶ τὸ προειρημένον ἱερὸν παρανομίαν.", "st": "31.11"}, {"sp": "N", "t": "ὅτι Δημήτριος ὁ τοῦ Σελεύκου πολὺν ἤδη χρόνον κατεχόμενος ἐν τῇ Ῥώμῃ κατὰ τὴν ὁμηρείαν πάλαι μὲν ἐδόκει παρὰ τὸ δίκαιον κατέχεσθαι· δοθῆναι γὰρ ὑπὸ Σελεύκου τοῦ πατρὸς τῆς ἐκείνου πίστεως ἕνεκεν, Ἀντιόχου δὲ μετειληφότος τὴν βασιλείαν οὐκ ὀφείλειν ὑπὲρ τῶν ἐκείνου τέκνων ὁμηρεύειν. οὐ μὴν ἀλλὰ τὸν μὲν πρὸ τοῦ χρόνον ἦγε τὴν ἡσυχίαν, καὶ μάλιστα διὰ τὴν ἀδυναμίαν· ἦν γὰρ ἔτι παῖς· τότε δὲ τὴν ἀκμαιοτάτην ἔχων ἡλικίαν ἐποιήσατο λόγους, εἰσελθὼν εἰς τὴν σύγκλητον, ἀξιῶν καὶ παρακαλῶν κατάγειν αὑτὸν ἐπὶ τὴν βασιλείαν· καθήκειν γὰρ αὑτῷ μᾶλλον ἢ τοῖς Ἀντιόχου τέκνοις τὴν ἀρχήν. διαθεμένου δὲ καὶ πλείονας λόγους αὐτοῦ πρὸς τὴν προειρημένην ὑπόθεσιν καὶ μάλιστα προσδραμόντος ἐν τῷ λέγειν, διότι συμβαίνει καὶ πατρίδα καὶ τροφὸν τὴν Ῥώμην ὑπάρχειν αὐτῷ, καὶ τοὺς μὲν υἱοὺς τῶν ἐκ τοῦ συνεδρίου σύμπαντας ἀδελφῶν ἔχειν διάθεσιν, τοὺς δὲ βουλευτὰς πατέρων διὰ τὸ παραγενέσθαι μὲν ἔτι νήπιος, τότε δὲ κατὰ τὴν ἡλικίαν ὑπάρχειν ἐτῶν εἴκοσι καὶ τριῶν, ἐνετρέποντο μὲν ἅπαντες ἀκούοντες ἐν ἑαυτοῖς, κοινῇ γε μὴν ἔδοξε τῇ συγκλήτῳ τὸν μὲν Δημήτριον κατασχεῖν, τῷ δὲ καταλελειμμένῳ παιδὶ συγκατασκευάζειν τὴν ἀρχήν. τοῦτο δ’ ἐποίησεν, ὡς ἐμοὶ δοκεῖν, ὑπιδομένη τὴν ἀκμὴν τοῦ Δημητρίου, μᾶλλον δὲ κρίνασα συμφέρειν τοῖς σφετέροις πράγμασι τὴν νεότητα καὶ τὴν ἀδυναμίαν τοῦ παιδὸς τοῦ διαδεδεγμένου τὴν βασιλείαν. ἐγένετο δὲ τοῦτο δῆλον ἐκ τῶν μετὰ ταῦτα συμβάντων. εὐθέως γὰρ καταστήσαντες πρεσβευτὰς τοὺς περὶ Γνάιον Ὀκτάουιον καὶ Σπόριον Λοκρήτιον καὶ Λεύκιον Αὐρήλιον ἐξέπεμψαν, τοὺς διοικήσοντας τὰ κατὰ τὴν βασιλείαν, ὡς αὐτὴ προῃρεῖτο διὰ τὸ μηδένα τὸν ἐμποδὼν στησόμενον εἶναι τοῖς ἐπιταττομένοις, τοῦ μὲν βασιλέως παιδὸς ὄντος, τῶν δὲ προεστώτων ἀσμενιζόντων ἐπὶ τῷ μὴ παραδεδόσθαι τὰ πράγματα τῷ Δημητρίῳ· μάλιστα γὰρ τοῦτο προσεδόκων. οἱ μὲν οὖν περὶ τὸν Γνάιον ἐξώρμησαν, ἔχοντες ἐντολὰς πρῶτον μὲν τὰς ναῦς τὰς καταφράκτους διαπρῆσαι, μετὰ δὲ ταῦτα τοὺς ἐλέφαντας νευροκοπῆσαι καὶ καθόλου λυμήνασθαι τὴν βασίλειον δύναμιν. προσενετείλαντο δὲ τούτοις καὶ τὰ κατὰ τὴν Μακεδονίαν ἐπισκέψασθαι· συνέβαινε γὰρ τοὺς Μακεδόνας ἀήθεις ὄντας δημοκρατικῆς καὶ συνεδριακῆς πολιτείας στασιάζειν πρὸς αὑτούς. ἔδει δὲ τοὺς περὶ τὸν Γνάιον καὶ τὰ περὶ τοὺς Γαλάτας καὶ τὰ κατὰ τὴν Ἀριαράθου βασιλείαν ἐποπτεῦσαι. μετὰ δέ τινα χρόνον αὐτοῖς ἐπαπεστάλη γράμματα παρὰ τῆς συγκλήτου καὶ τοὺς ἐν Ἀλεξανδρείᾳ βασιλεῖς διαλῦσαι κατὰ δύναμιν. —", "st": "31.12"}, {"sp": "N", "t": "ὅτι κατὰ τοὺς καιροὺς τούτους παρεγένοντο πρέσβεις ἐκ τῆς Ῥώμης πρῶτον μὲν οἱ περὶ τὸν Μάρκον Ἰούνιον, διευκρινήσοντες τὰ πρὸς τοὺς Γαλάτας διαφέροντα τῷ βασιλεῖ. ἐπειδὴ γὰρ οὐκ ἠδυνήθησαν οἱ Τρόκμοι δι’ αὑτῶν ἀποτεμέσθαι τῆς Καππαδοκίας οὐδέν, ἀλλ’ ἐκ χειρὸς ᾨκοδομήσαντο τὴν δίκην ἐπιβαλόμενοι τόλμαν, καταφυγόντες ἐπὶ Ῥωμαίους διαβάλλειν ἐπειρῶντο τὸν Ἀριαράθην. ὧν χάριν ἀπεστάλησαν οἱ περὶ τὸν Ἰούνιον. πρὸς οὓς ὁ βασιλεὺς ποιησάμενος τοὺς ἁρμόζοντας λόγους καὶ τἄλλα φιλανθρώπως ὁμιλήσας ἐκείνους μὲν εὐλογοῦντας ἀπέστειλε. μετὰ δὲ ταῦτα, παραγενομένων πρεσβευτῶν τῶν περὶ Γνάιον Ὀκτάουιον καὶ Σπόριον Λοκρήτιον καὶ διαλεγομένων τῷ βασιλεῖ πάλιν περὶ τῶν πρὸς τοὺς Γαλάτας αὐτῷ διαφερόντων, βραχέα περὶ τούτων κοινολογησάμενος καὶ φήσας εὐεπάγωγος εἶναι πρὸς τὸ κριθέν, λοιπὸν ἤδη τὸν πλείω λόγον ὑπὲρ τῶν κατὰ Συρίαν ἐποιεῖτο πραγμάτων, εἰδὼς ἐκεῖσε προάγοντας τοὺς περὶ τὸν Ὀκτάουιον, ὑποδεικνύων αὐτοῖς τὴν ἀκαταστασίαν τῆς βασιλείας καὶ τὴν εἰκαιότητα τῶν προεστώτων αὐτῆς καὶ προσεπαγγελλόμενος ἀκολουθήσειν μετὰ δυνάμεως καὶ συνεφεδρεύειν τοῖς καιροῖς, ἕως ἂν ἐπανέλθωσι πάλιν ἐκ τῆς Συρίας ἀσφαλῶς. οἱ δὲ περὶ τὸν Γνάιον ἐν πᾶσιν ἀποδεχόμενοι τὴν τοῦ βασιλέως εὔνοιαν καὶ προθυμίαν κατὰ μὲν τὸ παρὸν οὐκ ἔφασαν προσδεῖσθαι τῆς παραπομπῆς, εἰς δὲ τὸ μέλλον, ἐάν τις ὑποπίπτῃ χρεία, διασαφήσειν ἀόκνως· κρίνειν γὰρ αὐτὸν ἕνα τῶν ἀληθινῶν Ῥωμαίοις φίλων. —", "st": "31.13"}, {"sp": "N", "t": "ὅτι παρεγένοντο κατὰ τὸν αὐτὸν καιρὸν παρ’ Ἀριαράθου τοῦ νεωστὶ διαδεδεγμένου τὴν Καππαδοκῶν βασιλείαν πρέσβεις, ἀνανεωσόμενοι τήν τε φιλίαν καὶ συμμαχίαν τὴν προϋπάρχουσαν, καὶ καθόλου παρακαλέσοντες τὴν σύγκλητον ἀποδέξασθαι τὴν τοῦ βασιλέως εὔνοιαν καὶ προθυμίαν, ἣν ἔχει καὶ κοινῇ καὶ κατ’ ἰδίαν πρὸς ἅπαντας Ῥωμαίους. ἡ δὲ σύγκλητος διακούσασα τῶν λόγων τήν τε φιλίαν ἀνενεώσατο καὶ τὴν συμμαχίαν καὶ καθόλου τὴν ὅλην αἵρεσιν ἀποδεξαμένη τοῦ βασιλέως φιλανθρώπως ἐγενήθη. τοῦτο δ’ ἐγένετο μάλιστα διὰ τὸ τοὺς περὶ τὸν Τεβέριον, καθ’ ὃν καιρὸν ἐξαπεστάλησαν ἐπισκεψόμενοι τὰ κατὰ τοὺς βασιλεῖς, ἐπανελθόντας εὐφήμους λόγους ποιήσασθαι περί τε τοῦ πατρὸς καὶ καθόλου τῆς βασιλείας αὐτῶν. οἷς πιστεύσαντες οἱ τοῦ συνεδρίου τούς τε πρεσβευτὰς φιλανθρώπως ἀπεδέξαντο καὶ τὴν ὅλην αἵρεσιν τοῦ βασιλέως.", "st": "31.14"}, {"sp": "N", "t": "ὅτι Ῥόδιοι διαπεπνευκότες ἐκ τῆς περὶ αὐτοὺς γενομένης δυσχερείας ἔπεμπον εἰς τὴν Ῥώμην πρεσβευτὰς τοὺς περὶ Κλεαγόραν, Κάλυνδα μὲν ἀξιώσοντας σφίσι παραχωρηθῆναι, περὶ δὲ τῶν ἐχόντων ἐν τῇ Λυκίᾳ καὶ Καρίᾳ κτήσεις αἰτησομένους τὴν σύγκλητον, ἵν’ αὐτοῖς ἔχειν ἐξῇ, καθὰ καὶ πρότερον. ἐψηφίσαντο δὲ καὶ κολοσσὸν στῆσαι τοῦ δήμου τῶν Ῥωμαίων ἐν τῷ τῆς Ἀθηνᾶς ἱερῷ τριακοντάπηχυν. —", "st": "31.15"}, {"sp": "N", "t": "ὅτι τῶν Καλυνδέων ἀποστάντων Καυνίων, καὶ μετὰ ταῦτα πολιορκεῖν ἐπιβαλομένων αὐτοὺς τῶν Καυνίων, τὰς μὲν ἀρχὰς ἐπεκαλέσαντο Κνιδίους οἱ Καλυνδεῖς· ὧν καὶ παραπεσόντων κατὰ βοήθειαν, ἐπὶ ποσὸν ἀντεῖχον τοῖς ὑπεναντίοις, ἀγωνιῶντες δὲ τὸ μέλλον πρεσβεύειν μὲν, ἐγχειρίζοντες σφᾶς αὐτοὺς καὶ τὴν πόλιν. οἱ δὲ Ῥόδιοι πέμψαντες βοήθειαν καὶ κατὰ γῆν καὶ κατὰ θάλατταν τήν τε πολιορκίαν ἔλυσαν καὶ παρέλαβον τὴν πόλιν. συνέβη δὲ καὶ τὴν σύγκλητον αὐτοῖς βεβαιῶσαι τὴν τῶν Καλυνδέων κτῆσιν.", "st": "31.16"}, {"sp": "N", "t": "ὁ δὲ Ἀριαράθης ὁ βασιλεὺς Καππαδοκίας προσδεδεγμένος τοὺς εἰς τὴν Ῥώμην ἀποσταλέντας πρεσβευτάς, νομίσας ἐκ τῶν ἀποκρίσεων ἐν ὀρθῷ κεῖσθαι τὴν βασιλείαν αὑτῷ νῦν, ἐπειδὴ καθῖκται τῆς Ῥωμαίων εὐνοίας, ἔθυε τοῖς θεοῖς χαριστήρια τῶν γεγονότων καὶ τοὺς ἡγεμόνας εἱστία. μετὰ δὲ ταῦτα πρεσβευτὰς ἀπέστειλε πρὸς τοὺς περὶ τὸν Λυσίαν εἰς τὴν Ἀντιόχειαν, σπουδάζων ἀνακομίσασθαι τὰ τῆς ἀδελφῆς καὶ μητρὸς ὀστᾶ. τὸ μὲν οὖν ἐγκαλεῖν ὑπὲρ τοῦ γεγονότος ἀσεβήματος ἀπεδοκίμαζεν, οὐ βουλόμενος ἐρεθίζειν τοὺς περὶ τὸν Λυσίαν, ἵνα μὴ διαψευσθῇ τῆς προθέσεως, καίπερ βαρέως φέρων τὸ γεγονός· ἀξιωματικὰς δὲ δοὺς ἐντολὰς ἐξαπέστειλε τοὺς πρέσβεις. τῶν δὲ περὶ τὸν Λυσίαν συγχωρησάντων, καὶ τῶν ὀστῶν ἀνακομισθέντων ὡς αὐτόν, ἀποδεξάμενος μεγαλομερῶς τὴν παρουσίαν αὐτῶν ἔθαψε παρὰ τὸν τοῦ πατρὸς τάφον κηδεμονικῶς. —", "st": "31.17"}, {"sp": "N", "t": "ὅτι Ἀρταξίας ἐβούλετο ἐπανελέσθαι παραινέσεσι δὲ Ἀριαράθου τοῦτ’ οὐκ ἔπραξεν ἀλλ’ ἐντιμότερον εἶχεν αὐτὸν ἢ πρότερον. οὕτως ἥ τε τοῦ δικαίου φύσις ἔχει μεγάλην δύναμιν, αἵ τε τῶν ἀγαθῶν ἀνδρῶν γνῶμαι καὶ παραινέσεις, ὥστε μὴ μόνον τοὺς φίλους ἀλλὰ καὶ τοὺς ἐχθροὺς πολλάκις σῴζειν καὶ μετατιθέναι τὰς φύσεις αὐτῶν πρὸς τὸ βέλτιον. — ὅτι παντὸς ἐπιστολίου τὸ κάλλος ἐστὶ συστατικώτερον.", "st": "31.17"}, {"sp": "N", "t": "ὅτι μετὰ τὸ μερίσαι τοὺς Πτολεμαίους τὴν βασιλείαν παρεγένετο Πτολεμαῖος ὁ νεώτερος εἰς τὴν Ῥώμην, ἀθετεῖν βουλόμενος τὸν γεγονότα μερισμὸν αὐτῷ πρὸς τὸν ἀδελφόν, φάσκων οὐχ ἑκών, ἀλλὰ κατ’ ἀνάγκην τῷ καιρῷ περιληφθεὶς πεποιηκέναι τὸ προσταττόμενον. καὶ παρεκάλει τὴν σύγκλητον μερίσαι τὴν Κύπρον αὑτῷ· καὶ γὰρ τούτου γενομένου καταδεεστέραν ἕξειν μερίδα τἀδελφοῦ παρὰ πολύ. τῶν δὲ περὶ τὸν Κανολήιον καὶ Κόιντον ἀπομαρτυρούντων τοῖς περὶ τὸν Μένυλλον, τοῖς παρὰ τοῦ πρεσβυτέρου παραγεγονόσι πρεσβευταῖς, διότι καὶ τὴν Κυρήνην ὁ νεώτερος καὶ τὸ πνεῦμα δι’ αὐτοὺς ἔχοι· τοιαύτην γενέσθαι τὴν τῶν ὄχλων πρὸς αὐτὸν ἀλλοτριότητα καὶ προσκοπήν· διὸ καὶ παρ’ ἐλπίδα καὶ παραδόξως δεδομένων αὐτῷ τῶν κατὰ Κυρήνην πραγμάτων ἀσμένως δέξαιτο, καὶ σφαγίων τμηθέντων καὶ λάβοι τοὺς ὅρκους παρὰ τἀδελφοῦ καὶ δοίη περὶ τούτου· τοῦ δὲ Πτολεμαίου πᾶσι τούτοις ἀντιλέγοντος, ἡ σύγκλητος, ἅμα μὲν ὁρῶσα τὸν μερισμὸν γεγονότα τελέως, ἅμα δὲ βουλομένη διελεῖν τὴν βασιλείαν πραγματικῶς, αὐτῶν αἰτίων γενομένων τῆς διαιρέσεως, συγκατέθετο τοῖς ὑπὸ τοῦ νεωτέρου παρακαλουμένοις ἐπὶ τῷ σφετέρῳ συμφέροντι. πολὺ γὰρ ἤδη τοῦτο τὸ γένος ἐστὶ τῶν διαβουλίων παρὰ Ῥωμαίοις, ἐν οἷς διὰ τῆς τῶν πέλας ἀγνοίας αὔξουσι καὶ κατασκευάζονται τὴν ἰδίαν ἀρχὴν πραγματικῶς, ἅμα χαριζόμενοι καὶ δοκοῦντες εὐεργετεῖν τοὺς ἁμαρτάνοντας. διὸ καὶ καθορῶντες τὸ μέγεθος τῆς ἐν Αἰγύπτῳ δυναστείας καὶ δεδιότες, ἄν ποτε τύχῃ προστάτου, μὴ μεῖζον φρονήσῃ τοῦ καθήκοντος, κατέστησαν πρεσβευτὰς Τίτον Τορκουᾶτον καὶ Γνάιον Μερόλαν τοὺς κατάξοντας ἐπὶ τὴν Κύπρον τὸν Πτολεμαῖον καὶ τελειώσοντας ἅμα τὴν ἐκείνων καὶ τὴν αὑτῶν πρόθεσιν. καὶ παραχρῆμα τούτους ἐξαπέστειλαν, δόντες ἐντολὰς διαλῦσαι τοὺς ἀδελφοὺς καὶ κατασκευάσαι τῷ νεωτέρῳ τὴν Κύπρον χωρὶς πολέμου. —", "st": "31.18"}, {"sp": "N", "t": "ὅτι κατὰ τὸν καιρὸν τοῦτον προσπεσούσης τῆς περὶ τὸν Γνάιον περιπετείας, ὡς ἀνῃρέθη, καὶ τῶν παρὰ τοῦ βασιλέως Ἀντιόχου πρεσβευόντων, ὧν ὁ Λυσίας ἔπεμψε, παραγεγονότων καὶ πολλοὺς διαθεμένων λόγους ὑπὲρ τοῦ μὴ κεκοινωνηκέναι τῆς πράξεως τοὺς τοῦ βασιλέως φίλους, ἡ μὲν σύγκλητος παρέπεμπε τοὺς πρεσβευτάς, οὐ βουλομένη διδόναι περὶ τούτων ἀπόφασιν οὐδεμίαν οὐδ’ ἐκτίθεσθαι καθόλου τὴν αὑτῆς γνώμην, ὁ δὲ Δημήτριος πτοηθεὶς ἐπὶ τοῖς ἠγγελμένοις ἐξ αὐτῆς προσεκάλει τὸν Πολύβιον καὶ προσανέφερεν διαπορῶν εἰ δεῖ πάλιν ἐντυχεῖν τῇ συγκλήτῳ περὶ τῶν καθ’ αὑτόν. ὁ δὲ παρεκάλει μὴ δὶς πρὸς τὸν αὐτὸν λίθον πταίειν, ἀλλ’ ἐν ἑαυτῷ τὰς ἐλπίδας ἔχειν καὶ τολμᾶν τι βασιλείας ἄξιον· πολλὰς γὰρ ὑποδεικνύειν ἀφορμὰς τοὺς ἐνεστῶτας καιρούς. ὁ δὲ Δημήτριος συννοήσας τὸ λεγόμενον τότε μὲν ἀπεσιώπησεν, μετ’ ὀλίγον δέ τινι τῶν συνήθων Ἀπολλωνίῳ μετέδωκε περὶ τῶν αὐτῶν. ὁ δὲ προειρημένος, ἄκακος ὢν καὶ κομιδῇ νέος, συνεβούλευε πεῖραν ἔτι λαβεῖν τῆς συγκλήτου· πεπεῖσθαι γάρ, ἐπεὶ τῆς βασιλείας ἀλόγως αὐτὸν ἐστέρησεν, τῆς γ’ ὁμηρείας αὐτὸν ἀπολύσειν· ἄτοπον γὰρ εἶναι τελέως, Ἀντιόχου τοῦ παιδὸς διαδεδεγμένου τὴν ἐν Συρίᾳ βασιλείαν, Δημήτριον ὁμηρεύειν ὑπὲρ αὐτοῦ. τούτοις μὲν οὖν τοῖς λόγοις πεισθεὶς πάλιν εἰσῆλθεν εἰς τὴν σύγκλητον ὁ προειρημένος καὶ παρεκάλει τῆς γε κατὰ τὴν ὁμηρείαν ἀνάγκης αὑτὸν ἀπολύειν, ἐπεὶ τὴν βασιλείαν ἔκριναν Ἀντιόχῳ συγκατασκευάζειν. καὶ πλείω δὲ πρὸς ταύτην τὴν ὑπόθεσιν αὐτοῦ διαλεχθέντος, ἔμεινεν ἡ σύγκλητος ἐπὶ τῆς αὐτῆς αἱρέσεως ὅπερ εἰκὸς ἦν. καὶ γὰρ πρότερον οὐ διὰ τὸ μὴ λέγειν τὰ δίκαια τὸν Δημήτριον ἔκρινεν τὴν ἀρχὴν τῷ παιδὶ συνδιαφυλάττειν, ἀλλὰ διὰ τὸ συμφέρειν τοῖς σφετέροις πράγμασιν, μενόντων δὲ τῶν ὅλων ἐπὶ τῆς αὐτῆς διαθέσεως μένειν εἰκὸς ἦν καὶ τὴν τῆς συγκλήτου διάληψιν ἐπὶ τῆς αὐτῆς προαιρέσεως.", "st": "31.19"}, {"sp": "N", "t": "πλὴν ὅ γε Δημήτριος μάτην ἐξᾴσας τὸ κύκνειον καὶ γνοὺς ὅτι καλῶς αὐτῷ συνεβούλευεν ὁ Πολύβιος μὴ δὶς πρὸς τὸν αὐτὸν λίθον πταίειν, μεταμεληθεὶς ἐπὶ τοῖς γεγονόσιν, ἅμα δὲ καὶ φύσει μεγαλόφρων ὑπάρχων καὶ τόλμαν ἱκανὴν ἔχων πρὸς τὸ κριθέν, εὐθέως ἐκάλει Διόδωρον προσφάτως ἐκ τῆς Συρίας παραγεγονότα καὶ μετεδίδου περὶ τῶν καθ’ αὑτόν. ὁ δὲ Διόδωρος τροφεὺς μὲν ἐγεγόνει τοῦ Δημητρίου, πανοῦργος δ’ ὢν καὶ κατωπτευκὼς ἐπιμελῶς τὰ κατὰ τὴν Συρίαν ὑπεδείκνυεν αὐτῷ, διότι τῶν μὲν ἐκεῖ τεταραγμένων διὰ τὸν Γναΐου φόνον, καὶ διαπιστούντων τῶν μὲν πολλῶν τοῖς περὶ τὸν Λυσίαν, τῶν δὲ περὶ τὸν Λυσίαν τοῖς πολλοῖς, τῆς δὲ συγκλήτου πεπεισμένης ἐκ τῶν τοῦ βασιλέως φίλων γεγονέναι τὴν εἰς τοὺς σφετέρους πρεσβευτὰς παρανομίαν, κάλλιστον εἶναι καιρὸν ἐπιφανῆναι τοῖς πράγμασιν· ταχέως γὰρ τοὺς μὲν ἐκεῖ μεταρρίψειν τὴν βασιλείαν εἰς αὐτόν, κἂν ὅλως μετὰ παιδὸς ἑνὸς ποιήσηται τὴν παρουσίαν, τὴν δὲ σύγκλητον οὐ τολμήσειν ἔτι βοηθεῖν οὐδὲ συνεπισχύειν τοῖς περὶ τὸν Λυσίαν τοιαῦτα διεργασαμένοις. λοιπὸν εἶναι τὸ λαθεῖν ἐκ τῆς Ῥώμης ἀπελθόντας, καὶ μηδένα λαβεῖν ἔννοιαν τῆς ἐπιβολῆς αὐτοῦ. δοξάντων δὲ τούτων μετεπέμπετο τὸν Πολύβιον καὶ δηλώσας τὰ δεδογμένα παρεκάλει συνεπιλαβέσθαι τῆς ἐπιβολῆς καὶ συνδιανοηθῆναι πῶς ἂν χειρισθείη τὰ κατὰ τὸν δρασμόν. συνέβαινε δὲ κατὰ τὸν καιρὸν τοῦτον Μένυλλον μὲν τὸν Ἀλαβανδέα παρεῖναι πρεσβεύοντα παρὰ τοῦ πρεσβυτέρου βασιλέως Πτολεμαίου χάριν τοῦ συγκαταστῆναι καὶ δικαιολογηθῆναι πρὸς τὸν νεώτερον Πτολεμαῖον· ἐτύγχανε δὲ προϋπάρχουσα τῷ Πολυβίῳ πρὸς τὸν Μένυλλον ἰσχυρὰ συνήθεια καὶ πίστις. διὸ καὶ νομίσας αὐτὸν ἐπιτήδειον εἶναι πρὸς τὴν ἐνεστῶσαν χρείαν συνέστησε τῷ Δημητρίῳ μετὰ μεγάλης σπουδῆς καὶ φιλοτιμίας. ὁ δὲ κοινωνήσας τῆς ἐπιβολῆς ἀνεδέξατο τήν τε ναῦν ἑτοιμάσαι καὶ τἄλλα πρὸς τὸν πλοῦν ἀπαρτιεῖν. οὗτος μὲν οὖν εὑρὼν ἐν τῷ στόματι τοῦ Τιβέριος ὁρμοῦσαν Καρχηδονίαν ναῦν ἱεραγωγόν, ταύτην ἐναυλώσατο· συμβαίνει δὲ τὰ πλοῖα ταῦτα λαμβάνεσθαι κατ’ ἐκλογὴν ἐκ τῆς Καρχηδόνος, ἐφ’ οἷς εἰς τὴν Τύρον ἐκπέμπουσιν οἱ Καρχηδόνιοι τὰς πατρίους ἀπαρχὰς τοῖς θεοῖς· ἐναυλοῦτο δὲ φανερῶς εἰς τὴν ἰδίαν ἀνακομιδήν. διὸ καὶ τήν τε τῶν ἐπιμηνίων παρασκευὴν ἀνυπόπτως ἐποιεῖτο καὶ φανερῶς ἐλάλει καὶ συνέταττε τοῖς ναυτικοῖς.", "st": "31.20"}, {"sp": "N", "t": "ἐπειδὴ δὲ πάντ’ ἦν ἕτοιμα τῷ ναυκλήρῳ λοιπόν τ’ ἔδει τὸν Δημήτριον ἀπαρτίζειν τὰ καθ’ αὑτόν, τὸν τροφέα προαπέστειλεν εἰς τὴν Συρίαν ὠτακουστήσοντα καὶ κατοπτεύσοντα τἀκεῖ συμβαίνοντα περὶ τοὺς ὄχλους. ὁ δὲ σύντροφος Ἀπολλώνιος ἐξ ἀρχῆς αὐτῷ μετεῖχε τῆς ἐπιβολῆς· δυεῖν δ’ ὑπαρχόντων ἀδελφῶν, Μελεάγρου καὶ Μενεσθέως, τούτοις ἐκοινώσατο τὴν πρᾶξιν, ἄλλῳ δ’ οὐδενὶ τῶν μετ’ αὐτοῦ, καίτοι πλειόνων ὄντων. οὗτοι δ’ ἦσαν Ἀπολλωνίου κατὰ φύσιν υἱοί, τοῦ μεγάλην μὲν εὐκαιρίαν ἔχοντος παρὰ Σελεύκῳ, μεταστάντος δὲ κατὰ τὴν Ἀντιόχου μετάληψιν τῆς ἀρχῆς εἰς Μίλητον. τῆς δὲ συνταχθείσης ἡμέρας πρὸς τοὺς ναυτικοὺς συνεγγιζούσης, ἔδει γενέσθαι παρά τινι τῶν φίλων ὑποδοχὴν πρὸς τὴν ἔξοδον. παρὰ γὰρ αὐτῷ ποιεῖν τὸ δεῖπνον οὐχ οἷόν τ’ ἦν· εἴθιστο γὰρ ἐπιμελῶς καλεῖν ἅπαντας τοὺς περὶ αὐτὸν ὄντας. οἱ δὲ συνειδότες τὴν πρᾶξιν ἔμελλον ἐξ οἴκου δειπνήσαντες ἐπὶ τὸ πλοῖον ἥξειν, ἔχοντες ἕνα παῖδα μεθ’ ἑαυτῶν ἕκαστος· τοὺς γὰρ λοιποὺς ἀπεστάλκεισαν εἰς Ἀναγνείας, κατὰ τὴν ἐπιοῦσαν αὐτοὶ παρεψόμενοι. τὸν δὲ Πολύβιον συνέβαινεν κατὰ τὸν καιρὸν τοῦτον ἠσθενηκότα μένειν κατὰ κλίνην, εἰδέναι δὲ πάντα τὰ πραττόμενα, τοῦ Μενύλλου συνεχῶς αὐτῷ μεταδιδόντος αἰεὶ περὶ τῶν ὑποπιπτόντων. διόπερ ἀγωνιάσας ὁ προειρημένος μὴ τῆς συνηθείας ἑλκυσθείσης, ἅτε τοῦ Δημητρίου συμποτικοῦ φυσικῶς καὶ νεωτέρου τελέως ὑπάρχοντος, ἀπόρημά τι γένηται περὶ τὴν ἔξοδον διὰ τὴν μέθην, γράψας βραχὺ πιττάκιον καὶ σφραγισάμενος πέμπει παρ’ αὑτοῦ παῖδα συσκοτάζοντος ἄρτι τοῦ θεοῦ, συντάξας ἐκκαλεσάμενον τὸν οἰνοχόον τοῦ Δημητρίου δοῦναι τὸ πιττάκιον, μηδὲν εἰπόντα τίς ἢ παρὰ τίνος, καὶ κελεύειν ἀποδιδόναι τῷ Δημητρίῳ παραχρῆμα διαναγνῶναι. γενομένων δὲ πάντων κατὰ τὸ συνταχθέν, λαβὼν ὁ Δημήτριος ἐπανέγνω. τὸ δὲ πιττάκιον περιεῖχε τὰς γνώμας ταύτας. ὁ δρῶν τὰ τοῦ μέλλοντος οἴχεται φέρων. ἴσον φέρει νύξ, τοῖς δὲ τολμῶσιν πλέον. τόλμα τι, κινδύνευε, πρᾶττ’, ἀποτύγχανε, ἐπίτυχε, πάντα μᾶλλον ἢ σαυτὸν προοῦ. νᾶφε καὶ μέμνασ’ ἀπιστεῖν· ἄρθρα ταῦτα τᾶν φρενῶν.", "st": "31.21"}, {"sp": "N", "t": "ταῦτα διαναγνοὺς ὁ Δημήτριος καὶ συννοήσας τὰς ὑποθέσεις, καὶ τίνες καὶ παρὰ τίνος εἰσίν, παραυτίκα προσποιηθεὶς ὡς ἐπιναύσιος γεγονὼς ἀπηλλάττετο, συμπροπεμπόντων αὐτὸν καὶ τῶν φίλων. παραγενόμενος δ’ ἐπὶ σκηνὴν τοὺς μὲν ἀνεπιτηδείους τῶν οἰκετῶν ἐξέπεμψεν εἰς τὰς Ἀναγνείας, συντάξας λαβόντας τὰ λίνα καὶ τοὺς κύνας ἀπαντᾶν ἐπὶ τὸ Κίρκαιον· ἐκεῖ γὰρ ἐπιμελῶς εἰώθει κυνηγετεῖν τὸν ὗν· ἐξ οὗ καὶ τῆς πρὸς τὸν Πολύβιον αὐτῷ συνηθείας τὴν καταρχὴν γενέσθαι συνέπεσεν. μετὰ δὲ ταῦτα τοῖς περὶ τὸν Νικάνορα διεσάφει τὴν ἐπιβολὴν καὶ κοινωνεῖν παρεκάλει τῶν αὐτῶν ἐλπίδων. πάντων δὲ προθύμως δεξαμένων τὸν λόγον, παρήγγειλε κατὰ σπουδὴν ἐπανελθόντας ἐπὶ τὰς ἰδίας καταλύσεις τοῖς μὲν παισὶν συντάξαι προάγειν ὑπὸ τὴν ἑωθινὴν εἰς τὰς Ἀναγνείας καὶ μετὰ τῶν κυνηγῶν ἀπαντᾶν εἰς τὸ Κίρκαιον, αὐτοὺς δὲ λαβόντας ἐσθῆτας τὰς ὁδοιπορικὰς ἀνακάμπτειν ὡς αὐτόν, εἰπόντας τοῖς οἰκέταις ὅτι μετὰ Δημητρίου συμμίξουσιν αὐτοῖς κατὰ τὴν ἐπιοῦσαν ἐπὶ τὸν προειρημένον τόπον. γενομένων δὲ πάντων καθὼς προείρηται, προῆγον εἰς τὴν Ὠστίαν νυκτὸς ἐπὶ τὸ στόμα τοῦ Τιβέριος. ὁ δὲ Μένυλλος προπορευόμενος ἐκοινολογεῖτο τοῖς ναυτικοῖς, φάσκων αὑτῷ προσπεπτωκέναι παρὰ τοῦ βασιλέως δι’ ὃ δέον ἐστὶν αὐτὸν μὲν μένειν κατὰ τὸ παρὸν ἐν τῇ Ῥώμῃ, τῶν δὲ νεανίσκων τοὺς πιστοτάτους ἐκπέμψαι πρὸς αὐτόν, παρ’ ὧν ἐπιγνώσεται πάντα τὰ κατὰ τὸν ἀδελφόν. διόπερ αὐτὸς μὲν οὐκ ἔφησεν ἐμβαίνειν, τοὺς δὲ νεανίσκους ἥξειν περὶ μέσας νύκτας τοὺς μέλλοντας πλεῖν. τῶν δὲ ναυκλήρων ἀδιαφορούντων διὰ τὸ μένειν αὐτοῖς τὸ ταχθὲν ναῦλον ἐξ ἀρχῆς καὶ πάντα κατηρτικότων ἐκ πολλοῦ τὰ πρὸς τὸν πλοῦν, παρῆσαν οἱ περὶ τὸν Δημήτριον κατὰ τρίτην φυλακὴν λήγουσαν, ὄντες ὀκτὼ καὶ παῖδες πέντε καὶ παιδάρια τρία. τοῦ δὲ Μενύλλου κοινολογηθέντος αὐτοῖς καὶ παραδείξαντος τὴν τῶν ἐπιμηνίων παρασκευήν, ἔτι δὲ συστήσαντος τῷ ναυκλήρῳ καὶ τοῖς ἐπιβάταις ἐκτενῶς, οὗτοι μὲν ἐπέβησαν, ὁ δὲ κυβερνήτης ἄρτι διαφαύσκοντος ἄρας τὰς ἀγκύρας ἐτέλει τὸν πλοῦν, ἁπλῶς οὐδεμίαν ἔννοιαν ἔχων τοῦ πράγματος, ἀλλ’ ὡς στρατιώτας τινὰς ἄγων παρὰ τοῦ Μενύλλου πρὸς τὸν Πτολεμαῖον.", "st": "31.22"}, {"sp": "N", "t": "ἐν δὲ τῇ Ῥώμῃ κατὰ τὴν ἐπιοῦσαν οὐδεὶς ἐπιζητήσειν ἔμελλε τὸν Δημήτριον οὐδὲ τοὺς μετ’ ἐκείνου προάγοντας· οἱ μὲν γὰρ αὐτοῦ μένοντες ὡς ἐπὶ τὸ Κίρκαιον ὡρμηκότα διελάμβανον, οἱ δ’ ἐν ταῖς Ἀναγνείαις ἀπήντων ἐπὶ τὸν αὐτὸν τόπον, ὡς ἐκεῖ παρεσόμενον. διὸ συνέβαινε τελέως ἄσημον εἶναι τὸν δρασμόν, ἕως οὗ τῶν παίδων τις μεμαστιγωμένος ἐν ταῖς Ἀναγνείαις ἔδραμεν ἐπὶ τὸ Κίρκαιον, ὡς ἐκεῖ τῷ Δημητρίῳ συμμίξων· οὐχ εὑρὼν δὲ πάλιν εἰς τὴν Ῥώμην ἔτρεχεν, ὡς κατὰ πορείαν ἀπαντήσων. οὐδαμῇ δὲ συντυχὼν αὐτῷ τοῦτο διεσάφησεν τοῖς ἐν Ῥώμῃ φίλοις καὶ τοῖς καταλελειμμένοις ἐπὶ τῆς οἰκίας. ἐπιζητουμένου δὲ τοῦ Δημητρίου κατὰ τὴν τετάρτην ἡμέραν ἀφ’ ἧς ὥρμησεν, ὑπενοήθη τὸ γεγονός. τῇ δὲ πέμπτῃ σύγκλητος εὐθέως συνήγετο περὶ τούτων, ἐν ᾗ συνέβαινε τὸν Δημήτριον ἐκτὸς ἤδη τοῦ πορθμοῦ τοῦ κατὰ Σικελίαν ὑπάρχειν. τὸ μὲν οὖν διώκειν ἀπέγνωσαν, ἅμα μὲν ὑπολαμβάνοντες αὐτὸν πολὺ προειληφέναι κατὰ τὸν πλοῦν, καὶ γὰρ ἔσχε φορὸν ἄνεμον, ἅμα δὲ προορώμενοι τὸ βουληθέντες κωλύειν ἀδυνατῆσαι· πρεσβευτὰς δὲ κατέστησαν μετά τινας ἡμέρας τοὺς περὶ Τεβέριον Γράκχον καὶ Λεύκιον Λέντλον καὶ Σερουίλιον Γλαυκίαν, οἵτινες ἔμελλον πρῶτον μὲν ἐποπτεύσειν τὰ κατὰ τοὺς Ἕλληνας, εἶτ’ ἐπιβαλόντες ἐπὶ τὴν Ἀσίαν τά τε κατὰ τὸν Δημήτριον καραδοκήσειν καὶ τὰς τῶν ἄλλων βασιλέων προαιρέσεις ἐξετάσειν καὶ τὰ πρὸς τοὺς Γαλάτας ἀντιλεγόμενα τοῖς προειρημένοις διευκρινήσειν. διὸ τὸν Τεβέριον κατεστήσαντο πάντων αὐτόπτην γεγονέναι. καὶ τὰ μὲν κατὰ τὴν Ἰταλίαν ἐν τούτοις ἦν. — ὁ δὲ Δημήτριος προσανέχων τῇ παρουσίᾳ τοῦ διαποσταλησομένου πρὸς αὐτόν.", "st": "31.23"}, {"sp": "N", "t": "ἐφ’ οἷς καὶ Μάρκος ἀγανακτῶν εἶπέ ποτε πρὸς τὸν δῆμον ὅτι μάλιστ’ ἂν κατίδοιεν τὴν ἐπὶ τὸ χεῖρον προκοπὴν τῆς πολιτείας ἐκ τούτων, ὅταν πωλούμενοι πλεῖον εὑρίσκωσιν οἱ μὲν εὐπρεπεῖς παῖδες τῶν ἀγρῶν, τὰ δὲ κεράμια τοῦ ταρίχου τῶν ζευγηλατῶν.", "st": "31.24"}, {"sp": "N", "t": "ὅτι Ῥόδιοι τἄλλα σῴζοντες τὴν τοῦ πολιτεύματος προστασίαν βραχὺ παρώλισθον ἐν τούτοις τοῖς καιροῖς, ὡς ἐμὴ δόξα· ἐπεδέξαντο γὰρ σίτου μυριάδας ὀκτὼ καὶ εἴκοσι παρ’ Εὐμένους χάριν τοῦ τὸ λογευθὲν ἐκ τούτων δανείζεσθαι, τὸν δὲ τόκον εἰς τοὺς μισθοὺς ὑπάρχειν τοῖς παιδευταῖς καὶ διδασκάλοις τῶν υἱῶν. τοῦτο δέ, στενοχωρίας μὲν ὑπαρχούσης καθάπαξ ἐπὶ τῶν κατ’ ἰδίαν βίων, ἴσως ἂν ἐπιδέξαιτό τις παρὰ τῶν φίλων ἕνεκα τοῦ μὴ περιιδεῖν ἀπαίδευτα γενόμενα τὰ τέκνα διὰ τὴν ἀπορίαν· εὐκαιρῶν δὲ τῷ βίῳ πᾶν ἄν τις ὑπομείναι μᾶλλον ἢ τὸν διδόμενον τοῖς διδασκάλοις μισθὸν ἐρανίζεσθαι παρὰ τῶν φίλων· ὅσῳ δὲ μεῖζον δεῖ πολιτείαν ἰδιώτου φρονεῖν, τοσῷδε καὶ τὸ πρέπον ἐπὶ τῶν πολιτικῶν μᾶλλον ἢ τῶν ἰδίων τηρητέον, Ῥοδίοις δὲ καὶ τελέως διά τε τὴν εὐκαιρίαν τὴν ἐν τοῖς κοινοῖς καὶ τὴν ἐπίφασιν τῆς σεμνότητος.", "st": "31.25"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα Πτολεμαῖοις ὁ νεώτερος παραγεγονὼς εἰς τὴν Ἑλλάδα μετὰ τῶν πρεσβευτῶν συνήθροιζε ξενολόγιον ἐμβριθές. ἐν οἷς προσελάβετο καὶ τὸν Μακεδόνα Δαμάσιππον, ὃς κατασφάξας ἐν τῷ Φάκῳ τοὺς συνέδρους ἔφυγεν μετὰ γυναικὸς καὶ τέκνων ἐκ τῆς Μακεδονίας. ἀφικόμενος δ’ εἰς τὴν τῶν Ῥοδίων Περαίαν καὶ ξενισθεὶς ὑπὸ τοῦ δήμου προετίθετο πλεῖν εἰς τὴν Κύπρον. οἱ δὲ περὶ τὸν Τορκουᾶτον θεωροῦντες αὐτὸν συνεσταμένον ξενικὴν χεῖρα βαρεῖαν ὑπεμίμνησκον τῶν ἐντολῶν, διότι δεῖ χωρὶς πολέμου ποιεῖσθαι τὴν κάθοδον· καὶ τέλος ἔπεισαν αὐτὸν ἕως Σίδης προαγαγόντα τὸ ξενολόγιον διαλύσασθαι καὶ τῆς εἰς Κύπρον ἐπιβολῆς ἀποστῆναι καὶ συμμίσγειν αὑτοῖς ἐπὶ τοὺς τῶν Κυρηναίων ὅρους. αὐτοὶ δὲ πλεύσαντες εἰς τὴν Ἀλεξάνδρειαν ἔφασαν παραστήσεσθαι τὸν βασιλέα πρὸς τὰ παρακαλούμενα καὶ συναντήσειν ἐπὶ τοὺς ὅρους, ἔχοντες κἀκεῖνον μεθ’ αὑτῶν. τούτοις μὲν οὖν τοῖς λόγοις πεισθεὶς ὁ νεώτερος Πτολεμαῖος, ἀπογνοὺς τὰ κατὰ τὴν Κύπρον τὸ μὲν ξενολόγιον διέλυσεν, αὐτὸς δὲ τὸ μὲν πρῶτον εἰς Κρήτην ἀπέπλευσεν, τόν τε Δαμάσιππον ἔχων μεθ’ ἑαυτοῦ καὶ τῶν πρεσβευτῶν ἕνα Γνάιον Μερόλαν· ξενολογήσας δ’ ἐκ τῆς Κρήτης περὶ χιλίους στρατιώτας ἀνήχθη καὶ διάρας εἰς τὴν Λιβύην κατέσχεν ἐπὶ τὸν Ἆπιν.", "st": "31.26"}, {"sp": "N", "t": "οἱ δὲ περὶ τὸν Τορκουᾶτον διακομισθέντες εἰς τὴν Ἀλεξάνδρειαν ἐπειρῶντο μὲν παρακαλεῖν τὸν πρεσβύτερον Πτολεμαῖον διαλύεσθαι πρὸς τὸν ἀδελφὸν καὶ συγχωρεῖν αὐτῷ τὴν Κύπρον· τοῦ δὲ Πτολεμαίου τὰ μὲν ἐπαγγελλομένου, τὰ δὲ παρακούοντος, καὶ τῷ τοιούτῳ τρόπῳ κατατρίβοντος τὸν χρόνον, στρατοπεδεύων ὁ νεώτερος μετὰ τῶν Κρητῶν ἐν τῇ Λιβύῃ περὶ τὸν Ἆπιν κατὰ τὸ συντεταγμένον καὶ τελέως ἀσχάλλων ἐπὶ τῷ μηδὲν διασαφήσασθαι, τὸ μὲν πρῶτον ἐξαπέστειλε τὸν Γνάιον εἰς τὴν Ἀλεξάνδρειαν, ὡς διὰ τούτου κἂν τοὺς περὶ τὸν Τορκουᾶτον ἐπιγενομένους. συνεξομοιωθέντος δὲ τούτου τοῖς πρότερον, καὶ τοῦ χρόνου διελκομένου, καὶ τετταράκοντα διελθουσῶν ἡμερῶν, καὶ μηδενὸς προσπίπτοντος, εἰς ἀπορίαν ἐνέπιπτε περὶ τῶν ὅλων. ὁ γὰρ πρεσβύτερος βασιλεὺς πᾶν γένος ἀρεσκείας προσφερόμενος πάντας ἐξιδιάσατο τοὺς πρεσβευτὰς καὶ παρακατέσχε τὸ πλεῖον οὐχ ἑκόντας, ἀλλ’ ἄκοντας. κατὰ δὲ τὸν καιρὸν τοῦτον προσέπεσε τῷ νεωτέρῳ Πτολεμαίῳ τούς τε Κυρηναίους ἀφεστάναι καὶ τὰς πόλεις συμφρονεῖν τούτοις, κεκοινωνηκέναι δὲ περὶ τῆς ἀποστάσεως καὶ Πτολεμαῖον τὸν Συμπετῆσιν, ὃς ἦν τὸ γένος Αἰγύπτιος, ἐπιστεύθη δὲ τὴν ἐπιμέλειαν τῶν ὅλων ὑπὸ τοῦ βασιλέως, καθ’ ὃν καιρὸν ἐποιεῖτο τὸν πλοῦν εἰς τὴν Ῥώμην. τούτων δὲ προσπιπτόντων τῷ βασιλεῖ, καὶ μετ’ ὀλίγον διότι στρατοπεδεύουσιν ἐν τοῖς ὑπαίθροις οἱ Κυρηναῖοι, δείσας μὴ βουλόμενος προσλαβεῖν τὴν Κύπρον καὶ τὴν Κυρήνην ἀπολέσῃ, πάντα τἄλλα πάρεργα θέμενος ἀνέζευξεν ἐπὶ Κυρήνης. παραγενόμενος δ’ εἰς τὸν μέγαν καλούμενον Καταβαθμὸν κατέλαβε τοὺς Λίβυας μετὰ τῶν Κυρηναίων κατέχοντας τὰς δυσχωρίας. ὁ δὲ Πτολεμαῖος ἀπορούμενος ἐπὶ τῷ συμβαίνοντι τοὺς μὲν ἡμίσεις τῶν στρατιωτῶν ἐμβιβάσας εἰς τὰ πλοῖα περιπλεῖν τὰς δυσχωρίας ἐπέταξε καὶ κατὰ νώτου τοῖς πολεμίοις ἐπιφαίνεσθαι, τοὺς δ’ ἡμίσεις ἔχων αὐτὸς ἐβιάζετο κατὰ στόμα πρὸς τὴν ἀνάβασιν. τῶν δὲ Λιβύων καταπλαγέντων τὴν ἐξ ἀμφοῖν ἔφοδον καὶ λειπόντων τοὺς τόπους, ἅμα τῆς ἀναβάσεως ἐγένετο κύριος καὶ τῆς ὑποκειμένης Τετραπυργίας, ἐν ᾗ συνέβαινε πλῆθος ἄφθονον ὕδατος ὑπάρχειν. ὅθεν ἀφορμήσας ἑβδομαῖος ἧκε διὰ τῆς ἐρήμου. παραπλεόντων δ’ αὐτῷ καὶ τῶν ἐπὶ Μοχυρίνου, συνέβαινε τοὺς Κυρηναίους στρατοπεδεύειν πεζοὺς μὲν ὄντας εἰς ὀκτακισχιλίους, ἱππεῖς δὲ περὶ πεντακοσίους. οἱ γὰρ Κυρηναῖοι πεῖραν εἰληφότες τῆς τοῦ Πτολεμαίου προαιρέσεως ἐκ τῶν κατὰ τὴν Ἀλεξάνδρειαν πεπραγμένων καὶ θεωροῦντες οὐ βασιλικήν, ἀλλὰ τυραννικὴν οὖσαν τὴν ἀρχὴν αὐτοῦ καὶ τὴν ὅλην αἵρεσιν, οὐχ οἷοί τ’ ἦσαν ἐθελοντὴν σφᾶς αὐτοὺς ὑποτάττειν, ἀλλὰ πᾶν ὑπομένειν ἐτόλμων, ἀντεχόμενοι τῆς πρὸς τὴν ἐλευθερίαν ἐλπίδος. διὸ καὶ τότε συνεγγίσαντος αὐτοῦ ἐξ αὐτῆς παρετάξαντο· καὶ τέλος ἡττήθη. —", "st": "31.27"}, {"sp": "N", "t": "ὅτι κατὰ τὸν καιρὸν τοῦτον ἦλθε καὶ Γνάιος ὁ Μερόλας ἐκ τῆς Ἀλεξανδρείας, διασαφῶν τῷ βασιλεῖ διότι πρὸς οὐθὲν τῶν ἀξιουμένων προσελήλυθεν ὁ ἀδελφός, ἀλλά φησι δεῖν μένειν ἐπὶ τοῖς ἐξ ἀρχῆς διομολογουμένοις. ὁ δὲ βασιλεὺς ταῦτα διακούσας, εὐθέως προχειρισάμενος Κομανὸν καὶ Πτολεμαῖον τοὺς ἀδελφοὺς ἐξαπέστελλε πρεσβευτὰς εἰς τὴν Ῥώμην μετὰ τοῦ Γναΐου, διασαφήσοντας τῇ συγκλήτῳ περὶ τῆς τἀδελφοῦ πλεονεξίας καὶ καταφρονήσεως. ἀπέλυσε δὲ κατὰ τὸν αὐτὸν καιρὸν καὶ τοὺς περὶ Τίτον ἀπράκτους ὁ πρεσβύτερος Πτολεμαῖος. καὶ τὰ μὲν κατὰ τὴν Ἀλεξάνδρειαν καὶ Κυρήνην ἐπὶ τούτων ἦν.", "st": "31.28"}, {"sp": "HDR", "t": "Βιβλίον ΛΒʹ", "st": "32"}, {"sp": "N", "t": "ὅτι κατὰ τοὺς ὑποκειμένους καιροὺς ἧκον παρὰ τοῦ νεωτέρου Πτολεμαίου πρέσβεις οἱ περὶ τὸν Κομανὸν καὶ παρὰ τοῦ πρεσβυτέρου παραπλησίως οἱ περὶ τὸν Μένυλλον τὸν Ἀλαβανδέα. ὧν εἰσελθόντων εἰς τὴν σύγκλητον, καὶ πολλῶν λόγων γινομένων καὶ φιλαπεχθῶν κατὰ πρόσωπον εἰς ἀλλήλους, καὶ τῶν περὶ Τίτον καὶ Γνάιον ἀπομαρτυρούντων καὶ συνεπισχυόντων τῷ νεωτέρῳ μετὰ πολλῆς σπουδῆς, ἔδοξε τῇ συγκλήτῳ τοὺς περὶ Μένυλλον ἐν πένθ’ ἡμέραις ἀποτρέχειν ἐκ τῆς Ῥώμης, καὶ τὴν συμμαχίαν ἀναιρεῖν τὴν πρὸς τὸν πρεσβύτερον, πρὸς δὲ τὸν νεώτερον πέμψαι πρεσβευτὰς τοὺς διασαφήσοντας τὰ δεδογμένα τῇ συγκλήτῳ. καὶ κατεστάθησαν Πόπλιος Ἀπούστιος καὶ Γάιος Λέντλος, οἳ καὶ πλεύσαντες ἐξ αὐτῆς εἰς τὴν Κυρήνην ἀνήγγειλαν τῷ Πτολεμαίῳ τὰ δεδογμένα μετὰ πολλῆς σπουδῆς. ὁ δὲ Πτολεμαῖος ἐπαρθεὶς εὐθέως ἐξενολόγει καὶ ταῖς ἐπιβολαῖς ὅλος καὶ πᾶς ἦν περὶ τὴν Κύπρον. καὶ τὰ μὲν κατὰ τὴν Ἰταλίαν ἐν τούτοις ἦν.", "st": "32.1"}, {"sp": "N", "t": "ὅτι κατὰ τὴν Λιβύην Μασαννάσας θεωρῶν τὸ πλῆθος τῶν πόλεων τῶν περὶ τὴν μικρὰν Σύρτιν ἐκτισμένων καὶ τὸ κάλλος τῆς χώρας, ἣν καλοῦσιν Ἐμπόρια, καὶ πάλαι τὸ πλῆθος τῶν προσόδων τῶν γινομένων ἐν τούτοις τοῖς τόποις ὀφθαλμιῶν, ἐπεβάλετο καταπειράζειν τῶν Καρχηδονίων οὐ πολλοῖς ἀνώτερον χρόνοις τῶν νῦν λεγομένων καιρῶν. τῆς μὲν οὖν χώρας ταχέως ἐγενήθη κύριος, ἅτε τῶν ὑπαίθρων κρατῶν διὰ τὸ τοὺς Καρχηδονίους αἰεὶ μὲν ἀλλοτρίους ὑπάρχειν τῆς ἐν τῇ γῇ χρείας, τότε δὲ καὶ τελέως ἐκτεθηλύνθαι διὰ τὴν πολυχρόνιον εἰρήνην· τῶν δὲ πόλεων οὐκ ἠδυνήθη γενέσθαι κύριος διὰ τὸ τοὺς Καρχηδονίους ἐπιμελῶς τηρεῖν αὐτάς. ἀμφοτέρων δὲ ποιουμένων τὴν ἀναφορὰν ἐπὶ τὴν σύγκλητον ὑπὲρ τῶν ἀμφισβητουμένων, καὶ πρεσβευτῶν πολλάκις ἐληλυθότων διὰ ταῦτα παρ’ ἑκατέρων, αἰεὶ συνέβαινε τοὺς Καρχηδονίους ἐλαττοῦσθαι παρὰ τοῖς Ῥωμαίοις, οὐ τοῖς δικαίοις, ἀλλὰ τῷ πεπεῖσθαι τοὺς κρίνοντας συμφέρειν σφίσι τὴν τοιαύτην γνώμην, ἐπείτοι χρόνοις οὐ πολλοῖς ἀνώτερον αὐτὸς ὁ Μασαννάσας διώκων τὸν Ἀφθῆρα τὸν ἀποστάτην μετὰ στρατοπέδου δίοδον ᾐτήσατο τοὺς Καρχηδονίους διὰ ταύτης τῆς χώρας, οἱ δ’ οὐχ ὑπήκουσαν, ὡς οὐδὲν αὐτῷ προσηκούσης. οὐ μὴν ἀλλὰ τέλος εἰς τοῦτο συνεκλείσθησαν οἱ Καρχηδόνιοι διὰ τῶν ἀποφάσεων κατὰ τοὺς νῦν λεγομένους καιροὺς ὥστε μὴ μόνον τὰς πόλεις καὶ τὴν χώραν ἀποβαλεῖν, ἀλλὰ καὶ πεντακόσια τάλαντα προσθεῖναι τῆς καρπείας τῶν χρόνων, ἐξ οὗ συνέβη γενέσθαι τὴν ἀμφισβήτησιν.", "st": "32.2"}, {"sp": "N", "t": "ὅτι κατὰ τὴν Ἀσίαν Προυσίας μὲν ἐξέπεμψεν εἰς τὴν Ῥώμην πρεσβευτὰς μετὰ Γαλατῶν τοὺς κατηγορήσοντας Εὐμένους, οὗτος δὲ πάλιν τὸν ἀδελφὸν Ἄτταλον ἐξαπέστειλεν ἀπολογησόμενον πρὸς τὰς διαβολάς. Ἀριαράθης δὲ τῇ τε Ῥώμῃ στέφανον ἀπὸ χρυσῶν μυρίων ἔπεμψε καὶ πρεσβευτὰς τοὺς διασαφήσοντας τῇ συγκλήτῳ τὴν πρὸς τὸν Τεβέριον ἀπάντησιν αὐτοῦ καὶ καθόλου παρακαλέσοντας διασαφεῖν ὑπὲρ ὧν ἂν δέωνται, διότι πᾶν ποιήσειν ἕτοιμός ἐστι Ῥωμαίοις τὸ παραγγελλόμενον. —", "st": "32.3"}, {"sp": "N", "t": "ὅτι τοῦ Μηνοχάρους παραγενηθέντος εἰς τὴν Ἀντιόχειαν πρὸς Δημήτριον καὶ διασαφήσαντος τῷ βασιλεῖ τὴν γεγενημένην ἔντευξιν αὐτῷ πρὸς τοὺς περὶ Τεβέριον ἐν τῇ Καππαδοκίᾳ, νομίσας ὁ βασιλεὺς ἀναγκαιότατον εἶναι τῶν παρόντων τὸ τοὺς προειρημένους ἄνδρας ἐξομιλῆσαι καθ’ ὅσον οἷός τ’ ἦν, πάντα τἄλλα πάρεργα ποιησάμενος διεπέμπετο πρὸς τούτους, τὸ μὲν πρῶτον εἰς Παμφυλίαν, μετὰ δὲ ταῦτα πάλιν εἰς Ῥόδον, πάντα ποιήσειν Ῥωμαίοις ἀναδεχόμενος, ἕως ἐξειργάσατο βασιλεὺς ὑπ’ αὐτῶν προσαγορευθῆναι. καὶ γὰρ ἦν ὁ Τεβέριος εὔνους αὐτῷ διαφερόντως· διὸ καὶ μεγάλα συνεβάλετο πρὸς τὸ καθικέσθαι καὶ κτήσασθαι τὰ κατὰ τὴν ἀρχὴν αὐτόν. ὁ δὲ Δημήτριος τυχὼν τῆς προειρημένης ἀφορμῆς εὐθέως εἰς τὴν Ῥώμην ἔπεμπε πρεσβευτὰς στέφανόν τε κομίζοντας καὶ τὸν αὐτόχειρα τοῦ Γναΐου γεγονότα καὶ σὺν τούτοις τὸν κριτικὸν Ἰσοκράτην.", "st": "32.4"}, {"sp": "N", "t": "ὅτι κατὰ τὸν καιρὸν τοῦτον ἧκον παρ’ Ἀριαράθου πρέσβεις στέφανόν τε κομίζοντες ἀπὸ μυρίων χρυσῶν καὶ διασαφοῦντες τὴν τοῦ βασιλέως προαίρεσιν, ἣν ἔχει πρὸς τὰ Ῥωμαίων πράγματα, καὶ τούτων μάρτυρας ἐπήγοντο τοὺς περὶ τὸν Τεβέριον. ὧν ἀνθομολογησαμένων ἡ σύγκλητος τόν τε στέφανον ἀπεδέξατο μετὰ μεγάλης χάριτος καὶ τὰ μέγιστα τῶν παρ’ αὐτῇ νομιζομένων δώρων ἀνταπέστειλε, τόν τε σκίπωνα καὶ τὸν ἐλεφάντινον δίφρον. τούτους μὲν οὖν ἐξ αὐτῆς ἔτι πρὸ τοῦ χειμῶνος ἀπέλυσεν ἡ σύγκλητος. μετὰ δὲ τούτους Ἀττάλου παραγενηθέντος, ἤδη τῶν ὑπάτων τὰς ἀρχὰς εἰληφότων, καὶ τῶν Γαλατῶν αὐτοῦ κατηγορησάντων, οὓς ἀπεστάλκει Προυσίας, καὶ πλειόνων ἑτέρων ἀπὸ τῆς Ἀσίας, διακούσασα πάντων ἡ σύγκλητος οὐ μόνον ἀπέλυσε τῶν διαβολῶν τὸν Ἄτταλον, ἀλλὰ καὶ προσαυξήσασα τοῖς φιλανθρώποις ἐξαπέστειλε· καθ’ ὅσον γὰρ ἀπηλλοτρίωτο τοῦ βασιλέως καὶ διεφέρετο πρὸς τὸν Εὐμένη, κατὰ τοσοῦτον ἐφιλοποιεῖτο καὶ συνηῦξε τὸν Ἄτταλον. —", "st": "32.5"}, {"sp": "N", "t": "ὅτι ἧκον καὶ παρὰ τοῦ Δημητρίου τοῦ βασιλέως πρέσβεις οἱ περὶ τὸν Μηνοχάρην, στέφανον ἀπὸ μυρίων χρυσῶν τῇ Ῥώμῃ κομίζοντες, ἅμα δὲ καὶ τὸν προσενέγκαντα τῷ Γναΐῳ τὰς χεῖρας ἄγοντες. ἡ δὲ σύγκλητος ἐπὶ πολὺν μὲν χρόνον διηπόρησε περὶ τούτων πῶς δεῖ χρήσασθαι τοῖς πράγμασιν, ὅμως δὲ προσεδέξατο καὶ τοὺς πρεσβευτὰς καὶ τὸν στέφανον· τούς γε μὴν ἀγομένους ἀνθρώπους οὐ προσεδέξατο. καίτοι γε Δημήτριος οὐ μόνον τὸν Λεπτίνην ἀπέστειλε τὸν αὐτόχειρα τοῦ Γναΐου γενόμενον, ἀλλὰ καὶ τὸν Ἰσοκράτην. οὗτος δ’ ἦν μὲν γραμματικὸς τῶν τὰς ἀκροάσεις ποιουμένων, φύσει δ’ ὢν λάλος καὶ πέρπερος καὶ κατακορὴς προσέκοπτε μὲν καὶ τοῖς Ἕλλησιν, ἅτε καὶ τῶν περὶ τὸν Ἀλκαῖον ἐν ταῖς Συγκρίσεσιν ἐπιδεξίως σκωπτόντων αὐτὸν καὶ διαχλευαζόντων, παραγενόμενος δ’ εἰς τὴν Συρίαν καὶ καταφρονήσας τῶν ἀνθρώπων οὐκ ἠρκεῖτο περὶ τῶν ἰδίων ἐπιτηδευμάτων ποιούμενος τοὺς λόγους, ἀλλὰ καὶ πραγματικὰς ἀποφάσεις ἐξέβαλε, φάσκων δίκαια πεπονθέναι τὸν Γνάιον, δεῖν δὲ καὶ τοὺς ἄλλους πρεσβευτὰς ἀπολωλέναι πρὸς τὸ μηδὲ τὸν ἀγγελοῦντα καταλειφθῆναι τοῖς Ῥωμαίοις τὸ γεγονός, ἵνα παύσωνται τῶν ὑπερηφάνων ἐπιταγμάτων καὶ τῆς ἀνέδην ἐξουσίας. τοιαῦτα μὲν οὖν ῥιψολογῶν ἐνέπεσεν εἰς τὴν προειρημένην ἀτυχίαν.", "st": "32.6"}, {"sp": "N", "t": "ἐγένετο δέ τι περὶ τοὺς προειρημένους ἄξιον μνήμης. ὁ μὲν γὰρ Λεπτίνης μετὰ τὸ προσενεγκεῖν Γναΐῳ τὰς χεῖρας εὐθέως ἐν τῇ Λαοδικείᾳ περιῄει φανερῶς, φάσκων δίκαια πεποιηκέναι καὶ μετὰ τῆς τῶν θεῶν γνώμης ταῦτα πεπραχέναι. τοῦ δὲ Δημητρίου παραλαβόντος τὰ πράγματα, προσεπορεύετο τῷ βασιλεῖ, παρακαλῶν αὐτὸν μὴ δεδιέναι διὰ τὸν Γναΐου φόνον μηδὲ βουλεύεσθαι μηδὲν δυσχερὲς κατὰ τῶν Λαοδικέων· αὐτὸς γὰρ εἰς τὴν Ῥώμην πορεύσεσθαι καὶ διδάξειν τὴν σύγκλητον ὅτι μετὰ τῆς τῶν θεῶν γνώμης ταῦτα πεποίηκεν. καὶ πέρας διὰ τὴν ἑτοιμότητα καὶ προθυμίαν οὗτος μὲν ἄνευ δεσμῶν ἤχθη καὶ φυλακῆς, ὁ δ’ Ἰσοκράτης ἐμπεσὼν εἰς τὴν αἰτίαν ὁλοσχερῶς παρεξέστη τῇ διανοίᾳ. τοῦ κλοιοῦ δ’ αὐτῷ περὶ τὸν τράχηλον περιτεθέντος καὶ τῆς ἁλύσεως, σπανίως μὲν καὶ τὴν τροφὴν προσίετο, τῆς δὲ τοῦ σώματος θεραπείας εἰς τέλος ἀπέστη. διὸ καὶ παρεγένετ’ εἰς τὴν Ῥώμην θέαμα θαυμάσιον, εἰς ὃν ἀποβλέψας ἄν τις ὁμολογήσειεν διότι καὶ κατὰ σῶμα καὶ κατὰ ψυχὴν οὐδέν ἐστιν ἀνθρώπου φοβερώτερον, ὅταν ἅπαξ ἀποθηριωθῇ. ἥ τε γὰρ ὄψις ἐκτόπως ἦν αὐτοῦ φοβερὰ καὶ θηριώδης, ὡς ἂν πλεῖον ἐνιαυτοῦ μὴ τὸν ῥύπον, μὴ τοὺς ὄνυχας, μὴ τὰς τρίχας ἀφῃρημένου, τά τε κατὰ τὴν διάνοιαν ἐκ τῆς τῶν ὀμμάτων ἐμφάσεως καὶ κινήσεως τοιαύτην ἐποιεῖτο τὴν φαντασίαν ὥστε τὸν θεασάμενον πρὸς πᾶν ζῷον ἑτοιμότερον ἂν προσελθεῖν ἢ πρὸς ἐκεῖνον. ὁ δὲ Λεπτίνης μένων ἐπὶ τῆς ἐξ ἀρχῆς προαιρέσεως εἴς τε τὴν σύγκλητον ἕτοιμος ἦν εἰσπορεύεσθαι πρός τε τοὺς ἐντυγχάνοντας ἁπλῶς ἀνθωμολογεῖτο περὶ τῆς πράξεως, καὶ προσδιωρίζετο μηδὲν αὑτῷ δυσχερὲς ἀπαντήσειν ὑπὸ Ῥωμαίων. καὶ τέλος εὐστόχησε τῆς ἐλπίδος· ἡ γὰρ σύγκλητος, ὡς ἐμοὶ δοκεῖν, ὑπολαβοῦσα διότι δόξει τοῖς πολλοῖς ἔχειν τοῦ φόνου δίκην, ἐὰν τοὺς αἰτίους παραλαβοῦσα τιμωρήσηται, τούτους μὲν οὐ προσεδέξατο μικροῦ δεῖν, ἐτήρει δὲ τὴν αἰτίαν ἀκέραιον, ὥστ’ ἔχειν ἐξουσίαν, ὅτε βουληθείη, χρήσασθαι τοῖς ἐγκλήμασι. διὸ καὶ τὴν ἀπόκρισιν ἔδωκε τοιαύτην τῷ Δημητρίῳ, διότι τεύξεται τῶν φιλανθρώπων, ἐὰν τὸ ἱκανὸν ποιῇ τῇ συγκλήτῳ κατὰ τὴν τῆς ἀρχῆς ἐξουσίαν. — ἧκον δὲ καὶ παρὰ τῶν Ἀχαιῶν πρέσβεις οἱ περὶ Ξένωνα καὶ Τηλεκλῆν ὑπὲρ τῶν κατῃτιαμένων, καὶ μάλιστα τοῦ Πολυβίου καὶ τοῦ Στρατίου χάριν· τοὺς μὲν γὰρ λοιποὺς σχεδὸν ἅπαντας ὁ χρόνος ἤδη καταναλώκει, τούς γε δὴ καὶ μνήμης ἀξίους. παρῆσαν δ’ οἱ πρέσβεις ἐντολὰς ἔχοντες ἁπλῶς ἀξιωματικὰς χάριν τοῦ πρὸς μηδὲν ἀντιφιλονικεῖν τῇ συγκλήτῳ. εἰσπορευθέντων δὲ καὶ ποιησαμένων τοὺς ἁρμόζοντας λόγους, οὐδ’ ὣς οὐδὲν ἠνύσθη, τὸ δ’ ἐναντίον ἔδοξε τῇ συγκλήτῳ μένειν ἐπὶ τῶν ὑποκειμένων.", "st": "32.7"}, {"sp": "N", "t": "ὅτι τὸ μέγιστον καὶ κάλλιστον σημεῖον τῆς Λευκίου Αἰμιλίου προαιρέσεως μεταλλάξαντος τὸν βίον ἐγένετο πᾶσιν ἔκδηλον· οἷος γὰρ ὁ τρόπος ζῶντος [αὐτοῦ] ἐδοξάζετο, τοιοῦτος εὑρέθη τὸν βίον μεταλλάξαντος, ὃ μέγιστον εἴποι τις ἂν ὑπάρχειν τεκμήριον ἀρετῆς. ὁ γὰρ πλεῖστον μὲν τῶν καθ’ αὑτὸν ἐξ Ἰβηρίας χρυσὸν εἰς τὴν Ῥώμην μετενηνοχώς, μεγίστων δὲ θησαυρῶν κύριος γενόμενος ἐν Μακεδονίᾳ, πλείστης δὲ περὶ τὰ προειρημένα τετευχὼς ἐξουσίας τοσοῦτον ἀπέλειπε τὸν ἴδιον βίον ὥστε μὴ δύνασθαι τὴν φερνὴν τῇ γυναικὶ διαλῦσαι πᾶσαν ἐκ τῶν ἐπίπλων, εἰ μὴ τῶν ἐγγείων τινὰς προσαπέδοντο κτήσεων. ὑπὲρ ὧν ἡμεῖς τὰ κατὰ μέρος ἐν τοῖς πρὸ τούτων εἰρήκαμεν. ἐξ ὧν εἴποι τις ἂν καταλελύσθαι τὴν δόξαν τῶν θαυμαζομένων παρὰ τοῖς Ἕλλησι περὶ τοῦτο τὸ μέρος ἀνδρῶν· εἰ γὰρ τὸ διδομένων χρημάτων ἐπὶ τῷ τοῦ διδόντος συμφέροντι, τούτων ἀπέχεσθαι θαυμαστόν ἐστιν, ὃ λέγεται γεγονέναι περί τε τὸν Ἀθηναῖον Ἀριστείδην καὶ περὶ τὸν Θηβαῖον Ἐπαμινώνδαν, τὸ κύριον γενόμενον αὐτὸν ἁπάσης τῆς βασιλείας καὶ λαβόντα τὴν ἐξουσίαν ὡς βούλεται χρήσασθαι, μηδενὸς ἐπιθυμῆσαι πόσῳ θαυμαστότερόν ἐστιν; εἰ δ’ ἀπίστῳ τὸ λεγόμενον ἐοικέναι δόξει τισίν, ἐκεῖνο δεῖ λαμβάνειν ἐν νῷ, διότι σαφῶς ὁ γράφων ᾔδει μάλιστα Ῥωμαίους ἀναληψομένους εἰς τὰς χεῖρας τὰ βυβλία ταῦτα διὰ τὸ τὰς ἐπιφανεστάτας καὶ τὰς πλείστας αὐτῶν πράξεις ἐν τούτοις περιέχεσθαι· παρ’ οἷς οὔτ’ ἀγνοεῖσθαι ταῦτα δυνατὸν οὔτε συγγνώμης τεύξεσθαι τὸν ψευδολόγον εἰκός, διόπερ οὐδεὶς ἂν ἑκὼν εἰς πρόδηλον ἀπιστίαν καὶ καταφρόνησιν ἔδωκεν αὑτόν. καὶ τοῦτο μνημονευέσθω παρ’ ὅλην τὴν πραγματείαν ἡμῖν, ὅταν τι παράδοξον δοκῶμεν λέγειν περὶ Ῥωμαίων.", "st": "32.8"}, {"sp": "N", "t": "τῆς δὲ κατὰ τὴν διήγησιν ἐφόδου καὶ τῶν καιρῶν ἐφεστακότων ἡμᾶς ἐπὶ τὴν οἰκίαν ταύτην, βούλομαι τὸ κατὰ τὴν προτέραν βύβλον ἐν ἐπαγγελίᾳ καταλειφθὲν συνεκπληρῶσαι τῶν φιληκόων ἕνεκα. προϋπεσχόμην γὰρ διηγήσασθαι διὰ τί καὶ πῶς ἐπὶ τοσοῦτο προέκοψε καὶ θᾶττον ἢ καθῆκεν ἐξέλαμψεν ἡ τοῦ Σκιπίωνος ἐν τῇ Ῥώμῃ δόξα, σὺν δὲ τούτῳ πῶς ἐπὶ τοσοῦτον αὐξηθῆναι συνέβη τῷ Πολυβίῳ τὴν πρὸς τὸν προειρημένον φιλίαν καὶ συνήθειαν ὥστε μὴ μόνον ἕως τῆς Ἰταλίας καὶ τῆς Ἑλλάδος ἐπιδιατεῖναι τὴν περὶ αὐτῶν φήμην, ἀλλὰ καὶ τοῖς πορρωτέρω γνώριμον γενέσθαι τὴν αἵρεσιν καὶ συμπεριφορὰν αὐτῶν. διότι μὲν οὖν ἡ καταρχὴ τῆς συστάσεως ἐγενήθη τοῖς προειρημένοις ἔκ τινος χρήσεως βυβλίων καὶ τῆς περὶ τούτων λαλιᾶς δεδηλώκαμεν· προβαινούσης δὲ τῆς συνηθείας καὶ τῶν ἀνακεκλημένων ἐκπεμπομένων ἐπὶ τὰς πόλεις, διέσπευσαν ὅ τε Φάβιος καὶ ὁ Σκιπίων οἱ τοῦ Λευκίου νεανίσκοι πρὸς τὸν στρατηγὸν μεῖναι τὸν Πολύβιον ἐν τῇ Ῥώμῃ. γενομένου δὲ τούτου, καὶ τῆς συμπεριφορᾶς ἐπὶ πολὺ προκοπτούσης, ἐγένετο συγκύρημά τι τοιοῦτον. ἐκπορευομένων γάρ ποτε κατ’ αὐτὸ πάντων ἐκ τῆς οἰκίας τῆς τοῦ Φαβίου, συνέβη τὸν μὲν Φάβιον ἐπὶ τὴν ἀγορὰν ἀπονεῦσαι, τὸν δὲ Πολύβιον ἐπὶ θάτερα μετὰ τοῦ Σκιπίωνος. προαγόντων δ’ αὐτῶν ὁ Πόπλιος ἡσυχῇ καὶ πρᾴως τῇ φωνῇ φθεγξάμενος καὶ τῷ χρώματι γενόμενος ἐνερευθής, \" τί δαί\" φησίν \"ὦ Πολύβιε, δύο τρώγομεν ἀδελφοί, καὶ διαλέγει συνεχῶς καὶ πάσας τὰς ἐρωτήσεις καὶ τὰς ἀποφάσεις ποιεῖ πρὸς ἐκεῖνον, ἐμὲ δὲ παραπέμπεις; ἢ δῆλον ὅτι καὶ σὺ περὶ ἐμοῦ τὴν αὐτὴν ἔχεις διάληψιν, ἣν καὶ τοὺς ἄλλους πολίτας ἔχειν πυνθάνομαι; δοκῶ γὰρ εἶναι πᾶσιν ἡσύχιός τις καὶ νωθρός, ὡς ἀκούω, καὶ πολὺ κεχωρισμένος τῆς Ῥωμαϊκῆς αἱρέσεως καὶ πράξεως, ὅτι κρίσεις οὐχ αἱροῦμαι λέγειν. τὴν δ’ οἰκίαν οὔ φασι τοιοῦτον ζητεῖν προστάτην ἐξ ἧς ὁρμῶμαι, τὸ δ’ ἐναντίον· ὃ καὶ μάλιστά με λυπεῖ.\"", "st": "32.9"}, {"sp": "N", "t": "ὁ δὲ Πολύβιος ξενισθεὶς τῇ τοῦ μειρακίου καταρχῇ τῶν λόγων· οὐ γὰρ εἶχε πλέον ἐτῶν ὀκτωκαίδεκα τότε· \" μὴ πρὸς θεῶν, Σκιπίων,\" ἔφη, \"μηδὲ λέγε ταῦτα μηδ’ ἐν νῷ λάμβανε ταῦτα τὸ παράπαν. οὐδὲ γὰρ καταγινώσκων οὔτε παραπέμπων ἐγώ σε ποιῶ τοῦτο, πολλοῦ γε δεῖν, ἀλλὰ τῷ πρεσβύτερον εἶναι τὸν ἀδελφὸν ἔν τε ταῖς ὁμιλίαις ἄρχομαί τ’ ἀπ’ ἐκείνου καὶ λήγω πάλιν εἰς ἐκεῖνον ἔν τε ταῖς ἀποφάσεσι καὶ συμβουλίαις πρὸς ἐκεῖνον ἀπερείδομαι, δοκῶν καὶ σὲ τῆς αὐτῆς μετέχειν γνώμης ἐκείνῳ. σοῦ γε μὴν ἄγαμαι νῦν ἀκούων, ὅτι δοκεῖ σοι λυπηρὸν τὸ πραΰτερον εἶναι τοῦ καθήκοντος τοῖς ἐκ ταύτης τῆς οἰκίας ὁρμωμένοις· δῆλος γὰρ εἶ διὰ τούτων μέγα φρονῶν. ἐγὼ δὲ κἂν αὐτὸς ἡδέως σοι συνεπιδοίην ἐμαυτὸν καὶ συνεργὸς γενοίμην εἰς τὸ καὶ λέγειν τι καὶ πράττειν ἄξιον τῶν προγόνων. περὶ μὲν γὰρ τὰ μαθήματα, περὶ ἃ νῦν ὁρῶ σπουδάζοντας ὑμᾶς καὶ φιλοτιμουμένους, οὐκ ἀπορήσετε τῶν συνεργησόντων ὑμῖν ἑτοίμως, καὶ σοὶ κἀκείνῳ· πολὺ γὰρ δή τι φῦλον ἀπὸ τῆς Ἑλλάδος ἐπιρρέον ὁρῶ κατὰ τὸ παρὸν τῶν τοιούτων ἀνθρώπων. εἰς δὲ τὰ λυποῦντά σε νῦν καὶ μάλιστα, καθὼς φής, δοκῶ μηδένα συναγωνιστὴν καὶ συνεργὸν ἄλλον εὑρεῖν ἂν ἡμῶν ἐπιτηδειότερον. \" ἔτι δὲ ταῦτα λέγοντος τοῦ Πολυβίου, λαβόμενος ἀμφοτέραις χερσὶ τῆς δεξιᾶς αὐτοῦ καὶ πιέσας ἐμπαθῶς \"εἰ γὰρ ἐγὼ ταύτην,\" φησίν, \"ἴδοιμι τὴν ἡμέραν, ἐν ᾗ σὺ πάντα τἄλλα δεύτερα θέμενος ἐμοὶ προσέξεις τὸν νοῦν καὶ μετ’ ἐμοῦ συμβιώσεις· δόξω γὰρ αὐτόθεν εὐθέως ἐμαυτῷ καὶ τῆς οἰκίας ἄξιος εἶναι καὶ τῶν προγόνων. \" ὁ δὲ Πολύβιος τὰ μὲν ἔχαιρε, θεωρῶν τὴν ὁρμὴν καὶ τὴν ἀποδοχὴν τοῦ μειρακίου, τὰ δὲ διηπορεῖτο, λαμβάνων ἐν νῷ τὴν ὑπεροχὴν τῆς οἰκίας καὶ τὴν εὐκαιρίαν τῶν ἀνδρῶν. πλὴν ἀπό γε ταύτης τῆς ἀνθομολογήσεως οὐκέτι τὸ μειράκιον ἐχωρίσθη τοῦ Πολυβίου, πάντα δ’ ἦν αὐτῷ δεύτερα τῆς ἐκείνου συμπεριφορᾶς.", "st": "32.10"}, {"sp": "N", "t": "ἀπὸ δὲ τούτων τῶν καιρῶν λοιπὸν ἤδη κατὰ τὸ συνεχὲς ἐπ’ αὐτῶν τῶν πραγμάτων πεῖραν αὑτῶν διδόντες ἀλλήλοις εἰς πατρικὴν καὶ συγγενικὴν ἦλθον αἵρεσιν καὶ φιλοστοργίαν πρὸς ἀλλήλους. πρώτη δέ τις ἐνέπεσεν ὁρμὴ καὶ ζῆλος τῶν καλῶν τὸ τὴν ἐπὶ σωφροσύνῃ δόξαν ἀναλαβεῖν καὶ παραδραμεῖν ἐν τούτῳ τῷ μέρει τοὺς κατὰ τὴν αὐτὴν ἡλικίαν ὑπάρχοντας. ὢν δὲ μέγας οὗτος καὶ δυσέφικτος ὁ στέφανος εὐθήρατος ἦν κατ’ ἐκεῖνον τὸν καιρὸν ἐν τῇ Ῥώμῃ διὰ τὴν ἐπὶ τὸ χεῖρον ὁρμὴν τῶν πλείστων. οἱ μὲν γὰρ εἰς ἐρωμένους τῶν νέων, οἱ δ’ εἰς ἑταίρας ἐξεκέχυντο, πολλοὶ δ’ εἰς ἀκροάματα καὶ πότους καὶ τὴν ἐν τούτοις πολυτέλειαν, ταχέως ἡρπακότες ἐν τῷ Περσικῷ πολέμῳ τὴν τῶν Ἑλλήνων εἰς τοῦτο τὸ μέρος εὐχέρειαν. καὶ τηλικαύτη τις ἐνεπεπτώκει περὶ τὰ τοιαῦτα τῶν ἔργων ἀκρασία τοῖς νέοις ὥστε πολλοὺς μὲν ἐρώμενον ἠγορακέναι ταλάντου, πολλοὺς δὲ ταρίχου Ποντικοῦ κεράμιον τριακοσίων δραχμῶν.", "st": "32.11"}, {"sp": "N", "t": "συνέβη δὲ τὴν παροῦσαν αἵρεσιν οἷον ἐκλάμψαι κατὰ τοὺς νῦν λεγομένους καιροὺς πρῶτον μὲν διὰ τὸ καταλυθείσης τῆς ἐν Μακεδονίᾳ βασιλείας δοκεῖν ἀδήριτον αὐτοῖς ὑπάρχειν τὴν περὶ τῶν ὅλων ἐξουσίαν, ἔπειτα διὰ τὸ πολλὴν ἐπίφασιν γενέσθαι τῆς εὐδαιμονίας περί τε τοὺς κατ’ ἰδίαν βίους καὶ περὶ τὰ κοινά, τῶν ἐκ Μακεδονίας μετακομισθέντων εἰς τὴν Ῥώμην χορηγίων. πλὴν ὅ γε Σκιπίων ὁρμήσας ἐπὶ τὴν ἐναντίαν ἀγωγὴν τοῦ βίου καὶ πάσαις ταῖς ἐπιθυμίαις ἀντιταξάμενος καὶ κατὰ πάντα τρόπον ὁμολογούμενον καὶ σύμφωνον ἑαυτὸν κατασκευάσας κατὰ τὸν βίον ἐν ἴσως πέντε τοῖς πρώτοις ἔτεσι πάνδημον ἐποιήσατο τὴν ἐπ’ εὐταξίᾳ καὶ σωφροσύνῃ δόξαν. μετὰ δὲ ταῦτα κατὰ τὸ συνεχὲς ὥρμησεν ἐπὶ τὸ περὶ τὰ χρήματα μεγαλοψυχίᾳ καὶ καθαρότητι διενεγκεῖν τῶν ἄλλων. πρὸς δὲ τοῦτο τὸ μέρος καλὴν μὲν ὑποδοχὴν εἶχε τὴν μετὰ τοῦ κατὰ φύσιν πατρὸς συμβίωσιν, καλὰς δ’ ἐκ φύσεως ὁρμὰς αὐτὸς ἐπὶ τὸ δέον· πολλὰ δ’ αὐτῷ καὶ ταὐτόματον συνήργησε πρὸς τὴν ἐπιβολὴν ταύτην.", "st": "32.11"}, {"sp": "N", "t": "πρώτη μὲν γὰρ αὐτῷ μετήλλαξε τὸν βίον ἡ τοῦ κατὰ θέσιν πατρὸς μήτηρ, ἥτις ἦν ἀδελφὴ μὲν τοῦ κατὰ φύσιν πατρὸς αὐτοῦ Λευκίου, γυνὴ δὲ τοῦ κατὰ θέσιν πάππου Σκιπίωνος τοῦ μεγάλου προσαγορευθέντος. ταύτης ἀπολιπούσης οὐσίαν μεγάλην κληρονόμος ὢν πρῶτον ἐν τούτοις ἔμελλε πεῖραν δώσειν τῆς ἑαυτοῦ προαιρέσεως. συνέβαινε δὲ τὴν Αἰμιλίαν, τοῦτο γὰρ ἦν ὄνομα τῇ προειρημένῃ γυναικί, μεγαλομερῆ τὴν περίστασιν ἔχειν ἐν ταῖς γυναικείαις ἐξόδοις, ἅτε συνηκμακυῖαν τῷ βίῳ καὶ τῇ τύχῃ τῇ Σκιπίωνος· χωρὶς γὰρ τοῦ περὶ τὸ σῶμα καὶ τὴν ἀπήνην κόσμου καὶ τὰ κανᾶ καὶ τὰ ποτήρια καὶ τἄλλα τὰ πρὸς τὴν θυσίαν, ποτὲ μὲν ἀργυρᾶ, ποτὲ δὲ χρυσᾶ, πάντα συνεξηκολούθει κατὰ τὰς ἐπιφανεῖς ἐξόδους αὐτῇ, τό τε τῶν παιδισκῶν καὶ τὸ τῶν οἰκετῶν τῶν παρεπομένων πλῆθος ἀκόλουθον ἦν τούτοις. ταύτην δὴ τὴν περικοπὴν ἅπασαν εὐθέως μετὰ τὸν τῆς Αἰμιλίας τάφον ἐδωρήσατο τῇ μητρί, ᾗ συνέβαινε κεχωρίσθαι μὲν ἀπὸ τοῦ Λευκίου πρότερον ἤδη χρόνοις πολλοῖς, τὴν δὲ τοῦ βίου χορηγίαν ἐλλιπεστέραν ἔχειν τῆς κατὰ τὴν εὐγένειαν φαντασίας. διὸ τὸν πρὸ τοῦ χρόνον ἀνακεχωρηκυίας αὐτῆς ἐκ τῶν ἐπισήμων ἐξόδων, τότε κατὰ τύχην οὔσης ἐπιφανοῦς καὶ πανδήμου θυσίας, ἐκπορευομένης αὐτῆς ἐν τῇ τῆς Αἰμιλίας περικοπῇ καὶ χορηγίᾳ, καὶ πρὸς τοῖς ἄλλοις καὶ τῶν ὀρεοκόμων καὶ τοῦ ζεύγους καὶ τῆς ἀπήνης τῆς αὐτῆς ὑπαρχούσης, συνέβη τὰς γυναῖκας θεωμένας τὸ γεγονὸς ἐκπλήττεσθαι τὴν τοῦ Σκιπίωνος χρηστότητα καὶ μεγαλοψυχίαν καὶ πάσας προτεινούσας τὰς χεῖρας εὔχεσθαι τῷ προειρημένῳ πολλὰ κἀγαθά. τοῦτο δὲ πανταχῇ μὲν ἂν εἰκότως φαίνοιτο καλόν, ἐν δὲ Ῥώμῃ καὶ θαυμαστόν· ἁπλῶς γὰρ οὐδεὶς οὐδενὶ δίδωσι τῶν ἰδίων ὑπαρχόντων ἑκὼν οὐδέν. πρώτη μὲν οὖν αὕτη καταρχὴ τῆς ἐπὶ καλοκἀγαθίᾳ φήμης αὐτῷ συνεκύρησε καὶ μεγάλην ἐποίησε προκοπήν, ἅτε τοῦ τῶν γυναικῶν γένους καὶ λάλου καὶ κατακοροῦς ὄντος, ἐφ’ ὅ,τι ἂν ὁρμήσῃ.", "st": "32.12"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα ταῖς Σκιπίωνος μὲν τοῦ μεγάλου θυγατράσιν, ἀδελφαῖς δὲ τοῦ κατὰ θέσιν πατρός, λαβόντος, αὐτὸν ἔδει τὴν ἡμίσειαν ἀποδοῦναι τῆς φερνῆς. ὁ γὰρ πατὴρ συνέθετο μὲν ἑκατέρᾳ τῶν θυγατέρων πεντήκοντα τάλαντα δώσειν, τούτων δὲ τὸ μὲν ἥμισυ παραχρῆμα τοῖς ἀνδράσιν ἔδωκεν ἡ μήτηρ, τὸ δ’ ἥμισυ κατέλειπεν ἀποθνήσκουσα προσοφειλόμενον, ὅθεν ἔδει τὸν Σκιπίωνα διαλύειν τοῦτο τὸ χρέος ταῖς τοῦ πατρὸς ἀδελφαῖς. κατὰ δὲ τοὺς Ῥωμαίων νόμους δέον ἐν τρισὶν ἔτεσιν ἀποδοῦναι τὰ προσοφειλόμενα χρήματα τῆς φερνῆς ταῖς γυναιξί, προδοθέντων πρώτων τῶν ἐπίπλων εἰς δέκα μῆνας κατὰ τὸ παρ’ ἐκείνοις ἔθος, εὐθέως ὁ Σκιπίων συνέταξε τῷ τραπεζίτῃ τῶν εἴκοσι καὶ πέντε ταλάντων ἑκατέρᾳ ποιήσασθαι τὴν ἀνταπόδοσιν ἐν τοῖς δέκα μησί. τοῦ δὲ Τεβερίου καὶ τοῦ Νασικᾶ Σκιπίωνος, οὗτοι γὰρ ἦσαν ἄνδρες τῶν προειρημένων γυναικῶν, ἅμα τῷ διελθεῖν τοὺς δέκα μῆνας προσπορευομένων πρὸς τὸν τραπεζίτην καὶ πυνθανομένων, εἴ τι συνετέτακτο Σκιπίων αὐτῷ περὶ τῶν χρημάτων, κἀκείνου κελεύοντος αὐτοὺς κομίζεσθαι καὶ ποιοῦντος τὴν διαγραφὴν ἑκατέρῳ τῶν εἴκοσι καὶ πέντε ταλάντων, ἀγνοεῖν αὐτὸν ἔφασαν· δεῖν γὰρ αὑτοὺς οὐ πᾶν κατὰ τὸ παρόν, ἀλλὰ τὸ τρίτον μέρος κομίζεσθαι κατὰ τοὺς νόμους. τοῦ δὲ φάσκοντος οὕτως αὐτῷ συντεταχέναι τὸν Σκιπίωνα, διαπιστήσαντες προῆγον ἐπὶ τὸν νεανίσκον, διειληφότες ἐκεῖνον ἀγνοεῖν. καὶ τοῦτ’ ἔπασχον οὐκ ἀλόγως· οὐ γὰρ οἷον πεντήκοντα τάλαντα δοίη τις ἂν ἐν Ῥώμῃ πρὸ τριῶν ἐτῶν, ἀλλ’ οὐδὲ τάλαντον ἓν πρὸ τῆς τεταγμένης ἡμέρας· τοιαύτη τίς ἐστι καὶ τηλικαύτη παρὰ πάντας ἅμα μὲν ἀκρίβεια. περὶ τὸ διάφορον, ἅμα δὲ λυσιτέλεια περὶ τὸν χρόνον. οὐ μὴν ἀλλὰ προσπορευθέντων αὐτῶν καὶ πυνθανομένων πῶς τῷ τραπεζίτῃ συντέταχε, τοῦ δ’ εἰπόντος ἀποδοῦναι πᾶν τὸ χρῆμα ταῖς ἀδελφαῖς, ἀγνοεῖν αὐτὸν ἔφασαν, ἅμα τὸ κηδεμονικὸν ἐμφανίζοντες· ἐξεῖναι γὰρ αὐτὸν κατὰ τοὺς νόμους χρῆσθαι τοῖς διαφόροις ἱκανὸν ἔτι χρόνον. ὁ δὲ Σκιπίων ἔφησεν ἀγνοεῖν τούτων οὐδέν, ἀλλὰ πρὸς μὲν τοὺς ἀλλοτρίους τὴν ἐκ τῶν νόμων ἀκρίβειαν τηρεῖν, τοῖς δὲ συγγενέσι καὶ φίλοις ἁπλῶς χρῆσθαι καὶ γενναίως κατὰ δύναμιν. διὸ παραλαμβάνειν αὐτοὺς ἐκέλευε πᾶν τὸ χρῆμα παρὰ τοῦ τραπεζίτου. οἱ δὲ περὶ τὸν Τεβέριον ταῦτ’ ἀκούσαντες ἐπανῆγον σιωπῶντες, καταπεπληγμένοι μὲν τὴν τοῦ Σκιπίωνος μεγαλοψυχίαν, κατεγνωκότες δὲ τῆς αὑτῶν μικρολογίας, καίπερ ὄντες οὐδενὸς δεύτεροι Ῥωμαίων.", "st": "32.13"}, {"sp": "N", "t": "μετὰ δ’ ἔτη δύο μεταλλάξαντος τοῦ κατὰ φύσιν πατρὸς αὐτοῦ Λευκίου καὶ καταλιπόντος κληρονόμους τῆς οὐσίας αὐτόν τε καὶ τὸν ἀδελφὸν Φάβιον, καλόν τι καὶ μνήμης ἄξιον ἐποίησεν. ὁ γὰρ Λεύκιος ὑπάρχων ἄτεκνος διὰ τὸ τοὺς μὲν εἰς ἑτέρας οἰκίας ἐκδεδόσθαι, τοὺς δ’ ἄλλους υἱούς, οὓς ἔτρεφε διαδόχους [καὶ] τοῦ γένους, πάντας μετηλλαχέναι, τούτοις ἀπέλιπε τὴν οὐσίαν. ὁ δὲ Σκιπίων θεωρῶν αὑτοῦ τὸν ἀδελφὸν καταδεέστερον ὄντα τοῖς ὑπάρχουσιν ἐξεχώρησε πάντων τῶν ὑπαρχόντων, οὔσης τῆς ὅλης τιμήσεως ὑπὲρ ἑξήκοντα τάλαντα, διὰ τὸ μέλλειν οὕτως ἴσον ὑπάρχειν αὐτῷ κατὰ τὴν οὐσίαν τὸν Φάβιον. γενομένου δὲ τούτου περιβοήτου, προσέθηκεν ἕτερον τούτῳ δεῖγμα τῆς αὑτοῦ προαιρέσεως ἐμφανέστερον· βουλομένου γὰρ τἀδελφοῦ μονομαχίας ἐπὶ τῷ πατρὶ ποιεῖν, οὐ δυναμένου δὲ δέξασθαι τὴν δαπάνην διὰ τὸ πλῆθος τῶν ἀναλισκομένων χρημάτων, καὶ ταύτης τὴν ἡμίσειαν εἰσήνεγκεν ὁ Σκιπίων ἐκ τῆς ἰδίας οὐσίας. ἔστι δ’ οὐκ ἐλάττων ἡ σύμπασα τριάκοντα ταλάντων, ἐάν τις μεγαλομερῶς ποιῇ. φήμης περὶ αὐτοῦ διαδιδομένης, μετήλλαξεν ἡ μήτηρ. ὁ δὲ τοσοῦτον ἀπέσχε τοῦ κομίσασθαί τι ὧν πρότερον ἐδωρήσατο, περὶ ὧν ἀρτίως εἶπον, ὥστε καὶ ταῦτα καὶ τὴν λοιπὴν οὐσίαν τὴν τῆς μητρὸς ἅπασαν ἀπέδωκε ταῖς ἀδελφαῖς, ἧς οὐδὲν αὐταῖς προσῆκε κατὰ τοὺς νόμους. διὸ πάλιν τῶν ἀδελφῶν παραλαβουσῶν τὸν ἐν ταῖς ἐξόδοις κόσμον καὶ τὴν περίστασιν τὴν τῆς Αἰμιλίας, πάλιν ἐκαινοποιήθη τὸ μεγαλόψυχον καὶ φιλοίκειον τῆς τοῦ Σκιπίωνος προαιρέσεως. ταῦτα μὲν οὖν προκατεσκευασμένος ἐκ τῆς πρώτης ἡλικίας Πόπλιος Σκιπίων προῆλθε πρὸς τὸ φιλοδοξεῖν σωφροσύνῃ καὶ καλοκἀγαθίᾳ. εἰς ἣν ἴσως ἑξήκοντα τάλαντα δαπανήσας, τοσαῦτα γὰρ ἦν προειμένος τῶν ἰδίων, ὁμολογουμένην ἔσχε τὴν ἐπὶ καλοκἀγαθίᾳ φήμην, οὐχ οὕτω τῷ πλήθει τῶν χρημάτων τὸ προκείμενον κατεργασάμενος ὡς τῷ καιρῷ τῆς δόσεως καὶ τῷ χειρισμῷ τῆς χάριτος. τὴν δὲ σωφροσύνην περιεποιήσατο δαπανήσας μὲν οὐδέν, πολλῶν δὲ καὶ ποικίλων ἡδονῶν ἀποσχόμενος προσεκέρδανε τὴν σωματικὴν ὑγίειαν καὶ τὴν εὐεξίαν, ἥτις αὐτῷ παρ’ ὅλον τὸν βίον παρεπομένη πολλὰς ἡδονὰς καὶ καλὰς ἀμοιβὰς ἀπέδωκεν ἀνθ’ ὧν πρότερον ἀπέσχετο τῶν προχείρων ἡδονῶν.", "st": "32.14"}, {"sp": "N", "t": "λοιποῦ δ’ ὄντος τοῦ κατὰ τὴν ἀνδρείαν μέρους καὶ κυριωτάτου σχεδὸν ἐν πάσῃ μὲν πολιτείᾳ μάλιστα δ’ ἐν τῇ Ῥώμῃ, μεγίστην ἔδει καὶ τὴν ἄσκησιν περὶ τοῦτο τὸ μέρος ποιήσασθαι. καλὸν μὲν οὖν τι πρὸς ταύτην τὴν ἐπιβολὴν αὐτῷ καὶ διὰ τῆς τύχης ἐγένετο συνέργημα. τῶν γὰρ ἐν Μακεδονίᾳ βασιλικῶν μεγίστην ποιουμένων σπουδὴν περὶ τὰς κυνηγεσίας καὶ Μακεδόνων ἀνεικότων τοὺς ἐπιτηδειοτάτους τόπους πρὸς τὴν τῶν θηρίων συναγωγήν, ταῦτα συνέβη τὰ χωρία τετηρῆσθαι μὲν ἐπιμελῶς, καθάπερ καὶ πρότερον, πάντα τὸν τοῦ πολέμου χρόνον, κεκυνηγῆσθαι δὲ μηδέποτε τῶν τεττάρων ἐτῶν διὰ τοὺς περισπασμούς· ᾗ καὶ θηρίων ὑπῆρχε πλήρη παντοδαπῶν. τοῦ δὲ πολέμου λαβόντος κρίσιν, ὁ Λεύκιος καλλίστην ὑπολαμβάνων καὶ τὴν ἄσκησιν καὶ τὴν ψυχαγωγίαν ὑπάρχειν τοῖς νέοις τὴν περὶ τὰ κυνηγέσια, τούς τε κυνηγοὺς συνέστησε τοὺς βασιλικοὺς τῷ Σκιπίωνι καὶ τὴν ἐξουσίαν τὴν περὶ τὰ κυνηγέσια παρέδωκε τούτῳ πᾶσαν· ἧς ἐπιλαβόμενος ὁ προειρημένος καὶ νομίσας οἱονεὶ βασιλεύειν, ἐν τούτῳ κατεγίνετο πάντα τὸν χρόνον, ὅσον ἐπέμεινε τὸ στρατόπεδον μετὰ τὴν μάχην ἐν τῇ Μακεδονίᾳ. γενομένης δὲ μεγάλης ἐνθουσιάσεως περὶ τοῦτο τὸ μέρος, ὡς κατά τε τὴν ἡλικίαν ἀκμαίως ἔχοντος αὐτοῦ καὶ κατὰ φύσιν οἰκείως διακειμένου, καθάπερ εὐγενοῦς σκύλακος, ἐπίμονον αὐτοῦ συνέβη γενέσθαι τὴν περὶ τὰς κυνηγεσίας ὁρμήν. διὸ καὶ παραγενόμενος εἰς τὴν Ῥώμην καὶ προσλαβὼν τὸν τοῦ Πολυβίου πρὸς τοῦτο τὸ μέρος ἐνθουσιασμόν, ἐφ’ ὅσον οἱ λοιποὶ τῶν νέων περὶ τὰς κρίσεις καὶ τοὺς χαιρετισμοὺς ἐσπούδαζον, κατὰ τὴν ἀγορὰν ποιούμενοι τὴν διατριβήν, καὶ διὰ τούτων συνιστάνειν ἑαυτοὺς ἐπειρῶντο τοῖς πολλοῖς, ἐπὶ τοσοῦτον ὁ Σκιπίων ἐν ταῖς κυνηγεσίαις ἀναστρεφόμενος καὶ λαμπρὸν ἀεί τι ποιῶν καὶ μνήμης ἄξιον καλλίω δόξαν ἐξεφέρετο τῶν ἄλλων. οἷς μὲν γὰρ οὐκ ἦν ἐπαίνου τυχεῖν, εἰ μὴ βλάψαιέν τινα τῶν πολιτῶν· ὁ γὰρ τῶν κρίσεων τρόπος τοῦτ’ ἐπιφέρειν εἴωθεν· ὁ δ’ ἁπλῶς οὐδένα λυπῶν ἐξεφέρετο τὴν ἐπ’ ἀνδρείᾳ δόξαν πάνδημον, ἔργῳ πρὸς λόγον ἁμιλλώμενος. τοιγαροῦν ὀλίγῳ χρόνῳ τοσοῦτον παρέδραμε τοὺς καθ’ αὑτὸν ὅσον οὐδείς πω μνημονεύεται Ῥωμαίων, καίπερ τὴν ἐναντίαν ὁδὸν πορευθεὶς ἐν φιλοδοξίᾳ τοῖς ἄλλοις ἅπασι πρὸς τὰ Ῥωμαίων ἔθη καὶ νόμιμα.", "st": "32.15"}, {"sp": "N", "t": "ἐγὼ δὲ πλείω πεποίημαι λόγον ὑπὲρ τῆς Σκιπίωνος αἱρέσεως ἐκ τῆς πρώτης ἡλικίας, ἡδεῖαν μὲν ὑπολαμβάνων εἶναι τοῖς πρεσβυτέροις, ὠφέλιμον δὲ τοῖς νέοις τὴν τοιαύτην ἱστορίαν, μάλιστα δὲ βουλόμενος πίστιν παρασκευάζειν τοῖς λέγεσθαι μέλλουσιν ἐν ταῖς ἑξῆς βύβλοις περὶ αὐτοῦ πρὸς τὸ μήτε διαπορεῖν τοὺς ἀκούοντας διὰ τὸ παράδοξά τινα φανήσεσθαι τῶν συμβαινόντων μετὰ ταῦτα περὶ αὐτόν, μήτ’ ἀφαιρουμένους τἀνδρὸς τὰ κατὰ λόγον γεγονότα κατορθώματα τῇ τύχῃ προσάπτειν, ἀγνοοῦντας τὰς αἰτίας, ἐξ ὧν ἕκαστα συνέβη γενέσθαι, πλὴν τελέως ὀλίγων, ἃ δεῖ μόνα προσάπτειν τῇ τύχῃ καὶ ταὐτομάτῳ. ταῦτα μὲν οὖν ἐπὶ τοσοῦτον ἡμεῖς διεληλυθότες κατὰ τὴν παρέκβασιν αὖθις ἐπάνιμεν ἐπὶ τὴν ἐκτροπὴν τῆς ὑποκειμένης διηγήσεως.", "st": "32.16"}, {"sp": "N", "t": "ὅτι παρὰ τῶν Ἀθηναίων ἧκον πρέσβεις καὶ παρὰ τῶν Ἀχαιῶν οἱ περὶ Θεαρίδαν καὶ Στέφανον ὑπὲρ τῶν Δηλίων. τοῖς γὰρ Δηλίοις δοθείσης ἀποκρίσεως παρὰ Ῥωμαίων, μετὰ τὸ συγχωρηθῆναι τὴν Δῆλον τοῖς Ἀθηναίοις, αὐτοῖς μὲν ἐκχωρεῖν ἐκ τῆς νήσου, τὰ δ’ ὑπάρχοντα κομίζεσθαι, μεταστάντες εἰς Ἀχαΐαν οἱ Δήλιοι καὶ πολιτογραφηθέντες ἐβούλοντο τὸ δίκαιον ἐκλαβεῖν παρὰ τῶν Ἀθηναίων κατὰ τὸ πρὸς τοὺς Ἀχαιοὺς σύμβολον. τῶν δ’ Ἀθηναίων φασκόντων μηδὲν εἶναι πρὸς αὐτοὺς τῆς δικαιοδοσίας ταύτης, ᾐτοῦντο ῥύσια τοὺς Ἀχαιοὺς οἱ Δήλιοι κατὰ τῶν Ἀθηναίων. ὑπὲρ ὧν τότε πρεσβεύσαντες ἔλαβον ἀπόκρισιν κυρίας εἶναι τὰς κατὰ τοὺς νόμους γεγενημένας παρὰ τοῖς Ἀχαιοῖς οἰκονομίας περὶ τῶν Δηλίων.", "st": "32.17"}, {"sp": "N", "t": "ὅτι τῶν Ἰσσίων πλεονάκις πεπρεσβευκότων εἰς τὴν Ῥώμην καὶ διασαφούντων ὅτι Δελματεῖς τὴν χώραν ἀδικοῦσι καὶ τὰς πόλεις τὰς μετ’ αὐτῶν ταττομένας· αὗται δ’ εἰσὶν Ἐπέτιον καὶ Τραγύριον· ὁμοίως δὲ καὶ τῶν Δαορσῶν ἐγκαλούντων, ἐξαπέστειλεν ἡ σύγκλητος πρεσβευτὰς τοὺς περὶ Γάιον Φάννιον ἐποπτεύσοντας τὰ κατὰ τὴν Ἰλλυρίδα, καὶ μάλιστα τούτων τὰ κατὰ τοὺς Δελματεῖς. οὗτοι δέ, μέχρι μὲν ἔζη Πλευρᾶτος, ὑπήκουον ἐκείνῳ· μεταλλάξαντος δὲ τούτου τὸν βίον, καὶ διαδεξαμένου Γενθίου τὴν βασιλείαν, ἀποστάντες ἀπὸ τούτου τοῖς ὁμόροις προσεπολέμουν καὶ κατεστρέφοντο τοὺς ἀστυγείτονας, ὧν ἔνιοι καὶ φόρους αὐτοῖς ἔφερον· ὁ δὲ φόρος ἦν θρέμματα καὶ σῖτος. καὶ οἱ μὲν περὶ Φάννιον ἐπὶ τούτοις ἐξώρμησαν. —", "st": "32.18"}, {"sp": "N", "t": "ὅτι Λυκίσκου τοῦ Αἰτωλοῦ ταρα χώδους ὄντος καὶ θορυβώδους, ἀναιρεθέντος δὲ τούτου, τὸ ἑξῆς οἱ Αἰτωλοὶ ὡμοφρόνησαν καὶ ὡμονόησαν ἑνὸς ἀνθρώπου παραχωρήσαντος· τηλικαύτη τίς ἐστιν, ὡς ἔοικε, δύναμις ἐν ταῖς τῶν ἀνθρώπων φύσεσιν, ὥστε μὴ μόνον στρατόπεδα καὶ πόλεις, ἀλλὰ καὶ τὰς ἐθνικὰς συστάσεις καὶ τὰς ὁλοσχερεῖς διαφορὰς τῆς οἰκουμένης δι’ ἑνὸς ἀνδρὸς ἀρετὴν καὶ κακίαν ποτὲ μὲν τῶν μεγίστων κακῶν, ποτὲ δὲ τῶν μεγίστων ἀγαθῶν πεῖραν λαμβάνειν. — ὅτι Λυκίσκος κάκιστος ὢν καλῶς κατέστρεψε τὸν βίον, ὥστε τοὺς πλείστους εἰκότως ὀνειδίζειν τῇ τύχῃ διότι τὸ τῶν ἀγαθῶν ἀνδρῶν ἆθλον τὴν εὐθανασίαν τοῖς χειρίστοις ἐνίοτε περιτίθησιν. —", "st": "32.19"}, {"sp": "N", "t": "ὅτι τὰ κατὰ τὴν Αἰτωλίαν καλῶς διετέθη, κατεσβεσμένης ἐν αὐτοῖς τῆς ἐμφυλίου στάσεως μετὰ τὸν Λυκίσκου θάνατον, καὶ Μνασίππου τοῦ Κορωναίου μεταλλάξαντος τὸν βίον βελτίων ἦν ἡ διάθεσις κατὰ τὴν Βοιωτίαν, ὁμοίως δὲ καὶ κατὰ τὴν Ἀκαρνανίαν Χρέμα γεγονότος ἐκποδών. σχεδὸν γὰρ ὡσανεὶ καθαρμόν τινα συνέβη γενέσθαι τῆς Ἑλλάδος, τῶν ἀλιτηρίων αὐτῆς ἐκ τοῦ ζῆν μεθισταμένων. καὶ γὰρ καὶ τὸν Ἠπειρώτην Χάροπα συνεκύρησε κατὰ τὸν ἐνιαυτὸν τοῦτον ἐν Βρεντεσίῳ μεταλλάξαι τὸν βίον. τὰ δὲ κατὰ τὴν Ἤπειρον ἔτ’ ἐν ἀκαταστασίαις ἦν καὶ ταραχαῖς, ὡς κατὰ τοὺς ἐπάνω χρόνους, διὰ τὴν Χάροπος ὠμότητα καὶ παρανομίαν, ἐξ οὗ συνέβη τελεσθῆναι τὸν πρὸς Περσέα πόλεμον. μετὰ γὰρ τὸ κατακρῖναι Λεύκιον Ἀνίκιον καὶ Λεύκιον Αἰμίλιον ἀνελεῖν τοὺς μὲν τῶν ἐπιφανῶν ἀνδρῶν, τοὺς δ’ ἀπαγαγεῖν εἰς τὴν Ῥώμην, ὅσοι καὶ βραχεῖαν ὑποψίαν εἶχον, τότε λαβὼν ὁ Χάροψ τὴν ἐξουσίαν ὃ βούλοιτο πράττειν, οὐκ ἔστι τῶν δεινῶν ὁποῖον οὐκ ἐποίει, τὰ μὲν δι’ αὑτοῦ, τὰ δὲ διὰ τῶν φίλων, ἅτε νέος μὲν ὢν αὐτὸς κομιδῇ, συνδεδραμηκότων δὲ πρὸς αὐτὸν τῶν χειρίστων καὶ τῶν εἰκαιοτάτων ἀνθρώπων διὰ τὸν ἐκ τῶν ἀλλοτρίων νοσφισμόν. εἶχε δ’ οἷον ἐφεδρείαν καὶ ῥοπὴν πρὸς τὸ πιστεύεσθαι διότι πράττει κατά τινα λόγον ἃ ποιεῖ καὶ μετὰ τῆς Ῥωμαίων γνώμης τήν τε προϋπάρχουσαν αὐτῷ σύστασιν πρὸς τοὺς προειρημένους καὶ πρὸς ταύτῃ Μύρτωνα πρεσβύτην ἄνθρωπον καὶ τὸν υἱὸν αὐτοῦ Νικάνορα, τἄλλα τε μετρίους ἀνθρώπους καὶ δοκοῦντας εἶναι Ῥωμαίων φίλους, οἳ πολύ τι κεχωρισμένοι τὸν πρὸ τοῦ χρόνον ἁπάσης ἀδικίας οὐκ οἶδ’ ὅπως τότε συνεπέδωκαν αὑτοὺς εἰς τὸ συνεπισχύειν καὶ κοινωνεῖν ταῖς τοῦ Χάροπος ἀνομίαις. ἐπειδὴ δ’ ὁ προειρημένος τοὺς μὲν κατὰ τὴν ἀγορὰν ἀναφανδὸν ἐφόνευσε, τοὺς δ’ ἐν ταῖς ἰδίαις οἰκίαις, ἐνίους δ’ ἐπὶ τῶν ἀγρῶν καὶ κατὰ τὰς ὁδοὺς ἐπαποστέλλων ἐδολοφόνησε καὶ πάντων τῶν τεθνεώτων ἐξηνδραποδίσατο τοὺς βίους, ἄλλην ἐπεισῆγε μηχανήν. προέγραφε γὰρ τοὺς εὐκαιροῦντας τοῖς βίοις φυγάδας, οὐ μόνον ἄνδρας ἀλλὰ καὶ γυναῖκας· ἀναταθεὶς δὲ τὸν φόβον τοῦτον ἐχρηματίζετ’ ἀεὶ τοὺς μὲν ἄνδρας δι’ ἑαυτοῦ, τὰς δὲ γυναῖκας διὰ τῆς μητρὸς Φιλώτιδος· πάνυ γὰρ εὐφυὲς ἐγένετο καὶ τοῦτο τὸ πρόσωπον, πρὸς δὲ βίαν καὶ πλεῖόν τι δυνάμενον συνεργεῖν ἢ κατὰ γυναῖκα.", "st": "32.20"}, {"sp": "N", "t": "ἐπειδὴ δὲ πάντας καὶ πάσας ἐξηργυρίσαντο κατὰ τὸ δυνατόν, εἰσῆγον εἰς τὸν δῆμον οὐδὲν ἧττον ἅπαντας τοὺς προγεγραμμένους. οἱ δὲ πολλοὶ τῶν ἐν τῇ Φοινίκῃ τὰ μὲν διὰ τὸν φόβον, τὰ δὲ καὶ δελεαζόμενοι διὰ τῶν περὶ τὸν Χάροπα κατέκριναν οὐ φυγῆς ἀλλὰ θανάτου πάντας τοὺς προσαγγελθέντας ὡς ἀλλότρια φρονοῦντας Ῥωμαίων. οὗτοι μὲν οὖν πάντες ἔφυγον, ὁ δὲ Χάροψ ὥρμησεν εἰς τὴν Ῥώμην, ἔχων χρήματα καὶ τοὺς περὶ τὸν Μύρτωνα μεθ’ αὑτοῦ, βουλόμενος ἐπισφραγίσασθαι διὰ τῆς συγκλήτου τὴν αὑτοῦ παρανομίαν. ἐν ᾧ καιρῷ κάλλιστον μὲν ἐγένετο δεῖγμα τῆς Ῥωμαίων αἱρέσεως, κάλλιστον δὲ θέαμα πᾶσι τοῖς Ἕλλησι τοῖς παρεπιδήμοις, μάλιστα δὲ τοῖς ἀνακεκλημένοις· ὅ τε γὰρ Μάρκος, ἀρχιερεὺς ὢν καὶ πρῶτος τῆς συγκλήτου γραφόμενος, ὅ τε Λεύκιος ὁ τὸν Περσέα νικήσας, μεγίστην ἔχων πίστιν καὶ δύναμιν, πυνθανόμενοι τὰ πεπραγμένα τῷ Χάροπι κατὰ τὴν Ἤπειρον ἐκώλυσαν εἰς τὰς οἰκίας αὑτῶν εἰσιέναι τὸν Χάροπα. οὗ γενομένου περιβοήτου πάντες ἐγενήθησαν οἱ παρεπιδημοῦντες περιχαρεῖς, ἀποδεχόμενοι τὸ μισοπόνηρον τῶν Ῥωμαίων. μετὰ δὲ ταῦτα τοῦ Χάροπος εἰσελθόντος εἰς τὴν σύγκλητον, οὐ συγκατέθετο τοῖς ἀξιουμένοις οὐδ’ ἐβουλήθη δοῦναι ῥητὴν ἀπόκρισιν, ἀλλὰ τοῖς ἀποστελλομένοις πρεσβευταῖς ἔφη δώσειν ἐντολὰς ἐπισκέψασθαι περὶ τῶν γεγονότων. ὁ δὲ Χάροψ ἀναχωρήσας ταύτην μὲν τὴν ἀπόκρισιν ἀπεσιώπησε, γράψας δὲ πρὸς τὴν ἰδίαν ὑπόθεσιν ἁρμόζουσαν ἀπήγγειλεν ὡς συνευδοκούντων Ῥωμαίων τοῖς ὑπ’ αὐτοῦ πραττομένοις.", "st": "32.21"}, {"sp": "N", "t": "ὅτι Εὐμένης ὁ βασιλεὺς τῇ μὲν σωματικῇ δυνάμει παραλελυμένος ἦν, τῇ δὲ τῆς ψυχῆς λαμπρότητι προσανεῖχεν, ἀνὴρ ἐν μὲν τοῖς πλείστοις οὐδενὸς δεύτερος τῶν καθ’ αὑτὸν βασιλέων γενόμενος, περὶ δὲ τὰ σπουδαιότατα καὶ κάλλιστα μείζων καὶ λαμπρότερος· ὅς γε πρῶτον μὲν παραλαβὼν παρὰ τοῦ πατρὸς τὴν βασιλείαν συνεσταλμένην τελέως εἰς ὀλίγα καὶ λιτὰ πολισμάτια ταῖς μεγίσταις τῶν καθ’ αὑτὸν δυναστειῶν ἐφάμιλλον ἐποίησε τὴν ἰδίαν ἀρχήν, οὐ τύχῃ τὸ πλεῖον συνεργῷ χρώμενος, οὐδ’ ἐκ περιπετείας, ἀλλὰ διὰ τῆς ἀγχινοίας καὶ φιλοπονίας, ἔτι δὲ πράξεως τῆς αὑτοῦ. δεύτερον φιλοδοξότατος ἐγενήθη καὶ πλείστας μὲν τῶν καθ’ αὑτὸν βασιλέων πόλεις Ἑλληνίδας εὐεργέτησε, πλείστους δὲ κατ’ ἰδίαν ἀνθρώπους ἐσωματοποίησε. τρίτον ἀδελφοὺς ἔχων τρεῖς καὶ κατὰ τὴν ἡλικίαν καὶ πρᾶξιν, πάντας τούτους συνέσχε πειθαρχοῦντας αὑτῷ καὶ δορυφοροῦντας καὶ σῴζοντας τὸ τῆς βασιλείας ἀξίωμα. τοῦτο δὲ σπανίως εὕροι τις ἂν γεγονός.", "st": "32.22"}, {"sp": "N", "t": "ὅτι Ἄτταλος ὁ ἀδελφὸς Εὐμένους παραλαβὼν τὴν ἐξουσίαν πρῶτον ἐξήνεγκε δεῖγμα τῆς αὑτοῦ προαιρέσεως καὶ πράξεως τὴν Ἀριαράθου καταγωγὴν ἐπὶ τὴν βασιλείαν.", "st": "32.22"}, {"sp": "N", "t": "ὅτι τῶν περὶ τὸν Γάιον Φάννιον παραγεγονότων ἐκ τῆς Ἰλλυρίδος καὶ διασαφούντων ὅτι τοσοῦτον ἀπέχοιεν οἱ Δελματεῖς τοῦ διορθοῦσθαί τι τῶν ἐγκαλουμένων πρὸς τοὺς ὑπ’ αὐτῶν φάσκοντας ἀδικεῖσθαι συνεχῶς, ὡς οὐδὲ λόγον ἐπιδέχοιντο καθόλου παρ’ αὐτῶν, λέγοντες οὐδὲν αὑτοῖς εἶναι καὶ Ῥωμαίοις κοινόν· πρὸς δὲ τούτοις διεσάφουν μήτε κατάλυμα δοθῆναι σφίσι μήτε παροχήν, ἀλλὰ καὶ τοὺς ἵππους, οὓς εἶχον παρ’ ἑτέρας πόλεως, ἀφελέσθαι τοὺς Δελματεῖς μετὰ βίας αὑτῶν· ἑτοίμους δ’ εἶναι καὶ τὰς χεῖρας προσάγειν, εἰ μὴ συνείξαντες τῷ καιρῷ μετὰ πολλῆς ἡσυχίας ἐποιήσαντο τὴν ἀπόλυσιν. ὧν ἡ σύγκλητος ἀκούσασα μετ’ ἐπιστάσεως ἠγανάκτει μὲν καὶ ἐπὶ τῇ τῶν Δελματέων ἀπειθείᾳ καὶ σκαιότητι, τὸ δὲ πλεῖστον ὑπέλαβε τὸν καιρὸν ἐπιτήδειον εἶναι πρὸς τὸ πολεμῆσαι τοῖς προειρημένοις διὰ πλείους αἰτίας. τά τε γὰρ μέρη ταῦτα τῆς Ἰλλυρίδος τὰ νεύοντα πρὸς τὸν Ἀδρίαν ἀνεπίσκεπτα τελέως ἦν αὐτοῖς, ἐξ οὗ Δημήτριον τὸν Φάριον ἐξέβαλον, τούς τε κατὰ τὴν Ἰταλίαν ἀνθρώπους οὐκ ἐβούλοντο κατ’ οὐδένα τρόπον ἀποθηλύνεσθαι διὰ τὴν πολυχρόνιον εἰρήνην· ἔτος γὰρ ἦν τότε δωδέκατον ἀπὸ τοῦ πρὸς Περσέα πολέμου καὶ τῶν ἐν Μακεδονίᾳ πράξεων. διόπερ ἐβουλεύοντο, πόλεμον ἐνστησάμενοι πρὸς τοὺς προειρημένους ἅμα μὲν ὡσανεὶ καινοποιῆσαι τὰς ὁρμὰς καὶ προθυμίας τῶν ἰδίων ὄχλων, ἅμα δὲ καταπληξάμενοι τοὺς Ἰλλυριοὺς ἀναγκάσαι πειθαρχεῖν τοῖς ὑπ’ αὐτῶν παραγγελλομένοις. αὗται μὲν οὖν ἦσαν αἰτίαι δι’ ἃς ἐπολέμησαν Ῥωμαῖοι Δελματεῦσι· τοῖς γε μὴν ἐκτὸς τὸν πόλεμον ἀνεδείκνυον, ὡς διὰ τὴν εἰς τοὺς πρεσβευτὰς ὕβριν κεκρικότες πολεμεῖν. —", "st": "32.23"}, {"sp": "N", "t": "ὅτι ὁ βασιλεὺς Ἀριαράθης παρεγένετο εἰς τὴν Ῥώμην ἔτι θερείας οὔσης· τότε δέ, παρειληφότων ὑπάτων τὰς ἀρχὰς τῶν περὶ τὸν Σέξτον Ἰούλιον καὶ Λεύκιον Αὐρήλιον, ἐγίνετο περὶ τὰς κατ’ ἰδίαν ἐντεύξεις, οἰκείαν ποιούμενος περικοπὴν καὶ φαντασίαν τῆς ὑποκειμένης περιστάσεως. παρῆσαν δὲ καὶ παρὰ Δημητρίου πρέσβεις οἱ περὶ τὸν Μιλτιάδην πρὸς ἑκατέραν τὴν ὑπόθεσιν ἡρμοσμένοι· καὶ γὰρ πρὸς Ἀριαράθην ἀπολογεῖσθαι καὶ κατηγορεῖν αὐτοῦ παρεσκευάζοντο φιλαπεχθῶς. ἀπεστάλκει δὲ καὶ Ὀροφέρνης πρεσβευτὰς τοὺς περὶ Τιμόθεον καὶ Διογένην, στέφανόν τε κομίζοντας τῇ Ῥώμῃ καὶ τὴν φιλίαν καὶ τὴν συμμαχίαν ἀνανεωσομένους, τὸ δὲ πλεῖον συγκαταστησομένους πρὸς τὸν Ἀριαράθην καὶ τὰ μὲν ἀπολογησομένους, τὰ δὲ κατηγορήσοντας. ἐν μὲν οὖν ταῖς κατ’ ἰδίαν ἐντεύξεσιν μείζω φαντασίαν εἷλκον οἱ περὶ τὸν Διογένην καὶ Μιλτιάδην, ἅτε καὶ κατὰ τὸ πλῆθος πρὸς ἕνα συγκρινόμενοι καὶ κατὰ τὴν ἄλλην περικοπὴν εὐτυχοῦντες πρὸς ἐπταικότα θεωρούμενοι· παραπλησίως δὲ καὶ περὶ τὴν τῶν πραγμάτων ἐξήγησιν πολὺ περιῆσαν· πᾶν μὲν γὰρ καὶ πρὸς παντοῖα λέγειν ἐθάρρουν, οὐδένα λόγον ποιούμενοι τῆς ἀληθείας, τὸ δὲ λεγόμενον ἀνυπεύθυνον ἦν, οὐκ ἔχον τὸν ἀπολογησόμενον. λοιπὸν ἀκονιτὶ τοῦ ψεύδους ἐπικρατοῦντος, ἐδόκει σφίσι τὰ πράγματα κατὰ γνώμην χωρεῖν.", "st": "32.24"}, {"sp": "N", "t": "ὅτι οὐκ ὀλίγοι τῶν ἀνθρώπων διὰ τὴν πρὸς τὸ πλεῖον ἐπιθυμίαν καὶ τὸ πνεῦμα προσέθηκαν τοῖς χρήμασιν, οἷς Ὀροφέρνης ὁ τῆς Καππαδοκίας βασιλεὺς κατάληπτος γενόμενος ἀπώλετο καὶ τῆς βασιλείας ἐξέπεσεν. ἡμεῖς δὲ συγκεφαλαιωσάμενοι τὴν τούτου κάθοδον ἐπανάξομεν τὴν διήγησιν ἐπὶ τὴν εἰθισμένην τάξιν, ᾗ χρώμεθα παρ’ ὅλην τὴν πραγματείαν· καὶ γὰρ νῦν ὑπερβάντες τὰ κατὰ τὴν Ἑλλάδα προελάβομεν τῶν κατὰ τὴν Ἀσίαν τὰ κατὰ τὴν Καππαδοκίαν διὰ τὸ μηδεμίαν εὔλογον ἔχειν διαίρεσιν τὸν ἐκ τῆς Ἰταλίας ἀπόπλουν καὶ τὴν ἐπὶ τὰ πράγματα κάθοδον [τοῦ] Ἀριαράθου. διόπερ ἐπάνειμι δηλώσων τὰ κατὰ τὴν Ἑλλάδα γενόμενα περὶ τοὺς αὐτοὺς καιρούς. ἐν οἷς ἴδιον καὶ παράλογον πρᾶγμα συνέβη γενέσθαι περὶ τὴν τῶν Ὠρωπίων πόλιν· ὑπὲρ οὗ τὰ μὲν ἀναδραμόντες, τὰ δὲ προλαβόντες τοῖς χρόνοις συγκεφαλαιωσόμεθα τὴν ὅλην πρᾶξιν, ἵνα μὴ κατὰ μέρος αὐτῆς οὔσης οὐδ’ ὅλως ἐπιφανοῦς ἐν διῃρημένοις χρόνοις ἀπαγγέλλοντες εὐτελῆ καὶ ἀσαφῆ ποιῶμεν τὴν διήγησιν. ὅταν γὰρ μόλις τὸ ὅλον ἄξιον ἐπιστάσεως φαίνηται τοῖς ἀκούουσιν, ἦ πού γε τοῖς κατὰ μέρος ἐκ διαστήματος λεγομένοις τὸν νοῦν προσέξει τις τῶν φιλομαθούντων; — ὅτι κατὰ τὸ πλεῖστον ἐν ταῖς ἐπιτυχίαις ὡς ἐπίπαν ἄνθρωποι συμφρονοῦσι, κατὰ δὲ τὰς ἀποτυχίας ἀσχάλλοντες τοῖς πράγμασιν ἑλκώδεις καὶ δύσκολοι γίνονται πρὸς τοὺς φίλους· ὃ καὶ περὶ τὸν Ὀροφέρνην συνέβη γενέσθαι, τῶν πραγμάτων αὐτῷ ἀντιπιπτόντων καὶ τῷ Θεοτίμῳ καὶ μεμφομένων ἀλλήλοις. — Ὀροφέρνην. … ὀλίγον χρόνον Καππαδοκίας βασιλεύσαντα καὶ παριδόντα τὰς πατρίους ἀγωγάς φησιν ἐν τῇ τριακοστῇ δευτέρᾳ εἰσαγαγεῖν τὴν Ἰακὴν καὶ τεχνιτικὴν ἀσωτίαν. —", "st": "32.25"}, {"sp": "N", "t": "κατὰ τὸν καιρὸν τοῦτον παραγεγονότων πρεσβευτῶν ἐξ Ἠπείρου παρά τε τῶν τὴν Φοινίκην κατεχόντων καὶ παρὰ τῶν ἐκπεπτωκότων καὶ ποιησαμένων λόγους κατὰ πρόσωπον, ἔδωκεν ἀπόκρισιν αὐτοῖς ἡ σύγκλητος ὅτι δώσει περὶ τούτων ἐντολὰς τοῖς ἀποστελλομένοις πρεσβευταῖς εἰς τὴν Ἰλλυρίδα μετὰ Γαΐου Μαρκίου.", "st": "32.26"}, {"sp": "N", "t": "ὅτι Προυσίας μετὰ τὸ νικῆσαι τὸν Ἄτταλον μετὰ τὸ παρελθεῖν πρὸς τὸ Πέργαμον παρασκευασάμενος θυσίαν πολυτελῆ προσήγαγε πρὸς τὸ τέμενος τἈσκληπιοῦ, καὶ βουθυτήσας καὶ καλλιερήσας τότε μὲν ἐπανῆλθεν εἰς τὴν παρεμβολήν, κατὰ δὲ τὴν ἐπιοῦσαν καταστήσας τὴν δύναμιν ἐπὶ τὸ Νικηφόριον τούς τε νεὼς ἅπαντας διέφθειρε καὶ τὰ τεμένη τῶν θεῶν, ἐσύλησε δὲ καὶ τοὺς ἀνδριάντας καὶ τὰ λίθινα τῶν ἀγαλμάτων. τὸ δὲ τελευταῖον καὶ τὸ τἈσκληπιοῦ βαστάσας ἄγαλμα, περιττῶς ὑπὸ Φυρομάχου κατεσκευασμένον, ἀπήνεγκεν ὡς αὑτόν, ᾧ τῇ πρότερον ἡμέρᾳ κατασπένδων ἐβουθύτει καὶ κατηύχετο, δεόμενος, ὅπερ εἰκός, ἵλεων αὑτῷ γενέσθαι καὶ εὐμενῆ κατὰ πάντα τρόπον. ἐγὼ δὲ τὰς τοιαύτας διαθέσεις καὶ πρότερον εἴρηκά που, περὶ Φιλίππου ποιούμενος τὸν λόγον, μανικάς. τὸ γὰρ ἅμα μὲν θύειν καὶ διὰ τούτων ἐξιλάσκεσθαι τὸ θεῖον, προσκυνοῦντα καὶ λιπαροῦντα τὰς τραπέζας καὶ τοὺς βωμοὺς ἐξάλλως, ὅπερ ὁ Προυσίας εἴθιστο ποιεῖν γονυπετῶν καὶ γυναικιζόμενος, ἅμα δὲ ταῦτα καὶ λυμαίνεσθαι καὶ διὰ τῆς τούτων καταφθορᾶς τὴν εἰς τὸ θεῖον ὕβριν διατίθεσθαι, πῶς οὐκ ἂν εἴποι τις εἶναι θυμοῦ λυττῶντος ἔργα καὶ ψυχῆς ἐξεστηκυίας τῶν λογισμῶν; ὃ καὶ τότε συνέβαινε γίνεσθαι περὶ τὸν Προυσίαν. ἀνδρὸς μὲν γὰρ ἔργον οὐδὲν ἐπιτελεσάμενος κατὰ τὰς προσβολάς, ἀγεννῶς δὲ καὶ γυναικοθύμως χειρίσας καὶ τὰ πρὸς θεοὺς καὶ τὰ πρὸς ἀνθρώπους μετήγαγε τὸ στράτευμα πρὸς Ἐλαίαν· καὶ καταπειράσας τῆς Ἐλαίας καί τινας προσβολὰς ποιησάμενος, οὐδὲν δὲ πράττειν δυνάμενος διὰ τὸ Σώσανδρον τὸν τοῦ βασιλέως σύντροφον εἰσεληλυθότα μετὰ στρατιωτῶν εἴργειν αὐτοῦ τὰς ἐπιβολάς, ἀπῆρεν ἐπὶ Θυατείρων. κατὰ δὲ τὴν ἐπάνοδον τὸ τῆς Ἀρτέμιδος ἱερὸν τῆς ἐν Ἱερᾷ κώμῃ μετὰ βίας ἐσύλησεν. ὁμοίως καὶ τὸ τοῦ Κυννείου Ἀπόλλωνος τέμενος τὸ περὶ Τῆμνον οὐ μόνον ἐσύλησεν, ἀλλὰ καὶ τῷ πυρὶ διέφθειρεν. καὶ ταῦτα διαπραξάμενος ἐπανῆλθεν εἰς τὴν οἰκείαν, οὐ μόνον τοῖς ἀνθρώποις ἀλλὰ καὶ τοῖς θεοῖς πεπολεμηκώς. ἐταλαιπώρησε δὲ καὶ τὸ πεζικὸν στράτευμα τῷ Προυσίᾳ κατὰ τὴν ἐπάνοδον ὑπό τε τοῦ λιμοῦ καὶ τῆς δυσεντερίας, ὥστε παρὰ πόδας ἐκ θεοπέμπτου δοκεῖν ἀπηντῆσθαι μῆνιν αὐτῷ διὰ ταύτας τὰς αἰτίας. —", "st": "32.27"}, {"sp": "N", "t": "ὅτι Ἄτταλος ἡττηθεὶς παρὰ Προυσίου, προχειρισάμενος Ἀθήναιον τὸν ἀδελφὸν ἐξαπέστειλε μετὰ τῶν περὶ τὸν Πόπλιον, διασαφήσοντα τῇ συγκλήτῳ τὸ γεγονός. οἱ γὰρ ἐν τῇ Ῥώμῃ, τοῦ μὲν Ἀνδρονίκου παραγενομένου καὶ διασαφοῦντος τὰ περὶ τὴν πρώτην ἔφοδον τῶν πολεμίων, οὐ προσεῖχον, ἀλλ’ ὑπενόουν τὸν Ἄτταλον βουλόμενον αὐτὸν ἐπιβαλεῖν τῷ Προυσίᾳ τὰς χεῖρας προφάσεις προκατασκευάζεσθαι καὶ προκαταλαμβάνειν διαβολαῖς· ἅμα δὲ τοῦ τε Νικομήδους καὶ τῶν περὶ τὸν Ἀντίφιλον, τῶν παρὰ τοῦ Προυσίου πρεσβευτῶν, διαμαρτυρομένων μηδὲν εἶναι τούτων, ἔτι μᾶλλον ἠπιστεῖτο τὰ λεγόμενα περὶ τοῦ Προυσίου. μετὰ δέ τινα χρόνον ἐπιδιασαφουμένης τῆς πραγματείας, ἀμφιδοξήσασα περὶ τῶν προσπιπτόντων ἡ σύγκλητος ἐξαπέστειλε πρεσβευτὰς Λεύκιον Ἀπολήιον καὶ Γάιον Πετρώνιον τοὺς ἐπισκεψομένους πῶς ἔχει τὰ κατὰ τοὺς προειρημένους βασιλεῖς.", "st": "32.28"}, {"sp": "HDR", "t": "Βιβλίον ΛΓʹ", "st": "33"}, {"sp": "N", "t": "ὅτι ἡ σύγκλητος ἔτι κατὰ χειμῶνα διακούσασα τῶν περὶ τὸν Πόπλιον Λέντλον ὑπὲρ τῶν κατὰ Προυσίαν διὰ τὸ νεωστὶ παραγεγονέναι τούτους ἐκ τῆς Ἀσίας, εἰσεκαλέσατο καὶ τὸν Ἀθήναιον τὸν Ἀττάλου τοῦ βασιλέως ἀδελφόν. οὐ μέντοι πολλῶν προσεδεήθη λόγων, ἀλλ’ εὐθέως καταστήσασα πρεσβευτὰς συνεξαπέστελλε τῷ προειρημένῳ τοὺς περὶ Γάιον Κλαύδιον Κέντωνα καὶ Λεύκιον Ὁρτήσιον καὶ Γάιον Αὐρογκολήιον, ἐντολὰς δοῦσα κωλύειν τὸν Προυσίαν Ἀττάλῳ πολεμεῖν. παρεγένοντο δὲ καὶ παρὰ τῶν Ἀχαιῶν πρέσβεις εἰς Ῥώμην ὑπὲρ τῶν κατεχομένων οἱ περὶ Ξένωνα τὸν Αἰγιέα καὶ Τηλεκλέα τὸν Αἰγειράτην. ὧν ποιησαμένων λόγους ἐν τῇ συγκλήτῳ, καὶ τοῦ διαβουλίου προτεθέντος, παρ’ ὀλίγον ἦλθον ἀπολῦσαι τοὺς κατῃτιαμένους οἱ τοῦ συνεδρίου. τὴν δ’ αἰτίαν ἔσχε τοῦ μὴ συντελεσθῆναι τὴν ἀπόλυσιν Αὖλος Ποστόμιος, στρατηγὸς ὢν ἑξαπέλεκυς καὶ βραβεύων τὸ διαβούλιον. τριῶν γὰρ οὐσῶν γνωμῶν, μιᾶς μὲν τῆς ἀφιέναι κελευούσης, ἑτέρας δὲ τῆς ἐναντίας ταύτης, τρίτης δὲ τῆς ἀπολύειν μέν, ἐπισχεῖν δὲ κατὰ τὸ παρόν, καὶ πλείστων δ’ ὄντων τῶν ἀφιέντων, παρελθὼν τὴν μίαν γνώμην διηρώτα τὰς δύο καθολικῶς, οἷς δοκεῖ τοὺς ἀνακεκλημένους ἀφιέναι καὶ τοὐναντίον. λοιπὸν οἱ κατὰ τὸ παρὸν ἐπέχειν κελεύοντες προσέβησαν πρὸς τοὺς μὴ φάσκοντας δεῖν ἀπολύειν, καὶ πλείους ἐγενήθησαν τῶν ἀφιέντων. καὶ ταῦτα μὲν ἐπὶ τούτων ἦν. —", "st": "33.1"}, {"sp": "N", "t": "ὅτι τῶν ἐκ τῆς Ῥώμης πρεσβευτῶν ἀνακαμψάντων εἰς τὴν Ἀχαΐαν καὶ διασαφούντων ὅτι παρ’ ὀλίγον ἔλθοι τὰ πράγματα τοῦ πάντας ἐπανελθεῖν τοὺς κατεχομένους, εὐέλπιδες γενόμενοι καὶ μετεωρισθέντες οἱ πολλοὶ πάλιν ἐξ αὐτῆς ἔπεμπον Τηλεκλέα καὶ τὸν Μεγαλοπολίτην Ἀναξίδαμον. καὶ τὰ μὲν κατὰ Πελοπόννησον ἐπὶ τούτων ἦν.", "st": "33.3"}, {"sp": "N", "t": "ὅτι Ἀριστοκράτης ὁ τῶν Ῥοδίων στρατηγὸς ἦν μὲν κατὰ τὴν ἐπιφάνειαν ἀξιωματικὸς καὶ καταπληκτικός. διόπερ ἐκ πάντων τοῦτον ὑπέλαβον οἱ Ῥόδιοι τελέως ἀξιόχρεων ἡγεμόνα καὶ προστάτην ἔχειν τοῦ πολέμου. διεψεύσθησαν μέντοι γε τῶν ἐλπίδων· ἐλθὼν γὰρ εἰς τὰς πράξεις ὥσπερ εἰς πῦρ, καθάπερ τὰ κίβδηλα τῶν νομισμάτων, ἀλλοῖος ἐφάνη. τοῦτο δ’ ἐγένετο δῆλον ἐπ’ αὐτῶν τῶν ἔργων.", "st": "33.4"}, {"sp": "N", "t": "προτείνειν αὐτῷ πεντακόσια τάλαντα παραχωρήσαντι τῆς Κύπρου, καὶ τἄλλα συνακολουθήσοντα λυσιτελῆ καὶ τίμια παρ’ αὐτῷ συνεπιδεικνύειν, προσενεγκαμένῳ τὴν χρείαν ταύτην. τῷ δὲ Πτολεμαίῳ γενομένης προσαγγελίας παρεῖναι τὸν Ἀρχίαν. — ὅτι Ἀρχίας βουλόμενος τὴν Κύπρον προδοῦναι τῷ Δημητρίῳ καὶ φωραθεὶς καὶ εἰς κρίσιν ἀχθεὶς καλῳδίῳ τῶν ἐκ τῆς αὐλαίας παραπεπετασμένων ἑαυτὸν ἀπεκρέμασεν. τῷ γὰρ ὄντι διὰ τὰς ἐπιθυμίας κενοὶ κενὰ λογίζονται κατὰ τὴν παροιμίαν. καὶ γὰρ ἐκεῖνος δόξας πεντακόσια τάλαντα προσλήψεσθαι καὶ τὰ προϋπάρχοντα χρήματα καὶ τὸ πνεῦμα προσαπέβαλεν.", "st": "33.5"}, {"sp": "N", "t": "ὅτι κατὰ τοὺς καιροὺς τούτους καὶ Πριηνεῖς ἐνέπεσον παραλόγῳ συμφορᾷ. δεξάμενοι γὰρ παρ’ Ὀροφέρνους, ὅτ’ ἐκράτησε τῆς ἀρχῆς, ἐν παραθήκῃ τετρακόσια τάλαντα ἀπῃτοῦντο κατὰ τοὺς ἑξῆς χρόνους ὑπ’ Ἀριαράθου, ὅτε μετέλαβε τὴν ἀρχήν. οἱ μὲν οὖν Πριηνεῖς, ὡς ἐμοὶ δοκεῖν, ὀρθῶς ἵσταντο, φάσκοντες μηδενὶ προήσεσθαι τὰ χρήματα ζῶντος Ὀροφέρνους πλὴν αὐτῷ τῷ παραθεμένῳ· ὁ δ’ Ἀριαράθης πολλοῖς ἐδόκει παραπίπτειν τοῦ καθήκοντος, ἀπαιτῶν τὴν ἀλλοτρίαν παραθήκην. οὐ μὴν ἀλλ’ ἕως μὲν τούτου τάχ’ ἄν τις ἔχοι συγγνώμην αὐτῷ καταπειράζοντι τῷ δοκεῖν τῆς ἐκείνου βασιλείας εἶναι τὰ χρήματα· τὸ δὲ καὶ πορρωτέρω προβαίνειν ὀργῆς καὶ φιλοτιμίας οὐδαμῶς ἐδόκει γενέσθαι κατὰ λόγον. κατὰ δὲ τοὺς νῦν λεγομένους καιροὺς ἐπαποστείλας ἐλεηλάτει τὴν χώραν τῶν Πριηνέων, συνεργοῦντος Ἀττάλου καὶ παροξύνοντος αὐτὸν διὰ τὴν ἰδίαν διαφοράν, ἣν εἶχε πρὸς τοὺς Πριηνεῖς. πολλῶν δὲ καὶ σωμάτων καὶ θρεμμάτων ἀπολομένων καὶ πρὸς τῇ πόλει πτωμάτων γενομένων, ἀμύνασθαι μὲν οὐχ οἷοί τ’ ἦσαν οἱ Πριηνεῖς, ἐπρέσβευον δὲ καὶ πρὸς Ῥοδίους, μετὰ δὲ ταῦτ’ ἐπὶ Ῥωμαίους κατέφυγον. οἱ δ’ οὐ προσεῖχον τοῖς λεγομένοις. καὶ Πριηνεῖς μὲν μεγάλας ἔχοντες ἐλπίδας ἐπὶ τῷ πλήθει τῶν χρημάτων τοῖς ἐναντίοις ἐνεκύρησαν· τῷ μὲν γὰρ Ὀροφέρνει τὴν παραθήκην ἀπέδωκαν, ὑπὸ δὲ τοῦ βασιλέως Ἀριαράθου ἱκαναῖς τισι βλάβαις περιέπεσον ἀδίκως διὰ τὴν παραθήκην.", "st": "33.6"}, {"sp": "N", "t": "ὅτι κατὰ τὸν αὐτὸν καιρὸν ἧκον πρεσβευταὶ καὶ παρὰ Μασσαλιητῶν, οἳ πάλαι μὲν κακῶς πάσχοντες ὑπὸ τῶν Λιγυστίνων, τότε δὲ συγκλειόμενοι τελέως, καὶ πρὸς τούτοις καὶ πολιορκουμένων τῶν πόλεων Ἀντιπόλεως καὶ Νικαίας, ἐξαπέστειλαν πρεσβευτὰς εἰς τὴν Ῥώμην τοὺς τά τε γινόμενα διασαφήσοντας καὶ δεησομένους σφίσι βοηθεῖν. ὧν καὶ παρελθόντων εἰς τὴν σύγκλητον, ἔδοξε τῷ συνεδρίῳ πρεσβευτὰς πέμψαι τοὺς ἅμα μὲν αὐτόπτας ἐσομένους τῶν γινομένων, ἅμα δὲ πειρασομένους λόγῳ διορθώσασθαι τῶν βαρβάρων τὴν ἄγνοιαν. —", "st": "33.7"}, {"sp": "N", "t": "ὅτι κατὰ τοὺς καιρούς, καθ’ οὓς ἐξέπεμψεν ἡ σύγκλητος τὸν Ὀπίμιον ἐπὶ τὸν τῶν Ὀξυβίων πόλεμον, ἧκε Πτολεμαῖος ὁ νεώτερος εἰς τὴν Ῥώμην, καὶ παρελθὼν εἰς τὴν σύγκλητον ἐποιεῖτο κατηγορίαν τἀδελφοῦ, φέρων τὴν αἰτίαν τῆς ἐπιβουλῆς ἐπ’ ἐκεῖνον. ἅμα δὲ τὰς ἐκ τῶν τραυμάτων οὐλὰς ὑπὸ τὴν ὄψιν δεικνὺς καὶ τὴν λοιπὴν δεινολογίαν ἀκόλουθον τούτοις διατιθέμενος ἐξεκαλεῖτο τοὺς ἀνθρώπους πρὸς ἔλεον. ἧκον δὲ καὶ παρὰ τοῦ πρεσβυτέρου πρέσβεις οἱ περὶ τὸν Νεολαΐδαν καὶ Ἀνδρόμαχον, ἀπολογούμενοι πρὸς τὰς ὑπὸ τἀδελφοῦ γενομένας κατηγορίας. ὧν ἡ σύγκλητος οὐδ’ ἀνέχεσθαι δικαιολογουμένων ἠβουλήθη, προκατειλημμένη ταῖς ὑπὸ τοῦ νεωτέρου διαβολαῖς· ἀλλὰ τούτοις μὲν ἐπανάγειν ἐκ τῆς Ῥώμης προσέταξεν ἐξ αὐτῆς, τῷ δὲ νεωτέρῳ πέντε πρεσβευτὰς καταστήσασα τοὺς περὶ Γνάιον Μερόλαν καὶ Λεύκιον Θέρμον καὶ πεντήρη δοῦσα τῶν πρεσβευτῶν ἑκάστῳ, τούτοις μὲν παρήγγειλε κατάγειν Πτολεμαῖον εἰς Κύπρον, τοῖς δὲ κατὰ τὴν Ἑλλάδα καὶ τὴν Ἀσίαν συμμάχοις ἔγραψαν ἐξεῖναι συμπράττειν τῷ Πτολεμαίῳ τὰ κατὰ τὴν κάθοδον.", "st": "33.8"}, {"sp": "N", "t": "ὅτι τῶν περὶ τὸν Ὁρτήσιον καὶ Αὐρογκολήιον παραγεγονότων ἐκ τοῦ Περγάμου καὶ διασαφούντων τήν τε τοῦ Προυσίου καταφρόνησιν τῶν τῆς συγκλήτου παραγγελμάτων, καὶ διότι παρασπονδήσας καὶ συγκλείσας εἰς τὸ Πέργαμον αὐτούς τε καὶ τοὺς περὶ τὸν Ἄτταλον πᾶσαν βίαν ἐνεδείξατο καὶ παρανομίαν, ἡ σύγκλητος ὀργισθεῖσα καὶ βαρέως φέρουσα τὸ γεγονὸς ἐξ αὐτῆς δέκα πρεσβευτὰς κατέστησε τοὺς περὶ Λεύκιον Ἀνίκιον καὶ Γάιον Φάννιον καὶ Κόιντον Φάβιον Μάξιμον, καὶ παραχρῆμ’ ἐξαπέστειλεν, ἐντολὰς αὐτοῖς δοῦσα διαλῦσαι τὸν πόλεμον καὶ τὸν Προυσίαν ἀναγκάσαι δίκας ὑποσχεῖν Ἀττάλῳ τῶν κατὰ πόλεμον ἀδικημάτων. —", "st": "33.9"}, {"sp": "N", "t": "ὅτι τῶν Μασσαλιητῶν διαπρεσβευσαμένων πρὸς Ῥωμαίους κακῶς πάσχειν αὑτοὺς ὑπὸ τῶν Λιγυστίνων, παραχρῆμα κατέστησαν Φλαμίνιον καὶ Ποπίλιον Λαινᾶτον καὶ Λεύκιον Πόπιον πρεσβευτάς. οἳ καὶ πλέοντες μετὰ τῶν Μασσαλιητῶν προσέσχον τῆς Ὀξυβίων χώρας κατὰ πόλιν Αἴγιτναν. οἱ δὲ Λιγυστῖνοι προακηκοότες ὅτι πάρεισιν ἐπιτάξοντες αὐτοῖς λύειν τὴν πολιορκίαν, τοὺς μὲν ἄλλους ἔτι καθορμιζομένους ἐπελθόντες ἐκώλυσαν τῆς ἀποβάσεως, τὸν δὲ Φλαμίνιον καταλαβόντες ἀποβεβηκότα καὶ τὰς ἀποσκευὰς ἀποτεθειμένον, τὰς μὲν ἀρχὰς ἐκέλευον αὐτὸν ἐκ τῆς χώρας ἀπολύεσθαι, τοῦ δὲ παρακούοντος ἤρξαντο τὰ σκεύη διαρπάζειν. τῶν δὲ παίδων καὶ τῶν ἀπελευθέρων ἀντιποιουμένων καὶ κωλυόντων, ἀπεβιάζοντο καὶ προσέφερον τούτοις τὰς χεῖρας. ἐν ᾧ καιρῷ καὶ τοῦ Φλαμινίου βοηθοῦντος τοῖς ἰδίοις, τοῦτον μὲν κατέτρωσαν, δύο δὲ τῶν οἰκετῶν κατέβαλον, τοὺς δὲ λοιποὺς κατεδίωξαν εἰς τὴν ναῦν, ὡς τὸν Φλαμίνιον μόγις ἀποκόψαντα τἀπίγυα καὶ τὰς ἀγκύρας διαφυγεῖν τὸν κίνδυνον. οὗτος μὲν ἀποκομισθεὶς εἰς Μασσαλίαν ἐθεραπεύετο μετὰ πάσης ἐπιμελείας· ἡ δὲ σύγκλητος πυθομένη τὰ γεγονότα παραχρῆμα τὸν ἕνα τῶν ὑπάτων Κόιντον Ὀπίμιον ἐξαπέστελλε μετὰ δυνάμεως πολεμήσοντα τοῖς Ὀξυβίοις καὶ Δεκιήταις.", "st": "33.10"}, {"sp": "N", "t": "ὁ δὲ Κόιντος συναθροίσας τὰς δυνάμεις εἰς τὴν τῶν Πλακεντίνων πόλιν καὶ ποιησάμενος τὴν πορείαν διὰ τῶν Ἀπεννίνων ὀρῶν ἧκεν εἰς τοὺς Ὀξυβίους. στρατοπεδεύσας δὲ παρὰ τὸν Ἄπρωνα ποταμὸν ἀνεδέχετο τοὺς πολεμίους, πυνθανόμενος αὐτοὺς ἁθροίζεσθαι καὶ προθύμους εἶναι πρὸς τὸ διακινδυνεύειν. καὶ προσαγαγὼν τὴν στρατιὰν ὁ Κόιντος πρὸς τὴν Αἴγιτναν, ἐν ᾗ συνέβη τοὺς πρεσβευτὰς παρασπονδηθῆναι, τὴν πόλιν κατὰ κράτος ἑλὼν ἐξηνδραποδίσατο καὶ τοὺς ἀρχηγοὺς τῆς ὕβρεως ἀπέστειλε δεσμίους εἰς τὴν Ῥώμην. καὶ ταῦτα διαπραξάμενος ἀπήντα τοῖς πολεμίοις. οἱ δ’ Ὀξύβιοι νομίζοντες ἀπαραίτητον αὑτοῖς εἶναι τὴν εἰς τοὺς πρεσβευτὰς ἁμαρτίαν, παραλόγῳ τινὶ χρησάμενοι θυμῷ καὶ λαβόντες ὁρμὴν παραστατικήν, πρὶν ἢ τοὺς Δεκιήτας αὐτοῖς συμμῖξαι, περὶ τετρακισχιλίους ἁθροισθέντες ὥρμησαν ἐπὶ τοὺς πολεμίους. ὁ δὲ Κόιντος ἰδὼν τὴν ἔφοδον καὶ τὸ θράσος τῶν βαρβάρων τὴν μὲν ἀπόνοιαν αὐτῶν κατεπλάγη, θεωρῶν δὲ μηδενὶ λόγῳ ταύτῃ χρωμένους τοὺς ἐχθροὺς εὐθαρσὴς ἦν, ἅτε τριβὴν ἐν πράγμασιν ἔχων καὶ τῇ φύσει διαφερόντως ἀγχίνους ὑπάρχων. διόπερ ἐξαγαγὼν τὴν αὑτοῦ στρατιὰν καὶ παρακαλέσας τὰ πρέποντα τοῖς καιροῖς ᾔει βάδην ἐπὶ τοὺς πολεμίους. χρησάμενος δὲ συντόνῳ προσβολῇ ταχέως ἐνίκησε τοὺς ἀντιταξαμένους καὶ πολλοὺς μὲν αὐτῶν ἀπέκτεινεν, τοὺς δὲ λοιποὺς ἠνάγκασε φυγεῖν προτροπάδην. οἱ δὲ Δεκιῆται συνηθροισμένοι παρῆσαν, ὡς μεθέξοντες τοῖς Ὀξυβίοις τῶν αὐτῶν κινδύνων· ὑστερήσαντες δὲ τῆς μάχης τούς τε φεύγοντας ἐξεδέξαντο καὶ μετ’ ὀλίγον συνέβαλον τοῖς Ῥωμαίοις μετὰ μεγάλης ὁρμῆς καὶ προθυμίας. ἡττηθέντες δὲ τῇ μάχῃ παραυτίκα πάντες παρέδωκαν σφᾶς αὐτοὺς καὶ τὴν πόλιν εἰς τὴν Ῥωμαίων πίστιν. ὁ δὲ Κόιντος κύριος γενόμενος τούτων τῶν ἐθνῶν παραυτίκα μὲν τῆς χώρας ὅσην ἐνεδέχετο προσέθηκε τοῖς Μασσαλιήταις, εἰς δὲ τὸ μέλλον ὅμηρα τοὺς Λιγυστίνους ἠνάγκασε διδόναι κατά τινας τακτοὺς χρόνους τοῖς Μασσαλιήταις· αὐτὸς δὲ παροπλίσας τοὺς ἀντιταξαμένους καὶ διελὼν τὴν δύναμιν ἐπὶ τὰς πόλεις αὐτοῦ τὴν παραχειμασίαν ἐποιήσατο. καὶ ταῦτα μὲν ὀξεῖαν ἔλαβε καὶ τὴν ἀρχὴν καὶ τὴν συντέλειαν. —", "st": "33.11"}, {"sp": "N", "t": "ὅτι κατὰ τὴν Ἀσίαν Ἄτταλος ἔτι κατὰ χειμῶνα συνήθροιζε μεγάλας δυνάμεις, ἅτε καὶ τῶν περὶ τὸν Ἀριαράθην καὶ τὸν Μιθριδάτην ἐξαπεσταλκότων αὐτῷ στρατιὰν ἱππέων καὶ πεζῶν κατὰ τὴν συμμαχίαν, ὧν ἡγεῖτο Δημήτριος Ἀριαράθου. ὄντος δὲ περὶ ταύτας αὐτοῦ τὰς κατασκευάς, ἧκον ἐκ τῆς Ῥώμης οἱ δέκα πρέσβεις, οἳ καὶ συμμίξαντες αὐτῷ περὶ Κάδους καὶ κοινολογηθέντες περὶ τῶν πραγμάτων ὥρμησαν πρὸς τὸν Προυσίαν. ἐπειδὴ δὲ συνέμιξαν, διεσάφουν αὐτῷ τὰ παρὰ τῆς συγκλήτου μετὰ πολλῆς ἀνατάσεως. ὁ δὲ Προυσίας ἔνια μὲν τῶν προσταττομένων προσεδέχετο, τοῖς δὲ πλείστοις ἀντέλεγε. διόπερ οἱ Ῥωμαῖοι προσκόψαντες αὐτῷ τήν τε φιλίαν ἀπείπαντο καὶ τὴν συμμαχίαν, καὶ πάντες ἐξ αὐτῆς ἀπηλλάττοντο πάλιν ὡς τὸν Ἄτταλον. ὁ δὲ Προυσίας μετανοήσας μέχρι μέν τινος ἐπηκολούθει λιπαρῶν, ἐπεὶ δ’ οὐδὲν ἤνυεν, ἀπαλλαγεὶς ἐν ἀμηχανίαις ἦν. οἱ δὲ Ῥωμαῖοι τὸν μὲν Ἄτταλον ἐκέλευον προκαθίσαντα τῆς αὑτοῦ χώρας μετὰ δυνάμεως αὐτὸν μὲν μὴ κατάρχειν τοῦ πολέμου, ταῖς δὲ πόλεσι ταῖς αὑτοῦ καὶ ταῖς κώμαις τὴν ἀσφάλειαν παρασκευάζειν· αὐτοὶ δὲ μερίσαντες σφᾶς αὐτούς, οἱ μὲν ἔπλεον κατὰ σπουδὴν ἀπαγγελοῦντες τῇ συγκλήτῳ τὴν ἀπείθειαν τοῦ Προυσίου, τινὲς δ’ ἐπὶ τῆς Ἰωνίας ἐχωρίσθησαν, ἕτεροι δ’ ἐφ’ Ἑλλησπόντου καὶ τῶν κατὰ τὸ Βυζάντιον τόπων, μίαν ἔχοντες καὶ τὴν αὐτὴν πρόθεσιν ἅπαντες, ἀπὸ μὲν τῆς Προυσίου φιλίας καὶ συμμαχίας ἀποκαλεῖν τοὺς ἀνθρώπους, Ἀττάλῳ δὲ προσνέμειν τὴν εὔνοιαν καὶ συμμαχεῖν κατὰ δύναμιν. —", "st": "33.12"}, {"sp": "N", "t": "κατὰ δὲ τοὺς αὐτοὺς καιροὺς Ἀθήναιος κατέπλευσε ναυσὶ καταφράκτοις ὀγδοήκοντα· ὧν αἱ πέντε μὲν τετρήρεις ἦσαν Ῥοδίων τῶν ἀποσταλεισῶν εἰς τὸν Κρητικὸν πόλεμον, εἴκοσι δὲ Κυζικηνῶν, ἑπτὰ δ’ ἐπὶ ταῖς εἴκοσι τῶν περὶ τὸν Ἄτταλον, αἱ δὲ λοιπαὶ τῶν ἄλλων συμμάχων. ποιησάμενος δὲ τὸν πλοῦν ἐφ’ Ἑλλησπόντου καὶ συνάψας ταῖς πόλεσι ταῖς ὑπὸ Προυσίαν ταττομέναις ἀποβάσεις τε συνεχεῖς ἐποιεῖτο καὶ κακῶς διετίθει τὴν χώραν. ἡ δὲ σύγκλητος διακούσασα τῶν παρὰ τοῦ Προυσίου πρεσβευτῶν ἀνακεχωρηκότων ἐξ αὐτῆς τρεῖς ἄλλους ἀπέστειλεν, Ἄππιόν τε τὸν Κλαύδιον καὶ Λεύκιον Ὄππιον καὶ Αὖλον Ποστόμιον. οἳ καὶ παραγενόμενοι πρὸς τὴν Ἀσίαν διέλυσαν τὸν πόλεμον, εἰς τὰς τοιαύτας συνθήκας ἐπαγαγόμενοι τοὺς βασιλέας ἀμφοτέρους, ὥστε παραχρῆμα μὲν εἴκοσι καταφράκτους νῆας ἀποδοῦναι Προυσίαν Ἀττάλῳ, πεντακόσια δὲ τάλαντα κατενεγκεῖν ἐν ἔτεσιν εἴκοσι· τὴν δὲ χώραν ἀμφοτέρους ἔχειν ἣν καὶ πρότερον εἶχον, ὅτ’ εἰς τὸν πόλεμον ἐνέβαινον. διορθώσασθαι δὲ Προυσίαν καὶ τὴν καταφθορὰν τῆς χώρας τῆς τε Μηθυμναίων καὶ τῶν Αἰγαιέων καὶ τῆς Κυμαίων καὶ Ἡρακλειωτῶν, ἑκατὸν τάλαντα δόντα τοῖς προειρημένοις. γραφεισῶν δ’ ἐπὶ τούτοις τῶν συνθηκῶν, ἀπῆγον τὰς δυνάμεις εἰς τὴν οἰκείαν οἱ περὶ τὸν Ἄτταλον, τὰς ναυτικὰς καὶ τὰς πεζικάς. καὶ τῆς μὲν Ἀττάλου καὶ Προυσίου διαφορᾶς τοιοῦτος ὅ τε κατὰ μέρος χειρισμὸς ἐγενήθη τῶν πράξεων", "st": "33.13"}, {"sp": "N", "t": "ὅτι κατὰ τὸν καιρὸν τοῦτον ἐν τῇ Ῥώμῃ τῶν ἐκ τῆς Ἀχαΐας πρεσβευτῶν εἰσελθόντων εἰς τὴν σύγκλητον περὶ τῶν ἀνακεκλημένων, ἔδοξε τῷ συνεδρίῳ μένειν ἐπὶ τῶν ὑποκειμένων. —", "st": "33.14"}, {"sp": "N", "t": "ὅτι ὁ Ἡρακλείδης ἔτι τῆς θερείας ἀκμαζούσης παρῆν εἰς τὴν Ῥώμην ἄγων τὴν Λαοδίκην καὶ τὸν Ἀλέξανδρον. ποιούμενος δὲ τὴν παρεπιδημίαν μετὰ τερατείας ἅμα καὶ κακουργίας ἐνεχρόνιζε, κατασκευαζόμενος τὰ περὶ τὴν σύγκλητον. — καὶ Ἀστυμήδης ὁ Ῥόδιος, πρεσβευτὴς ἅμα καὶ ναύαρχος καθεσταμένος, παρελθὼν ἐξ αὐτῆς εἰς τὴν σύγκλητον διελέγετο περὶ τοῦ πολέμου τοῦ πρὸς Κρηταιεῖς. ἡ δὲ σύγκλητος προσέχουσα τὸν νοῦν ἐπιμελῶς παραχρῆμα πρεσβευτὰς ἐξαπέστειλε τοὺς περὶ Κόιντον λύσοντας τὸν πόλεμον.", "st": "33.15"}, {"sp": "N", "t": "ὅτι κατὰ τὸν καιρὸν τοῦτον οἱ Κρηταιεῖς πρεσβευτὰς ἀπέστειλαν πρὸς Ἀχαιοὺς ὑπὲρ βοηθείας τοὺς περὶ Ἀντιφάταν Τηλεμνάστου Γορτύνιον, παραπλησίως δὲ καὶ Ῥόδιοι τοὺς περὶ Θευφάνην. οὔσης δὲ τῆς συνόδου τῶν Ἀχαιῶν ἐν Κορίνθῳ, καὶ διαλεγομένων τῶν πρεσβευτῶν ἑκατέρων ὑπὲρ τῆς βοηθείας, ἔρρεπον ταῖς γνώμαις οἱ πολλοὶ μᾶλλον ἐπὶ τοὺς Ῥοδίους, ἐντρεπόμενοι καὶ τὸ τῆς πόλεως ἀξίωμα καὶ τὴν ὅλην αἵρεσιν τῆς πολιτείας καὶ τῶν ἀνδρῶν. εἰς ἃ βλέπων Ἀντιφάτας ἐβουλήθη πάλιν ἐπεισελθεῖν, τοῦ δὲ στρατηγοῦ συγχωρήσαντος ἐχρήσατο λόγοις βαρυτέροις ἢ κατὰ Κρῆτα καὶ σπουδαιοτέροις· καὶ γὰρ ἦν ὁ νεανίσκος οὐδαμῶς Κρητικός, ἀλλὰ πεφευγὼς τὴν Κρητικὴν ἀναγωγίαν. διὸ καὶ συνέβαινε τοὺς Ἀχαιοὺς ἐπιδέχεσθαι τὴν παρρησίαν αὐτοῦ καὶ μᾶλλον ἔτι διὰ τὸ τὸν πατέρα τοῦ προειρημένου Τηλέμναστον μετὰ πεντακοσίων Κρητῶν ἐλθόντα συμπεπολεμηκέναι τὸν πρὸς Νάβιν πόλεμον εὐγενῶς αὐτοῖς. πλὴν διακούσαντες οὐδὲν ἧττον ὁρμὴν εἶχον οἱ πολλοὶ τοῖς Ῥοδίοις βοηθεῖν, ἕως Καλλικράτης ὁ Λεοντήσιος ἀναστὰς οὐκ ἔφη δεῖν οὔτε πολεμεῖν οὐδενὶ χωρὶς τῆς Ῥωμαίων γνώμης οὔτε βοήθειαν πέμπειν οὐδενὶ κατ’ οὐδενός. καὶ διὰ ταῦτα κατίσχυσε μένειν ἐπὶ τῶν ὑποκειμένων. —", "st": "33.16"}, {"sp": "N", "t": "ὅτι οἱ Ῥόδιοι δυσθετούμενοι τοῖς συμβαίνουσιν εἰς παραλόγους τινὰς ἐνέπεσαν ὁρμὰς καὶ παρασκευὰς καὶ πρὸς παραπλησίαν διάθεσιν ἦλθον τοῖς ἐν ταῖς πολυχρονίοις ἀρρωστίαις δυσποτμοῦσι. καὶ γὰρ ἐκεῖνοι πολλάκις, ἐπειδὰν πάντα ποιοῦντες κατὰ λόγον τῆς θεραπείας καὶ πειθαρχοῦντες τοῖς ἰατροῖς μὴ δύνωνται τῆς ἐπὶ τὸ βέλτιον προκοπῆς ἅψασθαι, δυσθετούμενοι τοῖς συμβαίνουσιν ἀποδυσπετεῖν ἀναγκάζονται, καὶ τινὲς μὲν θύταις καὶ μάντεσι προσέχειν, ἔνιοι δὲ πάσης ἐπῳδῆς καὶ παντὸς περιάμματος πεῖραν λαμβάνειν. ὃ καὶ περὶ τοὺς Ῥοδίους συνέβαινε· πάντων γὰρ αὐτοῖς παρὰ δόξαν ἀπαντωμένων, ἠναγκάζοντο παντὶ τῷ λεγομένῳ προσέχειν καὶ πᾶσαν ἐλπίδα σωματοποιεῖν καὶ προσδέχεσθαι. καὶ τοῦτ’ ἐδόκουν πάσχειν εἰκότως· ὅταν γὰρ μηδὲν ἀνύηται τῶν κατὰ λόγον, δέῃ δὲ κατ’ ἀνάγκην ἐνεργεῖσθαι τὸ συνεχές, ἀπάγκη πεῖραν λαμβάνειν καὶ τῶν παρὰ λόγον. διὸ καὶ Ῥόδιοι ἐμπεσόντες εἰς τοιαύτην διάθεσιν ἐποίησάν τι τῶν γινομένων καὶ ὃν ἀπεδοκίμασαν ἄρχοντα, τοῦτον πάλιν εἵλοντο ἄρχοντα, καὶ ἄλλα τινὰ παράλογα.", "st": "33.17"}, {"sp": "N", "t": "ὅτι πρέσβεων διαφόρων παραγενομένων εἰς τὴν Ῥώμην ἡ σύγκλητος πρῶτον μὲν εἰσεκαλέσατο τὸν Εὐμένους τοῦ βασιλέως υἱὸν Ἄτταλον· παραγεγόνει γὰρ ἔτι παῖς ὢν κατὰ τὸν καιρὸν τοῦτον εἰς Ῥώμην χάριν τοῦ τῇ τε συγκλήτῳ συσταθῆναι καὶ τὰς πατρικὰς ἀνανεώσασθαι φιλίας καὶ ξενίας. οὗτος μὲν οὖν φιλανθρώπως ὑπό τε τῆς συγκλήτου καὶ τῶν πατρικῶν φίλων ἀποδεχθεὶς καὶ λαβὼν ἀποκρίσεις ἃς ἐβούλετο καὶ τιμὰς ἁρμοζούσας τῇ καθ’ αὑτὸν ἡλικίᾳ, μετά τινας ἡμέρας ἐπανῆλθεν εἰς τὴν οἰκείαν, πασῶν αὐτὸν τῶν κατὰ τὴν Ἑλλάδα πόλεων ἐκτενῶς καὶ μεγαλοψύχως ἀποδεξαμένων κατὰ τὴν δίοδον. ἧκε δὲ καὶ Δημήτριος κατὰ τὸν αὐτὸν καιρόν, τυχὼν δὲ μετρίας ἀποδοχῆς ὡς παῖς αὖθις ἀνεχώρησεν εἰς τὴν οἰκείαν. ὁ δ’ Ἡρακλείδης κεχρονικὼς ἐν τῇ Ῥώμῃ παρῆλθεν εἰς τὴν σύγκλητον, ἔχων μεθ’ ἑαυτοῦ τὴν Λαοδίκην καὶ τὸν Ἀλέξανδρον. πρῶτον μὲν οὖν ὁ νεανίσκος ἐποιήσατό τινας μετρίους λόγους, ἠξίου δὲ Ῥωμαίους μνησθῆναι τῆς πρὸς τὸν Ἀντίοχον τὸν αὑτοῦ πατέρα φιλίας καὶ συμμαχίας, μάλιστα δὲ συγκατασκευάζειν αὑτῷ τὴν βασιλείαν· εἰ δὲ μή, συγχωρῆσαι τὴν κάθοδον καὶ μὴ κωλῦσαι τοὺς βουλομένους συμπράττειν αὐτῷ πρὸς τὸ καθικέσθαι τῆς πατρῴας ἀρχῆς. ὁ δ’ Ἡρακλείδης παραλαβὼν τὸν λόγον καὶ πολλήν τινα ποιησάμενος Ἀντιόχου μὲν μνείαν ἐπ’ ἀγαθῷ, Δημητρίου δὲ κατηγορίαν, εἰς τοῦτο κατήντησεν ὅτι δεῖ συγχωρεῖν τὴν κάθοδον τῷ τε νεανίσκῳ καὶ τῇ Λαοδίκῃ κατὰ τὸ δίκαιον, οὖσιν Ἀντιόχου τοῦ βασιλέως ἐκγόνοις κατὰ φύσιν. τοῖς μὲν οὖν μετρίοις τῶν ἀνθρώπων οὐδὲν ἤρεσκε τούτων, ἀλλὰ καὶ τὴν κατασκευὴν τοῦ δράματος ἐνενόουν καὶ τὸν Ἡρακλείδην ἐβδελύττοντο προφανῶς. οἱ δὲ πολλοὶ τεθεραπευμένοι ταῖς Ἡρακλείδου γοητείαις συγκατηνέχθησαν ἐπὶ τὸ γράφειν δόγμα τοιοῦτον· \" Ἀλέξανδρος καὶ Λαοδίκη, βασιλέως υἱοί, φίλου καὶ συμμάχου ἡμετέρου γεγενημένου, ἐπελθόντες ἐπὶ τὴν σύγκλητον λόγους ἐποιήσαντο· ἡ δὲ σύγκλητος αὐτοῖς ἐξουσίαν ἔδωκεν ἐπὶ τὴν πατρῴαν ἀρχὴν καταπορεύεσθαι, καὶ βοηθεῖν αὐτοῖς, ὡς ἠξίουν, ἔδοξεν. \" ὁ δ’ Ἡρακλείδης ἐπιλαβόμενος τῆς ἀφορμῆς ταύτης εὐθέως ἐξενολόγει καὶ προσεκαλεῖτο τῶν ἐπιφανῶν ἀνδρῶν ἀφικόμενος δ’ εἰς τὴν Ἔφεσον ἐγίνετο περὶ τὴν παρασκευὴν τῆς προκειμένης ἐπιβολῆς.", "st": "33.18"}, {"sp": "N", "t": "καὶ Δημήτριον δέ φησι, τὸν ἐκ τῆς Ῥώμη ὁμηρείαν διαφυγόντα, ἐν τῇ τρίτῃ καὶ τριακοστῇ βασιλεύσαντα Σύρων πολυπότην ὄντα τὸ πλεῖστον τῆς ἡμέρας μεθύσκεσθαι.", "st": "33.19"}, {"sp": "N", "t": "ὅτι ὅταν ἅπαξ οἱ πολλοὶ σχῶσιν ὁρμὴν πρὸς τὸ φιλεῖν ἢ μισεῖν τινας ὑπερβαλλόντως, πᾶσα πρόφασις ἱκανὴ γίνεται πρὸς τὸ συντελεῖν τὰς αὑτῶν προθέσεις. —", "st": "33.20"}, {"sp": "N", "t": "ἀλλὰ γὰρ ὀκνῶ μή ποτ’ εἰς τὸ περιφερόμενον ἐμπεσὼν λάθω, πότερον ὁ τὸν τράγον ἀμέλγων ἀφρονέστερος ἢ ὁ τὸ κόσκινον ὑπέχων· δοκῶ γὰρ δὴ κἀγὼ πρὸς ὁμολογουμένην ψευδολογίαν ἀκριβολογούμενος καὶ τὸν ἐπιμετροῦντα λόγον εἰσφέρων παραπλήσιόν τι ποιεῖν. διὸ καὶ μάτην τελέως περὶ τούτων λέγειν, εἰ μή τις καὶ γράφειν ἐνύπνια βούλεται καὶ θεωρεῖν ἐγρηγορότος ἐνύπνια.", "st": "33.20"}, {"sp": "HDR", "t": "Βιβλίον ΛΔʹ", "st": "34"}, {"sp": "N", "t": "οἱ δ’ ἐν τῇ κοινῇ τῆς ἱστορίας γραφῇ χωρὶς ἀποδείξαντες τὴν τῶν ἠπείρων τοπογραφίαν, καθάπερ Ἔφορός τε ἐποίησε καὶ Πολύβιος. — Πολύβιος … φήσας περὶ τῶν Ἑλληνικῶν καλῶς μὲν Εὔδοξον, κάλλιστα δ’ Ἔφορον ἐξηγεῖσθαι περὶ κτίσεων, συγγενειῶν, μεταναστάσεων, ἀρχηγετῶν, ἡμεῖς δέ, φησί, τὰ νῦν ὄντα δηλώσομεν καὶ περὶ θέσεως τόπων καὶ διαστημάτων· τοῦτο γάρ ἐστιν οἰκειότατον χωρογραφίᾳ. ἀλλὰ μὴν σύγε, ὦ Πολύβιε, ὁ τὰς λαοδογματικὰς ἀποφάσεις περὶ τῶν διαστημάτων εἰσάγων οὐκ ἐν τοῖς ἔξω τῆς Ἑλλάδος μόνον, ἀλλὰ καὶ ἐν τοῖς Ἑλληνικοῖς καὶ διδοῖς εὐθύνας τὰς μὲν Ποσειδωνίῳ, τὰς δ’ Ἀρτεμιδώρῳ, τὰς δ’ ἄλλοις πλείοσι. — Πολύβιος οὖν ὁ ἱστοριογράφος πεπραγμάτευται βιβλίον, ὃ ἐπιγραφὴν ἔχει \"περὶ τῆς ὑπὸ τὸν ἰσημερινὸν οἰκήσεως\". αὕτη δέ ἐστιν ἐν μέσῃ τῇ διακεκαυμένῃ ζώνῃ. καί φησιν οἰκεῖσθαι τοὺς τόπους καὶ εὐκρατοτέραν ἔχειν τὴν οἴκησιν τῶν περὶ τὰ πέρατα τῆς διακεκαυμένης ζώνης κατοικούντων. καὶ ἃ μὲν ἱστορίας φέρει τῶν κατωπτευκότων τὰς οἰκήσεις καὶ ἐπιμαρτυρούντων τοῖς φαινομένοις, ἃ δὲ ἐπιλογίζεται ἐπὶ τῆς φυσικῆς περὶ τὸν ἥλιον ὑπαρχούσης κινήσεως. ὁ γὰρ ἥλιος περὶ μὲν τοὺς τροπικοὺς κύκλους πολὺν ἐπιμένει χρόνον κατά τε τὴν πρόσοδον τὴν πρὸς αὐτοὺς καὶ τὴν ἀποχώρησιν, ὥστε σχεδὸν ἐφ’ ἡμέρας τετταράκοντα μένει πρὸς αἴσθησιν ἐπὶ τῶν τροπικῶν κύκλων. [δι’ ἣν αἰτίαν καὶ τὰ μεγέθη τῶν ἡμερῶν σχεδὸν ἐφ’ ἡμέρας μʹ τὰ αὐτὰ διαμένει.] ὅθεν ἐπιμονῆς γινομένης πρὸς τὰς οἰκήσεις τὰς κειμένας ὑπὸ τοὺς τροπικοὺς ἀνάγκη ἐκπυροῦσθαι τὴν οἴκησιν καὶ ἀοίκητον γίνεσθαι διὰ τὴν τοῦ καύματος ὑπερβολήν. ἀπὸ δὲ τοῦ ἰσημερινοῦ κύκλου ταχείας συμβαίνει τὰς ἀποχωρήσεις γίνεσθαι. [ὅθεν καὶ τὰ μεγέθη τῶν ἡμερῶν περὶ τὰς ἰσημερίας μεγάλας λαμβάνει τὰς παραυξήσεις.] εὔλογον οὖν καὶ τὰς ὑπὸ τὸν ἰσημερινὸν κειμένας οἰκήσεις εὐκρατοτέρας ὑπάρχειν, ἐπιμονῆς μὲν οὐ γινομένης ἐπὶ τοῦ κατὰ κορυφὴν σημείου, ταχέως δὲ ἀποχωροῦντος τοῦ ἡλίου. πάντες γὰρ οἱ μεταξὺ τῶν τροπικῶν κύκλων οἰκοῦντες παρὰ τὴν πάροδον ὁμοίως κεῖνται τοῦ ἡλίου· πλείονας δὲ χρόνους ἐπιμένει τοῖς περὶ τοὺς τροπικοὺς οἰκοῦσι. δι’ ἣν αἰτίαν εὐκρατοτέρας εἶναι συμβέβηκε τὰς ὑπὸ τὸν ἰσημερινὸν οἰκήσεις, αἵτινες κεῖνται ἐν μέσῃ τῇ διακεκαυμένῃ ζώνῃ, τῶν περὶ τὰ πέρατα τῆς διακεκαυμένης οἰκήσεων, αἵτινες ὑπὸ τοὺς τροπικοὺς κύκλους κεῖνται. — Πολύβιος δὲ ποιεῖ ζώνας ἕξ, δύο μὲν τὰς τοῖς ἀρκτικοῖς ὑποπιπτούσας, δύο δὲ τὰς μεταξὺ τούτων τε καὶ τῶν τροπικῶν καὶ δύο τὰς μεταξὺ τούτων καὶ τοῦ ἰσημερινοῦ. — ὁ δὲ Πολύβιος τοῦτο μὲν οὐκ εὖ, τὸ ποιεῖν τινας ζώνας τοῖς ἀρκτικοῖς διοριζομένας, δύο μὲν τὰς ὑποπιπτούσας αὐτοῖς, δύο δὲ τὰς μεταξὺ τούτων καὶ τῶν τροπικῶν. — εἰ δ’, ὥσπερ Ἐρατοσθένης φησίν, ἡ ὑποπίπτουσα τῷ ἰσημερινῷ ἐστιν εὔκρατος, καθάπερ καὶ Πολύβιος ὁμοδοξεῖ — προστίθησι δ’ οὗτος καὶ διότι ὑψηλοτάτη ἐστί· διόπερ καὶ κατομβρεῖται, τῶν βορείων νεφῶν κατὰ τοὺς ἐτησίας ἐκεῖ τοῖς ἀναστήμασι προσπιπτόντων πλείστων — πολὺ κρεῖττον τρίτην εὔκρατον ταύτην ποιεῖν στενήν τινα, ἢ τὰς ὑπὸ τοῖς τροπικοῖς εἰσάγειν. — ἐνίσταται δ’ ὁ Ποσειδώνιος τῷ Πολυβίῳ, διότι φησὶ τὴν ὑπὸ τῷ ἰσημερινῷ οἴκησιν ὑψηλοτάτην. — περὶ δὲ τοῦ ἀριθμοῦ αὐτῶν πολλὴ διαφωνία τοῖς μετ’ αὐτὸν γέγονεν· οἱ μὲν γὰρ ἓξ αὐτὰς εἶπον, ὡς Πολύβιος καὶ Ποσειδώνιος, τὴν διακεκαυμένην εἰς δύο διαιροῦντες.", "st": "34.1"}, {"sp": "N", "t": "ἐκ μηδενὸς δὲ ἀληθοῦς ἀνάπτειν κενὴν τερατολογίαν οὐχ Ὁμηρικόν. προσπίπτει γάρ, ὡς εἰκός, ὡς πιθανώτερον ἂν οὕτω τις ψεύδοιτο, εἰ καταμίσγοι τι καὶ αὐτῶν τῶν ἀληθινῶν· ὅπερ καὶ Πολύβιός φησι περὶ τῆς Ὀδυσσέως πλάνης ἐπιχειρῶν. — καὶ Πολύβιος δ’ ὀρθῶς ὑπονοεῖ τὰ περὶ τῆς πλάνης. τὸν γὰρ Αἴολον τὸν προσημαίνοντα τοὺς ἔκπλους ἐν τοῖς κατὰ τὸν πορθμὸν τόποις ἀμφιδρόμοις οὖσι καὶ δυσέκπλοις διὰ τὰς παλιρροίας ταμίαν τε εἰρῆσθαι τῶν ἀνέμων καὶ βασιλέα νενομίσθαι φησί, καθάπερ Δαναὸν μὲν τὰ ὑδρεῖα τὰ ἐν Ἄργει παραδείξαντα, Ἀτρέα δὲ τοῦ ἡλίου τὸν ὑπεναντίον τῷ οὐρανῷ δρόμον, μάντεις τε καὶ ἱεροσκοπουμένους ἀποδείκνυσθαι βασιλέας· τούς θ’ ἱερέας τῶν Αἰγυπτίων καὶ Χαλδαίους καὶ Μάγους σοφίᾳ τινὶ διαφέροντας τῶν ἄλλων ἡγεμονίας καὶ τιμῆς τυγχάνειν παρὰ τοῖς πρὸ ἡμῶν. οὕτω δὲ καὶ τῶν θεῶν ἕνα ἕκαστον τῶν χρησίμων τινὸς εὑρετὴν γενόμενον τιμᾶσθαι. ταῦτα δὲ προοικονομησάμενος οὐκ ἐᾷ τὸν Αἴολον ἐν μύθου σχήματι ἀκούεσθαι, οὐδ’ ὅλην τὴν Ὀδυσσέως πλάνην, ἀλλὰ μικρὰ μὲν προσμεμυθεῦσθαι, καθάπερ καὶ τῷ Ἰλιακῷ πολέμῳ, τὸ δ’ ὅλον περὶ Σικελίαν καὶ τῷ ποιητῇ πεποιῆσθαι καὶ τοῖς ἄλλοις συγγραφεῦσιν, ὅσοι τἀπιχώρια λέγουσι τὰ περὶ τὴν Ἰταλίαν καὶ Σικελίαν. οὐκ ἐπαινεῖ δὲ οὐδὲ τὴν τοιαύτην τοῦ Ἐρατοσθένους ἀπόφασιν, διότι φησὶ τότ’ ἂν εὑρεῖν τινα ποῦ Ὀδυσσεὺς πεπλάνηται, ὅταν εὕρῃ τὸν σκυτέα τὸν συρράψαντα τὸν τῶν ἀνέμων ἀσκόν. καὶ τοῦτο δ’ οἰκείως εἰρῆσθαι τοῖς συμβαίνουσι περὶ τὸ Σκύλλαιον καὶ τὴν θήραν τῶν γαλεωτῶν, τὸ ἐπὶ τῆς Σκύλλης, αὐτοῦ δ’ ἰχθυάᾳ, σκόπελον περιμαιμώωσα, δελφῖνάς τε κύνας τε καὶ εἴ ποθι μεῖζον ἕλῃσι κῆτος. τοὺς γὰρ θύννους ἀγεληδὸν φερομένους παρὰ τὴν Ἰταλίαν, ἐπειδὰν ἐκπέσωσι καὶ κωλυθῶσι τῆς Σικελίας ἅψασθαι, περιπίπτειν τοῖς μείζοσι τῶν ζῴων, οἷον δελφίνων καὶ κυνῶν καὶ ἄλλων κητωδῶν, ἐκ δὲ τῆς θήρας αὐτῶν πιαίνεσθαι τοὺς γαλεώτας, οὓς καὶ ξιφίας λέγεσθαι καὶ κύνας φησί. συμβαίνειν γὰρ ταὐτὸν ἐνθάδε καὶ κατὰ τὰς ἀναβάσεις τοῦ Νείλου καὶ τῶν ἄλλων ὑδάτων, ὅπερ ἐπὶ πυρὸς καὶ ὕλης ἐμπιπραμένης· ἁθροιζόμενα γὰρ τὰ θηρία φεύγειν τὸ πῦρ ἢ τὸ ὕδωρ καὶ βορὰν γίνεσθαι τοῖς κρείττοσι.", "st": "34.2"}, {"sp": "N", "t": "ταῦτα δ’ εἰπὼν διηγεῖται τῶν γαλεωτῶν θήραν, ἣ συνίσταται περὶ τὸ Σκύλλαιον. σκοπὸς γὰρ ἐφέστηκε κοινὸς ὑφορμοῦσιν ἐν δικώποις σκαφιδίοις πολλοῖς, δύο καθ’ ἕκαστον σκαφίδιον. καὶ ὁ μὲν ἐλαύνει, ὁ δ’ ἐπὶ τῆς πρῴρας ἕστηκε δόρυ ἔχων, σημήναντος τοῦ σκοποῦ τὴν ἐπιφάνειαν τοῦ γαλεώτου· φέρεται δὲ τὸ τρίτον μέρος ἔξαλον τὸ ζῷον. συνάψαντος δὲ τοῦ σκάφους ὁ μὲν ἔπληξεν ἐκ χειρός, εἶτ’ ἐξέσπασεν ἐκ τοῦ σώματος τὸ δόρυ χωρὶς τῆς ἐπιδορατίδος· ἀγκιστρώδης τε γάρ ἐστι καὶ χαλαρῶς ἐνήρμοσται τῷ δόρατι ἐπίτηδες, καλῴδιον δ’ ἔχει μακρὸν ἐξημμένον. τοῦτ’ ἐπιχαλῶσι τῷ τρωθέντι, τέως ἂν κάμῃ σφαδᾷζον καὶ ὑποφεῦγον· τότε δ’ ἕλκουσιν ἐπὶ τὴν γῆν ἢ εἰς τὸ σκάφος ἀναλαμβάνουσιν, ἐὰν μὴ μέγα ᾖ τελέως τὸ σῶμα. κἂν ἐκπέσῃ δὲ εἰς τὴν θάλατταν τὸ δόρυ, οὐκ ἀπόλωλεν· ἔστι γὰρ πηκτὸν ἔκ τε δρυὸς καὶ ἐλάτης, ὥστε βαπτιζομένου τοῦ δρυΐνου βάρει μετέωρον εἶναι τὸ λοιπὸν καὶ εὐανάληπτον. συμβαίνειν δέ ποτε καὶ τιτρώσκεσθαι διὰ τοῦ σκαφιδίου τὸν κωπηλάτην διὰ τὸ μέγεθος τοῦ ξίφους τῶν γαλεωτῶν καὶ τὸ τὴν ἀκμὴν τοῦ ζῴου συαγρώδη εἶναι καὶ τὴν θήραν. ἔκ τε δὴ τῶν τοιούτων εἰκάζοι τις ἄν, φησί, περὶ Σικελίαν γενέσθαι τὴν πλάνην κατὰ τὸν Ὅμηρον, ὅτι τῇ Σκύλλῃ προσῆψε τὴν τοιαύτην θήραν, ἣ μάλιστ’ ἐπιχώριός ἐστι τῷ Σκυλλαίῳ, καὶ ἐκ τῶν περὶ τῆς Χαρύβδεως λεγομένων ὁμοίων τοῖς τοῦ πορθμοῦ πάθεσι. τὸ δὲ τρὶς μὲν γάρ τ’ ἀνίησιν ἀντὶ τοῦ δὶς γραφικὸν εἶναι ἁμάρτημα ἢ ἱστορικόν. καὶ τὰ ἐν τῇ Μήνιγγι δὲ τοῖς περὶ τῶν Λωτοφάγων εἰρημένοις συμφωνεῖν.", "st": "34.3"}, {"sp": "N", "t": "εἰ δέ τινα μὴ συμφωνεῖ, μεταβολὰς αἰτιᾶσθαι δεῖν ἢ ἄγνοιαν ἢ καὶ ποιητικὴν ἐξουσίαν, ἣ συνέστηκεν ἐξ ἱστορίας καὶ διαθέσεως καὶ μύθου. τῆς μὲν οὖν ἱστορίας ἀλήθειαν εἶναι τέλος, ὡς ἐν Νεῶν καταλόγῳ τὰ ἑκάστοις τόποις συμβεβηκότα λέγοντος τοῦ ποιητοῦ, τὴν μὲν πετρήεσσαν, τὴν δὲ ἐσχατόωσαν πόλιν, ἄλλην δὲ πολυτρήρωνα, τὴν δ’ ἀγχίαλον· τῆς δὲ διαθέσεως ἐνέργειαν εἶναι τὸ τέλος, ὡς ὅταν μαχομένους εἰσάγῃ, μύθου δὲ ἡδονὴν καὶ ἔκπληξιν. τὸ δὲ πάντα πλάττειν οὐ πιθανὸν οὐδ’ Ὁμηρικόν· τὴν γὰρ ἐκείνου ποίησιν φιλοσόφημα πάντας νομίζειν, οὐχ ὡς Ἐρατοσθένης φησί, κελεύων μὴ κρίνειν πρὸς τὴν διάνοιαν τὰ ποιήματα μηδ’ ἱστορίαν ἀπ’ αὐτῶν ζητεῖν. πιθανώτερόν τε τὸ ἔνθεν δ’ ἐννῆμαρ φερόμην ὀλοοῖς ἀνέμοισιν ἐν βραχεῖ διαστήματι δέχεσθαι — οἱ γὰρ ὀλοοὶ οὐκ εὐθύδρομοι — ἢ ἐξωκεανίζειν, ὡς ἂν οὐρίων πνεόντων συνεχῶς. συνθεὶς δὲ τὸ διάστημα τὸ ἐκ Μαλεῶν ἐπὶ στήλας σταδίων δισμυρίων καὶ δισχιλίων πεντακοσίων, εἰ, φησί, τοῦτο θείημεν ἐν ταῖς ἐννέα ἡμέραις διηνύσθαι ἰσοταχῶς, ἑκάστης ἂν ἡμέρας ὁ πλοῦς συμβαίνοι σταδίων δισχιλίων πεντακοσίων. τίς οὖν ἱστόρηκεν ἐκ Λυκίας ἢ Ῥόδου δευτεραῖόν τινα ἀφιγμένον εἰς Ἀλεξάνδρειαν, ὄντος τοῦ διαστήματος σταδίων τετρακισχιλίων; πρὸς δὲ τοὺς ἐπιζητοῦντας πῶς τρὶς εἰς Σικελίαν ἐλθὼν οὐδ’ ἅπαξ διὰ τοῦ πορθμοῦ πέπλευκεν Ὀδυσσεύς, ἀπολογεῖται διότι καὶ οἱ ὕστερον ἔφευγον ἅπαντες τὸν πλοῦν τοῦτον. τοιαῦτα μὲν εἴρηκεν.", "st": "34.4"}, {"sp": "N", "t": "Πολύβιος δὲ τὴν Εὐρώπην χωρογραφῶν τοὺς μὲν ἀρχαίους ἐᾶν φησι, τοὺς δ’ ἐκείνους ἐλέγχοντας ἐξετάζειν Δικαίαρχόν τε καὶ Ἐρατοσθένη τὸν τελευταῖον πραγματευσάμενον περὶ γεωγραφίας καὶ Πυθέαν, ὑφ’ οὗ παρακρουσθῆναι πολλούς, ὅλην μὲν τὴν Βρεττανικὴν ἐμβαδὸν ἐπελθεῖν φάσκοντος, τὴν δὲ περίμετρον πλειόνων ἢ τεττάρων μυριάδων ἀποδόντος τῆς νήσου, προσιστορήσαντος δὲ καὶ τὰ περὶ τῆς Θούλης καὶ τῶν τόπων ἐκείνων, ἐν οἷς οὔτε γῆ καθ’ αὑτὴν ὑπῆρχεν ἔτι οὔτε θάλαττα οὔτ’ ἀήρ, ἀλλὰ σύγκριμά τι ἐκ τούτων πλεύμονι θαλαττίῳ ἐοικός, ἐν ᾧ φησι τὴν γῆν καὶ τὴν θάλατταν αἰωρεῖσθαι καὶ τὰ σύμπαντα, καὶ τοῦτον ὡς ἂν δεσμὸν εἶναι τῶν ὅλων, μήτε πορευτὸν μήτε πλωτὸν ὑπάρχοντα. τὸ μὲν οὖν τῷ πλεύμονι ἐοικὸς αὐτὸς ἑωρακέναι, τἄλλα δὲ λέγειν ἐξ ἀκοῆς. ταῦτα μὲν τὰ τοῦ Πυθέου, καὶ διότι ἐπανελθὼν ἐνθένδε πᾶσαν ἐπέλθοι τὴν παρωκεανῖτιν τῆς Εὐρώπης ἀπὸ Γαδείρων ἕως Τανάιδος· φησὶ δ’ οὖν ὁ Πολύβιος ἄπιστον καὶ αὐτὸ τοῦτο πῶς ἰδιώτῃ ἀνθρώπῳ καὶ πένητι τὰ τοσαῦτα διαστήματα πλωτὰ καὶ πορευτὰ γένοιτο. τὸν δ’ Ἐρατοσθένη διαπορήσαντα εἰ χρὴ πιστεύειν τούτοις, ὅμως περί τε τῆς Βρεττανικῆς πεπιστευκέναι καὶ τῶν κατὰ Γάδειρα καὶ τὴν Ἰβηρίαν. πολὺ δέ φησι βέλτιον τῷ Μεσσηνίῳ πιστεύειν ἢ τούτῳ· ὁ μέντοι γε εἰς μίαν χώραν τὴν Παγχαίαν λέγει πλεῦσαι· ὁ δὲ καὶ μέχρι τῶν τοῦ κόσμου περάτων κατωπτευκέναι τὴν προσάρκτιον τῆς Εὐρώπης πᾶσαν, ἣν οὐδ’ ἂν τῷ Ἑρμῇ πιστεύσαι τις λέγοντι. Ἐρατοσθένη δὲ τὸν μὲν Εὐήμερον Βεργαῖον καλεῖν, Πυθέᾳ δὲ πιστεύειν, καὶ ταῦτα μηδὲ Δικαιάρχου πιστεύσαντος. τὸ μὲν οὖν \"μηδὲ Δικαιάρχου πιστεύσαντος\" γελοῖον, ὥσπερ ἐκείνῳ κανόνι χρήσασθαι προσῆκον, καθ’ οὗ τοσούτους ἐλέγχους αὐτὸς προφέρεται· Ἐρατοσθένους δὲ εἴρηται ἡ περὶ τὰ ἑσπέρια καὶ τὰ ἀρκτικὰ τῆς Εὐρώπης ἄγνοια. ἀλλ’ ἐκείνῳ μὲν καὶ Δικαιάρχῳ συγγνώμη τοῖς μὴ κατιδοῦσι τοὺς τόπους ἐκείνους· Πολυβίῳ δὲ καὶ Ποσειδωνίῳ τίς ἂν συγγνοίη; ἀλλὰ μὴν Πολύβιός γέ ἐστιν ὁ λαοδογματικὰς καλῶν ἀποφάσεις, ἃς ποιοῦνται περὶ τῶν ἐν τούτοις τοῖς τόποις διαστημάτων καὶ ἐν ἄλλοις πολλοῖς, ἀλλ’ οὐδ’ ἐν οἷς ἐκείνους ἐλέγχει καθαρεύων.", "st": "34.5"}, {"sp": "N", "t": "τοῦ γοῦν Δικαιάρχου μυρίους μὲν εἰπόντος τοὺς ἐπὶ στήλας ἀπὸ τῆς Πελοποννήσου σταδίους, πλείους δὲ τούτων τοὺς ἐπὶ τὸν Ἀδρίαν μέχρι τοῦ μυχοῦ, τοῦ δ’ ἐπὶ στήλας τὸ μέχρι τοῦ πορθμοῦ τρισχιλίους ἀποδόντος, ὡς γίνεσθαι τὸ λοιπὸν ἑπτακισχιλίους τὸ ἀπὸ πορθμοῦ μέχρι στηλῶν, τοὺς μὲν τρισχιλίους ἐᾶν φησιν εἴτ’ εὖ λαμβάνονται εἴτε μή, τοὺς δ’ ἑπτακισχιλίους οὐδετέρως, οὔτε τὴν παραλίαν ἐκμετροῦντι οὔτε τὴν διὰ μέσου τοῦ πελάγους. τὴν μὲν γὰρ παραλίαν ἐοικέναι μάλιστ’ ἀμβλείᾳ γωνίᾳ, βεβηκυίᾳ ἐπί τε τοῦ πορθμοῦ καὶ τῶν στηλῶν, κορυφὴν δ’ ἐχούσῃ Νάρβωνα, ὥστε συνίστασθαι τρίγωνον, βάσιν ἔχον τὴν διὰ τοῦ πελάγους εὐθεῖαν, πλευρὰς δὲ τὰς τὴν γωνίαν ποιούσας τὴν λεχθεῖσαν· ὧν ἡ μὲν ἀπὸ τοῦ πορθμοῦ μέχρι Νάρβωνος μυρίων ἐστὶ καὶ πλειόνων ἢ διακοσίων ἐπὶ τοῖς χιλίοις, ἡ δὲ λοιπὴ μικρῷ λεῖπον [ἐλαττόνων ἢ] ὀκτακισχιλίων. καὶ μὴν πλεῖστον μὲν διάστημα ἀπὸ τῆς Εὐρώπης ἐπὶ τὴν Λιβύην ὁμολογεῖσθαι κατὰ τὸ Τυρρηνικὸν πέλαγος σταδίων οὐ πλειόνων ἢ τρισχιλίων, κατὰ τὸ Σαρδόνιον δὲ λαμβάνειν συναγωγήν. ἀλλ’ ἔστω, φησί, καὶ ἐκεῖνο τρισχιλίων, προειλήφθω δ’ ἐπὶ τούτοις δισχιλίων σταδίων τὸ τοῦ κόλπου βάθος τοῦ κατὰ Νάρβωνα, ὡς ἂν κάθετος ἀπὸ τῆς κορυφῆς ἐπὶ τὴν βάσιν τοῦ ἀμβλυγωνίου. δῆλον οὖν, φησίν, ἐκ τῆς παιδικῆς μετρήσεως ὅτι ἡ σύμπασα παραλία ἡ ἀπὸ τοῦ πορθμοῦ ἐπὶ στήλας ἔγγιστα ὑπερέχει τῆς διὰ τοῦ πελάγους εὐθείας πεντακοσίοις σταδίοις. προστεθέντων δὲ τῶν ἀπὸ τῆς Πελοποννήσου ἐπὶ τὸν πορθμὸν τρισχιλίων, οἱ σύμπαντες ἔσονται στάδιοι, αὐτοὶ οἱ ἐπ’ εὐθείας, πλείους ἢ διπλάσιοι ὧν Δικαίαρχος εἶπε. πλείους δὲ τούτων τοὺς ἐπὶ τὸν μυχὸν τὸν Ἀδριατικὸν δεήσει, φησί, τιθέναι κατ’ ἐκεῖνον. ἀλλ’, ὦ φίλε Πολύβιε, φαίη τις ἄν, ὥσπερ τούτου τοῦ ψεύσματος ἐναργῆ παρίστησι τὸν ἔλεγχον ἡ πεῖρα ἐξ αὐτῶν ὧν εἴρηκας αὐτός, εἰς μὲν Λευκάδα ἐκ Πελοποννήσου ἑπτακοσίους, ἐντεῦθεν δὲ τοὺς ἴσους εἰς Κόρκυραν, καὶ πάλιν ἐντεῦθεν εἰς τὰ Κεραύνια τοὺς ἴσους καὶ ἐν δεξιᾷ εἰς τὴν Ἰαπυδίαν ἀπὸ τῶν Κεραυνίων τὴν Ἰλλυρικὴν παραλίαν σταδίων ἑξακισχιλίων ἑκατὸν πεντήκοντα, οὕτως κἀκεῖνα ψεύσματά ἐστιν ἀμφότερα, καὶ ὃ Δικαίαρχος εἶπε, τὸ ἀπὸ πορθμοῦ ἐπὶ στήλας εἶναι σταδίων ἑπτακισχιλίων, καὶ ὃ σὺ δοκεῖς ἀποδεῖξαι· ὁμολογοῦσι γὰρ οἱ πλεῖστοι λέγοντες τὸ διὰ πελάγους μυρίων εἶναι καὶ δισχιλίων. — πῶς οὐκ ἂν εἰκότως δόξειεν ὑπερβεβηκέναι καὶ ἀπολεληρηκέναι τὸν Βεργαῖον Ἀντιφάνην καὶ καθόλου μηδενὶ καταλιπεῖν ὑπερβολὴν ἀνοίας τῶν ἐπιγινομένων; —", "st": "34.6"}, {"sp": "N", "t": "ἑξῆς δὲ τὰ τοῦ Ἐρατοσθένους ἐπανορθοῖ, τὰ μὲν εὖ, τὰ δὲ χεῖρον λέγων ἢ ἐκεῖνος. ἐξ Ἰθάκης μὲν γὰρ εἰς Κόρκυραν τριακοσίους εἰπόντος, πλείους φησὶν εἶναι τῶν ἐνακοσίων, ἐξ Ἐπιδάμνου δὲ εἰς Θεσσαλονίκειαν ἐνακοσίους ἀποδόντος, πλείους τῶν δισχιλίων φησί. ταῦτα μὲν εὖ, ἀπὸ δὲ Μασσαλίας ἐπὶ στήλας λέγοντος ἑπτακισχιλίους, ἀπὸ δὲ Πυρήνης ἑξακισχιλίους, αὐτὸς λέγει χεῖρον πλείους ἢ ἐνακισχιλίους τοὺς ἀπὸ Μασσαλίας, ἀπὸ δὲ Πυρήνης μικρὸν ἐλάττους ἢ ὀκτακισχιλίους· ἐγγυτέρω γὰρ τῆς ἀληθείας ἐκεῖνος εἴρηκεν. οἱ γὰρ νῦν ὁμολογοῦσιν, εἴ τις τὰς τῶν ὁδῶν ἀνωμαλίας ὑποτέμνοιτο, μὴ μείζω τῶν ἑξακισχιλίων σταδίων εἶναι τὸ μῆκος τὴν σύμπασαν Ἰβηρίαν ἀπὸ Πυρήνης ἕως τῆς ἑσπερίου πλευρᾶς. ὁ δ’ αὐτὸν τὸν Τάγον ποταμὸν ὀκτακισχιλίων τίθησι τὸ μῆκος ἀπὸ τῆς πηγῆς μέχρι τῶν ἐκβολῶν, οὐ δήπου τὸ σὺν τοῖς σκολιώμασιν — οὐ γὰρ γεωγραφικὸν τοῦτο — ἀλλ’ ἐπ’ εὐθείας λέγων· καίτοι γε ἀπὸ Πυρήνης αἱ τοῦ Τάγου πηγαὶ πλέον διέχουσιν ἢ χιλίους σταδίους. πάλιν δὲ τοῦτο μὲν ὀρθῶς ἀποφαίνεται ὅτι ἀγνοεῖ τὰ Ἰβηρικὰ ὁ Ἐρατοσθένης καὶ διότι περὶ αὐτῆς ἔσθ’ ὅπου τὰ μαχόμενα ἀποφαίνεται, ὅς γε μέχρι Γαδείρων ὑπὸ Γαλατῶν περιοικεῖσθαι φήσας τὰ ἔξωθεν αὐτῆς, εἴ γε τὰ πρὸς δύσιν τῆς Εὐρώπης μέχρι Γαδείρων ἔχουσιν ἐκεῖνοι, τούτων ἐκλαθόμενος κατὰ τὴν τῆς Ἰβηρίας περίοδον τῶν Γαλατῶν οὐδαμοῦ μέμνηται. τὸ δὲ μῆκος τῆς Εὐρώπης ὅτι ἔλαττόν ἐστι τοῦ συνάμφω τῆς τε Λιβύης καὶ τῆς Ἀσίας ἐκθείς, οὐκ ὀρθῶς τὴν σύγκρισιν ποιεῖται. τὸ μὲν γὰρ στόμα τὸ κατὰ στήλας φησὶν ὅτι κατὰ τὴν ἰσημερινὴν δύσιν ἐστίν, ὁ δὲ Τάναϊς ῥεῖ ἀπὸ θερινῆς ἀνατολῆς· ἐλαττοῦται δὴ τοῦ συνάμφω μήκους τῷ μεταξὺ τῆς θερινῆς ἀνατολῆς καὶ τῆς ἰσημερινῆς· τοῦτο γὰρ ἡ Ἀσία προλαμβάνει πρὸς τὴν ἰσημερινὴν ἀνατολὴν τοῦ πρὸς τὰς ἄρκτους ἡμικυκλίου. — προπεπτωκυίας δὲ τῆς Εὐρώπης ἄκραις πλείοσι, βέλτιον μὲν οὗτος εἴρηκε περὶ αὐτῶν Ἐρατοσθένους, οὔπω δὲ ἱκανῶς. ἐκεῖνος μὲν γὰρ τρεῖς ἔφη, τὴν ἐπὶ τὰς στήλας καθήκουσαν, ἐφ’ ἧς ἡ Ἰβηρία, καὶ τὴν ἐπὶ τὸν πορθμόν, ἐφ’ ἧς ἡ Ἰταλία, καὶ τρίτην τὴν κατὰ Μαλέας, ἐφ’ ἧς τὰ μεταξὺ τοῦ Ἀδρίου καὶ τοῦ Εὐξείνου πάντ’ ἔθνη καὶ τοῦ Τανάιδος· οὗτος δὲ τὰς μὲν δύο τὰς πρώτας ὁμοίως ἐκτίθεται, τρίτην δὲ τὴν κατὰ Μαλέας καὶ Σούνιον, ἐφ’ ἧς ἡ Ἑλλὰς πᾶσα καὶ ἡ Ἰλλυρὶς καὶ τῆς Θρᾴκης τινά, τετάρτην δὲ τὴν κατὰ τὴν Θρᾳκίαν χερρόνησον, ἐφ’ ἧς τὰ κατὰ Σηστὸν καὶ Ἄβυδον στενά — ἔχουσι δ’ αὐτὴν Θρᾷκες — πέμπτην δὲ τὴν κατὰ τὸν Κιμμερικὸν Βόσπορον καὶ τὸ στόμα τῆς Μαιώτιδος.", "st": "34.7"}, {"sp": "N", "t": "Πολύβιος δ’ ὁ Μεγαλοπολίτης ἐν τετάρτῃ καὶ τριακοστῇ τῶν Ἱστοριῶν περὶ τῆς ἐν Ἰβηρίᾳ Λυσιτανίας χώρας διαλεγόμενός φησιν ὅτι βάλανοί εἰσι κατὰ βάθος ἐν τῇ αὐτόθι θαλάττῃ πεφυτευμέναι, ὧν τὸν καρπὸν σιτουμένους τοὺς θύννους πιαίνεσθαι. διόπερ οὐκ ἂν ἁμάρτοι τις λέγων ὗς εἶναι θαλαττίους τοὺς θύννους. — λέγει δ’ ὁ Πολύβιος καὶ μέχρι τῆς Λατίνης ἐκπίπτειν τὴν βάλανον ταύτην, εἰ μὴ ἄρα, φησί, καὶ ἡ Σαρδὼ φέρει καὶ ἡ πλησιόχωρος ταύτῃ. — τὴν κατὰ Λυσιτανίαν — χώρα δ’ ἐστὶν αὕτη τῆς Ἰβηρίας, ἣν νῦν Ῥωμαῖοι Σπανίαν ὀνομάζουσι — διηγούμενος εὐδαιμονίαν Πολύβιος ὁ Μεγαλοπολίτης … ἐν τῇ τετάρτῃ καὶ τριακοστῇ τῶν Ἱστοριῶν φησιν ὡς αὐτόθι διὰ τὴν τοῦ ἀέρος εὐκρασίαν καὶ τὰ ζῷα πολύγονα καὶ οἱ ἄνθρωποι, καὶ οἱ ἐν τῇ χώρᾳ καρποὶ οὐδέποτε φθείρονται· ῥόδα μὲν γὰρ αὐτόθι καὶ λευκόια καὶ ἀσπάραγοι καὶ τὰ παραπλήσια τούτοις οὐ πλεῖον διαλείπει μηνῶν τριῶν, τὸ δὲ θαλάττιον ὄψον καὶ κατὰ τὸ πλῆθος καὶ κατὰ τὴν χρηστότητα καὶ κατὰ τὸ κάλλος μεγάλην ἔχει διαφορὰν πρὸς τὸ γινόμενον ἐν τῇ καθ’ ἡμᾶς θαλάττῃ. καὶ ὁ μὲν τῶν κριθῶν Σικελικὸς μέδιμνός ἐστι δραχμῆς, ὁ δὲ τῶν πυρῶν ἐννέα ὀβολῶν Ἀλεξανδρεινῶν· τοῦ δ’ οἴνου δραχμῆς ὁ μετρητὴς καὶ ἔριφος ὁ μέτριος ὀβολοῦ καὶ λαγώς. τῶν δ’ ἀρνῶν τριώβολον καὶ τετρώβολον ἡ τιμή. ὗς δὲ πίων ἑκατὸν μνᾶς ἄγων πέντε δραχμῶν καὶ πρόβατον δυεῖν. τάλαντον δὲ σύκων τριῶν ὀβολῶν, μόσχος δραχμῶν πέντε καὶ βοῦς ζύγιμος δέκα. τὰ δὲ τῶν ἀγρίων ζῴων κρέα σχεδὸν οὐδὲ κατηξιοῦτο τιμῆς, ἀλλ’ ἐν ἐπιδόσει καὶ χάριτι τὴν ἀλλαγὴν ποιοῦνται τούτων.", "st": "34.8"}, {"sp": "N", "t": "τοὺς δ’ ἐνοικοῦντας Τουρδητανούς τε καὶ Τουρδούλους προσαγορεύουσιν, οἱ μὲν τοὺς αὐτοὺς νομίζοντες, οἱ δ’ ἑτέρους· ὧν ἐστι καὶ Πολύβιος, συνοίκους φήσας τοῖς Τουρδητανοῖς πρὸς ἄρκτον τοὺς Τουρδούλους. — τῇ δὲ τῆς χώρας εὐδαιμονίᾳ καὶ τὸ ἥμερον καὶ τὸ πολιτικὸν συνηκολούθησε τοῖς Τουρδητανοῖς, καὶ τοῖς Κελτικοῖς δὲ διὰ τὴν γειτνίασιν, ὡς δ’ εἴρηκε Πολύβιος, διὰ τὴν συγγένειαν. — καὶ Δικαίαρχος δὲ καὶ Ἐρατοσθένης καὶ Πολύβιος καὶ οἱ πλεῖστοι τῶν Ἑλλήνων περὶ τὸν πορθμὸν ἀποφαίνουσι τὰς στήλας. — φησὶ δὲ ὁ Πολύβιος κρήνην ἐν τῷ Ἡρακλείῳ τῷ ἐν Γαδείροις εἶναι, βαθμῶν ὀλίγων κατάβασιν ἔχουσαν εἰς τὸ ὕδωρ, πότιμον, ἣν ταῖς παλιρροίαις τῆς θαλάττης ἀντιπαθεῖν, κατὰ μὲν τὰς πλήμας ἐκλείπουσαν, κατὰ δὲ τὰς ἀμπώτεις πληρουμένην. αἰτιᾶται δ’ ὅτι τὸ πνεῦμα τὸ ἐκ τοῦ βάθους εἰς τὴν ἐπιφάνειαν τῆς γῆς ἐκπῖπτον, καλυφθείσης μὲν αὐτῆς ὑπὸ τοῦ κύματος κατὰ τὰς ἐπιβάσεις τῆς θαλάττης, εἴργεται τῶν οἰκείων τοιούτων ἐξόδων, ἀναστρέψαν δὲ εἰς τὸ ἐντὸς ἐμφράττει τοὺς τῆς πηγῆς πόρους καὶ ποιεῖ λειψυδρίαν· γυμνωθείσης δὲ πάλιν εὐθυπορῆσαν ἐλευθεροῖ τὰς φλέβας τῆς πηγῆς, ὥστ’ ἀναβλύειν εὐπόρως. — Πολύβιος δὲ τῶν περὶ Καρχηδόνα Νέαν ἀργυρείων μνησθεὶς μέγιστα μὲν εἶναί φησι, διέχειν δὲ τῆς πόλεως ὅσον εἴκοσι σταδίους, περιειληφότα κύκλον τετρακοσίων σταδίων, ὅπου τέτταρας μυριάδας ἀνθρώπων μένειν τῶν ἐργαζομένων, ἀναφέροντας τότε τῷ δήμῳ τῶν Ῥωμαίων καθ’ ἑκάστην ἡμέραν δισμυρίας καὶ πεντακισχιλίας δραχμάς. τὴν δὲ κατεργασίαν τὴν μὲν ἄλλην ἐῶ — μακρὰ γάρ ἐστι —, τὴν δὲ συρτὴν βῶλον τὴν ἀργυρῖτίν φησι κόπτεσθαι καὶ κοσκίνοις εἰς ὕδωρ διαττᾶσθαι· κόπτεσθαι δὲ πάλιν τὰς ὑποστάσεις καὶ πάλιν διηθουμένας ἀποχεομένων τῶν ὑδάτων κόπτεσθαι· τὴν δὲ πέμπτην ὑπόστασιν χωνευθεῖσαν, ἀποχυθέντος τοῦ μολίβδου, καθαρὸν τὸν ἄργυρον ἐξάγειν. — Πολύβιος δὲ καὶ τὸν Ἄναν καὶ τοῦτον ἐκ τῆς Κελτιβηρίας ῥεῖν φησι, διέχοντας ἀλλήλων ὅσον ἐνακοσίους σταδίους. — Πολύβιος δὲ τὰ τῶν Οὐακκαίων καὶ τῶν Κελτιβήρων ἔθνη καὶ χωρία διεξιὼν συλλέγει ταῖς ἄλλαις πόλεσι καὶ Σεγεσάμαν καὶ Ἰντερκατίαν. — τοιοῦτον δέ τινα ὑφίσταται τῇ κατασκευῇ καὶ λαμπρότητι οἵανπερ Πολύβιος Ἴβηρός τινος βασιλέως οἰκίαν. ὃν καὶ ἐζηλωκέναι λέγει τὴν τῶν Φαιάκων τρυφὴν πλὴν τοῦ τοὺς κρατῆρας ἐν μέσῳ τῆς οἰκίας ἑστάναι πλήρεις οἴνου κριθίνου, ἀργυροῦς ὄντας καὶ χρυσοῦς.", "st": "34.9"}, {"sp": "N", "t": "Πολύβιος δ’ ἐν τῇ τετάρτῃ καὶ τριακοστῇ τῶν Ἱστοριῶν μετὰ τὴν Πυρήνην φησὶν ἕως τοῦ Νάρβωνος ποταμοῦ πεδίον εἶναι, δι’ οὗ φέρεσθαι ποταμοὺς Ἰλλέβεριν καὶ Ῥόσκυνον, ῥέοντας παρὰ πόλεις ὁμωνύμους, κατοικουμένας ὑπὸ Κελτῶν. ἐν οὖν τῷ πεδίῳ τούτῳ εἶναι τοὺς λεγομένους ἰχθῦς ὀρυκτούς. εἶναι δὲ τὸ πεδίον λεπτόγειον καὶ πολλὴν ἄγρωστιν ἔχον πεφυκυῖαν· ὑπὸ δὲ ταύτην διάμμου τῆς γῆς οὔσης ἐπὶ δύο καὶ τρεῖς πήχεις, ὑπορρεῖν τὸ πλαζόμενον ἀπὸ τῶν ποταμῶν ὕδωρ, μεθ’ οὗ ἰχθύες κατὰ τὰς παρεκχύσεις ὑποτρέχοντες ὑπὸ τὴν γῆν χάριν τῆς τροφῆς — φιληδοῦσι γὰρ τῇ τῆς ἀγρώστεως ῥίζῃ — πεποιήκασι πᾶν τὸ πεδίον πλῆρες ἰχθύων ὑπογείων, οὓς ἀνορύττοντες λαμβάνουσιν. — περὶ δὲ τῶν τοῦ Ῥοδανοῦ στομάτων Πολύβιος … ἐπιτιμᾷ Τιμαίῳ, φήσας εἶναι μὴ πεντάστομον, ἀλλὰ δίστομον. — ὁ δὲ Λίγηρ μεταξὺ Πικτόνων τε καὶ Ναμνιτῶν ἐκβάλλει. πρότερον δὲ Κορβιλὼν ὑπῆρχεν ἐμπόριον ἐπὶ τούτῳ τῷ ποταμῷ, περὶ ἧς εἴρηκε Πολύβιος, μνησθεὶς τῶν ὑπὸ Πυθέου μυθολογηθέντων, ὅτι Μασσαλιωτῶν μὲν τῶν συμμιξάντων Σκιπίωνι οὐδεὶς εἶχε λέγειν οὐδὲν μνήμης ἄξιον, ἐρωτηθεὶς ὑπὸ τοῦ Σκιπίωνος περὶ τῆς Βρετταννικῆς, οὐδὲ τῶν ἐκ Νάρβωνος οὐδὲ τῶν ἐκ Κορβιλῶνος, αἵπερ ἦσαν ἄρισται πόλεις τῶν ταύτῃ, Πυθέας δ’ ἐθάρρησε τοσαῦτα ψεύσασθαι. — φησὶ δὲ Πολύβιος καὶ ἰδιόμορφόν τι γεννᾶσθαι ζῷον ἐν αὐταῖς, ἐλαφοειδὲς τὸ σχῆμα πλὴν αὐχένος καὶ τριχώματος, ταῦτα δ’ ἐοικέναι κάπρῳ· ὑπὸ δὲ τῷ γενείῳ πυρῆνα ἴσχειν ὅσον σπιθαμιαῖον ἀκρόκομον, πωλικῆς κέρκου τὸ πάχος. — ἔτι φησὶ Πολύβιος ἐφ’ ἑαυτοῦ κατ’ Ἀκυληίαν μάλιστα ἐν τοῖς Ταυρίσκοις τοῖς Νωρικοῖς εὑρεθῆναι χρυσεῖον οὕτως εὐφυὲς ὥστ’ ἐπὶ δύο πόδας ἀποσύραντι τὴν ἐπιπολῆς γῆν εὐθὺς ὀρυκτὸν εὑρίσκεσθαι χρυσόν. τὸ δ’ ὄρυγμα μὴ πλειόνων ὑπάρχειν ἢ πεντεκαίδεκα ποδῶν. εἶναι δὲ τοῦ χρυσοῦ τὸν μὲν αὐτόθεν καθαρόν, κυάμου μέγεθος ἢ θέρμου, τοῦ ὀγδόου μέρους μόνον ἀφεψηθέντος, τὸν δὲ δεῖσθαι μὲν χωνείας πλείονος, σφόδρα δὲ λυσιτελοῦς. συνεργασαμένων δὲ τοῖς βαρβαροῖς τῶν Ἰταλιωτῶν ἐν διμήνῳ, παραχρῆμα τὸ χρυσίον εὐωνότερον γενέσθαι τῷ τρίτῳ μέρει καθ’ ὅλην τὴν Ἰταλίαν. αἰσθομένους δὲ τοὺς Ταυρίσκους μονοπωλεῖν ἐκβαλόντας τοὺς συνεργαζομένους. — ὁ δ’ αὐτὸς ἀνὴρ περὶ τοῦ μεγέθους τῶν Ἄλπεων καὶ τοῦ ὕψους λέγων παραβάλλει τὰ ἐν τοῖς Ἕλλησιν ὄρη τὰ μέγιστα, τὸ Ταΰγετον, τὸ Λύκαιον, Παρνασσόν, Ὄλυμπον, Πήλιον, Ὄσσαν, ἐν δὲ Θρᾴκῃ Αἷμον, Ῥοδόπην, Δούνακα. καί φησιν ὅτι τούτων μὲν ἕκαστον μικροῦ δεῖν αὐθημερὸν εὐζώνοις ἀναβῆναι δυνατόν, αὐθημερὸν δὲ καὶ περιελθεῖν, τὰς δ’ Ἄλπεις οὐδ’ ἂν πεμπταῖος ἀναβαίη τις· τὸ δὲ μῆκός ἐστι δισχιλίων καὶ διακοσίων σταδίων τὸ παρῆκον παρὰ τὰ πεδία. τέτταρας δ’ ὑπερβάσεις ὀνομάζει μόνον, διὰ Λιγύων μὲν τὴν ἔγγιστα τῷ Τυρρηνικῷ πελάγει, εἶτα τὴν διὰ Ταυρίνων, ἣν Ἀννίβας διῆλθεν, εἶτα τὴν διὰ Σαλασσῶν, τετάρτην δὲ τὴν διὰ Ῥαιτῶν, ἁπάσας κρημνώδεις. λίμνας δὲ εἶναί φησιν ἐν τοῖς ὄρεσι πλείους μέν, τρεῖς δὲ μεγάλας, ὧν ἡ μὲν Βήνακος ἔχει μῆκος πεντακοσίων σταδίων, πλάτος δὲ ἑκατὸν τριάκοντα, ἐκρεῖ δὲ ποταμὸς Μίγκιος· ἡ δ’ ἑξῆς Λάριος τετρακοσίων, πλάτος δὲ στενωτέρα τῆς πρότερον, ἐξίησι δὲ ποταμὸν τὸν Ἀδούαν· τρίτη δὲ Οὐερβανὸς μῆκος ἐγγὺς τριακοσίων σταδίων, πλάτος δὲ τριάκοντα, ποταμὸν δὲ ἐξίησι μέγαν Τίκινον. πάντες δ’ εἰς τὸν Πάδον συρρέουσι.", "st": "34.10"}, {"sp": "N", "t": "Πολύβιος δὲ διάφορον οἶνον ἐν Καπύῃ φησὶ γίνεσθαι τὸν ἀναδενδρίτην καλούμενον, ᾧ μηδένα συγκρίνεσθαι. — φησὶ δὲ Πολύβιος πεζῇ μὲν εἶναι τὴν παραλίαν τὴν ἀπὸ Ἰαπυγίας μέχρι πορθμοῦ καὶ τρισχιλίων σταδίων, κλύζεσθαι δ’ αὐτὴν τῷ Σικελικῷ πελάγει, πλέοντι δὲ καὶ πεντακοσίων δέουσαν. — τῆς δὲ Τυρρηνίας μῆκος μὲν τὸ μέγιστον εἶναί φασι τὴν παραλίαν ἀπὸ Λούνης μέχρι Ὠστίων δισχιλίων που καὶ πεντακοσίων σταδίων· πλάτος δὲ τοῦ ἡμίσους ἔλαττον τὸ πρὸς τοῖς ὄρεσιν. εἰς μὲν οὖν Πίσας ἀπὸ Λούνης πλείους τῶν τετρακοσίων σταδίων εἰσίν, ἐντεῦθεν δ’ εἰς Οὐολατέρρας διακόσιοι ὀγδοήκοντα, πάλιν δ’ ἐνθένδε εἰς Ποπλώνιον διακόσιοι ἑβδομήκοντα, ἐκ δὲ Ποπλωνίου εἰς Κόσαν ἐγγὺς ὀκτακόσιοι, οἱ δὲ ἑξακόσιοί φασι. Πολύβιος δ’ οὐκ εὖ καὶ τοὺς πάντας χιλίους τριακοσίους τριάκοντα λέγει. — Αἰθάλη, νῆσος Τυρσηνῶν. … Πολύβιος δ’ ἐν τριακοστῇ τετάρτῃ λέγει Αἰθάλειαν τὴν Λῆμνον καλεῖσθαι. — καλοῦσι δ’ αὐτὸν Κρατῆρα, ἀπὸ τοῦ Μισηνοῦ μέχρι τοῦ Ἀθηναίου, δυεῖν ἀκρωτηρίων, κολπούμενον. ὑπὲρ δὲ τούτων τῶν ᾐόνων Καμπανία πᾶσα ἵδρυται, πεδίον εὐδαιμονέστατον τῶν ἁπάντων. … Ἀντίοχος μὲν οὖν φησι τὴν χώραν ταύτην Ὀπικοὺς οἰκῆσαι, τούτους δὲ καὶ Αὔσονας καλεῖσθαι. Πολύβιος δ’ ἐμφαίνει δύο ἔθνη νομίζων ταῦτα· Ὀπικοὺς γάρ φησι καὶ Αὔσονας οἰκεῖν τὴν χώραν ταύτην περὶ τὸν Κρατῆρα. — Πολύβιος δ’ ἀπὸ τῆς Ἰαπυγίας μεμιλιάσθαι φησί, καὶ εἶναι μίλια πεντακόσια ἑξήκοντα δύο εἰς Σίλαν πόλιν, ἐντεῦθεν δ’ εἰς Ἀκυληίαν ἑκατὸν ἑβδομήκοντα ὀκτώ. — μετὰ δὲ ταύτας τὸ Λακίνιον, Ἥρας ἱερόν, πλούσιόν ποτε ὑπάρξαν καὶ πολλῶν ἀναθημάτων μεστόν. τὰ διάρματα δ’ οὐκ εὐκρινῶς λέγεται· πλὴν ὥς γε ἐπὶ τὸ πολὺ σταδίους ἀπὸ πορθμοῦ μέχρι Λακινίου Πολύβιος ἀποδίδωσι χιλίους καὶ τριακοσίους, ἐντεῦθεν δὲ καὶ δίαρμα εἰς ἄκραν Ἰαπυγίαν ἑπτακοσίους. — Πολύβιος δὲ τῶν τριῶν κρατήρων τὸν μὲν κατερρυηκέναι φησὶν ἐκ μέρους, τοὺς δὲ συμμένειν· τὸν δὲ μέγιστον τὸ χεῖλος ἔχειν περιφερὲς ὂν πέντε σταδίων, κατ’ ὀλίγον δὲ συνάγεσθαι εἰς πεντήκοντα ποδῶν διάμετρον· καθ’ οὗ βάθος εἶναι τὸ μέχρι θαλάττης σταδιαῖον, ὥστε καθορᾶν ταῖς νηνεμίαις. [εἰ δὲ ταῦτ’ ἐστὶ πιστά, οὐκ ἀπιστητέον ἴσως οὐδὲ τοῖς περὶ Ἐμπεδοκλέους μυθολογηθεῖσιν. ] ἐὰν μὲν οὖν νότος μέλλῃ πνεῖν, ἀχλὺν ὁμιχλώδη καταχεῖσθαι κύκλῳ φησὶ τῆς νησῖδος, ὥστε μηδὲ τὴν Σικελίαν ἄπωθεν φαίνεσθαι· ὅταν δὲ βορέας, φλόγας καθαρὰς ἀπὸ τοῦ λεχθέντος κρατῆρος εἰς ὕψος ἐξαίρεσθαι καὶ βρόμους ἐκπέμπεσθαι μείζους· τὸν δὲ ζέφυρον μέσην τινὰ ἔχειν τάξιν. τοὺς δ’ ἄλλους κρατῆρας ὁμοειδεῖς μὲν εἶναι, τῇ δὲ βίᾳ λείπεσθαι τῶν ἀναφυσημάτων· ἔκ τε δὴ τῆς διαφορᾶς τῶν βρόμων καὶ ἐκ τοῦ πόθεν ἄρχεται τὰ ἀναφυσήματα καὶ αἱ φλόγες καὶ αἱ λιγνύες προσημαίνεσθαι καὶ τὸν εἰς ἡμέραν τρίτην πάλιν μέλλοντα ἄνεμον πνεῖν. τῶν γοῦν ἐν Λιπάραις γενομένης ἀπλοίας προειπεῖν τινάς φησι τὸν ἐσόμενον ἄνεμον καὶ μὴ διαψεύσασθαι. ἀφ’ οὗ δὴ τὸ μυθωδέστατον δοκοῦν εἰρῆσθαι τῷ ποιητῇ οὐ μάτην φαίνεσθαι λεχθέν, ἀλλ’ αἰνιξαμένου τὴν ἀλήθειαν, ὅταν φῇ ταμίαν τῶν ἀνέμων τὸν Αἴολον.", "st": "34.11"}, {"sp": "N", "t": "καὶ ἄλλα δ’ οὐ πιστὰ λέγει, τό τε συντετρῆσθαι τὰ πελάγη ἀπὸ τοῦ εὑρίσκεσθαι κέραμόν τε Χῖον καὶ Θάσιον ἐν τῷ Νάρωνι, καὶ τὸ ἄμφω κατοπτεύεσθαι τὰ πελάγη ἀπό τινος ὄρους, καὶ τῶν νήσων τῶν Λιβυρνίδων Τιθείς, ὥστε κύκλον ἔχειν σταδίων καὶ πεντακοσίων, καὶ τὸ τὸν Ἴστρον ἑνὶ τῶν στομάτων εἰς τὸν Ἀδρίαν ἐμβάλλειν. τοιαῦτα δὲ καὶ τοῦ Ἐρατοσθένους ἔνια παρακούσματά ἐστι λαοδογματικά, καθάπερ Πολύβιός φησι καὶ περὶ αὐτοῦ καὶ τῶν ἄλλων λέγων συγγραφέων. — ἐκ δὲ τῆς Ἀπολλωνίας εἰς Μακεδονίαν ἡ Ἐγνατία ἐστὶν ὁδὸς πρὸς ἕω, βεβηματισμένη κατὰ μίλιον καὶ κατεστηλωμένη μέχρι Κυψέλων καὶ Ἕβρου ποταμοῦ· μιλίων δ’ ἐστὶ πεντακοσίων τριάκοντα πέντε. λογιζομένῳ δέ, ὡς μὲν οἱ πολλοί, τὸ μίλιον ὀκταστάδιον τετρακισχίλιοι ἂν εἶεν στάδιοι καὶ ἐπ’ αὐτοῖς διακόσιοι ὀγδοήκοντα, ὡς δὲ Πολύβιος, προστιθεὶς τῷ ὀκτασταδίῳ δίπλεθρον, ὅ ἐστι τρίτον σταδίου, προσθετέον ἄλλους σταδίους ἑκατὸν ἑβδομήκοντα ὀκτώ, τὸ τρίτον τοῦ τῶν μιλίων ἀριθμοῦ. συμβαίνει δ’ ἀπὸ ἴσου διαστήματος συμπίπτειν εἰς τὴν αὐτὴν ὁδὸν τούς τ’ ἐκ τῆς Ἀπολλωνίας ὁρμηθέντας καὶ τοὺς ἐξ Ἐπιδάμνου. ἡ μὲν οὖν πᾶσα Ἐγνατία καλεῖται, ἡ δὲ πρώτη ἐπὶ Κανδαουίας λέγεται, ὄρους Ἰλλυρικοῦ, διὰ Λυχνιδοῦ πόλεως καὶ Πυλῶνος, τόπου ὁρίζοντος ἐν τῇ ὁδῷ τήν τε Ἰλλυρίδα καὶ τὴν Μακεδονίαν. ἐκεῖθεν δ’ ἐστὶ παρὰ Βαρνοῦντα διὰ Ἡρακλείας καὶ Λυγκηστῶν καὶ Ἐορδῶν εἰς Ἔδεσσαν καὶ Πέλλαν μέχρι Θεσσαλονικείας· μίλια δ’ ἐστί, φησὶ Πολύβιος, ταῦτα διακόσια ἑξήκοντα ἑπτά. — ὅτι ἐκ Περίνθου εἰς Βυζάντιόν εἰσιν ἑξακόσιοι τριάκοντα, ἀπὸ δὲ Ἕβρου καὶ Κυψέλων εἰς Βυζάντιον μέχρι Κυανέων τρισχίλιοι ἑκατόν, ὥς φησιν Ἀρτεμίδωρος, τὸ δὲ σύμπαν μῆκος ἀπὸ Ἰονίου κόλπου τοῦ κατὰ Ἀπολλωνίαν μέχρι Βυζαντίου ἑπτακισχίλιοι τριακόσιοι εἴκοσι· προστίθησι δ’ ὁ Πολύβιος καὶ ἄλλους ἑκατὸν ὀγδοήκοντα, τὸ τρίτον τοῦ σταδίου προσλαμβάνων ἐπὶ τοῖς ὀκτὼ τοῦ μιλίου σταδίοις. ἡ δὲ περίμετρος μὴ κατακολπίζοντι τετρακισχιλίων σταδίων, ὡς Πολύβιος. — Πολυβίου δ’ εἰρηκότος τὸ ἀπὸ Μαλεῶν ἐπὶ τὰς ἄρκτους μέχρι τοῦ Ἴστρου διάστημα περὶ μυρίους σταδίους, εὐθύνει τοῦτο ὁ Ἀρτεμίδωρος οὐκ ἀτόπως … κατ’ ἐκεῖνον δὴ συμβαίνει τὸ ἐκ τοῦ Ἴστρου ἐπὶ Μαλέας ἑξακισχιλίων πεντακοσίων. αἴτιον δὲ τούτου τὸ μὴ τὴν σύντομον καταμετρεῖν ἀλλὰ τὴν τυχοῦσαν, ἣν ἐπορεύθη τῶν στρατηγῶν τις.", "st": "34.12"}, {"sp": "N", "t": "τὰ δ’ ἐπ’ εὐθείας τούτοις μέχρι τῆς Ἰνδικῆς τὰ αὐτὰ κεῖται καὶ παρὰ τῷ Ἀρτεμιδώρῳ, ἅπερ καὶ παρὰ τῷ Ἐρατοσθένει. λέγει δὲ καὶ Πολύβιος περὶ τῶν ἐκεῖ μάλιστα δεῖν πιστεύειν ἐκείνῳ.", "st": "34.13"}, {"sp": "N", "t": "ὁ γοῦν Πολύβιος γεγονὼς ἐν τῇ πόλει βδελύττεται τὴν τότε κατάστασιν καί φησι τρία γένη τὴν πόλιν οἰκεῖν, τό τε Αἰγύπτιον καὶ ἐπιχώριον φῦλον, ὀξὺ καὶ πολιτικόν, καὶ τὸ μισθοφορικόν, βαρὺ καὶ πολὺ καὶ ἀνάγωγον· ἐξ ἔθους γὰρ παλαιοῦ ξένους ἔτρεφον τοὺς τὰ ὅπλα ἔχοντας, ἄρχειν μᾶλλον ἢ ἄρχεσθαι δεδιδαγμένους διὰ τὴν τῶν βασιλέων οὐδένειαν. τρίτον δ’ ἦν γένος τὸ τῶν Ἀλεξανδρέων, οὐδ’ αὐτὸ εὐκρινῶς πολιτικὸν διὰ τὰς αὐτὰς αἰτίας, κρεῖττον δ’ ἐκείνων ὅμως· καὶ γὰρ εἰ μιγάδες, Ἕλληνες ὅμως ἀνέκαθεν ἦσαν καὶ ἐμέμνηντο τοῦ κοινοῦ τῶν Ἑλλήνων ἔθους. ἠφανισμένου δὲ καὶ τούτου τοῦ πλήθους, μάλιστα ὑπὸ τοῦ Εὐεργέτου τοῦ Φύσκωνος, καθ’ ὃν ἧκεν εἰς τὴν Ἀλεξάνδρειαν ὁ Πολύβιος — καταστασιαζόμενος γὰρ ὁ Φύσκων πλεονάκις τοῖς στρατιώταις ἐφίει τὰ πλήθη καὶ διέφθειρε —, τοιούτων δή, φησίν, ὄντων τῶν ἐν τῇ πόλει, λοιπὸν ἦν τῷ ὄντι τὸ τοῦ ποιητοῦ Αἴγυπτόνδ’ ἰέναι δολιχὴν ὁδὸν ἀργαλέην τε.", "st": "34.14"}, {"sp": "HDR", "t": "Βιβλίον ΛΕʹ", "st": "35"}, {"sp": "N", "t": "πύρινος πόλεμος, ὁ Ῥωμαίων πρὸς τοὺς Κελτίβηρας συσταθείς. θαυμαστὴν γὰρ ἔσχε τὴν ἰδιότητα τήν τε συνέχειαν τῶν ἀγώνων. τοὺς γὰρ κατὰ τὴν Ἑλλάδα πολέμους καὶ τοὺς κατὰ τὴν Ἀσίαν ὡς ἐπίπαν μία μάχη κρίνει, σπανίως δὲ δευτέρα, καὶ τὰς μάχας αὐτὰς εἷς καιρὸς ὁ κατὰ τὴν πρώτην ἔφοδον καὶ σύμπτωσιν τῆς δυνάμεως· κατὰ δὲ τοῦτον τὸν πόλεμον τἀναντία συνέβαινε τοῖς προειρημένοις. τοὺς μὲν γὰρ κινδύνους ὡς ἐπίπαν ἡ νὺξ διέλυε, τῶν ἀνδρῶν οὔτ’ εἴκειν ταῖς ψυχαῖς οὔτε παρακαθιέναι τοῖς σώμασι βουλομένων διὰ τὸν κόπον, ἀλλ’ ἐξ ὑποστροφῆς καὶ μεταμελείας αὖθις ἄλλας ἀρχὰς ποιουμένων. τόν γε μὴν ὅλον πόλεμον καὶ τὴν συνέχειαν τῶν ἐκ παρατάξεως διακρίσεων ὁ χειμὼν ἐπὶ ποσὸν διεῖργε. καθόλου γάρ, εἴ τις διανοηθείη πύρινον πόλεμον, οὐκ ἂν ἕτερον ἢ τοῦτον νοήσειε. —", "st": "35.1"}, {"sp": "N", "t": "ὅτι ἐπειδὴ οἱ Κελτίβηρες ἀνοχὰς ποιησάμενοι πρὸς Μάρκον Κλαύδιον τὸν στρατηγὸν τῶν Ῥωμαίων ἐξαπέστειλαν τὰς πρεσβείας εἰς τὴν Ῥώμην, οὗτοι μὲν τὴν ἡσυχίαν ἦγον, καραδοκοῦντες τὴν ἀπόφασιν τῆς συγκλήτου, Μάρκος δὲ στρατεύσας εἰς τοὺς Λυσιτανοὺς καὶ τὴν Νερκόβρικα πόλιν κατὰ κράτος ἑλὼν ἐν Κορδύβᾳ τὴν παραχειμασίαν ἐποιεῖτο. τῶν δὲ πρέσβεων εἰς τὴν Ῥώμην παραγενομένων, τοὺς μὲν παρὰ τῶν Βελλῶν καὶ Τίττων, ὅσοι τὰ Ῥωμαίων ᾑροῦντο, παρεδέξαντο πάντας εἰς τὴν πόλιν, τοὺς δὲ παρὰ τῶν Ἀραυακῶν πέραν τοῦ Τιβέρεως ἐκέλευσαν κατασκηνοῦν διὰ τὸ πολεμίους ὑπάρχειν, ἕως βουλεύσωνται περὶ τῶν ὅλων. γενομένου δὲ καιροῦ πρὸς ἔντευξιν, κατὰ πόλιν ὁ στρατηγὸς εἰσῆγε τοὺς συμμάχους. οἱ δὲ καίπερ ὄντες βάρβαροι διετίθεντο λόγους καὶ πάσας ἐξευκρινεῖν ἐπειρῶντο τὰς διαφοράς, ὑποδεικνύντες ὡς, εἰ μὴ συσταλήσονται καὶ τεύξονται τῆς ἁρμοζούσης κολάσεως οἱ πεπολεμηκότες, παραυτίκα μέν, ἐπανελθόντων τῶν Ῥωμαϊκῶν στρατοπέδων ἐκ τῆς Ἰβηρίας, ἐκ χειρὸς προσεπιθήσουσι τὴν δίκην αὐτοῖς. ὡς προδόταις γεγονόσι, ταχὺ δὲ πάλιν αὐτοὶ κινήσουσι πραγμάτων ἀρχήν, ἐὰν ἀνεπιτίμητοι διαφύγωσιν ἐκ τῆς πρώτης ἁμαρτίας, ἑτοίμους δὲ πάντας πρὸς καινοτομίαν ποιήσουσι τοὺς κατὰ τὴν Ἰβηρίαν, ὡς ἱκανοὶ γεγονότες ἀντίπαλοι Ῥωμαίοις. διόπερ ἠξίουν ἢ μένειν τὰ στρατόπεδα κατὰ τὴν Ἰβηρίαν καὶ διαβαίνειν καθ’ ἕκαστον ἔτος ὕπατον ἐφεδρεύσοντα τοῖς συμμάχοις καὶ κολάσοντα τὰς Ἀραυακῶν ἀδικίας, ἢ βουλομένους ἀπάγειν τὰς δυνάμεις παραδειγματιστέον εἶναι τὴν τῶν προειρημένων ἐπανάστασιν, ἵνα μηδεὶς ἔτι ποιεῖν θαρρῇ τὸ παραπλήσιον τούτοις. οἱ μὲν οὖν Βελλῶν καὶ Τίττων συμμαχοῦντες Ῥωμαίοις ταῦτα καὶ τὰ τούτοις παραπλήσια διελέχθησαν. ἐπὶ δὲ τούτοις εἰσῆγον τοὺς παρὰ τῶν πολεμίων. οἱ δ’ Ἀραυάκαι παρελθόντες κατὰ μὲν τὴν ὑπόκρισιν ἐχρῶντο τοῖς λόγοις ὑποπεπτωκότως καὶ ταπεινῶς, τῇ γε μὴν προαιρέσει [ὡς] διέφαινον οὐκ εἰκούσῃ τοῖς ὅλοις οὐδ’ ἡττωμένῃ. καὶ γὰρ τὰ τῆς τύχης ἄδηλα πολλάκις ὑπεδείκνυον καὶ τὰς προγεγενημένας μάχας ἀμφιδηρίτους ποιοῦντες ἐν πάσαις ἔμφασιν ἀπέλειπον ὡς ἐπικυδεστέρων αὐτῶν γεγονότων. τέλος δ’ ἦν τῶν λόγων· εἰ μέν τι δεῖ ῥητὸν πρόστιμον ὑπομένειν τῆς ἀγνοίας, ἀναδέχεσθαι τοῦτ’ ἔφασαν, τελεσθέντος δὲ τοῦ προστάγματος ἐπανάγειν ἠξίουν ἐπὶ τὰς κατὰ Τεβέριον ὁμολογίας αὐτοῖς γενομένας πρὸς τὴν σύγκλητον.", "st": "35.2"}, {"sp": "N", "t": "οἱ δ’ ἐν τῷ συνεδρίῳ διακούσαντες ἀμφοτέρων εἰσήγαγον τοὺς παρὰ τοῦ Μαρκέλλου πρέσβεις. θεωροῦντες δὲ καὶ τούτους ῥέποντας ἐπὶ τὴν διάλυσιν καὶ τὸν στρατηγὸν προσνέμοντα τὴν αὑτοῦ γνώμην τοῖς πολεμίοις μᾶλλον ἢ τοῖς συμμάχοις, τοῖς μὲν Ἀραυάκαις ἔδωκαν καὶ τοῖς συμμάχοις ἀπόκρισιν ὅτι Μάρκελλος ἀμφοτέροις ἐν Ἰβηρίᾳ διασαφήσει τὴν τῆς συγκλήτου γνώμην, αὐτοὶ δὲ νομίσαντες τοὺς συμμάχους ἀληθῆ καὶ συμφέροντα σφίσι λέγειν, τοὺς δ’ Ἀραυάκας ἀκμὴν μεγαλοφρονεῖν, τὸν δὲ στρατηγὸν ἀποδειλιᾶν τὸν πόλεμον, ἐντολὰς ἔδωκαν δι’ ἀπορρήτων τοῖς παρ’ ἐκείνου πρεσβευταῖς πολεμεῖν γενναίως καὶ τῆς πατρίδος ἀξίως. ἐπειδὴ δὲ τὸν πόλεμον ἐποίησαν κατάμονον, πρῶτον μὲν τῷ Μαρκέλλῳ διαπιστήσαντες ἕτερον στρατηγὸν ἔμελλον διαπέμπειν εἰς τὴν Ἰβηρίαν· ἤδη γὰρ ἔτυχον ὕπατοι τότε καθεσταμένοι καὶ τὰς ἀρχὰς παρειληφότες Αὖλος Ποστόμιος καὶ Λεύκιος Λικίννιος Λεύκολλος. ἔπειτα περὶ τὰς παρασκευὰς ἐγίνοντο φιλοτίμως καὶ μεγαλομερῶς, νομίζοντες διὰ ταύτης τῆς πράξεως κριθήσεσθαι τὰ κατὰ τὴν Ἰβηρίαν· κρατηθέντων μὲν γὰρ τῶν ἐχθρῶν πάντας ὑπέλαβον σφίσι ποιήσειν τὸ προσταττόμενον, ἀποστρεψαμένων δὲ τὸν ἐνεστῶτα φόβον οὐ μόνον Ἀραυάκας καταθαρρήσειν, ἀλλὰ καὶ τοὺς ἄλλους ἅπαντας.", "st": "35.3"}, {"sp": "N", "t": "ὅσῳ δὲ φιλοτιμότερον ἡ σύγκλητος διέκειτο πρὸς τὸν πόλεμον, τοσούτῳ σφίσι τὰ πράγματ’ ἀπέβαινε παραδοξότερα. τοῦ μὲν γὰρ Κοΐντου τοῦ τὸν πρότερον ἐνιαυτὸν στρατηγήσαντος ἐν Ἰβηρίᾳ καὶ τῶν μετ’ αὐτοῦ στρατευσαμένων ἠγγελκότων εἰς τὴν Ῥώμην τήν τε συνέχειαν τῶν ἐκ παρατάξεως κινδύνων καὶ τὸ πλῆθος τῶν ἀπολωλότων καὶ τὴν ἀνδρείαν τῶν Κελτιβήρων, τοῦ δὲ Μαρκέλλου προφανῶς ἀποδειλιῶντος τὸν πόλεμον, ἐνέπεσέ τις πτοία τοῖς νέοις παράλογος, οἵαν οὐκ ἔφασαν οἱ πρεσβῦται γεγενημένην πρότερον. εἰς γὰρ τοῦτο προύβη τὰ τῆς ἀποδειλιάσεως ὥστε μήτε χιλιάρχους προπορεύεσθαι πρὸς τὴν ἀρχὴν τοὺς ἱκανούς, ἀλλ’ ἐλλείπειν τὰς χώρας, τὸ πρότερον εἰθισμένων πολλαπλασιόνων προπορεύεσθαι τῶν καθηκόντων, μήτε τοὺς εἰσφερομένους ὑπὸ τῶν ὑπάτων πρεσβευτὰς ὑπακούειν, οὓς ἔδει πορεύεσθαι μετὰ τοῦ στρατηγοῦ, τὸ δὲ μέγιστον, τοὺς νέους διακλίνειν τὰς καταγραφὰς καὶ τοιαύτας πορίζεσθαι προφάσεις ἃς λέγειν μὲν αἰσχρὸν ἦν, ἐξετάζειν δ’ ἀπρεπές, ἐπιτέμνειν δ’ ἀδύνατον. τέλος δὲ καὶ τῆς συγκλήτου καὶ τῶν ἀρχόντων ἐν ἀμηχανίαις ὄντων τί τὸ πέρας ἔσται τῆς τῶν νέων ἀναισχυντίας — τούτῳ γὰρ ἠναγκάζοντο χρῆσθαι τῷ ῥήματι διὰ τὰ συμβαίνοντα — Πόπλιος Κορνήλιος [Ἀφρικανός], νέος μὲν ὤν, δοκῶν δὲ σύμβουλος γεγονέναι τοῦ πολέμου, τὴν ἐπὶ καλοκἀγαθίᾳ καὶ σωφροσύνῃ δόξαν ὁμολογουμένην πεποιημένος, τῆς δ’ ἐπ’ ἀνδρείᾳ φήμης προσδεόμενος, θεωρῶν τὴν σύγκλητον ἀπορουμένην, ἀναστὰς εἶπεν εἴτε χιλίαρχον εἴτε πρεσβευτὴν πέμπειν αὐτὸν εἰς τὴν Ἰβηρίαν μετὰ τῶν ὑπάτων ἐξεῖναι· πρὸς ἀμφότερα γὰρ ἑτοίμως ἔχειν. καίτοι γ’ ἔφη κατ’ ἰδίαν μὲν αὑτῷ τὴν εἰς Μακεδονίαν ἔξοδον ἅμα μὲν ἀσφαλεστέραν ἅμα δ’ οἰκειοτέραν εἶναι· συνέβαινε γὰρ τότε τοὺς Μακεδόνας ἐπ’ ὀνόματος καλεῖν τὸν Σκιπίωνα διαλύσοντα τὰς ἐν αὐτοῖς στάσεις· ἀλλὰ τοὺς τῆς πατρίδος καιροὺς ἔφη κατεπείγειν μᾶλλον καὶ καλεῖν εἰς τὴν Ἰβηρίαν τοὺς ἀληθινῶς φιλοδοξοῦντας. πᾶσιν δὲ παραδόξου φανείσης τῆς ἐπαγγελίας καὶ διὰ τὴν ἡλικίαν καὶ διὰ τὴν ἄλλην εὐλάβειαν, παραυτίκα μὲν εὐθέως συνέβη μεγάλην ἀποδοχὴν γενέσθαι τοῦ Σκιπίωνος, ἔτι δὲ μᾶλλον ταῖς ἑξῆς ἡμέραις· οἱ γὰρ πρότερον ἀποδειλιῶντες, ἐκτρεπόμενοι τὸν ἐκ παραθέσεως ἔλεγχον, οἱ μὲν πρεσβεύσειν ἐθελοντὴν ἐπηγγέλλοντο τοῖς στρατηγοῖς, οἱ δὲ πρὸς τὰς στρατιωτικὰς καταγραφὰς προσεπορεύοντο κατὰ συστρέμματα καὶ συνηθείας. —", "st": "35.4"}, {"sp": "N", "t": "Πολύβιος· ἐνέπεσε δέ τις ὁρμὴ τῷ Σκιπίωνι καὶ διαπόρησις, εἰ δεῖ συμβαλεῖν καὶ μονομαχῆσαι πρὸς τὸν βάρβαρον. — Πολύβιος … καὶ ἀλλαχοῦ· ὁ δ’ ἵππος ὁ τοῦ Σκιπίωνος ἐδυσχρήστησε μὲν ὑπὸ τῆς πληγῆς, οὐ μὴν ὁλοσχερῶς ἐσφάλμησε. διόπερ ὀρθὸς ἀπέπεσεν ἐπὶ τὴν γῆν ὁ Σκιπίων· Πολύβιος.", "st": "35.5"}, {"sp": "N", "t": "ὑπὲρ δὲ τῶν ἐξ Ἀχαΐας φυγάδων ἐντευχθεὶς διὰ Πολύβιον ὑπὸ Σκιπίωνος, ὡς πολὺς ἐν τῇ συγκλήτῳ λόγος ἐγίνετο, τῶν μὲν διδόντων κάθοδον αὐτοῖς, τῶν δ’ ἐνισταμένων, ἀναστὰς ὁ Κάτων \" ὥσπερ οὐκ ἔχοντες\" εἶπεν \"ὃ πράττωμεν, καθήμεθα τὴν ἡμέραν ὅλην περὶ γεροντίων Γραικῶν ζητοῦντες, πότερον ὑπὸ τῶν παρ’ ἡμῖν ἢ τῶν ἐν Ἀχαΐᾳ νεκροφόρων ἐκκομισθῶσι. \" ψηφισθείσης δὲ τῆς καθόδου τοῖς ἀνδράσιν, ἡμέρας ὀλίγας οἱ περὶ τὸν Πολύβιον διαλιπόντες αὖθις ἐπεχείρουν εἰς τὴν σύγκλητον εἰσελθεῖν, ὅπως ἃς πρότερον εἶχον ἐν Ἀχαΐᾳ τιμὰς οἱ φυγάδες ἀναλάβοιεν, καὶ τοῦ Κάτωνος ἀπεπειρῶντο τῆς γνώμης. ὁ δὲ μειδιάσας ἔφη τὸν Πολύβιον, ὥσπερ τὸν Ὀδυσσέα, βούλεσθαι πάλιν εἰς τὸ τοῦ Κύκλωπος σπήλαιον εἰσελθεῖν, τὸ πιλίον ἐκεῖ καὶ τὴν ζώνην ἐπιλελησμένον", "st": "35.6"}, {"sp": "HDR", "t": "Βιβλίον ΛϚʹ", "st": "36"}, {"sp": "N", "t": "ἴσως δέ τινες ἐπιζητοῦσι πῶς ἡμεῖς οὐκ ἐν ἀγωνίσματι κεχρήμεθα προφερόμενοι τοὺς κατὰ μέρος λόγους, τοιαύτης ὑποθέσεως ἐπειλημμένοι καὶ τηλικαύτης πράξεως· ὅπερ οἱ πλεῖστοι ποιοῦσι τῶν συγγραφέων, εἰς ἀμφότερα τὰ μέρη διατιθέμενοι τοὺς ἐνόντας λόγους. ἐγὼ δὲ διότι μὲν οὐκ ἀποδοκιμάζω τοῦτο τὸ μέρος, ἐν πλείοσι τόποις τῆς ἱστορίας δῆλον πεποίημαι, πολλάκις ἀπηγγελκὼς δημηγορίας καὶ συντάξεις ἀνδρῶν πολιτικῶν· ὅτι δ’ οὐκ ἐκ παντὸς τρόπου τοῦτο προαιροῦμαι πράττειν, νῦν ἔσται συμφανές· οὔτε γὰρ ὑπόθεσιν ἐπιφανεστέραν ταύτης εὑρεῖν ῥᾴδιον οὔθ’ ὕλην πλείω καὶ παράθεσιν. καὶ μὴν οὐδὲ προχειρότερον ἕτερον ἐμοὶ τῆς τοιαύτης παρασκευῆς. ἀλλ’ οὔτε τοῖς πολιτικοῖς ἀνδράσιν οἶμαι πρέπειν πρὸς πᾶν τὸ προτεθὲν διαβούλιον εὑρησιλογεῖν καὶ διεξοδικοῖς χρῆσθαι λόγοις, ἀλλ’ ἀεὶ τοῖς ἁρμόζουσι πρὸς τὸν ὑποκείμενον καιρόν, οὔτε τοῖς ἱστοριογράφοις ἐμμελετᾶν τοῖς ἀκούουσιν οὐδ’ ἐναποδείκνυσθαι τὴν αὑτῶν δύναμιν, ἀλλὰ τὰ κατ’ ἀλήθειαν ῥηθέντα καθ’ ὅσον οἷόν τε πολυπραγμονήσαντας διασαφεῖν, καὶ τούτων τὰ καιριώτατα καὶ πραγματικώτατα. —", "st": "36.1"}, {"sp": "N", "t": "πάλαι δὲ τούτου κεκυρωμένου βεβαίως ἐν ταῖς ἑκάστων γνώμαις καιρὸν ἐζήτουν ἐπιτήδειον καὶ πρόφασιν εὐσχήμονα πρὸς τοὺς ἐκτός. πολὺ γὰρ δὴ τούτου τοῦ μέρους ἐφρόντιζον Ῥωμαῖοι, καλῶς φρονοῦντες· ἔνστασις γὰρ πολέμου κατὰ τὸν Δημήτριον δικαία μὲν εἶναι δοκοῦσα καὶ τὰ νικήματα ποιεῖ μείζω καὶ τὰς ἀποτεύξεις ἀσφαλεστέρας, ἀσχήμων δὲ καὶ φαύλη τοὐναντίον ἀπεργάζεται· διὸ καὶ τότε περὶ τῆς τῶν ἐκτὸς διαλήψεως πρὸς ἀλλήλους διαφερόμενοι παρ’ ὀλίγον ἀπέστησαν τοῦ πολέμου. —", "st": "36.2"}, {"sp": "N", "t": "ὅτι τῶν Καρχηδονίων πάλαι βουλευομένων περὶ τοῦ πῶς ἀπαντῆσαι δεῖ πρὸς τὴν Ῥωμαίων ἀπόκρισιν, καὶ τῶν Ἰτυκαίων ὑποτεμομένων τὴν ἐπίνοιαν αὐτῶν, τοῖς Ῥωμαίοις τὴν ἑαυτῶν παραδόντων πόλιν, ὁλοσχερὴς ἀμηχανία περιέστη τοὺς ἀνθρώπους. μιᾶς γὰρ ἐλπίδος ἔτι φαινομένης αὐτοῖς, εἰ συγκαταβαῖεν εἰς τὸ δοῦναι τὴν ἐπιτροπὴν περὶ αὑτῶν, διότι πάντως εὐδοκεῖν ποιήσουσι τοὺς Ῥωμαίους, διὰ τὸ μηδ’ ἐν ταῖς μεγίσταις περιστάσεσιν καταπολεμηθέντες, καὶ πρὸς τοῖς τείχεσι τῶν πολεμίων ὑπαρχόντων, μηδέποτε τὴν ἐπιτροπὴν δεδωκέναι τῆς πατρίδος, καὶ ταύτης τῆς ἐπινοίας τὸν καρπὸν ἀπέβαλον, προκαταληφθέντες ὑπὸ τῶν Ἰτυκαίων· οὐδὲν γὰρ ξένον οὐδὲ παράδοξον ἔμελλε φανήσεσθαι τοῖς Ῥωμαίοις, εἰ ταὐτὸν ποιήσαιεν τοῖς προειρημένοις. οὐ μὴν ἀλλὰ κακῶν αἱρέσεως καταλειπομένης, ἢ τὸν πόλεμον ἀναδέχεσθαι γενναίως ἢ διδόναι τὴν ἐπιτροπὴν περὶ τῶν καθ’ αὑτούς, πολλοὺς καὶ ποικίλους ἐν τῷ συνεδρίῳ δι’ ἀπορρήτων ποιησάμενοι λόγους κατέστησαν πρεσβευτὰς αὐτοκράτορας, καὶ τούτους ἐξαπέστελλον, δόντες ἐντολὴν βλέποντας πρὸς τὰ παρόντα πράττειν τὸ δοκοῦν συμφέρειν τῇ πατρίδι, ἦσαν δ’ οἱ πρεσβεύοντες Γίσκων Στρυτάνος ἐπικαλούμενος, Ἀμίλκας, Μίσδης, Γιλλίμας, Μάγων. ἥκοντες δ’ οἱ πρέσβεις παρὰ τῶν Καρχηδονίων εἰς Ῥώμην καὶ καταλαβόντες πόλεμον δεδογμένον καὶ τοὺς στρατηγοὺς ὡρμηκότας μετὰ τῶν δυνάμεων, οὐκέτι διδόντων βουλὴν αὐτοῖς τῶν πραγμάτων, ἔδωκαν τὴν ἐπιτροπὴν περὶ αὑτῶν.", "st": "36.3"}, {"sp": "N", "t": "περὶ δὲ τῆς ἐπιτροπῆς εἴρηται μὲν ἡμῖν καὶ πρότερον, ἀναγκαῖον δ’ ἔστιν καὶ νῦν ὑπομνῆσαι κεφαλαιωδῶς. οἱ γὰρ διδόντες αὑτοὺς εἰς τὴν Ῥωμαίων ἐπιτροπὴν διδόασι πρῶτον μὲν χώραν τὴν ὑπάρχουσαν αὐτοῖς καὶ πόλεις τὰς ἐν ταύτῃ, σὺν δὲ τούτοις ἄνδρας καὶ γυναῖκας τοὺς ὑπάρχοντας ἐν τῇ χώρᾳ καὶ ταῖς πόλεσιν ἅπαντας, ὁμοίως ποταμούς, λιμένας, ἱερά, τάφους, συλλήβδην ὥστε πάντων εἶναι κυρίους Ῥωμαίους, αὐτοὺς δὲ τοὺς διδόντας ἁπλῶς μηκέτι μηδενός. γενομένης δὲ τῆς ἀνθομολογήσεως τοιαύτης ὑπὸ τῶν Καρχηδονίων, καὶ μετ’ ὀλίγον εἰσκληθέντων αὐτῶν εἰς τὸ συνέδριον, ἔλεγεν ὁ στρατηγὸς τὴν τῆς συγκλήτου γνώμην ὅτι καλῶς αὐτῶν βεβουλευμένων δίδωσιν αὐτοῖς ἡ σύγκλητος τήν τ’ ἐλευθερίαν καὶ τοὺς νόμους, ἔτι δὲ τὴν χώραν ἅπασαν καὶ τὴν τῶν ἄλλων ὑπαρχόντων κτῆσιν καὶ κοινῇ καὶ κατ’ ἰδίαν. οἱ δὲ Καρχηδόνιοι ταῦτ’ ἀκούσαντες ἔχαιρον, δόξαντες ὡς ἐν κακῶν αἱρέσει καλῶς σφίσιν κεχρῆσθαι τὴν σύγκλητον, ἅτε τῶν ἀναγκαιοτάτων καὶ μεγίστων αὐτοῖς συγκεχωρημένων. μετὰ δὲ ταῦτα τοῦ στρατηγοῦ διασαφοῦντος διότι τεύξονται τούτων, ἐὰν τριακοσίους ὁμήρους εἰς τὸ Λιλύβαιον ἐκπέμψωσιν ἐν τριάκονθ’ ἡμέραις τοὺς υἱοὺς τῶν ἐκ τῆς συγκλήτου καὶ τῆς γερουσίας καὶ τοῖς ὑπὸ τῶν ὑπάτων παραγγελλομένοις πειθαρχήσωσιν, ἐπὶ ποσὸν ἠπόρησαν ποῖα τὰ διὰ τῶν ὑπάτων αὐτοῖς ἔσται παραγγελλόμενα· πλὴν τότε γ’ ἐξ αὐτῆς ὥρμησαν, σπεύδοντες ἀναγγεῖλαι τῇ πατρίδι περὶ τούτων. παραγενόμενοι δ’ εἰς τὴν Καρχηδόνα διεσάφουν τοῖς πολίταις τὰ κατὰ μέρος. οἱ δὲ διακούσαντες τἄλλα μὲν ἐνδεχομένως ἐνόμιζον βεβουλεῦσθαι τοὺς πρεσβευτάς, περὶ δὲ πόλεως μὴ γεγονέναι μνείαν εἰς μεγάλην ἐπίστασιν αὐτοὺς ἦγε καὶ πολλὴν ἀμηχανίαν.", "st": "36.4"}, {"sp": "N", "t": "ἐν δὲ τῷ καιρῷ τούτῳ φασὶ Μάγωνα τὸν Βρέττιον χρήσασθαι λόγοις ἀνδρώδεσι καὶ πραγματικοῖς. δύο γάρ, ὡς ἔοικε, καιροὺς ἔφασκεν εἶναι τοῦ βουλεύσασθαι περὶ σφῶν καὶ τῆς πατρίδος, ὧν τὸν μὲν ἕνα παρεῖσθαι. δεῖν γὰρ οὐ μὰ Δία νῦν διαπορεῖν τί διὰ τῶν ὑπάτων αὐτοῖς παραγγελθήσεται, καὶ διὰ τί περὶ πόλεως οὐδεμίαν ἐποιήσατο μνείαν ἡ σύγκλητος, ἀλλὰ καθ’ ὃν καιρὸν ἐδίδοσαν τὴν ἐπιτροπήν· δόντας δὲ σαφῶς γινώσκειν διότι πᾶν τὸ παραγγελλόμενον ἐπιδεκτέον ἐστίν, ἐὰν μὴ τελέως ὑπερήφανον ᾖ καὶ παρὰ τὴν προσδοκίαν· εἰ δὲ μή, τότε πάλιν βουλεύεσθαι πότερα δεῖ προσδέχεσθαι τὸν πόλεμον εἰς τὴν χώραν καὶ πάσχειν ὅ, τι ποτ’ ἂν οὗτος ἐπιφέρῃ τῶν δεινῶν, ἢ κατορρωδήσαντας τὴν τῶν πολεμίων ἔφοδον ἐθελοντὴν ἀναδέχεσθαι πᾶν τὸ προσταττόμενον. πάντων δὲ διὰ τὸν ἐφεστῶτα πόλεμον καὶ διὰ τὸ τῆς προσδοκίας ἄδηλον φερομένων ἐπὶ τὸ πειθαρχεῖν τοῖς παραγγελλομένοις, ἔδοξεν πέμπειν τοὺς ὁμήρους εἰς τὸ Λιλύβαιον. καὶ παραυτίκα καταλέξαντες τριακοσίους τῶν νέων ἐξέπεμπον μετὰ μεγάλης οἰμωγῆς καὶ δακρύων, ἅτε προπεμπόντων ἕκαστον τῶν ἀναγκαίων καὶ συγγενῶν, καὶ μάλιστα τῶν γυναικῶν ἐκκαουσῶν τὴν τοιαύτην διάθεσιν. ἐπεὶ δὲ κατέπλευσαν εἰς τὸ Λιλύβαιον, οἱ μὲν ἐξ αὐτῆς παρεδόθησαν διὰ τῶν ὑπάτων Κοΐντῳ Φαβίῳ Μαξίμῳ — συνέβαινε γὰρ τοῦτον ἐπὶ τῆς Σικελίας τετάχθαι στρατηγὸν τότε — δι’ οὗ παρακομισθέντες ἀσφαλῶς εἰς τὴν Ῥώμην συνεκλείσθησαν ὁμοῦ πάντες εἰς τὸ τῆς ἑκκαιδεκήρους νεώριον", "st": "36.5"}, {"sp": "N", "t": "καὶ τῶν μὲν ὁμήρων ἐκεῖσε παραχθέντων, οἱ στρατηγοὶ κατήχθησαν εἰς τὴν τῆς Ἰτύκης ἄκραν. τούτων δὲ προσπεπτωκότων τοῖς Καρχηδονίοις ὀρθὴ καὶ περίφοβος ἦν ἡ πόλις διὰ τὴν ἀδηλότητα τῶν προσδοκωμένων. οὐ μὴν ἀλλ’ ἔδοξεν αὐτοῖς πρεσβευτὰς πέμπειν τοὺς πευσομένους τῶν ὑπάτων τί δεῖ ποιεῖν καὶ διασαφήσοντας ὅτι πρὸς πᾶν τὸ παραγγελλόμενον ἕτοιμοι πάντες εἰσίν. τῶν δὲ πρεσβευτῶν ἀφικομένων εἰς τὴν τῶν Ῥωμαίων παρεμβολήν, καὶ τοῦ συνεδρίου συναχθέντος, εἰσελθόντες οἱ πρέσβεις διελέγοντο κατὰ τὰς ἐντολάς. ὁ δὲ πρεσβύτερος τῶν ὑπάτων ἐπαινέσας αὐτῶν τὴν πρόθεσιν καὶ προαίρεσιν ἐκέλευε παραδιδόναι τά θ’ ὅπλα καὶ τὰ βέλη πάντα χωρὶς δόλου καὶ ἀπάτης. οἱ δὲ πρέσβεις ποιήσειν μὲν ἔφασαν τὸ παραγγελλόμενον, σκοπεῖσθαι δ’ αὐτοὺς ἠξίουν τὸ συμβησόμενον, ἐὰν αὐτοὶ μὲν παραχωρήσωσι τῶν ὅπλων, ἐκεῖνοι δὲ λαβόντες ἀποπλεύσωσιν. ὅμως ταῦτα ἔδωκαν. — δῆλον ἐγένετο διότι μέγα τὸ βάσταγμα τῆς πόλεως ἦν· πλείονα γὰρ εἴκοσι μυριάδων ὅπλα παρέδωκαν Ῥωμαίοις καὶ καταπέλτας δισχιλίους. —", "st": "36.6"}, {"sp": "N", "t": "ἁπλῶς δ’ οὐδὲν εἶδος τῶν μελλόντων ἔγνωσαν, ἐξ αὐτῆς δὲ τῆς ἐμφάσεως ὀττευόμενοι τῶν πρέσβεων εἰς παντοδαπὰς οἰμωγὰς καὶ θρήνους ἐνέπιπτον. — οἱ δὲ πάντες ἅμ’ ἀνακεκραγότες ἐξ αὐτῆς οἱονεὶ παρελύθησαν. ταχὺ δὲ τοῦ λόγου διαδοθέντος εἰς τὸ πλῆθος, οὐκέτι συνέβαινε γίνεσθαι τὴν ἀλογίαν, ἀλλ’ οἱ μὲν ἐπὶ τοὺς πρεσβευτὰς ὥρμων, ὡς αἰτίους σφίσι τῶν κακῶν ὄντας τούτων, οἱ δ’ ἐπὶ τοὺς κατειλημμένους τῶν Ἰταλικῶν καὶ ἐπὶ τούτους ἀπηρείσαντο τὸν θυμόν, οἱ δὲ πρὸς τὰς πύλας τῆς πόλεως —", "st": "36.7"}, {"sp": "N", "t": "Ἀμίλκας, ὁ καὶ Φαμέας, Καρχηδονίων στρατηγός, ὃς ὑπῆρχε κατὰ μὲν τὴν ἡλικίαν ἀκμάζων καὶ κατὰ τὴν ἕξιν ἐρρωμένος, τὸ δὲ μέγιστον ἐφόδιον πρὸς πολεμικὴν χρείαν, ἱππεὺς ἄγαν ἀγαθὸς καὶ τολμηρός. — οἱ δὲ διαζηλοτυπούμενοι πρὸς τὸν Σκιπίωνα ἐπεβάλοντο διασύρειν τὰς πράξεις αὐτοῦ. — τὰς προφυλακὰς βλέπων ὁ Φαμέας, ὢν οὐκ ἄψυχος, ἐξέκλινε τὰς πρὸς τὸν Σκιπίωνα συμπλοκάς. καί ποτε συνεγγίσας ταῖς ἐφεδρείαις, προβαλόμενος ὀφρὺν ἀπότομον ἐπέστη καὶ πλείω χρόνον. — αἱ δὲ σημεῖαι τῶν Ῥωμαίων συνεπεφεύγεσαν εἰς βουνόν· καὶ πάντων δόντων γνώμας ὁ Σκιπίων ἔφη, ὅταν ἐξ ἀκεραίου βουλεύωνται, καὶ πλείω ποιεῖσθαι πρόνοιαν τοῦ μηδὲν παθεῖν ἢ τοῦ δρᾶσαι κακῶς τοὺς ἐχθρούς. — οὐ χρὴ θαυμάζειν εἰ φιλοτιμότερον ἐξηγούμεθα τὰ κατὰ τὸν Σκιπίωνα καὶ πᾶν τὸ ῥηθὲν ὑπ’ αὐτοῦ μετὰ διαστολῆς ἐξαγγέλλομεν. — Πολύβιος· ἐν γὰρ τῇ Ῥώμῃ Μάρκον Πόρκιον ἀκούσαντα τὰς ἀριστείας Σκιπίωνος εἰπεῖν [πάλιν ἄλλον πρὸς ἐκεῖνον· τί ἀκήκοας] οἶος πέπνυται· τοὶ δὲ σκιαὶ ἀΐσσουσιν. — οἱ δὲ Ῥωμαῖοι ὑπερευδοκούμενοι κατὰ πάντα τρόπον τῇ τοῦ Σκιπίωνος ὁμολογίᾳ καὶ τῷ χειρισμῷ τῶν πραγμάτων", "st": "36.8"}, {"sp": "HDR", "t": "Βιβλίον ΛΖʹ", "st": "37"}, {"sp": "N", "t": "ὅτι περὶ Καρχηδονίων, ὅτε κατεπολέμησαν αὐτοὺς οἱ Ῥωμαῖοι, καὶ περὶ τῶν κατὰ τὸν Ψευδοφίλιππον κατὰ τὴν Ἑλλάδα πολλοὶ καὶ παντοῖοι διεφέροντο λόγοι, τὰς μὲν ἀρχὰς ὑπὲρ τῶν κατὰ Καρχηδονίους, μετὰ δὲ ταῦτα πάλιν ὑπὲρ τῶν κατὰ τὸν Ψευδοφίλιππον. τὰ μὲν οὖν περὶ Καρχηδονίους ἀμφιδοξουμένας εἶχε τὰς ἀποφάσεις καὶ τὰς διαλήψεις· ἔνιοι μὲν γὰρ συγκατῄνουν τοῖς Ῥωμαίοις, φάσκοντες αὐτοὺς φρονίμως καὶ πραγματικῶς βουλεύσασθαι περὶ τῆς δυναστείας· τὸ γὰρ τὸν ἐπικρεμάμενον φόβον καὶ τὴν πολλάκις μὲν ἠμφισβητηκυῖαν πρὸς αὐτοὺς πόλιν ὑπὲρ τῆς ἡγεμονίας, ἔτι δὲ καὶ νῦν δυναμένην ἀμφισβητῆσαι σὺν καιρῷ, ταύτην ἐπανελομένους βεβαιῶσαι τῇ σφετέρᾳ πατρίδι τὴν ἀρχὴν νοῦν ἐχόντων εἶναι καὶ μακρὰν βλεπόντων ἀνθρώπων. ἔνιοι δὲ τούτοις ἀντέλεγον, φάσκοντες οὐ ταύτην ἔχοντας αὐτοὺς τὴν προαίρεσιν κατεκτῆσθαι τὴν ἡγεμονίαν καὶ κατὰ μικρὸν εἰς τὴν Ἀθηναίων καὶ Λακεδαιμονίων ἐκτρέπεσθαι φιλαρχίαν καὶ βραδύτερον μὲν ἐκείνων ὁρμᾶν, ἥξειν δ’ ἐπὶ ταὐτὸ τέλος ἐκ τῶν προφαινομένων. πρότερον μὲν γὰρ πᾶσι πεπολεμηκέναι μέχρι τοῦ κρατῆσαι καὶ συγχωρῆσαι τοὺς ἀντιταξαμένους ὅτι δεῖ πείθεσθαι σφίσι καὶ ποιεῖν τὸ παραγγελλόμενον· νῦν δὲ προοίμιον μὲν ἐκτεθεῖσθαι τῆς ἰδίας προαιρέσεως τὰ κατὰ Περσέα, βαστάσαντας ἐκ ῥιζῶν τὴν Μακεδόνων βασιλείαν, τετελειωκέναι δὲ κατὰ τὸ παρὸν διὰ τῆς περὶ Καρχηδονίων διαλήψεως· μηδενὸς γὰρ ἀνηκέστου γεγονότος ἐξ ἐκείνων, ἀνηκέστως καὶ βαρέως βεβουλεῦσθαι περὶ αὐτῶν, πᾶν ἀναδεχομένων καὶ πᾶν ὑπομενόντων ποιήσειν τὸ προσταττόμενον. ἕτεροι δὲ καθόλου μὲν πολιτικὸν εἶναι τὸ Ῥωμαϊκὸν ἔθνος ἔφασαν καὶ τοῦτ’ ἴδιον εἶναι καὶ ἐπὶ τούτῳ σεμνύνεσθαι τοὺς Ῥωμαίους, ἐπὶ τῷ καὶ τοὺς πολέμους ἁπλῶς καὶ γενναίως πολεμεῖν, μὴ νυκτεριναῖς ἐπιθέσεσι χρωμένους μηδ’ ἐνέδραις, πᾶν δὲ τὸ δι’ ἀπάτης καὶ δόλου γινόμενον ἀποδοκιμάζοντας, μόνους δὲ τοὺς ἐκ προδήλου καὶ κατὰ πρόσωπον κινδύνους ὑπολαμβάνοντας αὑτοῖς καθήκειν. νῦν δὲ πάντα περὶ τοὺς Καρχηδονίους δι’ ἀπάτης καὶ δόλου κεχειρικέναι, κατὰ βραχὺ τὸ μὲν προτείνοντας, τὸ δ’ ἐπικρυπτομένους, ἕως οὗ παρείλαντο πάσας τὰς ἐλπίδας τοῦ βοηθεῖν αὐτοῖς τοὺς συμμάχους. τοῦτο δὲ μοναρχικῆς πραγματοποιίας οἰκεῖον εἶναι μᾶλλον ἢ πολιτικῆς καὶ Ῥωμαϊκῆς αἱρέσεως καὶ προσεοικὸς ἀσεβήματι καὶ παρασπονδήματι κατὰ τὸν ὀρθὸν λόγον. ἦσαν δέ τινες οἱ καὶ τούτοις ἀντιλέγοντες. εἰ μὲν γὰρ πρὶν ἢ δοῦναι τοὺς Καρχηδονίους τὴν ἐπιτροπὴν αὑτῶν οὕτως ἐχείριζον τὰ πράγματα, κατὰ βραχὺ τὰ μὲν προτείνοντες, τὰ δὲ παραγυμνοῦντες, εἰκότως ἂν αὐτοὺς ἐνόχους φαίνεσθαι τοῖς ἐγκαλουμένοις εἰ δὲ δόντων αὐτῶν τῶν Καρχηδονίων τὴν ἐπιτροπὴν ὥστε βουλεύεσθαι Ῥωμαίους ὅ, τι ποτὲ φαίνοιτο περὶ αὐτῶν, οὕτω κατὰ τὴν ἐξουσίαν, ὥς ποτε δοκοῖ σφίσι, τὸ κριθὲν ἐπέταττον καὶ παρήγγελλον, οὐκέτι τὸ γινόμενον ἀσεβήματι παραπλήσιον εἶναι καὶ μὴν οὐδὲ παρασπονδήματι μικροῦ δεῖν· ἔνιοι δ’ ἔφασαν οὐκ ἀδικήματι τὸ παράπαν· τριῶν γὰρ οὐσῶν διαφορῶν, εἰς ἃς τὸ πᾶν ἔγκλημα φύσει καταντᾶν, εἰς οὐδεμίαν ἐμπίπτειν τούτων τὸ γινόμενον ὑπὸ Ῥωμαίων· ἀσέβημα μὲν γὰρ εἶναι τὸ περὶ τοὺς θεοὺς καὶ τοὺς γονεῖς καὶ τοὺς τεθνεῶτας ἁμαρτάνειν, παρασπόνδημα δὲ τὸ παρὰ τὰς ἐνόρκους καὶ τὰς ἐγγράπτους ὁμολογίας πραττόμενον, ἀδίκημα δὲ τὸ παρὰ τοὺς νόμους καὶ τοὺς ἐθισμοὺς ἐπιτελούμενον· ὧν οὐδὲν κατὰ τὸ παρὸν ἐνόχους εἶναι Ῥωμαίους· οὐ γὰρ εἰς τοὺς θεοὺς οὐδ’ εἰς τοὺς γονεῖς οὐδ’ εἰς τοὺς τεθνεῶτας ἐξαμαρτάνειν, οὐδὲ μὴν ὅρκους οὐδὲ συνθήκας παραβαίνειν, τὸ δ’ ἐναντίον αὐτοὺς ἐγκαλεῖν τοῖς Καρχηδονίοις ὅτι παραβεβήκασι. καὶ μὴν οὐδὲ νόμους οὐδ’ ἐθισμοὺς οὐδὲ τὴν κατ’ ἰδίαν πίστιν ἀθετεῖν· λαβόντας γὰρ τὴν ἐπιτροπὴν παρ’ ἑκόντων ὃ βούλοιντο πράττειν, οὐ πειθαρχούντων τοῖς παραγγελλομένοις, οὕτως αὐτοῖς προσάγειν τὴν ἀνάγκην.", "st": "37.1"}, {"sp": "N", "t": "περὶ μὲν οὖν Ῥωμαίων καὶ Καρχηδονίων ταῦτ’ ἐλέγετο· περὶ δὲ τοῦ Ψευδοφιλίππου τὸ μὲν πρῶτον οὐδ’ ἀνεκτὸς ὁ λόγος ἐφαίνετο· πάρεστί τις ἐπὶ τὴν Μακεδονίαν ἀεροπετὴς Φίλιππος, καταφρονήσας οὐ μόνον Μακεδόνων ἀλλὰ καὶ Ῥωμαίων, οὐδεμίαν ἀφορμὴν εὔλογον ἔχων πρὸς τὴν ἐπιβολήν, ἅτε γινωσκομένου τοῦ κατ’ ἀλήθειαν Φιλίππου διότι σχεδὸν ὀκτωκαίδεκα γεγονὼς ἐτῶν μετήλλαξε τὸν βίον ἐν Ἄλβᾳ τῆς Ἰταλίας δυσὶν ὕστερον ἔτεσιν αὐτοῦ τοῦ Περσέως. μετὰ δὲ μῆνας τρεῖς ἢ τέτταρας προσπεσούσης φήμης διότι νενίκηκε μάχῃ τοὺς Μακεδόνας πέραν τοῦ Στρυμόνος κατὰ τὴν Ὀδομαντικήν, τινὲς μὲν ἀπεδέχοντο τὸν λόγον, οἱ δὲ πλείους ἀκμὴν ἠπίστουν. μετ’ οὐ πολὺ δὲ πάλιν ἅμα τοῦ λόγου προσπίπτοντος ὅτι νικᾷ μάχῃ τοὺς Μακεδόνας ἐπὶ τάδε τοῦ Στρυμόνος καὶ πάσης Μακεδονίας κρατεῖ, καὶ Θετταλῶν γράμματα καὶ πρεσβευτὰς πεμψάντων πρὸς τοὺς Ἀχαιοὺς καὶ παρακαλούντων βοηθεῖν, ὡς καὶ περὶ αὐτοὺς ὑπάρχοντος κινδύνου, θαυμαστὸν ἐφάνη καὶ παράδοξον τὸ γεγονός· οὐδεμία γὰρ οὔτε πιθανότης οὔτ’ εὐλογία προυφαίνετο περὶ τοῦ συμβεβηκότος. τοιαῦται μὲν οὖν περὶ τούτων ἦσαν διαθέσεις. —", "st": "37.2"}, {"sp": "N", "t": "ὅτι προσπεσόντων εἰς τὴν Πελοπόννησον γραμμάτων τοῖς Ἀχαιοῖς παρὰ τοῦ Μανιλίου διότι καλῶς ποιήσουσι Πολύβιον τὸν Μεγαλοπολίτην ἐκπέμψαντες μετὰ σπουδῆς εἰς Λιλύβαιον, ὡς χρείας οὔσης αὐτοῦ δημοσίων ἕνεκεν πραγμάτων, ἔδοξε τοῖς Ἀχαιοῖς ἐκπέμπειν ἀκολούθως τοῖς ὑπὸ τοῦ ὑπάτου γεγραμμένοις. ἡμεῖς δὲ νομίζοντες ἑαυτοῖς καθήκειν κατὰ πολλοὺς τρόπους τὸ πειθαρχεῖν Ῥωμαίοις, πάντα τἄλλα πάρεργα θέμενοι θερείας ἀρχομένης ἐξεπλεύσαμεν. ἀφικόμενοι δ’ εἰς Κέρκυραν καὶ καταλαβόντες αὐτοῦ γράμματα παρὰ τῶν ὑπάτων προσπεπτωκότα τοῖς Κερκυραίοις, ἐν οἷς διεσάφουν ὅτι τοὺς μὲν ὁμήρους ἤδη παραδεδώκασιν αὐτοῖς οἱ Καρχηδόνιοι, πάντως ἕτοιμοι δ’ εἰσὶν αὐτοῖς πειθαρχεῖν, νομίσαντες διαλελύσθαι τὸν πόλεμον καὶ μηκέτι χρείαν ἡμῶν εἶναι μηδεμίαν, αὖθις ἀπεπλεύσαμεν εἰς τὴν Πελοπόννησον. —", "st": "37.3"}, {"sp": "N", "t": "οὐ χρὴ δὲ θαυμάζειν ἐὰν ποτὲ μὲν τῷ κυρίῳ σημαίνωμεν αὑτοὺς ὀνόματι, ποτὲ δὲ ταῖς κοιναῖς ἐμφάσεσιν, οἷον οὕτως \"ἐμοῦ δὲ ταῦτ’ εἰπόντος\" καὶ πάλιν \"ἡμῶν δὲ συγκαταθεμένων.\" ἐπὶ πολὺ γὰρ ἐμπεπλεγμένων ἡμῶν εἰς τὰς μετὰ ταῦτα μελλούσας ἱστορεῖσθαι πράξεις, ἀναγκαῖόν ἐστι μεταλαμβάνειν τὰς περὶ αὑτῶν σημασίας, ἵνα μήτε τοὔνομα συνεχῶς προφερόμενοι προσκόπτωμεν ταυτολογοῦντες μήτε πάλιν \"ἐμοῦ\" καὶ \"δι’ ἐμέ\" παρ’ ἕκαστον λέγοντες λάθωμεν εἰς φορτικὴν διάθεσιν ἐμπίπτοντες, ἀλλὰ συγχρώμενοι πᾶσι τούτοις καὶ μεταλαμβάνοντες ἀεὶ τὸ τῷ καιρῷ πρέπον ἐφ’ ὅσον οἷόν τε διαφεύγωμεν τὸ λίαν ἐπαχθὲς τῆς περὶ αὑτῶν λαλιᾶς, ἐπειδὴ φύσει μὲν ἀπρόσδεκτός ἐστιν ὁ τοιοῦτος λόγος, ἀναγκαῖος δ’ ὑπάρχει πολλάκις, ὅταν μὴ δυνατὸν ἄλλως ᾖ δηλῶσαι τὸ προκείμενον. γέγονε δέ τι πρὸς τοῦτο τὸ μέρος ἡμῖν οἷον ἐκ ταὐτομάτου συνέργημα τὸ μηδένα μέχρι γε τῶν καθ’ ἡμᾶς καιρῶν ταὐτὸν ἡμῖν ὄνομα κεκληρονομηκέναι κυρίως, ὅσον γε καὶ ἡμᾶς εἰδέναι. —", "st": "37.4"}, {"sp": "N", "t": "ὅτι κατά τι σύμπτωμα τῶν μὲν τοῦ Καλλικράτους εἰκόνων εἰσφερομένων κατὰ τὸ σκότος, τῶν δὲ τοῦ Λυκόρτα κατὰ τὴν αὐτὴν ἡμέραν ἐκφερομένων εἰς τὸ φῶς κατὰ τὴν ἐξ ἀρχῆς διάθεσιν, πάντας ἠνάγκαζε τὸ γινόμενον ἐπιφθέγγεσθαι διότι δεῖ μηδέποτε τοῖς καιροῖς ὑπερηφάνως χρῆσθαι κατὰ τῶν πέλας, εἰδότα διότι καὶ λίαν τοῦτ’ ἔστιν ἴδιον ἐπιτήδευμα τῆς τύχης, τὸ τοῖς αὑτῶν ἐπινοήμασι καὶ νομοθετήμασιν ἐξ ὑποστροφῆς αὐτοὺς ὑποβάλλειν τοὺς νομοθετήσαντας. — ὅτι αὐτὸ τὸ φύσει φιλόκαινον τῶν ἀνθρώπων ἱκανόν ἐστι πρὸς πᾶσαν μεταβολήν.", "st": "37.5"}, {"sp": "N", "t": "ὅτι Ῥωμαῖοι ἔπεμψαν πρεσβευτὰς τοὺς ἐπιληψομένους τῆς ὁρμῆς τῆς τοῦ Νικομήδους καὶ κωλύσοντας τὸν Ἄτταλον πολεμεῖν τῷ Προυσίᾳ, καὶ κατεστάθησαν Μάρκος Λικίννιος, ἄνθρωπος ποδαγρικὸς καὶ τελείως ἀδύνατος τοῖς ποσί, καὶ μετὰ τοῦτον Αὖλος Μαγκῖνος, ὃς κεραμίδος εἰς τὴν κεφαλὴν ἐμπεσούσης αὐτῷ τηλικαύτας καὶ τοσαύτας οὐλὰς εἶχε διὰ τῆς κεφαλῆς ὥστε θαυμαστὸν εἶναι πῶς ἐσώθη, καὶ Λεύκιος Μαλλέολος, ὃς πάντων ἐδόκει Ῥωμαίων ἀναισθητότατος ὑπάρχειν. τῆς δὲ πράξεως προσδεομένης τάχους καὶ τόλμης ἐδόκουν ἀφυέστατοι πρὸς τὴν χρείαν εἶναι ταύτην οἱ καθεσταμένοι. διὸ καί φασι Μάρκον Πόρκιον τὸν Κάτωνα προσαγορευόμενον εἰπεῖν ἐν συγκλήτῳ διότι συμβήσεται μὴ μόνον ἀπολόμενον φθάσαι τὸν Προυσίαν, ἀλλὰ καὶ τὸν Νικομήδην γηράσαντ’ ἐν τῇ βασιλείᾳ· πῶς γὰρ οἷόν τε καταταχῆσαι, πῶς δὲ καταταχήσασαν ἀνύσασθαί τι τὴν πρεσβείαν, μήτε πόδας μήτε κεφαλὴν μήτε καρδίαν ἔχουσαν. —", "st": "37.6"}, {"sp": "N", "t": "ὅτι Προυσίας ὁ βασιλεύς, εἰδεχθὴς ὢν κατὰ τὴν ἔμφασιν, καίπερ ἐκ συλλογισμοῦ βελτίων ὑπάρχων, ἥμισυς ἀνὴρ ἦν κατὰ τὴν ἐπιφάνειαν καὶ πρὸς τὰς πολεμικὰς χρείας ἀγεννὴς καὶ γυναικώδης. οὐ γὰρ μόνον δειλὸς ἦν, ἀλλὰ καὶ πρὸς τὰς κακοπαθείας ἀλλότριος καὶ συλλήβδην ἐκτεθηλυμμένος καὶ τῇ ψυχῇ καὶ τῷ σώματι παρ’ ὅλον τὸν βίον· ὅπερ ἥκιστα βούλονται περὶ τοὺς βασιλεῖς ὑπάρχειν ἅπαντες μέν, μάλιστα δὲ τὸ τῶν Βιθυνῶν γένος. πολλὴ δέ τις ἀσέλγεια καὶ περὶ τὰς σωματικὰς ἐπιθυμίας αὐτῷ συνεξηκολούθει. παιδείας δὲ καὶ φιλοσοφίας καὶ τῶν ἐν τούτοις θεωρημάτων ἄπειρος εἰς τέλος ἦν καὶ συλλήβδην τοῦ καλοῦ τί ποτ’ ἔστιν οὐδ’ ἔννοιαν εἶχε, Σαρδαναπάλλου δὲ βάρβαρον βίον ἔζη καὶ μεθ’ ἡμέραν καὶ νύκτωρ. τοιγαροῦν ἅμα τῷ δράξασθαι βραχείας ἐλπίδος τὸ τῶν βασιλευομένων πλῆθος ἀμετάκλητον ὁρμὴν ἔσχεν εἰς τὸ μὴ μόνον ἀλλότρια φρονεῖν τοῦ βασιλέως, ἀλλὰ καὶ τιμωρίαν βούλεσθαι παρ’ αὐτοῦ λαμβάνειν.", "st": "37.7"}, {"sp": "N", "t": "Μούσειον, τόπος περὶ τὸν Ὄλυμπον τὸν ἐν Μακεδονίᾳ· Πολύβιος τριακοστῷ ἑβδόμῳ.", "st": "37.8"}, {"sp": "N", "t": "ἐγὼ δέ, φησὶν ὁ Πολύβιος ἐπιτιμῶν τοῖς τὴν τύχην καὶ τὴν εἱμαρμένην ἐπιγράφουσιν ἐπί τε τὰς κοινὰς πράξεις καὶ τὰς κατ’ ἰδίαν περιπετείας, νῦν βούλομαι περὶ τούτου τοῦ μέρους διαστείλασθαι καθ’ ὅσον ὁ τῆς πραγματικῆς ἱστορίας ἐπιδέχεται τρόπος. ὧν μὲν νὴ Δί’ ἀδύνατον ἢ δυσχερὲς τὰς αἰτίας καταλαβεῖν ἄνθρωπον ὄντα, περὶ τούτων ἴσως ἄν τις ἀπορῶν ἐπὶ τὸν θεὸν τὴν ἀναφορὰν ποιοῖτο καὶ τὴν τύχην, οἶον ὄμβρων καὶ νιφετῶν ἐξαισίων ἐπιφορὰ συνεχής, ἢ τἀναντία πάλιν αὐχμῶν καὶ πάγων καὶ διὰ ταῦτα φθορὰ καρπῶν, ὁμοίως λοιμικαὶ διαθέσεις συνεχεῖς, ἄλλα παραπλήσια τούτοις, ὧν οὐκ εὐμαρὲς τὴν αἰτίαν εὑρεῖν. διόπερ εἰκότως περὶ τῶν τοιούτων ἀκολουθοῦντες ταῖς τῶν πολλῶν δόξαις διὰ τὴν ἀπορίαν, ἱκετεύοντες καὶ θύοντες ἐξιλασκόμενοι τὸ θεῖον, πέμπομεν ἐρησόμενοι τοὺς θεοὺς τί ποτ’ ἂν ἢ λέγουσιν ἢ πράττουσιν ἡμῖν ἄμεινον εἴη καὶ γένοιτο παῦλα τῶν ἐνεστώτων κακῶν. ὧν δὲ δυνατόν ἐστι τὴν αἰτίαν εὑρεῖν, ἐξ ἧς καὶ δι’ ἣν ἐγένετο τὸ συμβαῖνον, οὐχί μοι δοκεῖ τῶν τοιούτων δεῖν ἐπὶ τὸ θεῖον ποιεῖσθαι τὴν ἀναφοράν. λέγω δ’ οἷον οὕτως. ἐπέσχεν ἐν τοῖς καθ’ ἡμᾶς καιροῖς τὴν Ἑλλάδα πᾶσαν ἀπαιδία καὶ συλλήβδην ὀλιγανθρωπία, δι’ ἣν αἵ τε πόλεις ἐξηρημώθησαν καὶ ἀφορίαν εἶναι συνέβαινε, καίπερ οὔτε πολέμων συνεχῶν ἐσχηκότων ἡμᾶς οὔτε λοιμικῶν περιστάσεων. εἴ τις οὖν περὶ τούτου συνεβούλευσεν εἰς θεοὺς πέμπειν ἐρησομένους τί ποτ’ ἂν ἢ λέγοντες ἢ πράττοντες πλείονες γινοίμεθα καὶ κάλλιον οἰκοίημεν τὰς πόλεις, ἆρ’ οὐ μάταιος ἂν ἐφαίνετο, τῆς αἰτίας προφανοῦς ὑπαρχούσης καὶ τῆς διορθώσεως ἐν ἡμῖν κειμένης; τῶν γὰρ ἀνθρώπων εἰς ἀλαζονείαν καὶ φιλοχρημοσύνην, ἔτι δὲ ῥᾳθυμίαν ἐκτετραμμένων καὶ μὴ βουλομένων μήτε γαμεῖν μήτ’, ἐὰν γήμωσι, τὰ γινόμενα τέκνα τρέφειν, ἀλλὰ μόλις ἓν τῶν πλείστων ἢ δύο χάριν τοῦ πλουσίους τούτους καταλιπεῖν καὶ σπαταλῶντας θρέψαι, ταχέως ἔλαθε τὸ κακὸν αὐξηθέν. ὅτε γὰρ ἑνὸς ὄντος ἢ δυεῖν, τούτων τὸν μὲν πόλεμος, τὸν δὲ νόσος ἐνστᾶσα παρείλετο, δῆλον ὡς ἀνάγκη καταλείπεσθαι τὰς οἰκήσεις ἐρήμους, καὶ καθάπερ ἐπὶ τῶν μελιττῶν τὰ σμήνη, τὸν αὐτὸν τρόπον κατὰ βραχὺ καὶ τὰς πόλεις ἀπορουμένας ἀδυνατεῖν. ὑπὲρ ὧν οὐδὲ χρεία παρὰ τῶν θεῶν πυνθάνεσθαι πῶς ἂν ἀπολυθείημεν τῆς τοιαύτης βλάβης· ὁ γὰρ τυχὼν τῶν ἀνθρώπων ἐρεῖ διότι μάλιστα μὲν αὐτοὶ δι’ αὑτῶν, μεταθέμενοι τὸν ζῆλον, εἰ δὲ μή, νόμους γράψαντες, ἵνα τρέφηται τὰ γινόμενα. περὶ τούτων οὔτε μάντεων οὔτε τερατειῶν χρεία. ὁ δ’ αὐτὸς λόγος καὶ περὶ τῶν κατὰ μέρος. ἀλλ’ ἐπ’ ἐκείνων ἐφ’ ὧν ἀλήπτους ἢ δυσλήπτους εἶναι τὰς αἰτίας συμβαίνει, διαπορητέον· ὧν ἓν ἦν καὶ τὸ περὶ Μακεδόνας γεγενημένον. Μακεδόνες μὲν γὰρ ὑπὸ Ῥωμαίων πολλῶν καὶ μεγάλων ἐτετεύχεισαν φιλανθρωπιῶν, κοινῇ μὲν πάντες ἀπολυθέντες μοναρχικῶν ἐπιταγμάτων καὶ φόρων καὶ μεταλαβόντες ἀπὸ δουλείας ὁμολογουμένως ἐλευθερίαν, ἰδίᾳ δὲ πάλιν κατὰ πόλεις ἐκλυθέντες ἐκ μεγάλων στάσεων καὶ φόνων ἐμφυλίων διὰ τῆς Ῥωμαίων … φιλοτιμίας· … ἅμα δυσμενείας μὲν ἢ βλάβης τῆς ἐν τοῖς πρότερον καιροῖς πρὸς Ῥωμαίους ἔτι γεύ … φιλ … πόλεως· ὑπὸ δὲ τοῦ Ψευδοφιλίππου πρῶτον μὲν πρ … εξετοι διῄτ … πολλοὺς μὲν ἀν … φρ … πλείστους ἐπεῖδον αὐτῶν ἐν πάνυ βραχεῖ χρόνῳ φυγαδευθέντας καὶ στρεβλωθέντας καὶ φονευθέντας ἢ τῶν ἐν τοῖς πρότερον καιροῖς ὑπὸ τῶν κατ’ ἀλήθειαν βασι … ἤδη τοῦτο γε εχ … ῶς απαντεσι ἐπὶ το … εἴ … αι τῶν ἐξ ἀρχῆς βασιλέων, ὡς … ὑβρίζ … καὶ … πλείστοις εμος τῶν βρ … καὶ … Ῥωμαίων στρατοπεδεύματος ἐξ αὐτῆς μεταμέλοι· ἐν ἀδικ … τῶν πρὸ τοῦ Ψευδοφιλίππου μὲν εἰς αὐτοὺς παρανομημάτων· οἱ δὲ τὸ … … πολλῶν τε μετὰ μὲν τοῦ Δημητρίου καὶ πάλιν μετὰ Περσέως μαχόμενοι πρὸς Ῥωμαίους ἡττήθησαν, ἀνδρὶ δὲ στυγνῷ συναγωνιζόμενοι καὶ περὶ τῆς τούτου βασιλείας ἀνδραγαθήσαντες ἐνίκησαν Ῥωμαίους. ἐξ ὧν τίς οὐκ ἂν ἐπαπορήσειεν ἐπὶ τῷ συμβάντι; τὴν γὰρ αἰτίαν εὑρεῖν τούτων δυσχερές. διόπερ ἄν τις ἐπὶ τῶν τοιούτων διαθέσεων δαιμονοβλάβειαν εἴπειε τὸ γεγονὸς καὶ μῆνιν ἐκ θεῶν ἅπασι Μακεδόσιν ἀπηντῆσθαι. δῆλον δ’ ἔστιν ἐκ τῶν λέγεσθαι μελλόντων.", "st": "37.9"}, {"sp": "N", "t": "ὅτι Μασανάσσης ὁ ἐν Λιβύῃ τῶν Νομάδων βασιλεὺς ἀνὴρ ἦν τῶν καθ’ ἡμᾶς βασιλέων ἄριστος καὶ μακαριώτατος, ὃς ἐβασίλευσεν ἔτη πλείω τῶν ἑξήκονθ’, ὑγιεινότατος ὢν καὶ πολυχρονιώτατος· ἐνενήκοντα γὰρ ἐτῶν ἐγεγόνει. ἐγένετο δὲ καὶ δυναμικώτατος τῶν καθ’ αὑτὸν κατὰ τὴν σωματικὴν ἕξιν, ὅς, ὅτε μὲν στῆναι δέοι, στὰς ἐν τοῖς αὐτοῖς ἴχνεσι δι’ ἡμέρας ἔμενε, καθεζόμενος δὲ πάλιν οὐκ ἠγείρετο. καὶ τὴν ἐπὶ τῶν ἱππικῶν κακοπάθειαν ἡμέραν καὶ νύκτα συνεχῶς διακαρτερῶν οὐδὲν ἔπασχεν. σημεῖον δὲ τῆς σωματικῆς αὐτοῦ δυνάμεως· ἔχων ἐνενήκοντ’ ἔτη, καθ’ ὃν καιρὸν μετήλλαξε τὸν βίον, υἱὸν ἀπέλειπε τεττάρων ἐτῶν, ὄνομα Σθέμβανον, ὃν μετὰ ταῦτα Μικίψης υἱοποιήσατο, πρὸς δὲ τούτοις υἱοὺς ἐννέα. διὰ δὲ τὴν πρὸς ἀλλήλους τούτων εὔνοιαν διετήρησε τὸν ὅλον βίον πάσης ἐπιβουλῆς καὶ παντὸς οἰκείου μιάσματος ἄμοιρον αὑτοῦ γενέσθαι τὴν βασιλείαν. τὸ δὲ μέγιστον καὶ θειότατον τούτου· τῆς γὰρ Νομαδίας ἁπάσης ἀχρήστου τὸν πρὸ τοῦ χρόνον ὑπαρχούσης καὶ νομιζομένης ἀδυνάτου τῇ φύσει πρὸς ἡμέρους καρποὺς ὑπάρχειν, πρῶτος καὶ μόνος ὑπέδειξε διότι δύναται πάντας ἐκφέρειν τοὺς ἡμέρους καρποὺς οὐδ’ ὁποίας ἧττον, ἑκάστῳ τῶν υἱῶν ἐν διαστάσει μυριοπλέθρους ἀγροὺς κατασκευάσας παμφόρους. τῇ μὲν οὖν ἐκείνου μεταστάσει ταῦτ’ ἄν τις εὐλόγως ἐπιφθέγξαιτο καὶ δικαίως. ὁ δὲ Σκιπίων παραγενόμενος εἰς τὴν Κίρταν ἡμέρᾳ τρίτῃ μετὰ τὸν τοῦ βασιλέως θάνατον διῴκησε καλῶς πάντα. — Μασανάσσην δ’ ἱστορεῖ Πολύβιος ἐνενήκοντα μὲν ἐτῶν ἀποθανεῖν, τετράετες καταλιπόντα παιδάριον ἐξ αὐτοῦ γεγενημένον· ὀλίγῳ δ’ ἔμπροσθεν τῆς τελευτῆς μάχῃ νικήσαντα μεγάλῃ Καρχηδονίους ὀφθῆναι τῇ ὑστεραίᾳ πρὸ τῆς σκηνῆς ῥυπαρὸν ἄρτον ἐσθίοντα καὶ πρὸς τοὺς θαυμάζοντας εἰπεῖν ὅτι τοῦτο ποιεῖ", "st": "37.10"}, {"sp": "HDR", "t": "Βιβλίον ΛΗʹ", "st": "38"}, {"sp": "N", "t": "ὅτι Ἀσδρούβας ὁ στρατηγὸς Καρχηδονίων κενόδοξος ἦν ἀλαζὼν καὶ πολὺ κεχωρισμένος τῆς πραγματικῆς καὶ στρατηγικῆς δυνάμεως. πολλὰ δὲ σημεῖα τῆς ἀκρισίας αὐτοῦ. πρῶτον μὲν γὰρ παρῆν ἐν πανοπλίᾳ, πορφυρίδα θαλαττίαν ἐπιπεπορπημένος, ἡνίκα Γολόσσῃ συνεγίνετο τῷ τῶν Νομάδων βασιλεῖ, μετὰ μαχαιροφόρων δέκα. ἔπειτα προβὰς ἀπὸ τῶν δέχ’ ὅσον εἴκοσι πόδας ἀπέστη, προβεβλημένος τάφρον καὶ χάρακα, καὶ κατένευε τῷ βασιλεῖ προσιέναι πρὸς αὑτόν, καθῆκον γίνεσθαι τοὐναντίον. οὐ μὴν ἀλλ’ ὁ Γολόσσης ἀφελῶς ἔχων Νομαδικῷ τινι τρόπῳ μόνος προσῄει πρὸς αὐτόν· καὶ προσεγγίσας ἤρετο τίνα φοβούμενος τὴν πανοπλίαν ἔχων ἧκε. τοῦ δ’ εἰπόντος ὅτι Ῥωμαίους, \"οὐκ ἂν ἄρ’\" ἔφησεν ὁ Γολόσσης \"ἔδωκας σαυτὸν εἰς τὴν πόλιν, μηδεμίαν ἔχων ἀνάγκην. πλὴν τί βούλει καὶ τί παρακαλεῖς;\" φησίν. ὁ δ’ Ἀσδρούβας \" ἐγώ\" φησὶ \"πρεσβευτήν σε παρακαλῶ γενέσθαι πρὸς τὸν στρατηγὸν καὶ πᾶν ἀναδέχεσθαι διότι ποιήσομεν τὸ προσταττόμενον· μόνον ἀπόσχεσθε τῆς ταλαιπώρου πόλεως ταύτης. \" καὶ [ὁ] Γολόσσης \"παιδικὴν δοκεῖς μοι\" φησὶν \"ἀξίωσιν ἀξιοῦν, ὦ βέλτιστε· ὑπὲρ ὧν γὰρ ἐξ ἀκεραίου πρεσβεύοντες, ἔτι καθημένων ἐν Ἰτύκῃ Ῥωμαίων, οὐκ ἐδύνασθε πείθειν, τίνι λόγῳ νῦν ἀξιοῖς ταῦτά σοι συγχωρεῖσθαι, περιτετειχισμένος καὶ κατὰ γῆν καὶ κατὰ θάλατταν καὶ σχεδὸν ἁπάσας ἀπεγνωκὼς τὰς τῆς σωτηρίας ἐλπίδας; \" ὁ δ’ Ἀσδρούβας ἀγνοεῖν αὐτὸν ἔφη· καὶ γὰρ ἐπὶ τοῖς ἔξωθεν συμμάχοις ἀκμὴν καλὰς ἐλπίδας ἔχειν· οὐ γάρ πω τὰ περὶ τοὺς Μαυρουσίους ἠκηκόει καὶ τὰ περὶ τῶν ὑπαίθρων δυνάμεων [ὅτι σώζονται]· καὶ μὴν οὐκ ἀπελπίζειν τὰ καθ’ αὑτούς· μάλιστα δὲ πεποιθέναι τῇ τῶν θεῶν συμμαχίᾳ καὶ ταῖς ἐν ἐκείνοις ἐλπίσιν· οὐ γὰρ περιόψεσθαι σφᾶς προφανῶς παρασπονδουμένους, ἀλλὰ πολλὰς δώσειν ἀφορμὰς πρὸς σωτηρίαν. διὸ παρακαλεῖν ἠξίου τὸν στρατηγὸν καὶ τῶν θεῶν ἕνεκεν καὶ τῆς τύχης φείσασθαι τῆς πόλεως, εἰδότα σαφῶς διότι μὴ δυνάμενοι τυχεῖν τούτου κατασφαγήσονται πρότερον ἢ παραχωρήσουσι ταύτης. τότε μὲν οὖν ταῦτα καὶ παραπλήσια διαλεχθέντες ἐχωρίσθησαν, ταξάμενοι μετὰ τρίτην ἡμέραν πάλιν συμπορεύεσθαι·", "st": "38.1"}, {"sp": "N", "t": "τοῦ δὲ Γολόσσου μεταδόντος τῷ στρατηγῷ περὶ τῶν εἰρημένων, γελάσας ὁ Πόπλιος \"ταῦτα μέλλων ἀξιοῦν\" ἔφη \"τοιαύτην καὶ τηλικαύτην ἀσέβειαν εἰς τοὺς αἰχμαλώτους ἡμῶν ἐναπεδείξω καὶ νῦν ἐπὶ τοῖς θεοῖς τὰς ἐλπίδας ἔχεις, παραβεβηκὼς καὶ τοὺς τῶν ἀνθρώπων νόμους; \" τοῦ δὲ βασιλέως βουλομένου τι προσυπομιμνήσκειν τὸν Σκιπίωνα, καὶ μάλιστα διότι δεῖ συντέλειαν ἐπιτίθεσθαι τοῖς πράγμασι· χωρὶς γὰρ τῶν ἀδήλων καὶ τὴν κατάστασιν τῶν ὑπάτων ἤδη συνεγγίζειν, ἧς δεῖν ἔφη στοχάζεσθαι, μὴ τοῦ χειμῶνος προκαταλαβόντος ἐπελθὼν ἕτερος ἀκονιτὶ λάβῃ τὴν ἐπιγραφὴν τῶν ἐκείνου πόνων· καὶ δὴ τούτων λεγομένων ἐπιστήσας ὁ στρατηγὸς ἐκέλευσεν ἀναγγέλλειν διότι δίδωσι τὴν ἀσφάλειαν αὐτῷ καὶ γυναικὶ καὶ τέκνοις καὶ δέκα τῶν συγγενῶν καὶ φίλων οἰκίαις, σὺν δὲ τούτοις δέκα τάλαντα λαβεῖν ἐκ τῶν ἰδίων ὑπαρχόντων καὶ τῶν οἰκετῶν ἐξαγαγεῖν ἑκατὸν οὓς ἂν αἱρῆται. ταῦτα μὲν οὖν ὁ Γολόσσης ἔχων τὰ φιλάνθρωπα συνῄει πρὸς τὸν Ἀσδρούβαν τῇ τρίτῃ τῶν ἡμερῶν· ὁ δὲ πάλιν ἐξεπορεύετο μετὰ μεγάλης ἀξίας ἐν τῇ πορφυρίδι καὶ τῇ πανοπλίᾳ βάδην, ὥστε τοὺς ἐν ταῖς τραγῳδίαις τυράννους πολύ τι προσοφείλειν. ἦν μὲν οὖν καὶ φύσει σάρκινος, τότε δὲ καὶ κοιλίαν εἰλήφει καὶ τῷ χρώματι παρὰ φύσιν ἐπικεκαυμένος ἦν, ὥστε δοκεῖν ἐν πανηγύρει που διαιτᾶσθαι παραπλησίως τοῖς σιτευτοῖς βουσίν, ἀλλὰ μὴ τηλικούτων καὶ τοιούτων κακῶν προστατεῖν, ὧν οὐδ’ ἂν ἐφίκοιτο τῷ λόγῳ διεξιὼν οὐδείς. οὐ μὴν ἀλλ’ ἐπεὶ συνῆλθε τῷ βασιλεῖ καὶ διήκουσε τῶν ὑπὸ τοῦ στρατηγοῦ προτεινομένων, πολλάκις τὸν μηρὸν πατάξας, τοὺς θεοὺς καὶ τὴν τύχην ἐπικαλεσάμενος, οὐδέποτε ταύτην ἔσεσθαι τὴν ἡμέραν ἔφασκεν ἐν ᾗ συμβήσεται τὸν ἥλιον Ἀσδρούβαν βλέπειν ἅμα καὶ τὴν πατρίδα πυρπολουμένην· καλὸν γὰρ ἐντάφιον εἶναι τοῖς εὖ φρονοῦσι τὴν πατρίδα καὶ τὸ ταύτης πῦρ. ὥσθ’ ὅτε μὲν εἰς τὰς ἀποφάσεις αὐτοῦ τις βλέψειε, θαυμάζειν τὸν ἄνδρα καὶ τὸ μεγαλόψυχον τῶν λόγων, ὅτε δ’ εἰς τὸν χειρισμὸν τῶν πραγμάτων, τὴν ἀγεννίαν καταπλήττεσθαι καὶ τὴν ἀνανδρίαν· ὃς πρῶτον μέν, τῶν ἄλλων πολιτῶν διαφθειρομένων ὁλοσχερῶς ὑπὸ τοῦ λιμοῦ, πότους αὐτὸς συνῆγε καὶ δευτέρας τραπέζας παρετίθετο πολυτελεῖς καὶ διὰ τῆς ἰδίας εὐεξίας παρεδειγμάτιζε τὴν ἐκείνων ἀτυχίαν· ἄπιστον μὲν γὰρ ἦν τὸ τῶν ἀποθνησκόντων πλῆθος, ἄπιστον δὲ τὸ τῶν αὐτομολούντων καθ’ ἡμέραν διὰ τὸν λιμόν· ἔπειτα τοὺς μὲν διαχλευάζων, οἷς δ’ ἐνυβρίζων καὶ φονεύων κατεπλήττετο τοὺς πολλοὺς καὶ τούτῳ τῷ τρόπῳ συνεῖχε τὴν ἐξουσίαν, ᾗ μόλις ἂν χρήσαιτο τύραννος ἐν εὐτυχούσῃ πόλει, καὶ ἐν δεδυστυχηκυίᾳ πατρίδι. διὸ καὶ λίαν δοκῶ καλῶς ἡμῖν εἰρῆσθαι διότι προστάτας πραγμάτων ὁμοιοτέρους τῶν παρὰ τοῖς Ἕλλησι τότε καὶ παρὰ τοῖς Καρχηδονίοις ὑπαρξάντων οὐκ ἂν εὕροι τις ῥᾳδίως. τοῦτο δ’ ἔσται δῆλον, ὅταν ἐκ παραθέσεως τὸν ὑπὲρ ἐκείνων ποιησώμεθα λόγον.", "st": "38.2"}, {"sp": "N", "t": "ὅτι ἡ ληʹ βίβλος περιέχει τὴν συντέλειαν τῆς τῶν Ἑλλήνων ἀτυχίας. καίπερ γὰρ τῆς Ἑλλάδος καὶ καθόλου καὶ κατὰ μέρος πλεονάκις ἐπταικυίας, ὅμως οὐδ’ ὁποίοις ἄν τις τῶν πρότερον ἐλαττωμάτων οἰκειότερον ἐφαρμόσαι τὸ τῆς ἀτυχίας ὄνομα καὶ τὴν ἔννοιαν ταύτην ὡς τοῖς καθ’ ἡμᾶς γεγονόσιν. οὐ γὰρ μόνον ἀφ’ ὧν ἔπαθον ἐλεήσαι τις ἂν τοὺς Ἕλληνας, ἔτι δὲ μᾶλλον ἐφ’ οἷς ἔπραξαν ἠτυχηκέναι νομίσειε, πυθόμενος περὶ ἑκάστων τὰς ἀληθείας. δοκοῦντος γοῦν μεγίστου πάθους γεγονέναι τοῦ περὶ τοὺς Καρχηδονίους οὐκ ἔλαττον ἄν τις ἡγήσαιτο, κατὰ δέ τι μεῖζον τὸ περὶ τὴν Ἑλλάδα τότε συμβάν. οἱ μὲν γὰρ τόπον ἔσχατον ἀπολογίας γε πρὸς τοὺς ἐπιγινομένους περὶ σφῶν ἀπέλειπον, οὗτοι δ’ οὐδ’ ἀφορμὴν εὔλογον ἔδοσαν τοῖς βουλομένοις σφίσι βοηθεῖν ὑπὲρ τῶν ἡμαρτημένων. καὶ Καρχηδόνιοι μὲν ἅμα ταῖς περιπετείαις ἄρδην ἀφανισθέντες ἀνεπαίσθητοι τῶν σφετέρων εἰς τὸ μέλλον ἐγένοντο συμπτωμάτων, οἱ δ’ Ἕλληνες ἐφορῶντες τὰς αὑτῶν ἀτυχίας παισὶ παίδων παραδόσιμον ἐποίησαν τὴν ἀκληρίαν. ὥστε καθ’ ὅσον τοὺς ζῶντας μετὰ τιμωρίας ἐλεεινοτέρους νομίζομεν τῶν ἐν αὐτοῖς τοῖς δεινοῖς ἐκλειπόντων τὸν βίον, κατὰ τοσοῦτο καὶ τὰς τότε περιπετείας τῶν Ἑλλήνων ἐλεεινοτέρας νομιστέον τῶν συμβάντων Καρχηδονίοις, ἐὰν μή τις ἀφροντιστῶν τοῦ καθήκοντος καὶ τοῦ καλοῦ, πρὸς αὐτὸ δὲ τὸ συμφέρον ἀποβλέπων ποιῆται τὴν ἀπόφασιν. ὅτι δ’ ἔστι τὸ νῦν εἰρημένον ὑφ’ ἡμῶν ἀληθές, εἴποι τις ἂν ὑπομνησθεὶς καὶ παραθεὶς τὰς δοκούσας μεγίστας συμφορὰς γεγονέναι κατὰ τὴν Ἑλλάδα πρὸς τὰ νῦν ὑφ’ ἡμῶν λεγόμενα.", "st": "38.3"}, {"sp": "N", "t": "μέγιστον ἡ τύχη δοκεῖ φόβον ἐπιστῆσαι τοῖς Ἕλλησι κατὰ τὴν Ξέρξου διάβασιν εἰς τὴν Εὐρώπην· τότε γὰρ ἐκινδύνευσαν μὲν πάντες, ἔπταισαν δὲ τελέως ὀλίγιστοι, μάλιστα δὲ τούτων Ἀθηναῖοι· προϊδόμενοι γὰρ ἐμφρόνως τὸ μέλλον ἐξέλιπον τὴν πατρίδα μετὰ τέκνων καὶ γυναικῶν. βλάβην μὲν οὖν ὁ καιρὸς αὐτοῖς ἐπήνεγκε· κύριοι γὰρ γενηθέντες οἱ βάρβαροι πικρῶς διέφθειραν τὰς Ἀθήνας· οὐ μὴν ὄνειδος οὐδ’ αἰσχύνην, τὸ δ’ ἐναντίον εὔκλειαν παρὰ πᾶσι τοῖς ἀνθρώποις τὴν μεγίστην ἀπηνέγκαντο διότι πάντ’ ἐν ἐλάττονι θέμενοι τῆς αὐτῆς τύχης εἵλαντο κοινωνεῖν τοῖς ἄλλοις Ἕλλησι. τοιγαροῦν καλῇ χρησάμενοι προαιρέσει, παρὰ πόδας οὐ μόνον ἀνεκτήσαντο τὴν πατρίδα καὶ τὴν ἑαυτῶν χώραν, ἀλλὰ καὶ περὶ τῆς τῶν ἄλλων Ἑλλήνων ἡγεμονίας μετ’ ὀλίγον ἠμφισβήτουν πρὸς Λακεδαιμονίους. μετὰ δὲ ταῦτα πάλιν ὑπὸ Σπαρτιατῶν καταπολεμηθέντες εἰς τοῦτ’ ἀνάγκης ἦλθον ὥστε καθελεῖν τὰ τείχη τῆς αὑτῶν πατρίδος. ἀλλὰ καὶ τοῦτο Λακεδαιμονίων, οὐκ Ἀθηναίων ἄν τις εἶναι φήσειε τοὔγκλημα, διότι βαρύτερον ἐχρήσαντο τῇ δοθείσῃ σφίσι παρὰ τῆς τύχης ἐξουσίᾳ. Σπαρτιᾶται δ’ ἡττηθέντες ὑπὸ Θηβαίων πάλιν ἀπέβαλον τὴν τῶν Ἑλλήνων ἡγεμονίαν καὶ μετὰ ταῦτα τῆς τῶν ἐκτὸς ἀρχῆς ἀποστάντες συνεκλείσθησαν εἰς τοὺς τῆς Λακωνικῆς ὅρους. καὶ τί δὴ τοῦτ’ αἰσχρόν, εἰ περὶ τῶν καλλίστων ἀμφισβητοῦντες ἐπὶ τοσοῦτον ἔπταισαν ὥστε πάλιν ἐπὶ τὴν πάτριον ἀναχωρῆσαι δυναστείαν; διὸ τὰ γεγονότα ταῦτα συμπτώματα μὲν εἶναι φατέον, ἀτυχήματα δ’ οὐδαμῶς ῥητέον. Μαντινεῖς ἠναγκάσθησαν ἐκλιπεῖν τὴν πατρίδα διοικισθέντες ὑπὸ Λακεδαιμονίων καὶ διασπασθέντες οἰκῆσαι κατὰ κώμας· ἀλλὰ πάντες ἐπὶ τούτοις οὐ τὴν τῶν Μαντινέων ἀβουλίαν, ἀλλὰ τὴν Λακεδαιμονίων ὠνείδιζον. Θηβαῖοι μετά τινα χρόνον ἄρδην ἐπεῖδον τὴν αὑτῶν πατρίδα γενομένην ἀνάστατον, ὅτε προθέμενος Ἀλέξανδρος εἰς τὴν Ἀσίαν διαβαίνειν ὑπέλαβε διὰ τῆς εἰς Θηβαίους τιμωρίας τῷ φόβῳ φρουρήσειν τοὺς Ἕλληνας κατὰ τοὺς ἰδίους περισπασμούς· ἀλλὰ τότε πάντες ἠλέουν μὲν τοὺς Θηβαίους ὡς ἄδικα καὶ δεινὰ πεπονθότας, διεδικαίου δὲ τὴν πρᾶξιν ταύτην οὐδεὶς Ἀλεξάνδρου.", "st": "38.4"}, {"sp": "N", "t": "τοιγαροῦν βραχεῖ χρόνῳ τυχόντες ἐπικουρίας τινὸς αὖθις ᾤκουν τὴν πατρίδα μετ’ ἀσφαλείας. ὁ γὰρ παρὰ τῶν ἐκτὸς ἔλεος οὐ μικρὸν ἐπίχειρόν ἐστι τοῖς ἀδίκως ἀκληροῦσιν, εἴ γε πολλάκις ἰδεῖν ἔστιν ἅμα ταῖς τῶν πολλῶν ὁρμαῖς καὶ τὴν τύχην μεταβαλλομένην καὶ τοὺς κρατοῦντας αὐτοὺς μεταμελομένους καὶ διορθουμένους τὰς τῶν παραλόγως ἠτυχηκότων περιπετείας. πάλιν ἐπείθοντο κατά τινας καιροὺς Χαλκιδεῖς καὶ Κορίνθιοι καί τινες ἕτεραι πόλεις διὰ τὴν τῶν τόπων εὐφυΐαν τοῖς ἐν Μακεδονίᾳ βασιλεῦσι καὶ φρουρὰς εἶχον· ἀλλὰ τοὺς μὲν δουλεύοντας πάντες ἐσπούδαζον κατὰ δύναμιν ἐλευθεροῦν, τοὺς δὲ καταδουλωσαμένους ἐμίσουν καὶ πολεμίους ἡγοῦντο διὰ τέλους. καθόλου δὲ κατὰ πόλεις ἔπταιον καὶ κατὰ πόλιν ἐσφάλλοντο τὸν πρὸ τοῦ χρόνον ὡς ἐπίπαν, οἱ μὲν ὑπὲρ ἡγεμονίας καὶ πραγμάτων ἀμφισβητοῦντες, οἱ δ’ ὑπὸ μονάρχων καὶ βασιλέων παρασπονδούμενοι· διὸ καὶ σπανίους ἂν εὕροις οἷς ὄνειδος ἠκολούθει τῶν ἀκληρούντων ἢ καὶ τὸ τῆς ἀτυχίας ὄνομα διέμενεν· ἀκληρεῖν μὲν γὰρ ἅπαντας ἡγητέον καὶ κοινῇ καὶ κατ’ ἰδίαν τοὺς παραλόγοις συμφοραῖς περιπίπτοντας, ἀτυχεῖν δὲ μόνους τούτους οἷς διὰ τὴν ἰδίαν ἀβουλίαν ὄνειδος αἱ πράξεις ἐπιφέρουσι. κατὰ δὲ τοὺς ὑποκειμένους καιροὺς ἠτύχησαν ἅμα Πελοποννήσιοι, Βοιωτοί, Φωκεῖς, … εῖς, Λοκροί, τινὲς τῶν τὸν Ἰόνιον κατοικούντων κόλπον, μετὰ δὲ τούτους ἔτι Μακεδόνες· … μὴ μόνον κατὰ τὸ πλῆθος … τῶν πρότερον, ἀλλὰ καὶ κατὰ … ἐπίπαν οὐκ ἠκλήρησαν, ἀλλ’ ἠτύχησαν ἀτυχίαν αἰσχρὰν ὡς ἔνι μάλιστα καὶ ἐπονείδιστον· ἅμα μὲν γὰρ ἀπιστίαν, ἅμα δ’ ἀνανδρίαν ἔδειξαν, καὶ πράξεις αὐτοῖς ἐπήνεγκαν διὰ τὴν ἀτ. … ἅμα. τοιγαροῦν στερηθέντες πάντων τῶν καλῶν οἱ μὲν ὑπὸ στέ …, ἔνιοι δὲ καὶ δ … ντες εἰς τὰς πόλεις τότε παρεδέξαντο ῥάβδους καὶ πελέκεις ἐθελο …· ἐν μεγάλῳ γὰρ φόβῳ διὰ τὴν ὑπερβολὴν τῶν ἰδίων ἁμαρτημάτων ἦσαν, εἰ χρ ὴ λέγειν ἰδίων· ἐγὼ γὰρ ἠγνοηκέναι μὲν φαίην ἂν τοὺς πολλοὺς καὶ παραπεπαικέναι τοῦ καθήκοντος, ἡμαρτηκέναι δὲ τοὺς αἰτίους γεγονότας τῆς ἐπὶ τοσοῦτον ἀγνοίας.", "st": "38.5"}, {"sp": "N", "t": "ὑπὲρ ὧν οὐ δεήσει θαυμάζειν ἐὰν παρεκβαίνοντες τὸ τῆς ἱστορικῆς διηγήσεως ἦθος ἐπιδεικτικωτέραν καὶ φιλοτιμοτέραν φαινώμεθα ποιούμενοι περὶ αὐτῶν τὴν ἀπαγγελίαν. καίτοι τινὲς ἴσως ἐπιτιμήσουσιν ἡμῖν ὡς φιλαπεχθῶς ποιουμένοις τὴν γραφήν, οἷς καθῆκον ἦν μάλιστα πάντων περιστέλλειν τὰς τῶν Ἑλλήνων ἁμαρτίας. ἐγὼ δ’ οὔτε φίλον οὐδέποτ’ ἂν ὑπολαμβάνω γνήσιον νομισθῆναι παρὰ τοῖς ὀρθῶς φρονοῦσι τὸν δεδιότα καὶ φοβούμενον τοὺς μετὰ παρρησίας λόγους, καὶ μὴν οὐδὲ πολίτην ἀγαθὸν τὸν ἐγκαταλείποντα τὴν ἀλήθειαν διὰ τὴν ἐσομένην ὑπ’ ἐνίων προσκοπὴν παρ’ αὐτὸν τὸν καιρόν· συγγραφέα δὲ κοινῶν πράξεων οὐδ’ ὅλως ἀποδεκτέον τὸν ἄλλο τι περὶ πλείονος ποιούμενον τῆς ἀληθείας. ὅσῳ γὰρ εἰς πλείους διατείνει καὶ ἐπὶ πλείω χρόνον ἡ διὰ τῶν ὑπομνημάτων παράδοσις τῶν πρὸς καιρὸν λεγομένων, τοσούτῳ χρὴ μᾶλλον καὶ τὸν γράφοντα περὶ πλείστου ποιεῖσθαι τὴν ἀλήθειαν καὶ τοὺς ἀκούοντας ἀποδέχεσθαι τὴν τοιαύτην αἵρεσιν. κατὰ μὲν γὰρ τοὺς τῶν περιστάσεων καιροὺς καθήκει βοηθεῖν τοὺς Ἕλληνας ὄντας τοῖς Ἕλλησι κατὰ πάντα τρόπον, τὰ μὲν ἀμύνοντας, τὰ δὲ περιστέλλοντας, τὰ δὲ παραιτουμένους τὴν τῶν κρατούντων ὀργήν· ὅπερ ἡμεῖς ἐπ’ αὐτῶν τῶν πραγμάτων ἐποιήσαμεν ἀληθινῶς· τὴν δ’ ὑπὲρ τῶν γεγονότων τοῖς ἐπιγινομένοις διὰ τῶν ὑπομνημάτων παράδοσιν ἀμιγῆ παντὸς ψεύδους ἀπολείπεσθαι χάριν τοῦ μὴ ταῖς ἀκοαῖς τέρπεσθαι κατὰ τὸ παρὸν τοὺς ἀναγινώσκοντας, ἀλλὰ ταῖς ψυχαῖς διορθοῦσθαι πρὸς τὸ μὴ πλεονάκις ἐν τοῖς αὐτοῖς διασφάλλεσθαι. καὶ περὶ μὲν τούτων ἐπὶ τοσοῦτον ἡμῖν εἰρήσθω.", "st": "38.6"}, {"sp": "N", "t": "ὅτι παραγενομένων ἐκ Πελοποννήσου τῶν περὶ τὸν Αὐρήλιον πρεσβευτῶν καὶ διασαφούντων τὰ συμβεβηκότα περὶ αὐτούς, ὅτι παρ’ ὀλίγον τοῖς ὅλοις ἐκινδύνευσαν, καὶ λεγόντων μετ’ αὐξήσεως καὶ καινολογίας· οὐ γὰρ ὡς κατὰ περιπέτειαν ἐπ’ αὐτοὺς ἥκοντος τοῦ δεινοῦ διεσάφουν, ἀλλ’ ὡς κατὰ πρόθεσιν ὡρμηκότων τῶν Ἀχαιῶν ἐπὶ τὸ παραδειγματίζειν αὐτούς· ἡ σύγκλητος ἠγανάκτησεν μὲν ἐπὶ τοῖς γεγονόσιν ὡς οὐδέποτε καὶ παραχρῆμα πρεσβευτὰς κατεστήσατο τοὺς περὶ τὸν Ἰούλιον, καὶ τούτους ἔπεμπε δοῦσα τοιαύτας ἐντολάς, διότι δεῖ μετρίως ἐπιτιμήσαντας καὶ μεμψαμένους ἐπὶ τοῖς γεγονόσι τὸ πλεῖον παρακαλεῖν καὶ διδάσκειν τοὺς Ἀχαιοὺς μήτε τοῖς ἐπὶ τὰ χείριστα παρακαλοῦσι προσέχειν μήτ’ αὐτοὺς λαθεῖν εἰς τὴν πρὸς Ῥωμαίους ἀλλοτριότητα διεμπεσόντας, ἀλλ’ ἔτι καὶ νῦν ποιήσασθαί τινα διόρθωσιν τῶν ἠγνοημένων, ἀπερεισαμένους τὴν ἄγνοιαν ἐπὶ τοὺς αἰτίους τῆς ἁμαρτίας. ἐξ ὧν καὶ λίαν δῆλον ἐγένετο διότι καὶ τοῖς περὶ τὸν Αὐρήλιον ἔδωκε τὰς ἐντολὰς οὐ διασπάσαι βουλομένη τὸ ἔθνος, ἀλλὰ πτοῆσαι καὶ καταπλήξασθαι [βουλομένη] τὴν αὐθάδειαν καὶ τὴν ἀπέχθειαν τῶν Ἀχαιῶν. τινὲς μὲν οὖν ὑπελάμβανον καθ’ ὑπόκρισιν τοὺς Ῥωμαίους διὰ τὸ μένειν ἀτελῆ τὰ κατὰ Καρχηδόνα· τὸ δ’ ἀληθὲς οὐχ οὕτως εἶχεν, ἀλλ’ ἀποδεδεγμένοι τὸ ἔθνος ἐκ πολλοῦ χρόνου καὶ νομίζοντες ἔχειν αὐτὸ πιστὸν μάλιστα τῶν Ἑλληνικῶν, ἀνασοβῆσαι μὲν ἔκριναν διὰ τὸ φρονηματίζεσθαι πέρα τοῦ δέοντος, πόλεμον δ’ ἀναλαβεῖν ἢ διαφορὰν ὁλοσχερῆ πρὸς τοὺς Ἀχαιοὺς οὐδαμῶς ἐβούλοντο. —", "st": "38.7"}, {"sp": "N", "t": "ὅτι οἱ περὶ τὸν Σέξτον προάγοντες ἐκ τῆς Ῥώμης εἰς τὴν Πελοπόννησον ἀπήντησαν τοῖς περὶ τὸν Θεαρίδαν, οἵπερ ἦσαν πρεσβευταὶ πεμφθέντες ὑπὸ τῶν Ἀχαιῶν παραιτησόμενοι καὶ διδάξοντες τὴν σύγκλητον ὑπὲρ τῶν εἰς τοὺς περὶ τὸν Αὐρήλιον γενομένων ἀλογημάτων. οἷς καὶ συμμίξαντες οἱ προειρημένοι παρεκάλεσαν αὐτοὺς ἀνακάμπτειν εἰς τὴν Ἀχαΐαν, ὅτι περὶ πάντων τούτων ἔχουσιν ἐντολὰς αὐτοὶ διαλέγεσθαι τοῖς Ἀχαιοῖς. παραγενομένων δὲ τῶν περὶ τὸν Σέξτον εἰς τὴν Πελοπόννησον καὶ διαλεγομένων τοῖς Ἀχαιοῖς ἐν τῇ τῶν Αἰγιέων πόλει καὶ προφερομένων πολλοὺς καὶ φιλανθρώπους λόγους, καὶ τὸ περὶ τοὺς πρεσβευτὰς ἔγκλημα παραπεμπόντων καὶ σχεδὸν οὐδὲν προσδεόμενον δικαιολογίας, ἀλλὰ βέλτιον ἐκδεχομένων τὸ γεγονὸς αὐτῶν τῶν Ἀχαιῶν, καθόλου δὲ παρακαλούντων μὴ πορρωτέρω προβῆναι τῆς ἁμαρτίας μήτε τῆς εἰς αὑτοὺς μήτε τῆς εἰς τοὺς Λακεδαιμονίους, τὸ μὲν σωφρονοῦν μέρος ἀσμένως ἀπεδέχετο τὰ λεγόμενα καὶ λίαν ἐνετρέπετο, συνειδὸς αὑτῷ τὰ πεπραγμένα καὶ πρὸ ὀφθαλμῶν λαμβάνον τὰ συμβαίνοντα τοῖς πρὸς Ῥωμαίους ἀντιταττομένοις, τὸ δὲ πλῆθος τῶν ἀνθρώπων ἀντιλέγειν μὲν οὐδὲν εἶχε τοῖς ὑπὸ τῶν περὶ τὸν Σέξτον λεγομένοις δικαίοις, ἀλλ’ ἦγε τὴν ἡσυχίαν, ἔμενε δὲ νοσοῦν καὶ διεφθαρμένον. οἱ δὲ περὶ τὸν Δίαιον καὶ Κριτόλαον καὶ πάντες οἱ μετέχοντες αὐτοῖς τῆς αὐτῆς γνώμης· οὗτοι δ’ ἦσαν ὥσπερ ἐπίτηδες ἐξ ἑκάστης πόλεως κατ’ ἐκλογὴν οἱ χείριστοι καὶ τοῖς θεοῖς ἐχθροὶ καὶ λυμαινόμενοι τὸ ἔθνος· καθάπερ ἡ παροιμία φησίν, οὐ μόνον τὰ διδόμενα τῇ δεξιᾷ παρὰ Ῥωμαίων ἐδέχοντο τῇ λαιᾷ χειρί, καθόλου δὲ καὶ συλλήβδην παρέπαιον τοῖς λογισμοῖς. ὑπέλαβον γὰρ τοὺς Ῥωμαίους διά τε τὰς ἐν τῇ Λιβύῃ καὶ τὰς κατὰ τὴν Ἰβηρίαν πράξεις δεδιότας τὸν ἀπὸ τῶν Ἀχαιῶν πόλεμον πᾶν ὑπομένειν καὶ πᾶσαν προΐεσθαι φωνήν. διὸ νομίσαντες ἴδιον τὸ παρὸν ἀπεκρίθησαν φιλανθρώπως τοῖς πρεσβευταῖς τοὺς μὲν περὶ τὸν Θεαρίδαν ὅμως ἀποστέλλειν εἰς τὴν σύγκλητον, αὐτοὶ δὲ παρακολουθήσαντες εἰς τὴν Τεγέαν καὶ κοινολογηθέντες τοῖς Λακεδαιμονίοις, ἵνα γένηταί τις ὡμολογημένη λύσις περὶ τοῦ πολέμου. ταῦτα δ’ ἀποκριθέντες ἐν τοῖς ἑξῆς ἦγον ἐπὶ τὴν πάλαι προκειμένην αὐτοῖς ἄγνοιαν τὸ ταλαίπωρον ἔθνος. καὶ τοῦτ’ εἰκότως συνέβαινε γίνεσθαι δι’ ἀπειρίαν καὶ κακίαν τῶν κρατούντων.", "st": "38.8"}, {"sp": "N", "t": "τὸ δὲ τέλος τῆς ἀπωλείας ἠνύσθη τοιῷδέ τινι τρόπῳ. παραγενομένων γὰρ εἰς τὴν Τεγέαν τῶν περὶ τὸν Σέξτον καὶ τοὺς Λακεδαιμονίους ἐπισπασαμένων χάριν τοῦ σύμφωνον αὐτοῖς γενέσθαι πρὸς τοὺς Ἀχαιοὺς τήν τε περὶ τῶν προγεγονότων ἐγκλημάτων δικαιοδοσίαν καὶ τὴν κατὰ τὸν πόλεμον ἐποχήν, ἕως ἂν πέμψωσι Ῥωμαῖοι τοὺς περὶ τῶν ὅλων ἐπισκεψομένους, συνεδρεύσαντες οἱ περὶ τὸν Κριτόλαον ἔκριναν τοὺς μὲν ἄλλους διακλῖναι τὴν ἀπάντησιν, τὸν δὲ Κριτόλαον προάγειν εἰς τὴν Τεγέαν. ὁ μὲν οὖν προειρημένος ἤδη σχεδὸν ἀπηλπικότων τῶν περὶ τὸν Σέξτον ἦλθε, γενομένης δὲ συγκαταστάσεως πρὸς τοὺς Λακεδαιμονίους εἰς οὐδὲν συγκατέβαινεν, φήσας οὐκ ἔχειν ἐξουσίαν οὐδὲν οἰκονομεῖν ἄνευ τῆς τῶν πολλῶν γνώμης· ἐπανοίσειν δὲ τοῖς Ἀχαιοῖς εἰς τὴν ἑξῆς ἔφη σύνοδον, ἣν ἔδει γενέσθαι μετὰ μῆνας ἕξ. διὸ σαφῶς ἐπιγνόντες οἱ περὶ τὸν Σέξτον ἐθελοκακοῦντα τὸν Κριτόλαον καὶ δυσχεραίνοντες ἐπὶ τοῖς ἀπαντωμένοις τοὺς μὲν Λακεδαιμονίους ἀπέλυσαν εἰς τὴν οἰκείαν, αὐτοὶ δ’ ἐπανῆγον εἰς τὴν Ἰταλίαν, κατεγνωκότες ἄγνοιαν καὶ μανίαν τοῦ Κριτολάου. ὁ δὲ Κριτόλαος χωρισθέντων τούτων ἐπιπορευόμενος κατὰ τὸν χειμῶνα τὰς πόλεις ἐκκλησίας συνῆγε, προφάσει μὲν χρώμενος ὅτι βούλεται τὰ ῥηθέντα πρὸς τοὺς Λακεδαιμονίους καὶ πρὸς τοὺς ἐν τῇ Τεγέᾳ διασαφεῖν αὐτοῖς, τῇ δ’ ἀληθείᾳ κατηγορίαν ποιούμενος Ῥωμαίων καὶ πᾶν τὸ λεγόμενον ὑπ’ ἐκείνων ἐπὶ τὸ χεῖρον ἐκδεχόμενος, ἐξ ὧν δυσμένειαν καὶ μῖσος ἐνειργάζετο τοῖς ὄχλοις. ἅμα δὲ τούτοις παρήγγειλε τοῖς ἄρχουσι μὴ πράττειν τοὺς ὀφειλέτας μηδὲ παραδέχεσθαι τοὺς ἀπαγομένους εἰς φυλακὴν πρὸς τὰ χρέα, τοὺς δ’ ἐράνους ἐπιμόνους ποιεῖν, ἕως ἂν λάβῃ τὰ τοῦ πολέμου κρίσιν. λοιπὸν ἐκ τῆς τοιαύτης δημαγωγίας πᾶν τὸ λεγόμενον ὑπ’ αὐτοῦ πιστὸν ἐγίνετο, καὶ πρὸς πᾶν τὸ παραγγελλόμενον ἕτοιμον ἦν τὸ πλῆθος, περὶ μὲν τοῦ μέλλοντος ἀδυνατοῦν προνοεῖσθαι. τῇ δὲ παρ’ αὐτὰ χάριτι καὶ ῥᾳστώνῃ δελεαζόμενον.", "st": "38.9"}, {"sp": "N", "t": "ὁ δὲ Κόιντος ὁ Καικίλιος ἐν τῇ Μακεδονίᾳ τάδε πυνθανόμενος καὶ τὴν ἐν Πελοποννήσῳ γενομένην ἀκρισίαν καὶ ταραχὴν ἐξέπεμψε πρεσβευτὰς Γνάιον Παπείριον καὶ τὸν νεώτερον Ποπίλιον Λαινᾶτον, σὺν δὲ τούτοις Αὖλον Γαβίνιον καὶ Γάιον Φάννιον· οἳ καὶ συνηγμένων τῶν Ἀχαιῶν εἰς Κόρινθον, κατὰ τύχην ἐλθόντες εἰς τοῦτον τὸν καιρὸν καὶ παραχθέντες εἰς τὰ πλήθη διετίθεντο πολλοὺς οὗτοι καὶ φιλανθρώπους λόγους παραπλησίους τοῖς περὶ τὸν Σέξτον, πᾶσαν ἐνδεικνύμενοι φιλοτιμίαν χάριν τοῦ μὴ προβῆναι τοὺς Ἀχαιοὺς εἰς ὁλοσχερεστέραν ἀπέχθειαν πρὸς Ῥωμαίους μήτ’ ἐκ τῆς πρὸς Λακεδαιμονίους προφάσεως μήτε διὰ τῆς πρὸς αὐτοὺς ἐκείνους ἀλλοτριότητος. ὧν οἱ μὲν πολλοὶ διακούοντες οὐδαμῶς ἀνείχοντο, χλευάζοντες δὲ τοὺς πρέσβεις μετὰ θορύβου καὶ κραυγῆς ἐξέβαλον. καὶ γὰρ συνηθροίσθη πλῆθος ἐργαστηριακῶν καὶ βαναύσων ἀνθρώπων ὅσον οὐδέποτε· πᾶσαι μὲν γὰρ ἐκορύζων αἱ πόλεις, πανδημεὶ δὲ καὶ μάλιστά πως ἡ τῶν Κορινθίων. ὀλίγοις δέ τισι καὶ λίαν ἤρεσκε τὰ λεγόμενα διὰ τῶν πρεσβευτῶν. ὁ δὲ Κριτόλαος, ὥσπερ κατ’ εὐχὴν ὑποθέσεως ἐπειλημμένος καὶ θεάτρου συνενθουσιῶντος καὶ παρεστηκότος ταῖς διανοίαις, κατανίστατο μὲν τῶν ἀρχόντων, διέσυρε δὲ τοὺς ἀντιπολιτευομένους, ἐνεπαρρησιάζετο δὲ τοῖς τῶν Ῥωμαίων πρεσβευταῖς, φάσκων βούλεσθαι μὲν Ῥωμαίων φίλος ὑπάρχειν, δεσπότας δ’ οὐκ ἂν εὐδοκῆσαι κτησάμενος. καθόλου δὲ παρῄνει, λέγων ὡς, ἐὰν μὲν ἄνδρες ὦσιν, οὐκ ἀπορήσουσι συμμάχων, ἐὰν δ’ ἀνδρόγυνοι, κυρίων. καὶ πολλὰ δή τινα πρὸς ταύτην τὴν ὑπόθεσιν ἐμπορεύων καὶ μεθοδευόμενος ἐκίνει καὶ παρώξυνε τοὺς ὄχλους. ἐποίει δ’ ἐμφάσεις καὶ περὶ τοῦ μὴ τυχόντως χρῆσθαι ταῖς ἐπιβολαῖς, ἀλλὰ καὶ τῶν βασιλέων τινὰς καὶ τῶν πολιτευμάτων ἔνια κοινωνεῖν αὐτῷ τῆς προθέσεως.", "st": "38.10"}, {"sp": "N", "t": "τῶν δὲ τῆς γερουσίας βουλομένων ἐπιλαμβάνεσθαι καὶ κωλύειν αὐτὸν τῶν τοιούτων λόγων, περισπασάμενος τοὺς στρατιώτας κατανίστατο, κελεύων προσελθεῖν, ἐγγίσαι, τολμῆσαί τινα μόνον ἅψασθαι τῆς χλαμύδος. καθόλου δ’ ἔφη πολὺν ἤδη χρόνον παρακατεσχηκὼς αὑτὸν οὐκέτι δύνασθαι καρτερεῖν, ἀλλ’ ἐρεῖν τὸ φαινόμενον. δεῖν γὰρ οὐ Λακεδαιμονίους οὐδὲ Ῥωμαίους ἀγωνιᾶν οὕτως ὡς τοὺς ἐξ αὐτῶν συνεργοῦντας τοῖς ἐχθροῖς· εἶναι γάρ τινας τοὺς πλεῖον Ῥωμαίοις εὐνοοῦντας καὶ Λακεδαιμονίοις ἢ τοῖς σφετέροις πράγμασιν. καὶ τούτων πίστιν ἔφερεν· ἔφη γὰρ Εὐαγόραν τὸν Αἰγιέα καὶ τὸν Τριταιέα Στρατίον πάντα τὰ λεγόμενα δι’ ἀπορρήτων ἐν ταῖς συναρχίαις διασαφεῖν τοῖς περὶ τὸν Γνάιον. τοῦ δὲ Στρατίου συμμεμιχέναι μὲν τοῖς ἀνθρώποις ὁμολογοῦντος καὶ μετὰ ταῦτα συμμίξειν φάσκοντος φίλοις οὖσι καὶ συμμάχοις, ἀνηγγελκέναι δ’ ὁρκιζομένου μηδὲν τῶν ἐν ταῖς συναρχίαις εἰρημένων, ὀλίγοι μέν τινες ἐπίστευον, οἱ δὲ πλείους προσεδέχοντο τὰς διαβολάς. ὁ δὲ Κριτόλαος παροξύνας τοὺς ὄχλους διὰ τῆς τούτων κατηγορίας ἔπεισε τοὺς Ἀχαιοὺς πάλιν ψηφίσασθαι λόγῳ μὲν τὸν πρὸς Λακεδαιμονίους πόλεμον, ἔργῳ δὲ τὸν πρὸς Ῥωμαίους· καὶ προσεπεμέτρησεν ἕτερον ψήφισμα παράνομον, ὥστε κυρίους εἶναι τοὺς ἀνθρώπους οὓς [ἂν] ἐπὶ στρατηγίαν αἱρήσονται· δι’ οὗ τρόπου τινὰ μοναρχικὴν ἀνέλαβεν ἐξουσίαν. οὗτος μὲν οὖν ταῦτα διοικησάμενος ἐγίνετο περὶ τὸ πραγματοκοπεῖν καὶ Ῥωμαίοις ἐπιβάλλειν τὰς χεῖρας, οὐδενὶ λόγῳ τοῦτο πράττων, ἀλλὰ πάντων ἀσεβεστάτοις καὶ παρανομωτάτοις ἐπιβαλλόμενος· τῶν δὲ πρέσβεων ὁ μὲν Γνάιος εἰς Ἀθήνας ἀπῆρεν κἀκεῖθεν εἰς Λακεδαίμονα προσεδρεύσων τοῖς καιροῖς, ὁ δ’ Αὖλος εἰς Ναύπακτον, οἱ δὲ δύο μέχρι τῆς τοῦ Καικιλίου παρουσίας ἔμειναν ἐν ταῖς Ἀθήναις. καὶ τὰ μὲν κατὰ τὴν Πελοπόννησον ἐν τούτοις ἦν. —", "st": "38.11"}, {"sp": "HDR", "t": "Βιβλίον ΛΘʹ", "st": "39"}, {"sp": "N", "t": "οὐ γὰρ ἀγνοῶ διότι τινὲς ἐπιλήψονται τῆς πραγματείας, φάσκοντες ἀτελῆ καὶ διερριμμένην ἡμᾶς πεποιῆσθαι τὴν ἐξήγησιν τῶν πραγμάτων, εἴγ’ ἐπιβαλλόμενοι λόγου χάριν διεξιέναι τὴν Καρχηδόνος πολιορκίαν, κἄπειτα μεταξὺ ταύτην ἀπολιπόντες καὶ μεσολαβήσαντες σφᾶς αὐτοὺς μεταβαίνομεν ἐπὶ τὰς Ἑλληνικὰς κἀντεῦθεν ἐπὶ τὰς Μακεδονικὰς ἢ Συριακὰς ἤ τινας ἑτέρας πράξεις· ζητεῖν δὲ τοὺς φιλομαθοῦντας τὸ συνεχὲς καὶ τὸ τέλος ἱμείρειν ἀκοῦσαι τῆς προθέσεως· καὶ γὰρ τὴν ψυχαγωγίαν καὶ τὴν ὠφέλειαν οὕτω μᾶλλον συνεκτρέχειν τοῖς προσέχουσιν. ἐμοὶ δ’ οὐχ οὕτως δοκεῖ, τὸ δ’ ἐναντίον. μάρτυρα δὲ τούτων ἐπικαλεσαίμην ἂν αὐτὴν τὴν φύσιν, ἥτις κατ’ οὐδ’ ὁποίαν τῶν αἰσθήσεων εὐδοκεῖ τοῖς αὐτοῖς ἐπιμένειν κατὰ τὸ συνεχές, ἀλλ’ ἀεὶ μεταβολῆς ἐστιν οἰκεία, τοῖς δ’ αὐτοῖς ἐγκυρεῖν ἐκ διαστήματος βούλεται καὶ διαφορᾶς. εἴη δ’ ἂν τὸ λεγόμενον ἐναργὲς πρῶτον μὲν ἐκ τῆς ἀκοῆς, ἥτις οὔτε κατὰ τὰς μελῳδίας οὔτε κατὰ τὰς λεκτικὰς ὑποκρίσεις εὐδοκεῖ συνεχῶς ταῖς αὐταῖς ἐπιμένειν στάσεσιν, ὁ δὲ μεταβολικὸς τρόπος καὶ καθόλου πᾶν τὸ διερριμμένον καὶ μεγίστας ἔχον ἀλλαγὰς καὶ πυκνοτάτας αὐτὴν κινεῖ. παραπλησίως καὶ τὴν γεῦσιν εὕροι τις ἂν οὐδὲ τοῖς πολυτελεστάτοις βρώμασιν ἐπιμένειν δυναμένην, ἀλλὰ σικχαίνουσαν καὶ χαίρουσαν ταῖς μεταβολαῖς καὶ προσηνεστέρως ἀποδεχομένην πολλάκις καὶ τὰ λιτὰ τῶν ἐδεσμάτων ἢ τὰ πολυτελῆ διὰ τὸν ξενισμόν. τὸ δ’ αὐτὸ καὶ περὶ τὴν ὅρασιν ἴδοι τις ἂν γινόμενον· ἥκιστα γὰρ δύναται πρὸς ἓν μένειν ἀτενίζουσα, κινεῖ δ’ αὐτὴν ἡ ποικιλία καὶ μεταβολὴ τῶν ὁρωμένων. μάλιστα δὲ περὶ τὴν ψυχὴν τοῦτό τις ἂν ἴδοι συμβαῖνον· αἱ γὰρ μεταλήψεις τῶν ἀτενισμῶν καὶ τῶν ἐπιστάσεων οἷον ἀναπαύσεις εἰσὶ τοῖς φιλοπόνοις τῶν ἀνδρῶν.", "st": "39.1"}, {"sp": "N", "t": "διὸ καὶ τῶν ἀρχαίων συγγραφέων οἱ λογιώτατοι δοκοῦσί μοι προσαναπεπαῦσθαι τῷ τρόπῳ τούτῳ, τινὲς μὲν μυθικαῖς καὶ διηγηματικαῖς κεχρημένοι παρεκβάσεσι, τινὲς δὲ καὶ πραγματικαῖς, ὥστε μὴ μόνον ἐν αὐτοῖς τοῖς κατὰ τὴν Ἑλλάδα τόποις ποιεῖσθαι τὰς μεταβάσεις, ἀλλὰ καὶ τῶν ἐκτὸς περιλαμβάνειν. λέγω δ’ οἷον ἐπειδὰν τὰ κατὰ τὴν Θετταλίαν ἐξηγούμενοι καὶ τὰς Ἀλεξάνδρου τοῦ Φεραίου πράξεις μεταξὺ τὰς κατὰ Πελοπόννησον Λακεδαιμονίων ἐπιβολὰς διηγῶνται, καὶ πάλιν τὰς παρὰ Θηβαίων, ἔτι δὲ τὰς κατὰ Μακεδονίαν ἢ τὴν Ἰλλυρίδα, κἄπειτα διατρίψαντες λέγωσι τὴν Ἰφικράτους εἰς Αἴγυπτον στρατείαν καὶ τὰ Κλεάρχῳ πραχθέντα παρανομήματα κατὰ τὸν Πόντον. ἐξ ὧν κεχρημένους μὲν ἅπαντας εὕροι τις ἂν τῷ τοιούτῳ χειρισμῷ, κεχρημένους γε μὴν ἀτάκτως, ἡμᾶς δὲ τεταγμένως. ἐκεῖνοι μὲν γὰρ μνησθέντες πῶς Βάρδυλλις ὁ τῶν Ἰλλυριῶν βασιλεὺς καὶ Κερσοβλέπτης ὁ τῶν Θρᾳκῶν κατεκτήσαντο τὰς δυναστείας, οὐκέτι προστιθέασι τὸ συνεχές, οὐδ’ ἀνατρέχουσιν ἐπὶ τἀκόλουθον ἐκ διαστήματος, ἀλλὰ καθάπερ ἐν ποιήματι χρησάμενοι πάλιν ἐπανάγουσιν ἐπὶ τὰς ἐξ ἀρχῆς ὑποθέσεις. ἡμεῖς δὲ πάντας διῃρημένοι τοὺς ἐπιφανεστάτους τόπους τῆς οἰκουμένης καὶ τὰς ἐν τούτοις πράξεις καὶ μίαν καὶ τὴν αὐτὴν ἔφοδον ἀεὶ ποιούμενοι κατὰ τὴν τάξιν τῆς διαλήψεως, ἔτι δὲ καθ’ ἕκαστον ἔτος ὡρισμένως ἐξηγούμενοι τὰς καταλλήλους πράξεις ἐνεστηκυίας, ἀπολείπομεν πρόδηλον τοῖς φιλομαθοῦσι τὴν ἐπαναγωγὴν ἐπὶ τὸν συνεχῆ λόγον καὶ τὰς μεσολαβηθείσας ἀεὶ τῶν πράξεων, ὥστε μηδὲν ἀτελὲς μηδ’ ἐλλιπὲς γίνεσθαι τοῖς φιληκόοις τῶν προειρημένων. καὶ περὶ μὲν τούτων ἐπὶ τοσοῦτον.", "st": "39.2"}, {"sp": "N", "t": "ἐπεὶ δὲ παρελθὼν εἰς τὸ τεῖχος, τῶν Καρχηδονίων ἐκ τῆς ἄκρας ἀμυνομένων, εὗρε τὴν διὰ μέσου θάλασσαν οὐ πάνυ βαθεῖαν οὖσαν, τοῦ Πολυβίου συμβουλεύοντος αὐτῷ κατασπεῖραι τριβόλους σιδηροῦς ἢ σανίδας ἐμβαλεῖν κεντρωτάς, ὅπως μὴ διαβαίνοντες οἱ πολέμιοι προσμάχωνται τοῖς χώμασιν, ἔφη γελοῖον εἶναι, κατειληφότας τὰ τείχη καὶ τῆς πόλεως ἐντὸς ὄντας, εἶτα πράττειν ὅπως οὐ μαχοῦνται τοῖς πολεμίοις. —", "st": "39.3"}, {"sp": "N", "t": "ὅτι τοῦ Ἀσδρούβου τοῦ τῶν Καρχηδονίων στρατηγοῦ ἱκέτου παραγενομένου τοῖς τοῦ Σκιπίωνος γόνασιν, ὁ στρατηγὸς ἐμβλέψας εἰς τοὺς συνόντας \"ὁρᾶτ’\" ἔφη \"τὴν τύχην, ὦ ἄνδρες, ὡς ἀγαθὴ παραδειγματίζειν ἐστὶ τοὺς ἀλογίστους τῶν ἀνθρώπων. οὗτός ἐστιν Ἀσδρούβας ὁ νεωστὶ πολλῶν αὐτῷ καὶ φιλανθρώπων προτεινομένων ὑφ’ ἡμῶν ἀπαξιῶν, φάσκων δὲ κάλλιστον ἐντάφιον εἶναι τὴν πατρίδα καὶ τὸ ταύτης πῦρ, νῦν πάρεστι μετὰ στεμμάτων δεόμενος ἡμῶν τυχεῖν τῆς ζωῆς καὶ πάσας τὰς ἐλπίδας ἔχων ἐν ἡμῖν. ἃ τίς οὐκ ἂν ὑπὸ τὴν ὄψιν θεασάμενος ἐν νῷ λάβοι διότι δεῖ μηδέποτε λέγειν μηδὲ πράττειν μηδὲν ὑπερήφανον ἄνθρωπον ὄντα; \" καὶ προελθόντες τινὲς τῶν αὐτομόλων ἐπὶ τὸ πέρας τοῦ τέγους παρῃτοῦντο τοὺς προμαχομένους ἀνασχεῖν μικρόν· τοῦ δὲ στρατηγοῦ κελεύσαντος ἐπισχεῖν, ἤρξαντο τὸν Ἀσδρούβαν λοιδορεῖν οἱ μὲν εἰς ἐπιορκίαν, φάσκοντες αὐτὸν πολλάκις ἐπὶ τῶν ἱερῶν ὀμωμοκέναι μὴ προλείψειν αὐτούς, οἱ δ’ εἰς ἀνανδρίαν καὶ καθόλου τὴν τῆς ψυχῆς ἀγεννίαν· καὶ ταῦτ’ ἐποίουν μετὰ χλευασμοῦ καὶ λοιδορίας ἀσυροῦς καὶ δυσμενικῆς. κατὰ δὲ τὸν καιρὸν τοῦτον ἡ γυνὴ θεωροῦσα τὸν Ἀσδρούβαν προκαθήμενον μετὰ τοῦ στρατηγοῦ προῆλθεν ἐκ τῶν αὐτομόλων, αὐτὴ μὲν ἐλευθερίως καὶ σεμνῶς ἠμφιεσμένη, τοὺς δὲ παῖδας ἐν χιτωνίσκοις ἐξ ἑκατέρου τοῦ μέρους προσειληφυῖα ταῖς χερσὶ μετὰ τῶν ἰδίων ἐνδυμάτων. καὶ τὸ μὲν πρῶτον ὀνομαστὶ προσεφώνει τὸν Ἀσδρούβαν, τοῦ δ’ ἀποσιωπῶντος καὶ νεύοντος εἰς τὴν γῆν, τὰς μὲν ἀρχὰς τοὺς θεοὺς ἐπεκαλεῖτο καὶ τῷ στρατηγῷ μεγάλας ἀπένεμε τὰς χάριτας, διότι τὸ μὲν ἐκείνου μέρος οὐκ αὐτὴ μόνον, ἀλλὰ καὶ τὰ τέκνα σῴζεται· βραχὺ δ’ ἐπισχοῦσα τὸν Ἀσδρούβαν ἤρετο πῶς αὐτῇ μὲν φάσκων οὐδὲν κατ’ ἰδίαν παρὰ τοῦ στρατηγοῦ πορίζοιτο τὴν σωτηρίαν αὐτομολήσας, πῶς δ’ οὕτως ἀναισχύντως ἐγκαταλιπὼν τὰ πράγματα καὶ τοὺς ἀστοὺς αὐτῷ πιστεύοντας ὑπέλθοι πρὸς τοὺς πολεμίους, πῶς δὲ παρὰ τούτοις τολμᾷ καθῆσθαι νῦν θαλλοὺς ἔχων πρὸς οὓς … πολλάκις οὐδέποτε ταύτην ἔσεσθαι τὴν ἡμέραν, ἐν ᾗ συμβήσεται τὸν ἥλιον ἅμα καθορᾶν Ἀσδρούβαν ζῶντα καὶ τὴν πατρίδα πυρπολουμένην· οὐ μὴν ἀλλ’ … … γε τοεινε … δ … φυλα … οι ουσαν συ πεποιηκας αισχρως δεγεπονειδιστως ηδε … ρω … και … τα τεκνα πράξομεν … κα … ταυτα παλιν … εις αυτην … επω λενων το … ς ν … ον … υ … πο … ου … τει λασα τους αυ … τοισα … τε παντας … συμπαθεις γενομενους τηι περπετεια και … η … ας της τυχης … ν … δοξαι διαμ", "st": "39.4"}, {"sp": "N", "t": "ὁ δὲ Σκιπίων πόλιν ὁρῶν … τότε ἄρδην τελευτῶσαν ἐς πανωλεθρίαν ἐσχάτην, λέγεται μὲν δακρῦσαι καὶ φανερὸς γενέσθαι κλαίων ὑπὲρ πολεμίων· ἐπὶ πολὺ δ’ ἔννους ἐφ’ ἑαυτοῦ γενόμενός τε καὶ συνιδὼν ὅτι καὶ πόλεις καὶ ἔθνη καὶ ἀρχὰς ἁπάσας δεῖ μεταβαλεῖν ὥσπερ ἀνθρώπους δαίμονα, καὶ τοῦτ’ ἔπαθε μὲν Ἴλιον, εὐτυχής ποτε πόλις, ἔπαθε δὲ ἡ Ἀσσυρίων καὶ Μήδων καὶ Περσῶν ἐπ’ ἐκείνοις ἀρχὴ μεγίστη γενομένη καὶ ἡ μάλιστα ἔναγχος ἐκλάμψασα ἡ Μακεδόνων, εἴτε ἑκών, εἴτε προφυγόντος αὐτὸν τοῦδε τοῦ ἔπους εἰπεῖν, ἔσσεται ἦμαρ ὅταν ποτ’ ὀλώλῃ Ἴλιος ἱρὴ καὶ Πρίαμος καὶ λαὸς ἐυμμελίω Πριάμοιο. Πολυβίου δ’ αὐτὸν ἐρομένου σὺν παρρησίᾳ· καὶ γὰρ ἦν αὐτοῦ καὶ διδάσκαλος· ὅ τι βούλοιτο ὁ λόγος, φασὶν οὐ φυλαξάμενον ὀνομάσαι τὴν πατρίδα σαφῶς, ὑπὲρ ἧς ἄρα ἐς τἀνθρώπεια ἀφορῶν ἐδεδίει. καὶ τάδε μὲν Πολύβιος αὐτὸς ἀκούσας συγγράφει.", "st": "39.5"}, {"sp": "N", "t": "και … χ … ς επεισαγαγο … δε … σδ … αυ … της … επειμιαν … τι … παρ … καὶ δι … νι … τὸ δικαιον ευ … ρων φησιν ὁ πολυβιος εγων οτι και τιν⟨ο⟩ … ραν επι … αν … τούτου καλλιον … ουτ … και τοῦτ’ εἴρηται παρὰ τῷ ποιητῇ· καὶ ἐπιστρέψας ἐξ αὐτῆς καὶ λαβόμενός μου τῆς δεξιᾶς \"ὦ Πολύβιε,\" ἔφη \"καλὸν μέν, ἀλλ’ οὐκ οἶδ’ ὅπως ἐγὼ δέδια καὶ προορῶμαι μή ποτέ τις ἄλλος τοῦτο τὸ παράγγελμα δώσει περὶ τῆς ἡμετέρας πατρίδος·\" ταύτης δὲ δύναμιν πραγματικωτέραν καὶ νουνεχεστέραν οὐ ῥᾴδιον εἰπεῖν· τὸ γὰρ ἐν τοῖς μεγίστοις κατορθώμασι καὶ ταῖς τῶν ἐχθρῶν συμφοραῖς ἔννοιαν λαμβάνειν τῶν οἰκείων πραγμάτων καὶ τῆς ἐναντίας περιστάσεως καὶ καθόλου πρόχειρον ἔχειν ἐν ταῖς ἐπιτυχίαις τὴν τῆς τύχης ἐπισφάλειαν ἀνδρός ἐστι μεγάλου καὶ τελείου καὶ συλλήβδην ἀξίου μνήμης. —", "st": "39.5"}, {"sp": "N", "t": "ὅτι Πυθέας ἦν μὲν ἀδελφὸς Ἀκαστίδου τοῦ σταδιέως, υἱὸς δὲ Κλεομνάστου, κακῶς δὲ βεβιωκὼς καὶ δοκῶν ἑαυτῷ παρακεχρῆσθαι τὴν πρώτην ἡλικίαν, ὁμοίως δὲ καὶ κατὰ τὴν πολιτείαν θρασὺς καὶ πλεονέκτης καὶ δι’ Εὐμένους καὶ Φιλεταίρου σεσωματοποιημένος διὰ τὰς προειρημένας αἰτίας. —", "st": "39.7"}, {"sp": "N", "t": "ὅτι τοῦ Κριτολάου τοῦ στρατηγοῦ τῶν Ἀχαιῶν μετηλλαχότος, καὶ τοῦ νόμου κελεύοντος, ἐπὰν συμβῇ τι περὶ τὸν ἐνεστῶτα στρατηγόν, τὸν προγεγονότα διαδέχεσθαι τὴν ἀρχήν, ἕως ἂν ἡ καθήκουσα σύνοδος γένηται τῶν Ἀχαιῶν, ἐπέβαλε τῷ Διαίῳ χειρίζειν καὶ προεστάναι τῶν κοινῶν πραγμάτων. διόπερ ἐκπέμψας εἰς τὰ Μέγαρα καὶ παραγενόμενος εἰς Ἄργος ἔγραψε ταῖς πόλεσι πάσαις τῶν οἰκογενῶν καὶ παρατρόφων τοὺς ἀκμάζοντας ταῖς ἡλικίαις εἰς μυρίους καὶ δισχιλίους ἐλευθεροῦν καὶ καθοπλίσαντας πέμπειν εἰς τὴν Κόρινθον. ἐμέρισε δὲ ταῖς πόλεσι τὴν ἐπιβολὴν τῶν σωμάτων εἰκῇ καὶ ἀνίσως, καθάπερ καὶ περὶ τῶν ἄλλων ἔπραττεν. οἷς δ’ ἂν ἐλλείπῃ τὸ τῶν παρατρόφων πλῆθος, ἀναπληροῦν ἔδει τὴν ἑκάστοις καθήκουσαν μοῖραν ἐκ τῶν ἄλλων οἰκετῶν. θεωρῶν δὲ τὴν ἀπορίαν τὴν ἐν τοῖς κοινοῖς ἰσχυρὰν οὖσαν διὰ τὸν πρὸς Λακεδαιμονίους γεγονότα πόλεμον, ἐπαγγελίας ποιεῖσθαι συνηνάγκαζε καὶ κατ’ ἰδίαν εἰσφέρειν τοὺς εὐπόρους, οὐ μόνον τοὺς ἄνδρας ἀλλὰ καὶ τὰς γυναῖκας. ἅμα δὲ τούτοις παρήγγειλεν πανδημεὶ τοὺς ἐν ταῖς ἡλικίαις ἁθροίζεσθαι μετὰ τῶν ὅπλων εἰς τὴν Κόρινθον. ἐξ ὧν συνέβαινε γίνεσθαι τὰς πόλεις πλήρεις ἀκρισίας, ταραχῆς, δυσθυμίας. καὶ τοὺς μὲν ἀπολωλότας ἐπῄνουν, τοὺς δ’ ἐκπορευομένους ἠλέουν, καὶ προσκατεκλαίοντο πάντες ὡσανεὶ προορώμενοι τὸ μέλλον· τὴν δὲ τῶν οἰκετῶν ἀνάτασιν καὶ τὸν ἐπισυρμὸν βαρέως ἔφερον, ὡς ἂν τῶν μὲν ἠλευθερωμένων ἄρτι, τῶν δὲ λοιπῶν πρὸς τὴν ἐλπίδα ταύτην μεμετεωρισμένων. ἅμα δὲ τούτοις οἱ μὲν ἄνδρες εἰσφέρειν ἠναγκάζοντο παρὰ τὴν αὑτῶν προαίρεσιν ὅ,τι τις ἔχειν δόξειεν, αἱ δὲ γυναῖκες ἀφαιρούμεναι σφῶν αὐτῶν καὶ τῶν ἰδίων τέκνων τὸν κόσμον ὥσπερ ἐπίτηδες εἰς αὐτὸν τὸν ὄλεθρον εἰσέφερον.", "st": "39.8"}, {"sp": "N", "t": "ἁπάντων δὲ τούτων ἐν ἑνὶ καιρῷ συμβαινόντων, ἡ τῶν κατὰ μέρος ἀεὶ προσπιπτόντων κατάπληξις ἀφῃρεῖτο τῶν ἀνθρώπων τὴν ὑπὲρ τῶν ὅλων ἐπίστασιν καὶ διάληψιν, δι’ ἧς ἔμελλον προνοεῖσθαι διότι πάντες εἰς πρόδηλον ὄλεθρον ἄγονται μετὰ τέκνων καὶ γυναικῶν. λοιπόν, οἷον ὑπὸ χειμάρρου τινὸς λάβρου προωθούμενοι καὶ φερόμενοι μετὰ βίας, ἐπηκολούθουν τῇ τοῦ προεστῶτος ἀγνοίᾳ καὶ παρακοπῇ. Ἠλεῖοι μὲν γὰρ καὶ Μεσσήνιοι κατὰ χώραν ἔμειναν, προσδοκῶντες τὸν ἀπὸ τοῦ στόλου κίνδυνον· οὓς οὐδὲν ἂν τῶν παρόντων ὤνησεν, εἴπερ ἐφάνη τὸ νέφος ἐκεῖνο κατὰ τὴν ἐξ ἀρχῆς πρόθεσιν. Πατρεῖς δὲ καὶ τὸ μετὰ τούτων συντελικὸν βραχεῖ χρόνῳ πρότερον ἐπταίκει κατὰ τὴν Φωκίδα, καὶ τὸ συμβαῖνον ἦν πολλῷ τῶν κατὰ Πελοπόννησον ἐλεεινότερον. οἱ μὲν γὰρ ἐκ τοῦ ζῆν παραλόγως αὑτοὺς ἐξῆγον, οἱ δ’ ἔφευγον ἐκ τῶν πόλεων ἀνοδίαις, πρὸς οὐδὲν ὡρισμένον ποιούμενοι τὴν ἀναχώρησιν διὰ τὴν ἔκπληξιν τῶν γινομένων ἐν ταῖς πόλεσιν. καὶ οἱ μὲν ἦγον ἐκδώσοντες ἀλλήλους τοῖς πολεμίοις ὡς ἀλλοτρίους γεγονότας Ῥωμαίων, οἱ δ’ ἐμήνυον καὶ κατηγόρουν τῶν πέλας, οὐδενὸς ἐπιζητοῦντος κατὰ τὸ παρὸν τὴν τοιαύτην χρείαν· οἱ δὲ μεθ’ ἱκετηρίας ἀπήντων, ὁμολογοῦντες παρεσπονδηκέναι καὶ πυνθανόμενοι τί δεῖ πάσχειν, μηδέπω μηδενὸς ἐπιζητοῦντος λόγον ὑπὲρ τούτων. πάντα δ’ ἦν πλήρη παρηλλαγμένης φαρμακείας τῶν ῥιπτούντων ἑαυτοὺς εἰς τὰ φρέατα καὶ κατὰ κρημνῶν, ὥστε κατὰ τὴν παροιμίαν κἂν ἐχθρὸν ἐλεῆσαι θεασάμενον τὴν τότε περιπέτειαν τῆς Ἑλλάδος. τὸν μὲν γὰρ πρὸ τοῦ χρόνον ἐσφάλλοντο καὶ τοῖς ὅλοις ἔπταιον ἐνίοτε, ποτὲ μὲν ὑπὲρ πραγμάτων διαφερόμενοι, ποτὲ δὲ παρασπονδούμενοι διὰ τῶν μονάρχων· κατὰ δὲ τοὺς νῦν λεγομένους καιροὺς ἠτύχησαν ἀτυχίαν ὁμολογουμένην διὰ τὴν τῶν προεστώτων ἀβουλίαν καὶ διὰ τὴν ἰδίαν ἄγνοιαν. οἱ δὲ Θηβαῖοι ἐκλιπόντες πανδημεὶ τὴν πόλιν ἔρημον τελέως κατέλειπον· ἐν οἷς καὶ Πυθέας εἰς Πελοπόννησον ἀποχωρήσας μετὰ γυναικὸς καὶ τῶν τέκνων ἠλᾶτο κατὰ τῆς χώρας. — παράδοξος αὐτῷ ἐφάνη ἡ ἀπάντησις τῶν πολεμίων. ἀλλά μοι δοκεῖ κατὰ τὴν παροιμίαν κενὰ κενοὶ λογίζονται. λοιπὸν εἰκότως τοῖς τοιούτοις τὰ πρόδηλα παράδοξα φαίνεται. — καὶ ἐβουλεύετο περὶ τῆς εἰς οἶκον ἀνακομιδῆς, ὅμοιον ποιῶν ὡς εἴ τις ἄπειρος ὑπάρχων τοῦ νεῖν καὶ μέλλων αὑτὸν ῥίπτειν εἰς τὸ πέλαγος περὶ μὲν τοῦ ῥῖψαι μὴ βουλεύοιτο, ῥίψας δὲ διανοοῖτο περὶ τοῦ πῶς ἂν ἐκνήξαιτο πρὸς τὴν γῆν. —", "st": "39.9"}, {"sp": "N", "t": "ὅτι ἄρτι τοῦ Διαίου παρόντος εἰς τὴν Κόρινθον, καθεσταμένου στρατηγοῦ διὰ τῶν πολλῶν, ἧκον οἱ περὶ τὸν Ἀνδρωνίδαν παρὰ τοῦ Καικιλίου· καθ’ ὧν προδιαδοὺς φήμην ὡς συμφρονούντων τοῖς ἐχθροῖς, παρέβαλε τοὺς ἀνθρώπους τοῖς ὄχλοις, ὥστε μετὰ πάσης ὕβρεως συλληφθέντας ἀπαχθῆναι δεδεμένους. ἧκε δὲ καὶ Φίλων ὁ Θετταλὸς πολλὰ φιλάνθρωπα τοῖς Ἀχαιοῖς προτείνων· ὧν ἀκούοντες συνέπραξάν τινες τῶν ἐκ τῆς χώρας, ἐν οἷς ἦν καὶ Στρατίος ἤδη γηραιὸς ὤν, ὃς ἐμπλεκόμενος καὶ λιπαρῶν ἐδεῖτο τοῦ Διαίου πεισθῆναι τοῖς ὑπὸ τοῦ Καικιλίου προτεινομένοις. οἱ δὲ συνεδρεύσαντες τοῖς μὲν ὑπὸ τοῦ Φίλωνος λεγομένοις οὐ προσεῖχον· οὐκ ἐνόμισαν γὰρ κοινὴν εἶναι τὴν σωτηρίαν, ἀλλ’ αὐτοὺς κατ’ ἰδίαν τὸ σφέτερον συμφέρον καὶ τὴν αὑτῶν ἀσφάλειαν ἐν πλείστῳ τιθεμένους ταῦτα λέγειν. διὸ πρὸς τοῦτον τὸν σκοπὸν ἐβουλεύσαντο περὶ τῶν ἐνεστώτων, εἰ καὶ πάντων ἅμα διήμαρτον. σαφῶς γὰρ σφίσι τὰ πεπραγμένα συνειδότες οὐδαμῶς ἐδύναντο πιστεῦσαι διότι τύχοιεν ἄν τινος ἐλέου παρὰ Ῥωμαίων. τὸ δ’ ὑπὲρ τῶν πραγμάτων καὶ τῆς τῶν πολλῶν σωτηρίας παθεῖν ὅ,τι δέοι γενναίως οὐδ’ ἐν νῷ καθάπαξ ἐλάμβανον· ὅπερ ἦν ἀνδρῶν φιλοδόξων καὶ προστατεῖν φασκόντων τῆς Ἑλλάδος. ἀλλὰ γὰρ πῶς ἔμελλε καὶ πόθεν παραστήσεσθαι τοῦτο τὸ φρόνημα τοῖς προειρημένοις; ἦσαν γὰρ οἱ βουλευόμενοι Δίαιος καὶ Δαμόκριτος, ἄρτι τῆς καθόδου τετευχὼς διὰ τὴν ἐνεστῶσαν ἀκρισίαν, σὺν δὲ τούτοις Ἀλκαμένης, Θεοδέκτης, Ἀρχικράτης. ὑπὲρ ὧν, τίνες ἦσαν καὶ τίνα φύσιν ἕκαστος εἶχε καὶ τίνα προαίρεσιν καὶ βίον, εἴρηται διὰ πλειόνων.", "st": "39.10"}, {"sp": "N", "t": "ὅθεν ἐν τοιούτοις ὄντος τοῦ διαβουλίου καὶ τὸ τέλος ἀκόλουθον ἐξέβη τῶν δοξάντων. παραυτίκα μὲν οὖν συνέκλεισαν οὐ μόνον τοὺς περὶ τὸν Ἀνδρωνίδαν καὶ Λάγιον, ἀλλὰ καὶ τὸν ὑποστράτηγον Σωσικράτην, ἐπενέγκαντες αἰτίαν ὅτι προστατήσαι τοῦ διαβουλίου καὶ συναποφήναιτο πέμπειν πρὸς τὸν Καικίλιον καὶ συλλήβδην πάντων εἴη τῶν κακῶν αἴτιος· εἰς δὲ τὴν ἐπαύριον καθίσαντες δικαστὰς τοῦ μὲν Σωσικράτους κατεδίκασαν θάνατον καὶ δήσαντες καὶ στρεβλοῦντες προσεκαρτέρουν, ἕως διέφθειραν τὸν ἄνθρωπον, οὐδὲν εἰπόντα τῶν ἐκείνοις προσδοκωμένων. τὸν δὲ Λάγιον καὶ τὸν Ἀνδρωνίδαν καὶ τὸν Ἄρχιππον ἀφῆκαν, ἅμα μὲν τοῦ πλήθους εἰς ἐπίστασιν παραγενομένου διὰ τὴν εἰς τὸν Σωσικράτη παρανομίαν, ἅμα δὲ τοῦ Διαίου λαβόντος παρὰ μὲν Ἀνδρωνίδου τάλαντον, παρὰ δ’ Ἀρχίππου τετταράκοντα μνᾶς. οὐδὲ γὰρ ἐπὶ τοῦ σκάμματος ὤν, τὸ δὴ λεγόμενον, ἐδύνατο λῆξαι τῆς περὶ τοῦτο τὸ μέρος ἀναισχυντίας καὶ παρανομίας ὁ προειρημένος. παραπλήσια δὲ τούτοις ἔπραξε καὶ βραχεῖ χρόνῳ πρότερον εἰς Φιλῖνον τὸν Κορίνθιον· προθεὶς γὰρ αἰτίαν ὅτι διαπέμπεται πρὸς Μεναλκίδαν καὶ τὰ Ῥωμαίων φρονεῖ, τόν τε Φιλῖνον καὶ τοὺς υἱοὺς αὐτοῦ μαστιγῶν καὶ στρεβλῶν ἐν συνόψει πάντας ἀλλήλων οὐ πρότερον ἔληξε πρὶν ἢ διέφθειρε τὰ μειράκια καὶ τὸν Φιλῖνον. τοιαύτης δὲ τῆς ἀνοίας καὶ τῆς ἀκρισίας συμβαινούσης περὶ πάντας οἵαν οὐδ’ ἂν ἐν βαρβάροις εὕροι τις ῥᾳδίως, δῆλον ὡς εἰκότως ἄν τις ἐπιζητήσειε πῶς οὐκ ἄρδην ἀπώλοντο πάντες. ἐγὼ γὰρ ἂν εἴποιμι διότι δοκεῖ μοι καθαπερανεὶ τύχη τις ἀντερεῖσαι πανοῦργος καὶ τεχνικὴ πρὸς τὴν ἄνοιαν καὶ μανίαν τῶν ἡγουμένων, ἥτις ἐξωθουμένη πάντῃ καὶ πάντως ὑπὸ τῆς ἀγνοίας τῶν προεστώτων, βουλομένη δὲ κατὰ πάντα τρόπον σῴζειν τοὺς Ἀχαιούς, ἐπὶ τὸ καταλειπόμενον ἦλθεν ὥσπερ ἀγαθὸς παλαιστής. τοῦτο δ’ ἦν τὸ ταχέως σφῆλαι καὶ ῥᾳδίως ἡττῆσαι τοὺς Ἕλληνας· ὅπερ ἐποίησε. διὰ γὰρ τοῦτο συνέβη μήτε τὴν τῶν Ῥωμαίων ὀργὴν καὶ θυμὸν ἐκκαυθῆναι πορρωτέρω, μηδ’ ἐλθεῖν τὰς ἐκ τῆς Λιβύης δυνάμεις, μήτε τοὺς προεστῶτας, ὄντας οἵους εἶπον, ἐπιλαβομένους δὲ προτερήματος, ἀποδείξασθαι τὴν αὑτῶν ἀσέβειαν εἰς τοὺς ὁμοφύλους. τί γὰρ εἰκὸς ἦν πρᾶξαι τούτους κατὰ τῶν ἰδίων, ἐπιλαβομένους ἀφορμῆς τινος ἢ προτερήματος, δῆλόν ἐστιν ἐκ τῶν προειρημένων διὰ τὸ κατὰ λόγον. ἅπαντες δὲ τότε τὴν παροιμίαν ταύτην διὰ στόματος ἔσχον, ὡς \"εἰ μὴ ταχέως ἀπωλόμεθα, οὐκ ἂν ἐσώθημεν.\"", "st": "39.11"}, {"sp": "N", "t": "ὅτι Αὖλος Ποστόμιος ἄξιος γέγονεν ἐπισημασίας ἀπεντεῦθεν. οἰκίας μὲν γὰρ ἦν καὶ γένους πρώτου, κατὰ δὲ τὴν ἰδίαν φύσιν στωμύλος καὶ λάλος καὶ πέρπερος διαφερόντως. ἐπιθυμήσας δ’ εὐθέως ἐκ παίδων τῆς Ἑλληνικῆς ἀγωγῆς καὶ διαλέκτου πολὺς μὲν ἦν ἐν τούτοις καὶ κατακορής, ὥστε δι’ ἐκεῖνον καὶ τὴν αἵρεσιν τὴν Ἑλληνικὴν προσκόψαι τοῖς πρεσβυτέροις καὶ τοῖς ἀξιολογωτάτοις τῶν Ῥωμαίων, τέλος δὲ καὶ ποίημα γράφειν καὶ πραγματικὴν ἱστορίαν ἐνεχείρησεν, ἐν ᾗ διὰ τοῦ προοιμίου παρεκάλει τοὺς ἐντυγχάνοντας συγγνώμην ἔχειν, ἐὰν Ῥωμαῖος ὢν μὴ δύνηται κατακρατεῖν τῆς Ἑλληνικῆς διαλέκτου καὶ τῆς κατὰ τὸν χειρισμὸν οἰκονομίας. πρὸς ὃν οἰκείως ἀπηντηκέναι δοκεῖ Μάρκος Πόρκιος Κάτων· θαυμάζειν γὰρ ἔφη πρὸς τίνα λόγον ποιεῖται τοιαύτην παραίτησιν. εἰ μὲν γὰρ αὐτῷ τὸ τῶν Ἀμφικτυόνων συνέδριον συνέταττε γράφειν ἱστορίαν, ἴσως ἔδει προφέρεσθαι ταῦτα καὶ παραιτεῖσθαι· μηδεμιᾶς δ’ ἀνάγκης οὔσης ἐθελοντὴν ἀπογράψασθαι κἄπειτα παραιτεῖσθαι συγγνώμην ἔχειν, ἐὰν βαρβαρίζῃ, τῆς ἁπάσης ἀτοπίας εἶναι σημεῖον, καὶ παραπλησίως ἄχρηστον ὡσανεί τις εἰς τοὺς γυμνικοὺς ἀγῶνας ἀπογραψάμενος πυγμὴν ἢ παγκράτιον, παρελθὼν εἰς τὸ στάδιον, ὅτε δέοι μάχεσθαι, παραιτοῖτο τοὺς θεωμένους συγγνώμην ἔχειν, ἐὰν μὴ δύνηται μήτε τὸν πόνον ὑπομένειν μήτε τὰς πληγάς. δῆλον γὰρ ὡς εἰκὸς γέλωτα τὸν τοιοῦτον ὀφλεῖν καὶ τὴν δίκην ἐκ χειρὸς λαμβάνειν· ὅπερ ἔδει καὶ τοὺς τοιούτους ἱστοριογράφους, ἵνα μὴ κατετόλμων τοῦ καλῶς ἔχοντος. παραπλησίως δὲ καὶ κατὰ τὸν λοιπὸν βίον ἐζηλώκει τὰ χείριστα τῶν Ἑλληνικῶν· καὶ γὰρ φιλήδονος ἦν καὶ φυγόπονος. τοῦτο δ’ ἔσται δῆλον ἐξ αὐτῶν τῶν ἐνεστώτων· ὃς πρῶτος παρὼν ἐν τοῖς κατὰ τὴν Ἑλλάδα τόποις, καθ’ ὃν καιρὸν συνέβαινε γίνεσθαι τὴν ἐν Φωκίδι μάχην, σκηψάμενος ἀσθένειαν εἰς Θήβας ἀνεχώρησεν χάριν τοῦ μὴ μετασχεῖν τοῦ κινδύνου· συντελεσθείσης δὲ τῆς μάχης πρῶτος ἔγραψε τῇ συγκλήτῳ περὶ τοῦ κατορθώματος, προσδιασαφῶν τὰ κατὰ μέρος, ὡς μετεσχηκὼς αὐτὸς τῶν ἀγώνων. —", "st": "39.12"}, {"sp": "N", "t": "Πολύβιος δὲ τὰ συμβάντα περὶ τὴν ἅλωσιν ἐν οἴκτου μέρει λέγων προστίθησι καὶ τὴν στρατιωτικὴν ὀλιγωρίαν τὴν περὶ τὰ τῶν τεχνῶν ἔργα καὶ τὰ ἀναθήματα· φησὶ γὰρ ἰδεῖν παρὼν ἐρριμμένους πίνακας ἐπ’ ἐδάφους, πεττεύοντας δὲ τοὺς στρατιώτας ἐπὶ τούτων. ὀνομάζει δ’ αὐτῶν Ἀριστείδου γραφὴν τοῦ Διονύσου, ἐφ’ οὗ τινες εἰρῆσθαί φασι τὸ \"Οὐδὲν πρὸς τὸν Διόνυσον\", καὶ τὸν Ἡρακλέα τὸν καταπονούμενον τῷ τῆς Δηιανείρας χιτῶνι. —", "st": "39.13"}, {"sp": "N", "t": "ὅτι διὰ τὴν προϋπάρχουσαν τοῦ πλήθους πρὸς Φιλοποίμενα εὔνοιαν οὐ καθεῖλον τὰς εἰκόνας αὐτοῦ ἐν πόλεσί τισιν οὔσας· οὕτως μοι δοκεῖ πᾶν τὸ γινόμενον ἀληθινῶς ἐνεργάζεσθαί τινα δυσεξάλειπτον εὔνοιαν τοῖς εὖ παθοῦσι. — διὸ καὶ δικαίως ἂν εἴποι τις τὸ περιφερόμενον, οὐ θύρᾳ, τὸ δὴ λεγόμενον, ἀλλ’ ἀμφόδῳ διέψευσται. — οὐσῶν δὲ πολλῶν μὲν εἰκόνων αὐτοῦ μεγάλων δὲ τιμῶν, ἃς αἱ πόλεις ἐψηφίσαντο, Ῥωμαῖος ἀνὴρ ἐν τοῖς περὶ Κόρινθον ἀτυχήμασι τῆς Ἑλλάδος ἐπεχείρησεν ἀνελεῖν ἁπάσας καὶ διώκειν αὐτόν, ἐνδεικνύμενος ὥσπερ ἔτι ζῶντα Ῥωμαίοις πολέμιον καὶ κακόνουν γενέσθαι. λόγων δὲ λεχθέντων καὶ Πολυβίου πρὸς τὸν συκοφάντην ἀντειπόντος, οὔθ’ ὁ Μόμμιος οὔτε οἱ πρέσβεις ὑπέμειναν ἀνδρὸς ἐνδόξου τιμὰς ἀφανίσαι. — ἐπεβάλετο διδάσκειν διὰ πλειόνων ἀκολούθως τοῖς ἐν ἀρχαῖς ἡμῖν εἰρημένοις περὶ τἀνδρός. ταῦτα δ’ ἦν ὅτι διαφέροιτο μὲν πρὸς Ῥωμαίους πολλάκις ὑπὲρ τῶν ἐπιταττομένων, διαφέροιτο δ’ ἐπὶ τοσοῦτον ἐφ’ ὅσον διδάσκειν καὶ πείθειν ὑπὲρ τῶν ἀμφισβητουμένων, οὐδὲ τοῦτο ποιεῖν εἰκῇ. πεῖραν δὲ τῆς προαιρέσεως αὐτὸν ἀληθινὴν ἔφη καὶ τὸ δὴ λεγόμενον ἐκ πυρὸς παρεσχῆσθαι χάριν κατὰ τοὺς Φιλιππικοὺς καὶ κατὰ τοὺς Ἀντιοχικοὺς καιρούς· πλείστην γὰρ ἔχοντα ῥοπὴν τότε τῶν Ἑλλήνων καὶ διὰ τὴν αὑτοῦ δύναμιν καὶ τὴν τῶν Ἀχαιῶν ἀληθινώτατα διατετηρηκέναι τὴν πρὸς Ῥωμαίους φιλίαν, μετασχόντα τοῦ δόγματος τοῖς Ἀχαιοῖς, ἐν ᾧ τετραμήνῳ πρότερον τῆς Ῥωμαίων διαβάσεως Ἀντιόχῳ καὶ τοῖς Αἰτωλοῖς τὸν ἀπὸ τῆς χώρας πόλεμον ἐξήνεγκαν, τῶν ἄλλων Ἑλλήνων σχεδὸν ἁπάντων ἀπηλλοτριωμένων τῆς Ῥωμαίων φιλίας. ὧν οἱ δέκα διακούσαντες καὶ τὴν προαίρεσιν ἀποδεξάμενοι τοῦ λέγοντος συνεχώρησαν καταμόνους αὐτῷ τὰς τιμὰς ὑπάρχειν ἐν πάσαις ταῖς πόλεσι. λαβόμενος δὲ τῆς ἀφορμῆς ταύτης Πολύβιος τὰς εἰκόνας ᾐτήσατο τὸν στρατηγόν, καίπερ ἤδη μετακεκομισμένας εἰς Ἀκαρνανίαν ἐκ Πελοποννήσου, λέγω δὲ τὴν Ἀχαιοῦ καὶ τὴν Ἀράτου καὶ Φιλοποίμενος. ἐν οἷς ἀγασθὲν τὸ πλῆθος αὐτοῦ τὴν προαίρεσιν ἔστησεν αὐτοῦ λιθίνην εἰκόνα. —", "st": "39.14"}, {"sp": "N", "t": "ὅτι μετὰ τὴν κατάστασιν τῶν δέκα, ἣν ἐποιήσαντο ἐν τῇ Ἀχαΐᾳ, οὗτοι οἱ δέκα τῷ ταμίᾳ τῷ μέλλοντι πωλεῖν τὴν οὐσίαν τοῦ Διαίου συνέταξαν, ὅ,τι ποτ’ ἂν ἐκλέξασθαι βουληθῇ τῶν ὑπαρχόντων ὁ Πολύβιος, ὑφελόντα καὶ δόντα δωρεάν, τἄλλα πωλεῖν τοῖς ὠνουμένοις. ὁ δὲ προειρημένος τοσοῦτον ἀπέσχε τοῦ προσδέξασθαί τι τῶν τοιούτων ὡς καὶ τοὺς φίλους παρεκάλεσε καθόλου μηθενὸς ἐπιθυμῆσαι τῶν ὑπὸ τοῦ ταμίου πωλουμένων. συνέβαινε γὰρ τοῦτον ἐπιπορευόμενον τὰς πόλεις πάντων τῶν τῷ Διαίῳ κοινωνησάντων πωλεῖν τὰς οὐσίας, τῶν καὶ κατακριθέντων, ὅσοι μὴ παῖδας ἢ γονέας εἶχον. ὧν τινὲς μὲν οὐ προσέσχον, οἱ δὲ κατακολουθήσαντες τῇ συμβουλίᾳ καλλίστην δόξαν ἐξηνέγκαντο παρὰ τοῖς πολίταις.", "st": "39.15"}, {"sp": "N", "t": "ταῦτα δὲ διοικήσαντες ἐν ἓξ μησὶν οἱ δέκα [καὶ] τῆς ἐαρινῆς ὥρας ἐνισταμένης ἀπέπλευσαν εἰς τὴν Ἰταλίαν, καλὸν δεῖγμα τῆς Ῥωμαίων προαιρέσεως ἀπολελοιπότες πᾶσι τοῖς Ἕλλησιν. ἐνετείλαντο δὲ τῷ Πολυβίῳ χωριζόμενοι τὰς πόλεις ἐπιπορευθῆναι καὶ περὶ ὧν οἱ ἄνθρωποι ἀμφιβάλλουσι διευκρινῆσαι, μέχρις οὗ συνήθειαν ἔχωσι τῇ πολιτείᾳ καὶ τοῖς νόμοις. ὃ δὴ καὶ μετά τινα χρόνον ἐποίησε πρὸς λόγον τοὺς ἀνθρώπους στέρξαι τὴν δεδομένην πολιτείαν καὶ μηδὲν ἀπόρημα μήτε κατ’ ἰδίαν μήτε κατὰ κοινὸν ἐκ τῶν νόμων γενέσθαι περὶ μηδενός. διὸ καὶ καθόλου μὲν ἐξ ἀρχῆς ἀποδεχόμενοι καὶ τιμῶντες τὸν ἄνδρα, περὶ τοὺς ἐσχάτους καιροὺς καὶ τὰς προειρημένας πράξεις εὐδοκούμενοι κατὰ πάντα τρόπον ταῖς μεγίσταις τιμαῖς ἐτίμησαν αὐτὸν κατὰ πόλεις καὶ ζῶντα καὶ μεταλλάξαντα. πάντες δ’ ἔκριναν κατὰ λόγον τοῦτο ποιεῖν· μὴ γὰρ ἐξεργασαμένου τούτου καὶ γράψαντος τοὺς περὶ τῆς κοινῆς δικαιοδοσίας νόμους ἄκριτα πάντα ἦν καὶ πολλῆς γέμοντα ταραχῆς. διὸ καὶ τοῦτο κάλλιστον Πολυβίῳ πεπρᾶχθαι νομιστέον πάντων τῶν προειρημένων. —", "st": "39.16"}, {"sp": "N", "t": "ὅτι ὁ στρατηγὸς τῶν Ῥωμαίων μετὰ τὸ χωρισθῆναι ἐξ Ἀχαΐας τὸ συνέδριον, ἐπισκευάσας τὸν ἐν Ἰσθμῷ τόπον καὶ κοσμήσας τὸν ἐν Ὀλυμπίᾳ καὶ Δελφοῖς νεὼν ταῖς ἑξῆς ἡμέραις ἐπεπορεύετο τὰς πόλεις, τιμώμενος ἐν ἑκάστῃ καὶ τυγχάνων τῆς ἁρμοζούσης χάριτος. εἰκότως δὲ τιμᾶσθαι συνέβαινεν αὐτὸν καὶ κοινῇ καὶ κατ’ ἰδίαν· καὶ γὰρ ἐγκρατῶς καὶ καθαρῶς ἀνεστράφη καὶ πρᾴως ἐχρήσατο τοῖς ὅλοις πράγμασι, μέγαν καιρὸν ἐν τοῖς Ἕλλησιν ἔχων καὶ μεγάλην ἐξουσίαν. καὶ γὰρ ἐν οἷς ἐδόκει παρεωρακέναι τι τῶν καθηκόντων, ἐμοὶ μὲν οὐκ ἐφαίνετο δι’ ἑαυτὸν τοῦτο πεποιηκέναι, διὰ δὲ τοὺς παρακειμένους φίλους. τοῦτο δ’ ἦν ἐκφανέστατον ἐν τοῖς τῶν Χαλκιδέων ἱππεῦσιν, οὓς ἀνεῖλεν.", "st": "39.17"}, {"sp": "N", "t": "ὅτι Πτολεμαῖος ὁ τῆς Συρίας βασιλεὺς κατὰ τὸν πόλεμον πληγεὶς ἐτελεύτησε τὸν βίον, κατὰ μέν τινας μεγάλων ἐπαίνων καὶ μνήμης ὢν ἄξιος, κατὰ δέ τινας τοὐναντίον. πρᾷος μὲν γὰρ ἦν καὶ χρηστός, εἰ καί τις ἄλλος τῶν προγεγονότων βασιλέων. σημεῖον δὲ τούτου μέγιστον· ὃς πρῶτον μὲν οὐδένα τῶν ἑαυτοῦ φίλων ἐπ’ οὐδενὶ τῶν ἐγκλημάτων ἐπανείλετο· δοκῶ δὲ μηδὲ τῶν ἄλλων Ἀλεξανδρέων μηδένα δι’ ἐκεῖνον ἀποθανεῖν· ἔπειτα δόξας ἐκπεσεῖν ἀπὸ τῆς ἀρχῆς ὑπὸ τἀδελφοῦ, τὸ μὲν πρῶτον ἐν Ἀλεξανδρείᾳ λαβὼν κατ’ αὐτοῦ καιρὸν ὁμολογούμενον ἀμνησικάκητον ἐποιήσατο τὴν ἁμαρτίαν· μετὰ δὲ ταῦτα πάλιν ἐπιβουλεύσαντος τῇ Κύπρῳ, κύριος γενόμενος ἐν Λαπήθῳ τοῦ σώματος ἅμα καὶ τῆς ψυχῆς αὐτοῦ, τοσοῦτον ἀπέσχε τοῦ κολάζειν ὡς ἐχθρὸν ὥστε καὶ δωρεὰς προσέθηκε παρὰ τὰς πρότερον ὑπαρχούσας αὐτῷ κατὰ συνθήκας καὶ τὴν θυγατέρα δώσειν ὑπέσχετο. κατὰ μέντοι γε τὰς ἐπιτυχίας καὶ κατορθώσεις ἐξελύετο τῇ ψυχῇ, καί τις οἷον ἀσωτία καὶ ῥᾳθυμία περὶ αὐτὸν Αἰγυπτιακὴ συνέβαινεν· καὶ κατὰ τὰς τοιαύτας διαθέσεις εἰς περιπετείας ἐνέπιπτεν.", "st": "39.18"}, {"sp": "N", "t": "ὅτι ὁ Πολύβιός φησι κατὰ τὸ τέλος τῆς συγγραφῆς· ταῦτα μὲν οὖν ἡμεῖς καταπράξαντες ἐκ τῆς Ῥώμης ἐπανήλθομεν, ὡσανεὶ κεφάλαιά τινα τῶν προπεπολιτευμένων κατειργασμένοι, χάριν ἀξίαν τῆς πρὸς Ῥωμαίους εὐνοίας. διὸ καὶ πᾶσι τοῖς θεοῖς εὐχὰς ποιούμεθα τὸ λοιπὸν μέρος τῆς ζωῆς ἐν τούτοις καὶ ἐπὶ τούτων διαμεῖναι, θεωροῦντες τὴν τύχην ὡς ἔστιν ἀγαθὴ φθονῆσαι τοῖς ἀνθρώποις καὶ μάλιστα κατὰ τοῦτο τὸ μέρος ἰσχύει καθ’ ὅ τις ἂν δοκῇ μάλιστα μακαρίζεσθαι καὶ κατορθοῦν ἐν τῷ βίῳ. καὶ ταῦτα μὲν οὕτω γενέσθαι συνέπεσεν· ἡμεῖς δὲ παραγεγονότες ἐπὶ τὸ τέρμα τῆς ὅλης πραγματείας βουλόμεθα, προσαναμνήσαντες τῆς ἀρχῆς καὶ τῆς προεκθέσεως ἧς ἐποιησάμεθα καταβαλόμενοι τὴν ἱστορίαν, συγκεφαλαιώσασθαι τὴν ὅλην ὑπόθεσιν, οἰκειώσαντες τὴν ἀρχὴν τῷ τέλει καὶ καθόλου καὶ κατὰ μέρος. ἐξεθέμεθα τοιγαροῦν ἐν ἀρχαῖς ὅτι τῆς μὲν προκατασκευῆς ποιησόμεθα τὴν ἀρχὴν ἀφ’ ὧν Τίμαιος ἀπέλιπεν· ἐπιδραμόντες δὲ κεφαλαιωδῶς τὰς κατὰ τὴν Ἰταλίαν καὶ Σικελίαν καὶ Λιβύην πράξεις, ἐπειδὴ περὶ μόνων τῶν τόπων τούτων κἀκεῖνος πεποίηται τὴν ἱστορίαν, ὅτ’ ἀνήλθομεν ἐπὶ τοὺς χρόνους, ἐν οἷς Ἀννίβας μὲν παρέλαβε τὰς Καρχηδόνος δυνάμεις, ὁ δὲ Δημητρίου Φίλιππος τὴν ἐν Μακεδονίᾳ βασιλείαν, Κλεομένης δ’ ὁ Σπαρτιάτης ἔφυγεν ἐκ τῆς Ἑλλάδος, ἅμα δὲ τούτοις Ἀντίοχος μὲν τὴν ἐν τῇ Συρίᾳ βασιλείαν διεδέδεκτο, Πτολεμαῖος δὲ τὴν κατ’ Αἴγυπτον ὁ κληθεὶς Φιλοπάτωρ, ἐπηγγειλάμεθα διότι πάλιν ἀπὸ τούτων τῶν καιρῶν ἀρξάμενοι καθ’ οὓς ἦν ὀλυμπιὰς ἐνάτη καὶ τριακοστὴ πρὸς ταῖς ἑκατόν, διέξιμεν τὰς κοινὰς τῆς οἰκουμένης πράξεις, περιγράφοντες κατ’ ὀλυμπιάδας καὶ διαιροῦντες κατ’ ἔτος καὶ συγκρίνοντες ἐκ παραβολῆς τὰς καταλλήλους ἕως τῆς Καρχηδόνος ἁλώσεως καὶ τῆς Ἀχαιῶν καὶ Ῥωμαίων περὶ τὸν Ἰσθμὸν μάχης, ἔτι δὲ τῆς ἐπιγενομένης ἐκ τούτων ἀποκαταστάσεως περὶ τοὺς Ἕλληνας. ἐξ ὧν τὸ κάλλιστον ἔφαμεν, ἅμα δ’ ὠφελιμώτατον περιγενέσθαι τοῖς φιλομαθοῦσι· τοῦτο δ’ ἦν τὸ γνῶναι πῶς καὶ τίνι γένει πολιτείας ἐπικρατηθέντα σχεδὸν ἅπαντα τὰ κατὰ τὴν οἰκουμένην ὑπὸ μίαν ἀρχὴν ἔπεσε τὴν Ῥωμαίων, ὃ πρότερον οὐχ εὑρίσκεται γεγονός. τούτων δὴ πάντων ἡμῖν ἐπιτετελεσμένων λείπεται διασαφῆσαι τοὺς χρόνους τοὺς περιειλημμένους ὑπὸ τῆς ἱστορίας καὶ τὸ πλῆθος τῶν βύβλων καὶ τὸν ἀριθμὸν τῆς ὅλης πραγματείας.", "st": "39.19"}, {"sp": "HDR", "t": "Ἀποσπάσματα", "st": "fr"}, {"sp": "N", "t": "οὐ γὰρ ἠξίουν ὡς Πολύβιος ὁ Μεγαλοπολίτης τοσοῦτον μόνον εἰπεῖν, ὅτι κατὰ τὸ δεύτερον ἔτος τῆς ἑβδόμης ὀλυμπιάδος τὴν Ῥώμην ἐκτίσθαι πείθομαι, οὐδ’ ἐπὶ τοῦ παρὰ τοῖς ἀρχιερεῦσι κειμένου πίνακος ἑνὸς καὶ μόνου τὴν πίστιν ἀβασάνιστον καταλιπεῖν …", "st": "fr"}, {"sp": "N", "t": "ἱστοροῦσι δὲ οἱ περὶ Ἀριστόδημον τὸν Ἠλεῖον ὡς ἀπὸ εἰκοστῆς καὶ ἑβδόμης ὀλυμπιάδος ἤρξαντο οἱ ἀθληταὶ ἀναγράφεσθαι, ὅσοι δηλαδὴ νικηφόροι· πρὸ τοῦ γὰρ οὐδεὶς ἀνεγράφη, ἀμελησάντων τῶν πρότερον· τῇ δὲ εἰκοστῇ ὀγδόῃ τὸ στάδιον νικῶν Κόροιβος Ἠλεῖος ἀνεγράφη πρῶτος· καὶ ἡ ὀλυμπιὰς αὕτη πρώτη ἐτάχθη, ἀφ’ ἧς Ἕλληνες ἀριθμοῦσι τοὺς χρόνους· τὰ δ’ αὐτὰ τῷ Ἀριστοδήμῳ καὶ Πολύβιος ἱστορεῖ.", "st": "fr"}, {"sp": "N", "t": "ὄνομα δὲ τῷ πολίσματι τούτῳ τίθενται Παλλάντιον ἐπὶ τῆς ἐν Ἀρκαδίᾳ σφῶν μητροπόλεως· … ὡς δέ τινες ἱστοροῦσιν, ὧν ἐστι καὶ Πολύβιος ὁ Μεγαλοπολίτης, ἐπί τινος μειρακίου Πάλλαντος αὐτόθι τελευτήσαντος· τοῦτον δὲ Ἡρακλέους εἶναι παῖδα καὶ Λαύνας τῆς Εὐάνδρου θυγατρός· χώσαντα δ’ αὐτῷ τὸν μητροπάτορα τάφον ἐπὶ τῷ λόφῳ Παλλάντιον ἐπὶ τοῦ μειρακίου τὸν τόπον ὀνομάσαι.", "st": "fr"}, {"sp": "N", "t": "παρὰ Ῥωμαίοις δέ, ὥς φησι Πολύβιος ἐν τῇ ἕκτῃ, ἀπείρηται γυναιξὶ πίνειν οἶνον, τὸ δὲ καλούμενον πάσσον πίνουσιν. τοῦτο δὲ ποιεῖται μὲν ἐκ τῆς ἀσταφίδος καί ἐστι παραπλήσιος πινόμενος τῷ Αἰγοσθενεῖ τῷ γλυκεῖ καὶ τῷ Κρητικῷ· διὸ πρὸς τὸ κατεπεῖγον τοῦ δίψους χρῶνται αὐτῷ. λαθεῖν δ’ ἐστὶν ἀδύνατον τὴν γυναῖκα πιοῦσαν οἶνον. πρῶτον μὲν γὰρ οὐδ’ ἔχει οἴνου κυρείαν ἡ γυνή· πρὸς δὲ τούτοις φιλεῖν δεῖ τοὺς συγγενεῖς τοὺς ἑαυτῆς καὶ τοὺς τοῦ ἀνδρὸς ἕως ἐξανεψιῶν καὶ τοῦτο ποιεῖν καθ’ ἡμέραν, ὁπόταν ἴδῃ πρῶτον. λοιπὸν ἀδήλου τῆς ἐντυχίας οὔσης τίσιν ἀπαντήσει φυλάσσεται· τὸ γὰρ πρᾶγμα κἂν γεύσηται μόνον οὐ προσδεῖ διαβολῆς.", "st": "fr"}, {"sp": "N", "t": "ἔκτισε δὲ καὶ πόλιν Ὠστίαν ἐπὶ τοῦ Τιβέριδος. Πολύβιος ἕκτῳ.", "st": "fr"}, {"sp": "N", "t": "ὅτι Λεύκιος ὁ Δημαράτου τοῦ Κορινθίου υἱὸς εἰς Ῥώμην ὥρμησε πιστεύων αὑτῷ τε καὶ τοῖς χρήμασι, πεπεισμένος οὐδενὸς ἔλαττον ἕξειν ἐν τῇ πολιτείᾳ [διά] τινας ἀφορμάς, ἔχων γυναῖκα χρησίμην τά τ’ ἄλλα καὶ πρὸς πᾶσαν ἐπιβολὴν πραγματικὴν εὐφυῆ συνεργόν. παραγενόμενος δ’ εἰς τὴν Ῥώμην καὶ τυχὼν τῆς πολιτείας, εὐθέως ἡρμόσατο πρὸς τὴν τοῦ βασιλέως ἀρέσκειαν. ταχὺ δὲ καὶ διὰ τὴν χορηγίαν καὶ διὰ τὴν τῆς φύσεως ἐπιδεξιότητα καὶ μάλιστα διὰ τὴν ἐκ παίδων ἀγωγήν, ἁρμόσας τῷ προεστῶτι μεγάλης ἀποδοχῆς ἔτυχε καὶ πίστεως παρ’ αὐτῷ. χρόνου δὲ προϊόντος εἰς τοῦτ’ ἦλθε παραδοχῆς ὥστε συνδιοικεῖν καὶ συγχειρίζειν τῷ Μαρκίῳ τὰ κατὰ τὴν βασιλείαν. ἐν δὲ τούτοις ἐπ’ ἀγαθῷ πᾶσι γενόμενος καὶ συνεργῶν καὶ συγκατασκευάζων τοῖς δεομένοις ἀεί τι τῶν χρησίμων, ἅμα δὲ καὶ τῇ τοῦ βίου χορηγίᾳ μεγαλοψύχως εἰς τὸ δέον ἑκάστοτε καὶ σὺν καιρῷ χρώμενος, ἐν πολλοῖς μὲν ἀπετίθετο χάριν, ἐν πᾶσι δ’ εὔνοιαν ἐνειργάσατο καὶ φήμην ἐπὶ καλοκἀγαθίᾳ καὶ τῆς βασιλείας ἔτυχεν.", "st": "fr"}, {"sp": "N", "t": "ὅτι πάντα χρὴ τὰ τῆς ἀρετῆς ἔργα τοὺς καλῶς ἀσκοῦντας ἐκ παίδων ἀσκεῖν, μάλιστα δὲ τὴν ἀνδρείαν.", "st": "fr"}, {"sp": "N", "t": "τὸ γὰρ ἀδύνατον ἐν τῷ ψεύδει μόνον οὐδ’ ἀπολογίαν ἐπιδέχεται τοῖς ἁμαρτάνουσιν.", "st": "fr"}, {"sp": "N", "t": "πρᾶγμα ποιῶν φρονίμου καὶ νουνεχοῦς ἀνδρός, τὸ γνῶναι κατὰ τὸν Ἡσίοδον ὅσῳ πλέον ἥμισυ παντός.", "st": "fr"}, {"sp": "N", "t": "τὸ γὰρ μανθάνειν ἀψευστεῖν πρὸς τοὺς θεοὺς ὑπόθυψίς ἐστι τῆς πρὸς ἀλλήλους ἀληθείας.", "st": "fr"}, {"sp": "N", "t": "ἐν γὰρ τοῖς πλείστοις τῶν ἀνθρωπείων ἔργων οἱ μὲν κτησάμενοι πρὸς τὴν τήρησιν, οἱ δ’ ἕτοιμα παραλαβόντες πρὸς τὴν ἀπώλειαν εὐφυεῖς εἰσιν.", "st": "fr"}], []);})();
